typedef struct {
    int value;
} Record;

void init_data_structures(int arraySize, int minValue, int maxValue, int* offsets, int* keys, Record* records, size_t* recordsCount) {
    *offsets = malloc(arraySize * sizeof(long));
    if (!*offsets) {
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(arraySize * sizeof(int));
    if (!*keys) {
        free(*offsets);
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    *recordsCount = malloc(sizeof(size_t));
    if (!*recordsCount) {
        free(*keys);
        free(*offsets);
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    *records = malloc(arraySize * sizeof(Record));
    if (!*records) {
        free(*keys);
        free(*offsets);
        free(*recordsCount);
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    size_t i;
    for (i = 0; i < arraySize; ++i) {
        (*keys)[i] = rand() % (maxValue - minValue + 1) + minValue;
        (*offsets)[i] = i;
        (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    *recordsCount = arraySize;

    // Logging mechanism integration
    #if LOGGING_ENABLED
    int averageValue = 0;
    for (i = 0; i < arraySize; ++i) {
        averageValue += (*records)[i].value;
    }
    averageValue /= arraySize;
    logTotalRecords(*recordsCount);
    logAverageValue(averageValue);
    #endif

    // Deallocation mechanism
    free_data_structures(offsets, keys, records, recordsCount);
}

void free_data_structures(int* offsets, int* keys, Record* records, size_t* recordsCount) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (recordsCount) free(recordsCount);
    if (records) free(records);
}
