    int opt, ch, csv = 0, manpage = 0, show_progress = 1;
    const char *input_file = NULL;
    const char *output_file = NULL;
    FILE *log_fp = NULL;

    while ((opt = getopt(argc, argv, "hVm:o:cs")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return 0;
            case 'V':
                printf("Version: v1.0\n");
