    if (regcomp(&phone_rx, "(\\d{3}-\\d{3}-\\d{4})|(\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}|\\(?\\d{4}\\)?[-. ]?\\d{4}|\\d{10})", REG_EXTENDED | REG_NEWLINE)) {
        perror("Error compiling regular expression");
        return -1;
    }

    if (manpage) {
        // Print manpage here
    }

    pthread_mutex_init(&log_mutex, NULL);
    total_lines = 0;

    if (!input_file) {
        char buf[MAX_LINE_LEN];
        while (fgets(buf, sizeof(buf), stdin)) {
            process_line((void *)buf);
        }
    } else {
        FILE *fp = input_file == "-" ? stdin : fopen(input_file, "r");
        if (!fp) {
            perror("Error opening file");
            return -1;
        }

        char buf[MAX_LINE_LEN];
        while (fgets(buf, sizeof(buf), fp)) {
            process_line((void *)buf);
        }

        if (fclose(fp)) {
            perror("Error closing file");
            return -1;
        }
    }

    regfree(&email_rx);
    regfree(&phone_rx);
    pthread_mutex_destroy(&log_mutex);

    if (output_file) {
