void *process_line(void *arg) {
    char *line = (char *)arg;
    size_t line_len = strlen(line);
    regmatch_t email_match[1];
    regmatch_t phone_match[1];
    regsearch(&email_rx, line, email_match, 0, 0);
    regsearch(&phone_rx, line, phone_match, 0, 0);

    total_lines++;

    if (regerrors(1) || !email_match[0].rm_eooff || !phone_match[0].rm_eooff) {
        return NULL;
    }

    // Process matched patterns here

    pthread_mutex_lock(&log_mutex);
    log_statistics("Processed a line.");
    pthread_mutex_unlock(&log_mutex);

    return NULL;
}

void print_usage() {
    printf("Usage: program [options] [input_file]\n");
    printf("\t-h\tDisplay this help message and exit.\n");
    printf("\t-V\tPrint version information and exit.\n");
    printf("\t-m\tDisplay the manual page and exit.\n");
    printf("\t-o output_file\tOutput file for the processed data (defaults to stdout).\n");
    printf("\t-c\tCompress the output using zlib before writing it to the specified output file.\n");
    printf("\t-s\tDisable progress bar.\n");
}

void log_statistics(const char *message) {
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_fp, "%s\n", message);
    fclose(log_fp);
}
