typedef struct {
    int *arr;
    size_t capacity;
    size_t count;
} IntArray;

IntArray* create_int_array() {
    return calloc(1, sizeof(IntArray));
}

void resize_int_array(IntArray *arr) {
    arr->capacity *= 2;
    arr->arr = realloc(arr->arr, arr->capacity * sizeof(int));
}

bool is_integer(char c) {
    return (c >= '0' && c <= '9') || (c == '-');
}

bool parse_integer(const char **str, int *value) {
    bool negative = false;
    uintmax_t num = 0;

    if (**str == '-') {
        negative = true;
        ++*str;
    }

    while (is_integer(**str)) {
        num = num * 10 + (**str - '0');
        ++*str;
    }

    if (!negative)
        *value = num;
    else
        *value = -num;

    return **str == '\0';
}

void free_int_array(IntArray *arr) {
    free(arr->arr);
    free(arr);
}

int find_max(const IntArray *arr) {
    int max = INT32_MIN;

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->arr[i] > max)
            max = arr->arr[i];
    }

    return max;
}

void read_and_process(IntArray *arr) {
    char input[1024];
    int value;

    printf("Enter integers (or 'q' to quit):\n");

    while (true) {
        if (!fgets(input, sizeof(input), stdin)) break;

        input[strlen(input) - 1] = '\0'; // remove trailing newline

        if (strcmp(input, "q") == 0) return;

        if (!parse_integer(&input, &value)) continue;

        if (arr->count >= arr->capacity) resize_int_array(arr);
        arr->arr[arr->count++] = value;
    }
}

void largest_integer(const char *program_name) {
    IntArray *arr = create_int_array();
    read_and_process(arr);

    printf("The largest integer entered is: %d\n", find_max(arr));

    free_int_array(arr);
}
