#include <stdarg.h>
#include <stdio.h>
#include <time.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_LOG_ENTRIES 10000
#define LOG_FILE_ROTATION_SIZE (1048576) // 1MB

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char message[4096];
};

void log_rotate() {
    char new_log_path[sizeof(LOG_FILE) + 16]; // 16 for extension and slash
    snprintf(new_log_path, sizeof(new_log_path), "%s.%ld", LOG_FILE, (long)time(NULL));
    rename(LOG_FILE, new_log_path);
}

void log_flush() {
    log_rotate();
    FILE *file = fopen(LOG_FILE, "w");
    if (!file) return;

    struct LogEntry* entries = log_entries;
    struct LogEntry* current = log_entries;
    int index = 0;
    while (index < MAX_LOG_ENTRIES && current != NULL) {
        fwrite(current, sizeof(struct LogEntry), 1, file);
        current = current->next;
        index++;
    }

    free(log_entries);
    log_entries = entries;
    fclose(file);
}

struct LogEntry* log_entries = NULL;
char LOG_FILE[] = "error.log";

void log(LogLevel level, const char *format, ...) {
    time_t now = time(NULL);
    struct tm local_time;
    localtime_r(&now, &local_time);

    if (log_entries == NULL || MAX_LOG_ENTRIES - 1 <= index) {
        log_flush();
    }

    va_list args;
    struct LogEntry *entry = malloc(sizeof(struct LogEntry));
    entry->timestamp = now;
    entry->level = level;

    va_start(args, format);
    vsnprintf(entry->message, sizeof(entry->message), format, args);
    va_end(args);

    if (log_entries) {
        struct LogEntry* last = log_entries + MAX_LOG_ENTRIES - 1;
        if (last->timestamp <= now - 60 * 60 * 24 * 7) { // keep a week of logs at max
            free(log_entries);
            log_entries = entry;
            log_entries->next = NULL;
        } else {
            last->next = entry;
            entry->next = NULL;
        }
    } else {
        log_entries = entry;
    }
}
