#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>

#define QUEUE_ITEM_MAX 10

typedef struct {
    void* item;
    struct node* next;
} node;

struct queue {
    node* head;
    node* tail;
    sem_t full, empty;
    int capacity;
    int size;
};

void initQueue(struct queue* q, int capacity) {
    q->head = q->tail = NULL;
    q->capacity = capacity;
    q->size = 0;
    sem_init(&q->full, 0, 0);
    sem_init(&q->empty, 0, capacity);
}

void enqueue(struct queue* q, void* item) {
    node* newNode = malloc(sizeof(node));
    if (!newNode) return;

    newNode->item = item;
    newNode->next = NULL;

    sem_wait(&q->empty);
    if (q->tail) q->tail->next = newNode;
    else q->head = newNode;
    q->tail = newNode;

    if (!++(q->size)) sem_post(&q->full);
}

void* dequeue(struct queue* q) {
    void* item;
    node* temp;

    sem_wait(&q->full);
    if (!q->head) return NULL;

    item = q->head->item;
    temp = q->head;
    q->head = q->head->next;

    if (!(--(q->size))) sem_post(&q->empty);

    if (!q->head) q->tail = NULL;
    free(temp);
    return item;
}

bool isEmpty(struct queue* q) {
    return sem_trywait(&q->empty) == 0;
}

bool isFull(struct queue* q) {
    return sem_trywait(&q->full) == 0;
}

void destroyQueue(struct queue* q) {
    while (dequeue(q)) {}
    free(q->head);
    sem_destroy(&q->empty);
    sem_destroy(&q->full);
    free(q);
}
