#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/functional/hash.hpp>
#include <boost/foreach.hpp>
#include <boost/interprocess/managed_shared_memory.hpp>
#include <boost/make_shared.hpp>
#include <boost/random/uniform_int_distribution.hpp>
#include <chrono>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <thread>

namespace bs = boost::asio;
namespace bi = boost::interprocess;

// Test double for InterfaceTable class
class MockInterfaceTable {
public:
    std::string FindVmUuidFromMetadataIp(const std::string& ip) {
        static thread_local bool success = rand() % 3 == 0; // Set probability of success for each call
        if (success) {
            return "mock-uuid";
        } else {
            return "";
        }
    }
};

// Cache class
class Cache {
public:
    void Insert(const std::string& key, const std::string& value) {
        auto cached_value = std::make_shared<std::pair<std::string, time_t>>(value, std::time(nullptr));
        cache_.insert_or_assign(boost::hash<std::string>{}(key), cached_value);
    }

    const std::shared_ptr<std::pair<std::string, time_t>> Find(const std::string& key) {
        auto it = cache_.find(boost::hash<std::string>{}(key));
        if (it != cache_.end()) {
            auto current_time = std::time(nullptr);
            if ((current_time - it->second->second) < timeout_) {
                return it->second;
            } else {
                it->second.reset(); // Evict expired value
            }
        }
        return {};
    }

private:
    bi::managed_shared_memory<bi::fixed_sized_segment> cache_;
    std::chrono::seconds timeout_{10}; // Set timeout for cache in seconds
};

// Sandesh client class
class SandeshClient {
public:
    explicit SandeshClient(MockInterfaceTable& interfaceTable, Cache& cache, const std::string& server_url)
        : interfaceTable_(interfaceTable), cache_(cache), server_url_(server_url), io_service_(bs::io_service()),
          request_counter_(0), proxy_sessions_(0), internal_errors_(0), cache_hits_(0), cache_misses_(0) {}

    void Start() {
        bs::strand<bs::io_service> strand(io_service_);
        auto self = shared_from_this();
        for (size_t i = 0; i < num_threads_; ++i) {
            threads_.emplace_back([this, self]() { Run(); });
        }
        io_service_.run();
    }

private:
    void Run() {
        while (true) {
            bs::io_service::work work(io_service_);
            io_service_.post(work);
            bs::io_service::work::execute(strand);
        }
    }

    void SendRequest(const std::string& unique_id) {
        ++request_counter_;
        auto it = cache_.Find(unique_id);
        if (it != nullptr && std::chrono::system_clock::now() - it->second > std::chrono::seconds(timeout_)) {
            cache_.Insert(unique_id, SendGetRequest(unique_id));
        } else if (it == nullptr || it->second == nullptr) {
            cache_.Insert(unique_id, SendGetRequest(unique_id));
        }
    }

    std::string SendGetRequest(const std::string& unique_id) {
        ++proxy_sessions_;
        // Simulate slow server response with sleep call
        std::this_thread::sleep_for(std::chrono::seconds(rand() % 5));

        if (internal_errors_) {
            throw bs::system_error(boost::asio::error::make_errc(boost::asio::error::host_unreachable));
        }

        ++cache_hits_; // Assume cache hit when no exception is thrown

        std::cout << "Request #" << request_counter_ << ": Sent GET to " << server_url_ << ", unique_id: " << unique_id
                  << ", proxy_session: " << ++proxy_sessions_ << ", Cache hit/miss: " << (it != nullptr ? "hit" : "miss")
                  << ", Timestamp: " << std::chrono::system_clock::now().time_since_epoch().count() << std::endl;

        return "Response for request #" + std::to_string(request_counter_);
    }

    MockInterfaceTable& interfaceTable_;
    Cache& cache_;
    const std::string server_url_;
    bs::io_service io_service_;
    size_t request_counter_{0};
    size_t proxy_sessions_{0};
    size_t internal_errors_{0};
    size_t cache_hits_{0};
    size_t cache_misses_{0};
    std::vector<std::thread> threads_;
    unsigned int num_threads_{std::thread::hardware_concurrency() * 2}; // Increase concurrency for high volume of requests
};

int main(int argc, char* argv[]) {
    MockInterfaceTable mock_interface;
    Cache cache;
    SandeshClient client(mock_interface, cache, "https://example.com");
    client.Start();

    std::ofstream logfile("sandesh_client_log.txt", std::ios::out | std::ios::app);
    logfile << "Number of requests: " << client.request_counter_ << '\n'
            << "Number of proxy sessions: " << client.proxy_sessions_ << '\n'
            << "Number of internal errors: " << client.internal_errors_ << '\n'
            << "Number of cache hits: " << client.cache_hits_ << '\n'
            << "Number of cache misses: " << client.cache_misses_ << std::endl;
    return 0;
}
```

