namespace Logging {
    enum class Level { DEBUG, INFO, WARNING, ERROR, CRITICAL };
    std::ofstream logFiles[static_cast<int>(Level::CRITICAL) + 1];
    static std::recursive_mutex mtx;
    static int currentLogLevel = static_cast<int>(Level::INFO);

    class Logger {
        public:
            Logger() {
                for (auto& file : logFiles) {
                    file.open(std::string("log.") + std::to_string(static_cast<int>(type)) + ".txt");
                }
            }

            ~Logger() {
                for (auto& file : logFiles) {
                    if (file.is_open()) {
                        file << '\n';
                        file.flush();
                        file.close();
                    }
                }
            }

            static void setLogLevel(int level) { currentLogLevel = level; }

            static void log(Level level, const std::string& msg) {
                if (level <= currentLogLevel) {
                    std::lock_guard<std::recursive_mutex> lock(mtx);
                    auto timestamp = std::chrono::system_clock::now().time_since_epoch().count();
                    auto ts_s = std::chrono::duration_cast<std::chrono::seconds>(timestamp).count();
                    auto ts_ms = std::chrono::duration_cast<std::chrono::milliseconds>(timestamp).count();

                    std::stringstream ss;
                    ss << "[" << ts_s * 1000 + ts_ms << "] [";

                    switch (level) {
                        case Level::DEBUG:   ss << "DEBUG] "; break;
                        case Level::INFO:    ss << "INFO] "; break;
                        case Level::WARNING: ss << "WARN] "; break;
                        case Level::ERROR:   ss << "ERROR] "; break;
                        case Level::CRITICAL: ss << "CRITICAL] "; break;
                    }

                    ss << msg << '\n';
                    logFiles[level] << ss.str();
                }
            }
    };
}

int main() {
    Logging::Logger logger;
    // Use the Logger object to write logs at different levels:
    Logging::Logger::log(Logging::Level::DEBUG, "This is a debug log.");
    Logging::Logger::log(Logging::Level::INFO, "This is an info log.");
    Logging::Logger::log(Logging::Level::WARNING, "This is a warning log.");
    // Change the log level and write new logs:
    Logging::Logger::setLogLevel(static_cast<int>(Logging::Level::INFO));
    Logging::Logger::log(Logging::Level::DEBUG, "This debug log will not be visible due to the changed log level.");
    Logging::Logger::log(Logging::Level::ERROR, "This error log should still be visible because it's above the current log level.");

    return 0;
}
```

