public IDataReader OptimizeQueryExecutionPlan(List<object> values, SqlConnection connection, string sqlCommand, int loadThreshold)
{
    var server = new Server(new ServerConnection(connection));
    var db = server.Databases[connection.Database];

    // Analyze current database load (You might use a custom method here)
    int currentLoad = GetCurrentDatabaseLoad(db);

    if (currentLoad > loadThreshold)
    {
        // Query is likely to benefit from parameter sniffing, create a parameterized SQL command
        var cmd = new SqlCommand(sqlCommand, connection);
        cmd.Parameters.AddRange(values.ToArray());
        return cmd.ExecuteReader();
    }
    else
    {
        // Query is more likely to benefit from recompilation, remove parameters and create non-parameterized SQL command
        string parameterlessSqlCommand = sqlCommand.Replace("@", "");
        var cmd = new SqlCommand(parameterlessSqlCommand, connection);
        return cmd.ExecuteReader();
    }
}
