public class ConfigSettings
{
    public string DatabaseConnectionString { get; set; }
    public string ApiEndpoint { get; set; }
    public int CachingIntervalInSeconds { get; set; }
}

public static class ConfigLoader
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();
    private const string ConfigFileName = "appconfig.json";

    public static ConfigSettings Load()
    {
        try
        {
            string json = File.ReadAllText(ConfigFileName);
            return JsonConvert.DeserializeObject<ConfigSettings>(json);
        }
        catch (Exception ex)
        {
            logger.Error($"Failed to load configuration settings: {ex}");
            throw;
        }
    }

    public static void Validate(ConfigSettings config)
    {
        if (string.IsNullOrEmpty(config.DatabaseConnectionString))
        {
            logger.Error("Configuration setting 'DatabaseConnectionString' is empty.");
            throw new ArgumentException("DatabaseConnectionString must be provided.");
        }

        if (string.IsNullOrEmpty(config.ApiEndpoint))
        {
            logger.Error("Configuration setting 'ApiEndpoint' is empty.");
            throw new ArgumentException("ApiEndpoint must be provided.");
        }

        if (config.CachingIntervalInSeconds <= 0)
        {
            logger.Error($"Configuration setting 'CachingIntervalInSeconds' must be greater than zero. Found: {config.CachingIntervalInSeconds}");
            throw new ArgumentOutOfRangeException("CachingIntervalInSeconds", "Value must be greater than zero.");
        }
    }
}

public class Program
{
    public static void Main()
    {
        var config = ConfigLoader.Load();
        ConfigLoader.Validate(config);
        // Use the loaded configuration settings
        Console.WriteLine($"Successfully loaded configuration: DatabaseConnectionString - {config.DatabaseConnectionString}, ApiEndpoint - {config.ApiEndpoint}, CachingIntervalInSeconds - {config.CachingIntervalInSeconds}");
    }
}
