const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const mongoose = require('mongoose');
const UserProfile = mongoose.model('UserProfile');

// Update user profile
router.put('/:id', async (req, res) => {
    try {
        const user = await UserProfile.findOneAndUpdate(
            { _id: req.params.id },
            req.body,
            { new: true, runValidators: true }
        );
        res.json(user);
    } catch (err) {
        res.status(500).send(err);
    }
});

// Delete user profile
router.delete('/:id', async (req, res) => {
    try {
        const user = await UserProfile.findByIdAndDelete(req.params.id);
        if (!user) return res.status(404).send('User not found');

        // Archive profile instead of deleting
        user.isArchived = true;
        await user.save();

        res.json({ message: 'Profile archived' });
    } catch (err) {
        res.status(500).send(err);
    }
});

// Retrieve latest version of profile
router.get('/:id', async (req, res) => {
    try {
        const user = await UserProfile.findById(req.params.id).sort({ updatedAt: -1 });
        if (!user) return res.status(404).send('User not found');

        // Check if profile is archived and not accessible
        if (user.isArchived) return res.status(403).send('Profile is currently archived');

        res.json(user);
    } catch (err) {
        res.status(500).send(err);
    }
});

// Restore archived profile to active state
router.put('/:id/restore', async (req, res) => {
    try {
        const user = await UserProfile.findByIdAndUpdate(
            req.params.id,
            { isArchived: false },
            { new: true }
        );
        if (!user) return res.status(404).send('User not found');

        res.json({ message: 'Profile restored' });
    } catch (err) {
        res.status(500).send(err);
    }
});

// Middleware for logging and auditing
function logAudit(req, res, next) {
    const action = req.method; // 'create', 'update', 'delete', 'restore'
    const userId = req.user._id;
    const profileId = req.params.id || null;

    const auditLog = new AuditLog({
        userId,
        action,
        resourceId: profileId,
        ipAddress: req.ip,
        userAgent: req.get('User-Agent'),
    });

    auditLog.save();

    next();
}

router.use('/', logAudit);

module.exports = router;
