using System.Diagnostics;

public class XPathElementFinder
{
    public static IEnumerable<XElement> FindElementsByNamespace(string xml, string namespaceUri, string localName)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            using (var reader = XmlReader.Create(new StringReader(xml)))
            {
                var element = XElement.Load(reader);
                var xpathExpression = $"{{{namespaceUri}}}{localName}";
                Debug.WriteLine($"Processing document: {Path.GetFileName(xml)}");
                Debug.WriteLine($"Searching for elements with name: {xpathExpression}");

                using (var xpathReader = XPathDocument.Load(reader).CreateNavigator())
                {
                    var nodeSet = xpathReader.Select(xpathExpression);

                    return FromXPathNodeIterator(nodeSet, element);
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Error while processing XML: {ex.Message}");
            throw;
        }
        finally
        {
            Debug.WriteLine($"Time taken to process XML: {stopwatch.ElapsedMilliseconds} milliseconds");
        }
    }

    private static IEnumerable<XElement> FromXPathNodeIterator(IEnumerator nodeIterator, XElement root)
    {
        while (nodeIterator.MoveNext())
        {
            if (nodeIterator.Current is XPathNavigator nav)
            {
                yield return XElement.ReadFrom(new XmlReader() { XmlResolver = null, NameTable = root.NameTable });
            }
        }
    }
}
