```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.stream.Collectors;

public class MD5Hasher {

 private static final int BATCH_SIZE = 100;

 public List<String> hashStrings(List<String> inputStrings) {
 if (inputStrings.size() > BATCH_SIZE) {
 splitAndHash(inputStrings);
 } else {
 return hashBatch(inputStrings);
 }
 }

 private void splitAndHash(List<String> inputStrings) {
 ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
 ConcurrentLinkedQueue<Future<List<String>>> resultsQueue = new ConcurrentLinkedQueue<>();
 int batchSize = Math.min(BATCH_SIZE, inputStrings.size());
 for (int i = 0; i < inputStrings.size(); i += batchSize) {
 int end = Math.min(i + batchSize, inputStrings.size());
 resultsQueue.add(executor.submit(() -> hashBatch(inputStrings.subList(i, end))));
 }

 List<String> finalResults = new ArrayList<>();
 while (!resultsQueue.isEmpty()) {
 Future<List<String>> resultFuture = resultsQueue.poll();
 try {
 List<String> batchResults = resultFuture.get();
 finalResults.addAll(batchResults);
 } catch (InterruptedException | ExecutionException e) {
 e.printStackTrace();
 }
 }
 executor.shutdown();
 while (!executor.isTerminated()) {}
 return finalResults;
 }

 private List<String> hashBatch(List<String> inputStrings) {
 List<String> processedStrings = inputStrings.stream()
 .map(this::processString)
 .collect(Collectors.toList());
 return processedStrings.stream()
 .map(s -> md5(s))
 .collect(Collectors.toList());
 }

 private String processString(String s) {
 return s.trim().replaceAll("[^A-Za-z0-9]", "_").toUpperCase();
 }

 private BigInteger md5(String str) {
 try {
 MessageDigest digest = MessageDigest.getInstance("MD5");
 byte[] messageDigest = digest.digest(str.getBytes());
 BigInteger no = new BigInteger(1, messageDigest);
 return no;
 } catch (NoSuchAlgorithmException e) {
 throw new RuntimeException(e);
 }
 }
}
```

In this code:

- The `hashStrings()` method takes a list of strings as input and processes them in batches if the size exceeds 100. If not, it directly processes the given batch.
- The `splitAndHash()` method is responsible for splitting large lists into smaller batches and processing them concurrently using an ExecutorService. It ensures thread safety by shutting down the executor after all tasks have been processed.
- The `hashBatch()` method performs the following transformations on each string in a given batch: trimming whitespace, converting to uppercase, and replacing non-alphanumeric characters with underscores. Then it calculates the MD5 hash of the processed strings using the `md5()` helper method.
- The `processString()` method performs the required transformations on a given string.
- The `md5()` method takes a string as input, converts it to bytes, and then calculates its MD5 hash using MessageDigest. It throws a RuntimeException if there's no such algorithm available.']

