const { setTimeout } = require('timers/promises');

async function runTests(label, modulePath, f) {
  try {
    const module = require(modulePath); // Load the module
    console.log(`Testing ${chalk.bold(modulePath)}:`);

    let passed = 0;
    let failed = 0;
    let total = 0;

    blueslip.reset(); // Reset the mocking library

    for (let testCase of Object.keys(f)) {
      total++;
      console.log(`\nRunning test case '${testCase}':`);

      const startTime = Date.now();
      const promise = f[testCase](); // Run the test case

      try {
        const result = await promise;
        if (result) passed++;
        else failed++;
      } catch (error) {
        console.log(`\nTest case '${testCase}' failed:\n`, error);
        failed++;
      }

      // Set a timeout for each test case
      const timeout = 10 * 1000; // 10 seconds
      await promise.finally(() => {
        if (Date.now() - startTime > timeout) {
          console.warn(`Test case '${testCase}' exceeded the ${timeout}ms timeout.\n`);
        }
      });
    }

    console.log(`\nPassed: ${passed}, Failed: ${failed}, Total: ${total}`);
  } catch (error) {
    console.log(chalk.red(`Error while loading or testing module '${modulePath}':`), error);
  }
}
