function dynamicSelect(selector, customAttribute, callback) {
  const observer = new MutationObserver((mutationsList, observer) => {
    mutationsList.forEach((mutation) => {
      if (mutation.addedNodes.length > 0) {
        mutation.addedNodes.forEach(node => {
          if (node.nodeType === Node.ELEMENT_NODE) {
            const matchesCSS = document.querySelectorAll(selector, node).length > 0;
            const hasCustomAttr = node.getAttribute(customAttribute) !== null;

            if (matchesCSS && hasCustomAttr) {
              callback(node);
            }

            if (node.hasAttributes && node.hasAttributes()) {
              dynamicSelect(selector, customAttribute, callback, node);
            }
          }
        });
      }
    });
  });

  observer.observe(document.body, { childList: true, subtree: true });

  requestAnimationFrame(() => {
    const elements = document.querySelectorAll(selector);
    elements.forEach((element) => {
      if (element.getAttribute(customAttribute) !== null) {
        callback(element);
      }
    });

    if (window.ReactVirtualized) {
      Object.keys(window.ReactVirtualized).forEach(key => {
        const List = window[key].List;
        const Grid = window[key].Grid;

        const listInstances = document.querySelectorAll(`${key} ${selector}`);
        listInstances.forEach((instance) => {
          if (instance.getElementsByTagName('ul')[0]) {
            const children = instance.getElementsByTagName('li');
            Array.from(children).forEach((child) => {
              dynamicSelect(selector, customAttribute, callback, child);
            });
          }
        });
      });
    } else if (window._vue && window._Vue) {
      const vueInstances = document.querySelectorAll(`[is="vuejs"] ${selector}`);
      vueInstances.forEach((instance) => {
        instance.update();
        instance.$el.querySelectorAll(selector).forEach((child) => {
          dynamicSelect(selector, customAttribute, callback, child);
        });
      });
    }
  });
}
