use reqwest::Client;
use reqwest::header::{HeaderMap, UserAgent};
use std::sync::atomic::AtomicUsize;
use std::time::Duration;
use tokio::sync::RwLock;
use log::*;

type Response = reqwest::Response;

struct RateLimiter {
    burst: u64,
    sustained: f64,
    counter: RwLock<AtomicUsize>,
    timer: std::time::Instant,
}

impl RateLimiter {
    fn new(burst: u64, sustained: f64) -> Self {
        Self {
            burst,
            sustained,
            counter: RwLock::new(AtomicUsize::new(0)),
            timer: std::time::Instant::now(),
        }
    }

    async fn acquire(&self) {
        let elapsed = self.timer.elapsed().as_secs_f64();
        if elapsed >= 1.0 / self.sustained {
            *self.counter.write().await += 1;
            self.timer.set_time(std::time::Instant::now());
        }

        if *self.counter.read().await < self.burst as usize {
            return true;
        }

        let sleep_duration = std::time::Duration::from_secs_f64((1.0 / self.sustained - elapsed).max(0.0));
        tokio::time::sleep(sleep_duration).await;

        *self.counter.write().await += 1;
        true
    }
}

fn create_client(disable_cert_validation: bool) -> Client {
    let client = reqwest::Client::builder()
        .user_agent(UserAgent::new2("my-app", "1.0.0"))
        .build()
        .unwrap();

    if disable_cert_validation {
        // Set up custom TLS config to disable certificate validation
        let mut tls = client.get_mut().borrow_mut().tls_connector();
        tls.set_native_roots(Some(vec![]));
    }

    client
}

async fn create_request_builder(base_url: &str, rate_limiter: RateLimiter, max_redirects: u32) -> reqwest::RequestBuilder {
    let mut builder = create_client(false).get(base_url);

    // Set custom headers as needed
    let mut headers = HeaderMap::new();
    // ...

    builder.headers(headers)
        .redirect(reqwest::redirect::Policy::max(max_redirects))
        .timeout_some(Duration::from_secs(30))
        .on_response(|res| {
            let status = res.status();
            if !status.is_success() && (status >= 500 && status <= 599) {
                // Log the error and retry with exponential backoff up to 5 attempts
                if let Ok(mut rl) = rate_limiter.acquire().await {
                    if rl {
                        // Retry after backoff delay
                        let delay = Duration::from_secs(1 << (5 - rl as u32));
                        tokio::time::sleep(delay).await;

                        // Recursively call create_request_builder and send the request again
                        create_request_builder(base_url, rate_limiter.clone(), max_redirects)
                            .send()
                            .await
                            .unwrap()
                    } else {
                        // Log the error and give up after 5 attempts
                        error!("Failed to send request with status {}", status);
                        res
                    }
                } else {
                    // Rate limiting exceeded, log error and return current response
                    error!("Rate limiting exceeded");
                    res
                }
            } else {
                // Log the success or informational responses
                trace!("Successfully sent request with status {}", status);
                res
            }
        })
}
