['```php
function updateUserProfiles(array $userIds, array $updates) {
    $successReports = [];
    $log = [];

    $conn = new PDO('mysql:host=localhost;dbname=mydb', 'username', 'password');
    $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    foreach ($userIds as $userId) {
        if (!array_key_exists($userId, $updates)) continue;

        // Start transaction to handle concurrent updates gracefully
        $conn->beginTransaction();

        try {
            $stmt = $conn->prepare('SELECT * FROM users WHERE id = ?');
            $stmt->execute([$userId]);
            $user = $stmt->fetch(PDO::FETCH_ASSOC);

            if (!$user) throw new Exception("User with ID {$userId} not found.");

            // Validate input
            foreach ($updates[$userId] as $field => $value) {
                if (!in_array($field, ['firstname', 'lastname', 'email'])) throw new Exception("Invalid field for update: {$field}.");
                if (!is_string($value)) throw new Exception("Invalid data type for field: {$field}. Expected string.");
            }

            // Update user profile
            $stmt = $conn->prepare('UPDATE users SET firstname = ?, lastname = ?, email = ? WHERE id = ?');
            $stmt->execute(array_merge([$updates[$userId]['firstname'], $updates[$userId]['lastname'], $updates[$userId]['email']], [$userId]));

            // Log update attempt
            $log[] = "User ID: {$userId}, Firstname: {$updates[$userId]['firstname']}, Lastname: {$updates[$userId]['lastname']}, Email: {$updates[$userId]['email']}";

            // Commit transaction if update was successful
            $conn->commit();
            $successReports[] = "User ID: {$userId}, Successfully updated.";
        } catch (Exception $e) {
            // Rollback transaction and log error
            $conn->rollback();
            $log[] = "Error: {$e->getMessage()}";
        }
    }

    // Log all update attempts for auditing purposes
    file_put_content('update_log.txt', implode("\n", $log), FILE_APPEND);

    return array_merge($successReports, array_fill(count($successReports), 1, "Failed updates due to database constraints or invalid input."));
}
