<?php
namespace Utilities;

class Security {
    private const CHARACTER_SET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    private const ALLOWED_ALGORITHMS = ['bcrypt', 'argon2id'];
    private $charSet;
    private $pattern;
    private $algorithm;
    private $workFactor;

    public function __construct($charSet = self::CHARACTER_SET, $pattern = '/.{6,32}/', $algorithm = 'bcrypt', $workFactor = 10) {
        $this->charSet = strlen($charSet) < 64 ? $charSet : strtr(substr($charSet, 0, 64), ' ', self::CHARACTER_SET);
        $this->pattern = $pattern;
        $this->algorithm = in_array($algorithm, self::ALLOWED_ALGORITHMS) ? $algorithm : 'bcrypt';
        $this->workFactor = is_numeric($workFactor) && $workFactor >= 1 ? $workFactor : 10;
    }

    public function generateRandomString($length = 32): string {
        $randomString = '';
        $maxAttempts = 10000;
        do {
            $randomChars = array_map(function () use ($this->charSet) { return $this->charSet[rand(0, strlen($this->charSet)-1)]; }, range(0, $length-1));
            shuffle($randomChars);
            $randomString = implode('', $randomChars);
        } while (!preg_match($this->pattern, $randomString) && --$maxAttempts > 0);
        return $randomString;
    }

    public function hashPassword($plainText): string {
        return password_hash($plainText, $this->algorithm, ['cost' => $this->workFactor]);
    }

    public function verifyHash($hashedData, $plainText): bool {
        return password_verify($plainText, $hashedData);
    }
}
```

