#include <stdlib.h>
#include <stdbool.h>

typedef struct FSA {
    int start;
    int num_states;
    int **transition_table;
} FSA;

// Function to dynamically allocate a linked list of states for an FSA
struct state *extend_state_list(struct state *, const int, const int);
bool is_valid_transition(const int, const int, const int);

struct state* extend_fsa_states(struct state *current_list, const int *states, int num_states, FSA *fsa, int last_state, int max_size) {
    if (current_list == NULL || fsa == NULL) {
        return NULL;
    }

    // Validate the number of states and the start state
    if (num_states <= 0 || num_states > fsa->num_states || fsa->start < 0 || fsa->start >= fsa->num_states) {
        return NULL;
    }

    // Validate the input parameters against the transition table
    for (int i = 0; i < num_states; ++i) {
        if (!is_valid_transition(states[i], last_state, fsa->transition_table[states[i]][last_state])) {
            return NULL;
        }
    }

    // Create a new state to be the first in the extended list
    struct state *new_list = (struct state*) malloc(sizeof(struct state));
    if (new_list == NULL) {
        return NULL;
    }
    new_list->state = states[0];
    new_list->next = current_list;

    // Allocate memory for the rest of the extended list, ensuring it does not exceed max_size
    struct state *extended_list = extend_state_list(current_list, max_size - 1, num_states);
    if (extended_list == NULL) {
        free(new_list);
        return NULL;
    }

    // Initialize the last state in the extended list to point to the new list
    extended_list[max_size - 1]->next = new_list;

    return extended_list;
}

// Helper function to extend the linked list of states
struct state* extend_state_list(struct state *current, const int num_states, const int start_index) {
    if (current == NULL) {
        // If the current list is empty, allocate memory for the first node and return it
        struct state *new_node = (struct state*) malloc(sizeof(struct state));
        if (new_node == NULL) {
            return NULL;
        }
        new_node->state = start_index;
        new_node->next = NULL;

        return new_node;
    }

    // Iterate through the current list to find the last state, and extend it with more nodes as needed
    struct state *last = current;
    while (last->next != NULL) {
        last = last->next;
    }

    // Allocate memory for additional nodes and connect them to the last node in the list
    int num_to_allocate = num_states - 1 - (last - current);
    struct state *new_nodes = (struct state*) malloc(num_to_allocate * sizeof(struct state));
    if (new_nodes == NULL) {
        return NULL;
    }

    last->next = new_nodes;

    for (int i = 0; i < num_to_allocate; ++i) {
        new_nodes[i].state = start_index + i + 1;
        new_nodes[i].next = NULL;
    }

    return new_nodes;
}

// Helper function to check if a transition is valid according to the FSA's transition table
bool is_valid_transition(const int current, const int last, const int transition) {
    return transition == fsa->transition_table[current][last];
}
