['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

public class RandomValueGenerator
{
    private float _minFloat;
    private float _maxFloat;
    private int _minInt;
    private int _maxInt;
    private int _seed;

    public RandomValueGenerator(int minInt, int maxInt, float minFloat = 0, float maxFloat = 1)
    {
        if (minInt > maxInt)
            throw new ArgumentException("Minimum integer value must be smaller than the maximum.");

        if (maxFloat - minFloat < Constants.Epsilon)
            throw new ArgumentOutOfRangeException(nameof(minFloat), "The minimum and maximum float values are too close together.");

        _minInt = minInt;
        _maxInt = maxInt;
        _minFloat = minFloat;
        _maxFloat = maxFloat;
    }

    public void SetSeed(int seed) => _seed = seed;

    private Random _random;

    public float GetRandomFloat(bool inclusive)
    {
        if (_random == null || _seed > 0)
            _random = new Random(_seed);

        var randomValue = (float)_random.NextDouble();
        return inclusive ? _minFloat + (randomValue * (_maxFloat - _minFloat)) : _minFloat + (randomValue * (_maxFloat - _minFloat)) + (_maxFloat - _minFloat);
    }

    public int GetRandomInt(bool inclusive) => (int)(GetRandomFloat(inclusiveive) * (_maxInt - _minInt + 1)) + _minInt;

    public Vector3 GetRandomVector3() => new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());

    public Quaternion GetRandomQuaternion() => new Quaternion(GetRandomFloat(), GetRandomFloat(), GetRandomFloat(), GetRandomFloat());

    public override string ToString() => $"Range: {_minInt}-{_maxInt} ({_minFloat},{_maxFloat})";

    private static readonly float Constants.Epsilon = 0.01f;
}
```
