/**
 * Asynchronous Reduction Function
 * @param {Array<number>} arr - The array containing numbers to be reduced.
 * @param {Function} callback - The user-defined reduction operation (accepts two parameters, acc and value).
 * @param {number|undefined} initialValue - An optional initial value for the accumulator.
 */
async function asyncReduce(arr, callback, initialValue) {
  let accumulator = initialValue !== undefined ? initialValue : arr[0];

  try {
    for (let i = initialValue === undefined ? 1 : 0; i < arr.length; i++) {
      accumulator = await callback(accumulator, arr[i], i, arr);
    }

    return accumulator;
  } catch (error) {
    console.error(`Error during reduction: ${error.message}`);
    throw error;
  }
}

