int resource_bundle_load(const char *path, struct ResourceBundle **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    ResourceFormat format;
    char extension[5];
    strcpy(extension, strrchr(path, '.'));
    if (strcmp(extension, ".json") == 0) {
        format = JSON;
    } else if (strcmp(extension, ".xml") == 0) {
        format = XML;
    } else {
        printf("Unsupported file format: %s\n", path);
        fclose(file);
        return -1;
    }

    cJSON *root = NULL;
    xmlDocPtr doc = NULL;
    struct ResourceBundle *bundle_ptr = malloc(sizeof(struct ResourceBundle));
    if (!bundle_ptr) {
        perror("Failed to allocate memory for bundle");
        fclose(file);
        return -1;
    }

    bundle_ptr->format = format;
    pthread_mutex_init(&bundle_ptr->lock, NULL);
    bundle_ptr->item_count = 0;
    bundle_ptr->max_items = 0;
    bundle_ptr->items = NULL;

    if (format == JSON) {
        root = cJSON_Parse(fread(file, 1, INT_MAX, file), 0);
        if (!root || cJSON_IsInvalid(root)) {
            printf("Malformed JSON data\n");
            fclose(file);
            free(bundle_ptr);
            return -1;
