AES_KEY *aes_init(const unsigned char *key, const unsigned char *iv, int mode);
unsigned char* aes_encrypt(const unsigned char *data, size_t len, AES_KEY *key);
unsigned char* aes_decrypt(const unsigned char *data, size_t len, AES_KEY *key);

TIFFInfo processTIFFAndEncrypt(const char *file_path, const char *command) {
    TIFF *tif = open_tiff(file_path);
    TIFFInfo info;
    get_tiff_info(tif, &info);

    if (info.bits_per_sample != 1 && info.bits_per_sample != 2 &&
        info.bits_per_sample != 4 && info.bits_per_sample != 8 &&
        info.bits_per_sample != 16) {
        printf("Error: Unsupported bits per sample.\n");
        close_tiff(tif);
        exit(EXIT_FAILURE);
    }

    AES_KEY *key = NULL;
    unsigned char *cipher_data = NULL;

    if (strcasecmp(command, "encrypt") == 0) {
        const unsigned char *key_material = ... ; // your key material here
        const unsigned char *iv = ... ; // initialization vector here
        key = aes_init(key_material, iv, AES_MODE_CBC);
        cipher_data = aes_encrypt(TIFFGetData(tif), TIFFScanlineSize(tif), key);
    } else if (strcasecmp(command, "decrypt") == 0) {
        const unsigned char *key_material = ... ; // your key material here
        const unsigned char *iv = ... ; // initialization vector here
        key = aes_init(key_material, iv, AES_MODE_CBC);
        cipher_data = TIFFGetData(tif);
        cipher_data = aes_decrypt(cipher_data, TIFFScanlineSize(tif), key);
    } else {
        printf("Error: Unsupported command.\n");
        close_tiff(tif);
        exit(EXIT_FAILURE);
    }

    free(key); // deallocate memory after use
    TIFF *encrypted_tif = TIFCopy(tif, "EncryptedTIFF");
    TIFFSetField(encrypted_tif, TIFFTagSampleFormat, (long) (cipher_data[0] << 8 | cipher_data[1]));
    TIFFSetData(encrypted_tif, cipher_data, TIFFScanlineSize(tif));

    close_tiff(tif);
    return info;
}

TIFF* open_tiff(const char *file_path) {
    TIFF *tif = TIFFOpen(file_path, "r");
    if (!tif) {
        printf("Error: Failed to open the TIFF file.\n");
        exit(EXIT_FAILURE);
    }
    return tif;
}

void close_tiff(TIFF *tif) {
    if (tif) {
        TIFClose(tif);
    }
}

void get_tiff_info(TIFF *tif, TIFFInfo *info) {
    info->bits_per_sample = TIFFGetField(tif, TIFFTagBitspersample);
    info->sample_per_pixel = TIFFGetField(tif, TIFFTagSamplperpixel);
    info->photometric_interpretation = TIFFGetField(tif, TIFFTagPhotometricinterpretation);
    info->extra_samples = TIFFNumberOfDirectoryEntries(tif) - 3; // 3: ImageDescription, Make, Model
}

AES_KEY *aes_init(const unsigned char *key, const unsigned char *iv, int mode) {
    AES_KEY key_;
    AES_set_encrypt_key(key, 128, &key_);
    AES_KEY *result = malloc(sizeof(AES_KEY));
    memcpy(result, &key_, sizeof(AES_KEY));
    AES_set_iv(result, iv);
    return result;
}

unsigned char* aes_encrypt(const unsigned char *data, size_t len, AES_KEY *key) {
    unsigned char *encrypted_data = malloc(len);
    int encrypted_len = 0;
    AES_cbc_encrypt(data, encrypted_data, len, key, iv, AES_ENCRYPT);
    encrypted_len = strlen((const char *) encrypted_data);
    return encrypted_data;
}

unsigned char* aes_decrypt(const unsigned char *data, size_t len, AES_KEY *key) {
    unsigned char *decrypted_data = malloc(len);
    int decrypted_len = 0;
    AES_cbc_encrypt(data, decrypted_data, len, key, iv, AES_DECRYPT);
    decrypted_len = strlen((const char *) decrypted_data);
    return decrypted_data;
}
