char *rename_file(const char *input_filename, const char *version_string) {
    size_t base_name_len = strrchr(input_filename, '.') ? strlen(input_filename) - strrchr(input_filename, '.') - 1 : strlen(input_filename);
    size_t digits = (base_name_len > 5) ? base_name_len - 5 : 0;
    char base_name[256];
    char extension[9];
    strncpy(base_name, input_filename, (base_name_len > 255) ? 255 : base_name_len);
    base_name[base_name_len] = '\0';
    strncpy(extension, strchr(input_filename, '.') + 1, sizeof(extension));
    extension[sizeof(extension) - 1] = '\0';

    char new_filename[256];
    sprintf(new_filename, "%s.v%d%.3s%s", base_name, digits, version_string, extension);

    // Handle potential buffer overflows by ensuring the resulting filename does not exceed 255 characters
    if (strlen(new_filename) > 256) {
        new_filename[255] = '\0';
    }

    return strdup(new_filename);
}
