#include <openssl/sha.h>
#include <openssl/aes.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

typedef struct AESContext {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} AESContext;

unsigned int aes_init(AESContext *context, const char *password, size_t len) {
    if (len > 64) {
        return AES_ERR_PASSWORD_LENGTH;
    }

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, len);
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_Final(digest, &ctx);

    AES_set_encrypt_key(digest, 256, &context->key);
    randombytes_ex(context->iv, sizeof(context->iv), 0);

    return AES_ERR_NONE;
}

void aes_cleanup(AESContext *context) {
    memset(context->key.d, 0, sizeof(context->key.d));
    memset(context->iv, 0, sizeof(context->iv));
    AES_free_key(&context->key);
}

void* secure_memalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        abort(); // handle error gracefully as per your preference
    }
    memset(ptr, 0, size);
    return ptr;
}
