#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <getopt.h>
#include <libmagic.h>
#include <imagemagick/MagickWand.h>
#include <stdarg.h>
#include <stdbool.h>
#include <memory.h>
#include <regex.h>

#define THUMBNAIL_SIZE 100

typedef struct tagIMAGEDATA {
    MagickImage *image;
    char path[256];
} IMAGEDATA;

static int compareImages(const void *a, const void *b) {
    return strcmp((*(IMAGEDATA*)a)->path, *(*(IMAGEDATA*)b)->path);
}

static void generateThumbnail(IMAGEDATA *imgdata) {
    MagickBooleanType status;

    status = MagickReadImage(imgdata->image, imgdata->path);
    if (!status) {
        MagickErrorDialog("Cannot open image: %s\n", imgdata->path);
        return;
    }

    status = MagickThumbnailImage(imgdata->image, THUMBNAIL_SIZE, THUMBNAIL_SIZE);
    if (!status) {
        MagickErrorDialog("Cannot create thumbnail for image: %s\n", imgdata->path);
        return;
    }
}

static int readDirectory(const char *dirPath, const char *fileExt, IMAGEDATA *images, size_t imagesSize) {
    DIR *d;
    struct dirent *ent;
    struct stat st;
    char path[1024];
    regex_t re;
    regmatch_t match;

    regcomp(&re, fileExt, REG_EXTENDED);

    d = opendir(dirPath);
    if (d == NULL) {
        return 1;
    }

    while ((ent = readdir(d)) != NULL) {
        snprintf(path, sizeof(path), "%s/%s", dirPath, ent->d_name);

        if (stat(path, &st) == -1 || !S_ISREG(st.st_mode)) {
            continue;
        }

        if (regexec(&re, ent->d_name, 1, &match, 0) > 0) {
            IMAGEDATA *imageData = realloc(images, sizeof(IMAGEDATA) * (imagesSize + 1));
            if (!imageData) {
                closedir(d);
                return 1;
            }
            images = imageData;

            snprintf(images[imagesSize].path, sizeof(images[0].path), "%s", path);
            images[imagesSize++].image = MagickReadImageFromFile(path, "TrueColor");
        }
    }

    qsort(images, imagesSize, sizeof(IMAGEDATA), compareImages);

    closedir(d);
    regfree(&re);
    return 0;
}

static void generateReport(const char *templateFile, IMAGEDATA *images, size_t imagesSize) {
    FILE *fpTemplate, *fpReport;
    char template[1024], report[1024];
    char line[512];
    int i;

    fpTemplate = fopen(templateFile, "r");
    if (fpTemplate == NULL) {
        fprintf(stderr, "Cannot open template file: %s\n", templateFile);
        return;
    }

    fpReport = fopen("report.html", "w");
    if (fpReport == NULL) {
        fclose(fpTemplate);
        fprintf(stderr, "Cannot create report file\n");
        return;
    }

    while (fgets(line, sizeof(line), fpTemplate)) {
        snprintf(report, sizeof(report), line, images[0].image->columns, images[0].image->rows);
        for (i = 1; i < imagesSize; ++i) {
            generateThumbnail(&images[i]);
            snprintf(line, sizeof(line), "%s%s", report + strlen(report), line + strlen(line));
        }

        fputs(line, fpReport);
    }

    fclose(fpTemplate);
    fclose(fpReport);
}

int generateHTMLReport(const char *dirPath, const char *fileExt, const char *templateFile) {
    IMAGEDATA *images;
    size_t imagesSize = 0;

    if (readDirectory(dirPath, fileExt, images, imagesSize)) {
        free(images);
        return 1;
    }

    generateReport(templateFile, images, imagesSize);
    for (size_t i = 0; i < imagesSize; ++i) {
        MagickDestroyImage(&images[i].image);
    }
    free(images);

    return 0;
}
