#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE* log_file = stderr; // Set your own error log file here

typedef struct {
    pid_t pid;
    char command[256];
} Command;

void log_message(const char *format, ...) {
    va_list args;
    char timestamp[32];
    time_t now = time(NULL);
    struct tm* local = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);
    va_start(args, format);
    vfprintf(log_file, format, args);
    fprintf(log_file, " [PID: %d] ", getpid());
    fprintf(log_file, "[CID: %ld] ", pthread_self());
    fprintf(log_file, "\n");
    va_end(args);
}

int run_command_in_background(const char* command) {
    Command cmd = {0};
    int status;
    pid_t pid;

    strncpy(cmd.command, command, sizeof(cmd.command));

    if ((pid = fork()) < 0) {
        log_message("Failed to fork: %s\n", strerror(errno));
        return 0;
    }

    if (pid == 0) { // Child process
        setsid(); // Create a new session and disassociate from TTY
        execl("/bin/sh", "/bin/sh", "-c", command, NULL);
        log_message("Failed to execute command: %s\n", strerror(errno));
        _exit(127); // Exit with error code 127 if execl fails
    } else { // Parent process
        cmd.pid = pid;
        return 1;
    }

    pid_t wait_ret = waitpid(cmd.pid, &status, WNOHANG);
    if (wait_ret == -1 && errno != ECHILD) {
        log_message("Failed to wait for child: %s\n", strerror(errno));
        return 0;
    }
    return 1;
}

void run_command_concurrently(const char* command, void (*callback)(const char*, int)) {
    Command cmd = {0};
    int status;
    pid_t pid;

    strncpy(cmd.command, command, sizeof(cmd.command));

    if ((pid = fork()) < 0) {
        log_message("Failed to fork: %s\n", strerror(errno));
        return;
    }

    if (pid == 0) { // Child process
        setsid(); // Create a new session and disassociate from TTY
        execl("/bin/sh", "/bin/sh", "-c", command, NULL);
        log_message("Failed to execute command: %s\n", strerror(errno));
        _exit(127); // Exit with error code 127 if execl fails
    } else { // Parent process
        cmd.pid = pid;
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, callback, &cmd) != 0) {
            log_message("Failed to create thread: %s\n", strerror(errno));
        }
    }
}
```

