using System;
using System.IO;
using System.Diagnostics;
using System.Threading;
using System.Collections.Concurrent.SemaphoreSlim;
using Microsoft.Extensions.Logging;

public class WebsiteManager
{
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private readonly ILogger<WebsiteManager> _logger;

    public WebsiteManager(ILogger<WebsiteManager> logger)
    {
        _logger = logger;
    }

    public Website AddAndStartWebsite(string directoryPath, string siteName)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
            {
                _logger.LogError("Invalid directory path.");
                return null;
            }

            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                _logger.LogError($"Missing web.config file in '{directoryPath}'.");
                return null;
            }

            // Perform additional configuration checks or set up different web servers here...

            Website website = new Website { Name = siteName, DirectoryPath = directoryPath };

            _semaphore.Wait();
            try
            {
                var processStartInfo = new ProcessStartInfo
                {
                    FileName = Environment.GetEnvironmentVariable("WEBSERVER_EXECUTABLE"), // Replace with the appropriate executable for your environment or web server setup
                    Arguments = $"{directoryPath}",
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                var process = new Process { StartInfo = processStartInfo };
                if (!process.Start())
                {
                    _logger.LogError($"Failed to start website '{siteName}'.");
                    return null;
                }

                // Log the status of each operation for debugging and monitoring purposes...

                process.Exited += (sender, args) =>
                {
                    _semaphore.Release();
                };
            }
            catch (Exception ex)
            {
                _logger.LogError($"An error occurred while adding and starting website '{siteName}'. Error: {ex.Message}");
                return null;
            }

            _semaphore.Release();
            return website;
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while adding and starting website '{siteName}'. Error: {ex.Message}");
            return null;
        }
    }
}

public class Website
{
    public string Name { get; set; }
    public string DirectoryPath { get; set; }
}
