import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {
    private static final int MAX_RETRIES = 3;
    private static final long TIME_BETWEEN_ATTEMPTS = 1000L;
    private static final String LOGGING_SERVICE_URL = "your-logging-service-url";

    public void executeCommand(String command, String workingDirectory, String fileToDeletePath) {
        Path fileToDelete = Paths.get(workingDirectory + File.separator + fileToDeletePath);
        ScheduledExecutorService logger = Executors.newSingleThreadScheduledExecutor();

        // Attempt to delete the file up to MAX_RETRIES times with a delay of TIME_BETWEEN_ATTEMPTS between retries
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                Files.deleteIfExists(fileToDelete);
                break;
            } catch (Exception e) {
                if (i == MAX_RETRIES - 1) {
                    logResult("Failed to delete file: " + fileToDeletePath, false);
                }
            }
        }

        Process process;
        try {
            process = Runtime.getRuntime().exec(command, null, new File(workingDirectory));
        } catch (Exception e) {
            logResult("Failed to execute command: " + command, false);
            return;
        }

        BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String line;
        while ((line = stdOutput.readLine()) != null) {
            logResult("Command output: " + line, true);
        }

        while ((line = stdError.readLine()) != null) {
            logResult("Command error: " + line, false);
        }

        int exitCode = process.waitFor();
        logResult("Command exit code: " + exitCode, true);

        // Clean up any partially created files or resources
        cleanUp(process);
    }

    private void logResult(String message, boolean success) {
        logger.submit(() -> sendLog(message, success));
    }

    private void cleanUp(Process process) {
        try {
            process.destroy();
            process.getErrorStream().close();
            process.getInputStream().close();
        } catch (Exception e) {
            // Handle any exceptions that occur during cleanup
        }
    }

    private void sendLog(String message, boolean success) {
        // Implement logging using an external logging service
        // ...
    }
}
