bool validate_oauth2_token(const char *json_str) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    int expires;

    root = json_loads(json_str, 0, NULL);
    if (!root || !json_is_object(root)) {
        return false;
    }

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !json_is_string(access_token) || strlen(json_string_value(access_token)) == 0 || strchr(json_string_value(access_token), ' ') != NULL) {
        return false;
    }

    if (!expires_in || !json_is_number(expires_in) || json_integer_value(expires_in) <= 0 || json_integer_value(expires_in) > 604800) {
        return false;
    }

    if (!token_type || !json_string_equals(token_type, "Bearer")) {
        return false;
    }

    if (refresh_token && (!json_is_string(refresh_token) || strlen(json_string_value(refresh_token)) == 0 || strchr(json_string_value(refresh_token), ' ') != NULL)) {
        return false;
    }

    return true;
}
