    public int PropertyN { get; set; }
}

public async Task<IEnumerable<object[]>> ProcessLargeCsvAsync(string filePath, Func<CustomObject, bool> filter)
{
    var results = new List<object[]>();
    var customDataStructure = new CustomDataStructure();

    using (var reader = new StreamReader(filePath))
    using (var csv = new CsvReader(reader, CultureInfo.InvariantCulture))
    {
        while (await csv.ReadAsync())
        {
            customDataStructure.Add(csv.GetRecord<CustomObject>());
        }
    }

    customDataStructure.FilterProperty = FindIndexOfFilterProperty();

    ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

    Parallel.ForEach(customDataStructure, options, item =>
    {
        if (filter(item))
        {
            results.Add(item.ToObjectArray());
        }
    });

    return results;

    int FindIndexOfFilterProperty()
    {
        var index = 0;
        foreach (var propertyInfo in typeof(CustomObject).GetProperties())
        {
            if (propertyInfo.Name == "FilterProperty")
            {
                return index;
            }
            index++;
        }

        throw new Exception("FilterProperty not found.");
    }
}

public static object[] ToObjectArray(this CustomObject customObject)
{
    var array = new object[customObject.GetType().GetProperties().Length];
    int i = 0;

    foreach (var propertyInfo in customObject.GetType().GetProperties())
    {
        array[i++] = propertyInfo.GetValue(customObject);
    }

    return array;
}
