using Newtonsoft.Json;
using System;
using System.IO;
using System.Runtime.Caching;

public class ConfigSettings
{
    public string Key { get; set; }
    public string Value { get; set; }
}

public static class JsonConfigLoader
{
    private static readonly ObjectCache _cache = MemoryCache.Default;
    private const string ConfigFile = "config.json";

    public static ConfigSettings Load()
    {
        object cachedData = _cache.Get(nameof(ConfigSettings));

        if (cachedData != null)
            return (ConfigSettings)cachedData;

        try
        {
            string json = File.ReadAllText(ConfigFile);
            ConfigSettings settings = JsonConvert.DeserializeObject<ConfigSettings>(json);
            _cache.Add(nameof(ConfigSettings), settings, new CacheItemPolicy() { AbsoluteExpiration = DateTimeOffset.MaxValue });
            return settings;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            throw;
        }
    }
}
```
