import java.io.*;
import javax.script.*;
import sun.misc.BASE64Decoder;

public class JavaScriptLoader {
    private static ScriptEngineManager engineManager = new ScriptEngineManager();
    private static ScriptContext context = new SimpleScriptContext();

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed", e);
        }
    }

    public static void loadAndExecuteJSFile(String fileName) {
        try {
            URL url = JavaScriptLoader.class.getResource("/" + fileName);
            if (url == null) {
                throw new FileNotFoundException("JS file not found: " + fileName);
            }

            ScriptEngine engine = engineManager.getEngineByExtension(".js");
            InputStream is = url.openStream();
            BASE64Decoder decoder = new BASE64Decoder();
            byte[] jsBytes = decoder.decodeBuffer(new String(IOUtils.toByteArray(is), "UTF-8"));
            engine.put("loadAndExecute", JavaScriptLoader::loadAndExecute);
            engine.eval(new ByteArrayInputStream(jsBytes));
        } catch (Exception e) {
            throw new RuntimeException("Failed to load and execute JS file: " + e.getMessage(), e);
        }
    }

    private static Object loadAndExecute(String fileName) throws Exception {
        URL url = JavaScriptLoader.class.getResource("/" + fileName);
        if (url == null) {
            throw new FileNotFoundException("JS file not found: " + fileName);
        }

        ScriptEngine engine = engineManager.getEngineByExtension(".js");
        InputStream is = url.openStream();
        BASE64Decoder decoder = new BASE64Decoder();
        byte[] jsBytes = decoder.decodeBuffer(new String(IOUtils.toByteArray(is), "UTF-8"));
        return engine.eval(new ByteArrayInputStream(jsBytes));
    }
}
```

