const { exec } = require('child_process');

function runShellCommand(command) {
  const log = console;

  try {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        log.error(`Exec error: ${error}`);
        return;
      }

      if (stderr) {
        log.error(`Exec error:\n${stderr}`);
      } else {
        log.info(stdout);
      }
    });
  } catch (e) {
    log.error(`Unknown error: ${e}`);
  }
}

// Example usage
runShellCommand('/bin/ls');
