use tokio::runtime::Runtime;

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    directories: Vec<String>,
}

async fn process_function<F>(function: F) where F: FnOnce() + Send + 'static {
    let start = instant::Instant::now();

    // Implement your rate-limiting mechanism here

    tokio::spawn(function).await;

    println!("Function {} took {} ms", function.toString(), start.elapsed().as_millis());
}

async fn load_and_process() {
    let config = read_config().expect("Invalid configuration");

    let mut module_functions: HashMap<String, Box<dyn FnOnce() + Send + Sync>> = HashMap::new();

    let runtime = Runtime::new().expect("Failed to create Tokio runtime");

    for directory in &config.directories {
        let mut entries = dir_entrys(directory).expect("Could not read directory");

        while let Some(entry) = entries.next() {
            if entry.path().is_file() && entry.path().extension().and_then(|os| os == "rs").is_some() {
                let module = load_module(&entry).expect("Failed to load module");

                if let Some(function) = module.get("process") {
                    let function_box = Box::new(function.to_owned());
                    module_functions.insert(entry.file_name().to_str().unwrap().to_string(), function_box);
                }
            }
        }
    }

    for (name, function) in &module_functions {
        process_function(function).await;
    }
}

fn read_config() -> Result<Config, std::io::Error> {
    let mut json = String::new();
    let config_path = env::current_exe().unwrap().parent().unwrap().join("config.json");
    File::open(config_path)?.read_to_string(&mut json)?;

    serde_json::from_str::<Config>(&json).map_err(|error| error)
}

fn load_module<P: AsRef<Path>>(path: P) -> Result<HashMap<String, serde_json::Value>, std::io::Error> {
    let mut json = String::new();
    File::open(path)? .read_to_string(&mut json)?;

    serde_json::from_str::<HashMap<String, serde_json::Value>>(&json).map_err(|error| error)
}

fn main() {
    load_and_process().await;
}
