    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_CRITICAL,
} LogLevel;

typedef enum {
    FORMAT_PLAIN_TEXT,
    FORMAT_JSON,
} Format;

typedef struct Logger {
    LogLevel level;
    Format format;
    char *log_file_path;
    size_t max_log_size;
    FILE *log_file;
} Logger;

Logger *init_logger(const char *config) {
    Json_object *root = json_tokener_parse(config, 0);
    if (!root || !json_object_get(root, "log_level") || !json_object_get(root, "log_format") ||
        !json_object_get(root, "log_file_path")) {
        json_object_put(root);
        return false;
    }

    const char *log_level_str = json_object_get_string(json_object_get(root, "log_level"));
    const char *log_format_str = json_object_get_string(json_object_get(root, "log_format"));
    const char *log_file_path = json_object_get_string(json_object_get(root, "log_file_path"));

    size_t log_level;
    if (strcmp(log_level_str, "DEBUG") == 0) {
        log_level = LOG_LEVEL_DEBUG;
    } else if (strcmp(log_level_str, "INFO") == 0) {
        log_level = LOG_LEVEL_INFO;
    } else if (strcmp(log_level_str, "WARNING") == 0) {
        log_level = LOG_LEVEL_WARNING;
    } else if (strcmp(log_level_str, "ERROR") == 0) {
        log_level = LOG_LEVEL_ERROR;
    } else if (strcmp(log_level_str, "CRITICAL") == 0) {
        log_level = LOG_LEVEL_CRITICAL;
    } else {
        json_object_put(root);
        return false;
    }

    Format format;
    if (strcmp(log_format_str, "PLAIN_TEXT") == 0) {
        format = FORMAT_PLAIN_TEXT;
    } else if (strcmp(log_format_str, "JSON") == 0) {
        format = FORMAT_JSON;
    } else {
        json_object_put(root);
        return false;
    }

    size_t max_log_size = 0;
    if (json_object_get_ex(root, "max_log_size", &max_log_size)) {
        if (max_log_size <= 0) {
            json_object_put(root);
            return false;
        }
    }

    Logger *logger = malloc(sizeof(Logger));
    if (!logger) {
        json_object_put(root);
        return false;
    }

    logger->level = log_level;
    logger->format = format;
    logger->log_file_path = strdup(log_file_path);
    if (!logger->log_file_path) {
        free(logger);
        json_object_put(root);
        return false;
    }
    logger->max_log_size = max_log_size;

    // Initialize logging system here

    json_object_put(root);
    return logger;
}
