typedef struct {
    const char *name;
    EVP_ID id;
} CryptoType;

static pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
static bool is_loading = false;

void log(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int load_config(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        log("Error: Unable to open configuration file.");
        return 1;
    }

    is_loading = true;
    pthread_mutex_lock(&config_mutex);

    CryptoType ciphers[] = {{"AES", EVP_aes_128_cbc()}, {"Camellia", EVP_camellia_128_cbc()}};
    CryptoType digests[] = {{"MD5", EVP_md5()}, {"SHA-1", EVP_sha1()}, {"SHA-256", EVP_sha256()}};

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Validate the format of each configuration line
        if (strlen(line) < 3 || line[0] != '/' || line[1] != '/') {
            log("Warning: Invalid configuration format.");
            continue;
        }

        const char *type = &line[2];
        const char *id_or_alias = strchr(type, ':');
        if (!id_or_alias) {
            log("Warning: Missing ID or alias for configuration.");
            continue;
        }

        *id_or_alias++ = '\0';
        const char *name = type;
        const char *value = id_or_alias;

        // Add the cryptographic primitive to OpenSSL's library if it doesn't already exist
        if (!strcasecmp(name, "cipher")) {
            EVP_CIPHER *cipher;
            if ((cipher = EVP_get_cipherbyname(value)) || (cipher = EVP_add_cipher(EVP_cfm_new(), id_or_alias))) {
                for (size_t i = 0; i < sizeof(ciphers) / sizeof(CryptoType); ++i) {
                    if (!strcmp(ciphers[i].name, name)) {
                        log("Warning: Multiple instances of the same cipher type found.");
                        break;
                    }
                }
            } else {
                log("Error: Unable to add cipher '%s'.", value);
                continue;
            }
        } else if (!strcasecmp(name, "digest")) {
            EVP_MD *md;
            if ((md = EVP_get_digestbyname(value)) || (md = EVP_add_digest(EVP_sha1(), id_or_alias))) {
                for (size_t i = 0; i < sizeof(digests) / sizeof(CryptoType); ++i) {
                    if (!strcmp(digests[i].name, name)) {
                        log("Warning: Multiple instances of the same digest type found.");
                        break;
                    }
                }
            } else {
                log("Error: Unable to add digest '%s'.", value);
                continue;
            }
        } else if (!strcasecmp(name, "digest_alias")) {
            const char *id = strchr(value, ':');
            if (!id) {
                log("Warning: Missing ID for alias configuration.");
                continue;
            }
            *id++ = '\0';
            EVP_add_digest_alias(value, id);
        } else {
            log("Warning: Unknown configuration type '%s'.", name);
            continue;
        }
    }

    fclose(file);
    is_loading = false;
    pthread_mutex_unlock(&config_mutex);

    return 0;
}
