typedef struct {
    int value;
} record;

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s filename\n", argv[0]);
        return 1;
    }

    size_t len = strlen(argv[1]);
    char *filename = malloc(len + 8); // +8 for the extension and digit count
    strcpy(filename, argv[1]);

    int dot_idx = len - 1;
    int ext_start = dot_idx;
    while (dot_idx > 0 && argv[1][dot_idx] == '.') {
        dot_idx--;
        ext_start = dot_idx + 1;
    }

    size_t extension_len = len - ext_start;
    char *extension = malloc(extension_len + 2); // +2 for the digit count and null terminator
    strncpy(extension, argv[1] + ext_start, extension_len);

    int digit_count = 3;
    if (extension_len >= digit_count) {
        sprintf(extension + extension_len - digit_count, "%0*d.%s", digit_count, getpid(), argv[1] + ext_start);
    } else {
        sprintf(extension + extension_len, "%03d.%s", getpid(), argv[1] + ext_start);
    }
    strncpy(filename + dot_idx, extension, strlen(extension) + 1);

    size_t offset_size = (len - ext_start) / 2;
    int *offsets = malloc((offset_size > 50) ? 50 : offset_size) * sizeof(int);
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = i * 2;
    }

    size_t key_size = (len - ext_start) / 3;
    int *keys = malloc((key_size > 50) ? 50 : key_size) * sizeof(int);
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = offsets[i] + 1;
    }

    size_t array_size = 10;
    record *array = malloc(array_size * sizeof(record));
    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        array[i].value = rand() % 100 + 1;
    }

    free(filename);
    free(extension);
    return 0;
}
