import java.io.*;
import java.time.Instant;
import java.util.*;
import java.nio.file.*;
import java.util.concurrent.ConcurrentHashMap;
import java.security.MessageDigest;

public class SessionAnalyzer {
    private static final long MILLIS_PER_DAY = 86400000L;
    private static Map<String, Long> lastLogins = new ConcurrentHashMap<>();
    private static Map<String, Set<String>> devicesPerUser = new ConcurrentHashMap<>();
    private static final Logger log = Logger.getLogger(SessionAnalyzer.class);

    public long analyzeFile(Path filePath) throws IOException {
        Paths.walkFileTree(filePath, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (attrs.isRegularFile()) {
                    try (BufferedReader reader = Files.newBufferedReader(file)) {
                        String line;
                        List<String> lines = new ArrayList<>();
                        while ((line = reader.readLine()) != null) {
                            lines.add(line);
                        }
                        sortAndProcess(lines);
                    }
                }
                return FileVisitResult.CONTINUE;
            }
        });
        return extractSequenceNumber();
    }

    private void sortAndProcess(List<String> lines) {
        lines.sort(Comparator.comparing(s -> Instant.ofEpochMilli(Long.parseLong(s.split(" ")[2]))));
        for (int i = 1; i < lines.size(); ++i) {
            String[] currentLine = lines.get(i).split(" ");
            String userId = hash(currentLine[0]);
            Set<String> currentDevices = devicesPerUser.computeIfAbsent(userId, k -> new HashSet<>());
            String prevLineDevice = lines.get(i - 1).split(" ")[1];
            if (within24Hours(Long.parseLong(currentLine[2]), Long.parseLong(lines.get(i - 1).split(" ")[2])) && !currentDevices.contains(prevLineDevice)) {
                currentDevices.add(prevLineDevice);
            }
        }
    }

    private long extractSequenceNumber() {
        long sequenceNumber = -1;
        try {
            String lastLine = Files.readString(Paths.get("sequence_number.txt"));
            if (!lastLine.isEmpty()) {
                sequenceNumber = Long.parseLong(lastLine);
            }
        } catch (IOException e) {
            log.log(Level.WARNING, "Error reading sequence number file", e);
        }
        Set<String> finalDevicesPerUser = devicesPerUser.values().stream().flatMap(Set::stream).collect(Collectors.toUnmodifiableSet());
        for (Map.Entry<String, Set<String>> entry : devicesPerUser.entrySet()) {
            if (entry.getValue().size() > 1) {
                sequenceNumber = updateSequenceNumber();
                try {
                    Files.writeString(Paths.get("sequence_number.txt"), String.valueOf(sequenceNumber));
                } catch (IOException e) {
                    log.log(Level.WARNING, "Error writing sequence number file", e);
                }
            }
        }
        return sequenceNumber;
    }

    private long updateSequenceNumber() {
        Instant now = Instant.now();
        return (now.toEpochMilli() - MILLIS_PER_DAY) / MILLIS_PER_DAY + 1;
    }

    private boolean within24Hours(long timestamp1, long timestamp2) {
        return Math.abs(timestamp1 - timestamp2) <= MILLIS_PER_DAY;
    }

    private String hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
```']

