typedef enum { DEBUG, INFO, WARNING, ERROR, CRITICAL } log_level;
typedef enum { PLAIN_TEXT, JSON } log_format;

struct logger {
    log_level level;
    log_format format;
    char *log_file_path;
    size_t max_log_size;
    size_t concurrent_logger_count;
    pthread_mutex_t mutex;
    sem_t sem_loggers;
    void *log_buffer;
    FILE *file;
};

bool is_valid_config(const char *config) {
    json_object *json = json_tokener_parse(config);
    if (!json)
        return false;

    if (!json_object_get_ex(json, "log_level"))
        goto error;
    if (!json_object_get_ex(json, "log_format"))
        goto error;
    if (!json_object_get_ex(json, "log_file_path"))
        goto error;
    json_object_get(json, "max_log_size"); // Allow optional field
    json_object_get(json, "concurrent_logger_count"); // Allow optional field

    json_decref(json);
    return true;

error:
    json_decref(json);
    return false;
}

struct logger *init_logging_system(const char *config) {
    if (!is_valid_config(config))
        return nullptr;

    json_object *json = json_tokener_parse(config);

    log_level level = (log_level)json_object_get_int(json_object_get(json, "log_level"));
    log_format format = (log_format)json_object_get_int(json_object_get(json, "log_format"));
    const char *log_file_path = json_object_get_string(json_object_get(json, "log_file_path"));
    size_t max_log_size = json_object_get_int_ex(json, "max_log_size", 0);
    size_t concurrent_logger_count = json_object_get_int_ex(json, "concurrent_logger_count", SYSCONFDATAMAX);

    struct logger *logger = (struct logger *)calloc(1, sizeof(struct logger));
    if (!logger)
        goto error;

    logger->level = level;
    logger->format = format;
    logger->log_file_path = strdup(log_file_path);
    if (!logger->log_file_path)
        goto error;

    logger->max_log_size = max_log_size;
    logger->concurrent_logger_count = concurrent_logger_count;
    pthread_mutex_init(&logger->mutex, nullptr);
    sem_init(&logger->sem_loggers, 0, concurrent_logger_count);

    // Implement the logic for memory mapping, file opening and other necessary initializations here.

error:
    if (json) json_decref(json);
    if (logger) {
        free(logger->log_file_path);
        free(logger);
    }
    return logger;
}
```

