import java.util.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.math.BigInteger;

public class SessionCounter {
    private static final Map<String, Long> sessionMap = new HashMap<>();
    private static final Set<String> hashedDevices = new HashSet<>();
    private static final long ONE_DAY = 24 * 60 * 60 * 1000;

    public static long countDistinctSessions(List<Profile> profiles) {
        for (Profile profile : profiles) {
            String deviceHash = hashDevice(profile.getEmail());
            long lastLogin = profile.getLastLogin();

            // Check if the device is already in the hashedDevices set, and if its last login time is within 24 hours of the current session
            if (hashedDevices.contains(deviceHash)) {
                Long existingSession = sessionMap.get(deviceHash);
                if ((existingSession != null) && (System.currentTimeMillis() - lastLogin <= ONE_DAY)) {
                    sessionMap.put(deviceHash, existingSession + 1);
                }
            } else {
                // Add new device to the hashedDevices set and initialize a new session count for it
                if (!hasLastLoginWithin24Hours(lastLogin)) {
                    sessionMap.put(deviceHash, 1L);
                }
                hashedDevices.add(deviceHash);
            }
        }

        long distinctSessions = sessionMap.values().stream().filter(count -> count > 0).count();
        return distinctSessions;
    }

    private static String hashDevice(String email) {
        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(email.getBytes(StandardCharsets.UTF_8));
            BigInteger no = new BigInteger(1, digest);
            return no.toString(16);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean hasLastLoginWithin24Hours(long lastLogin) {
        return System.currentTimeMillis() - lastLogin <= ONE_DAY;
    }
}
