import java.util.concurrent.TimeUnit;

public class SessionAnalyzer {

    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ");
    private static Map<String, Long> sessionCache = new ConcurrentHashMap<>();

    public long compareSession(String username, String email, String lastLogin) {
        String key = hash(username + email);
        long currentTime = System.currentTimeMillis();
        long startTime = System.nanoTime();
        Long previousSession = sessionCache.get(key);
        if (previousSession != null && isWithin24Hours(lastLogin, previousSession)) {
            sessionCache.put(key, currentTime);
            return 0;
        } else {
            sessionCache.put(key, currentTime);
            return 1;
        }
    }

    private boolean isWithin24Hours(String lastLogin, Long previousSession) {
        try {
            Date dateLastLogin = DATE_FORMAT.parse(lastLogin);
            long timeDiff = Math.abs((System.currentTimeMillis() - previousSession) / (1000 * 60 * 60 * 24));
            return timeDiff <= 1;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    private String hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] messageDigest = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public void extractSequenceNumber() throws IOException, InterruptedException {
        List<String> lines = Files.readAllLines(getClass().getResourceAsStream("/profiles.txt").toPath());
        Collections.sort(lines);
        Long sequenceNumber = null;
        for (String line : lines) {
            if (line.startsWith("sequence_number")) {
                sequenceNumber = Long.parseLong(line.split(":")[1].trim());
            }
        }
        if (sequenceNumber == null) {
            throw new IOException("Sequence number not found in the file.");
        }
        TimeUnit.SECONDS.sleep(2); // Simulate some processing time
        System.out.println("Extracted sequence number: " + sequenceNumber);
    }
}
