    public static void generateThumbnails(List<String> imageFilePaths) throws InterruptedException, ExecutionException {
        if (imageFilePaths.size() > MAX_IMAGES) {
            publishToQueue(imageFilePaths);
        } else {
            processImagesLocally(imageFilePaths);
        }

        taskQueue.take().get(); // Drain the queue to ensure all tasks are completed before exiting
    }

