            generateThumbnail(imagePath);
        }
    }

    private static void publishToQueue(List<String> imageFilePaths) {
        MessageQueue messageQueue = new MessageQueue();
        for (String imagePath : imageFilePaths) {
            messageQueue.enqueueMessage(imagePath);
        }

        messageQueue.startProcessing();
    }

