import java.io.BufferedReader;
import java.io.FileReader;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ConcurrentHashMap;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.stream.Collectors;

public class TransactionProcessor {

    private static final String FILE_PATH = "transactions.csv";

    public void groupTransactions() throws InterruptedException {
        Map<Long, PriorityQueue<Transaction>> groupedTransactions = new ConcurrentHashMap<>();
        Instant startTime = Instant.now();

        try (BufferedReader reader = new BufferedReader(new FileReader(FILE_PATH))) {
            reader.lines()
                    .skip(1) // skip header row
                    .map(line -> line.split(","))
                    .filter(arr -> arr.length == 4)
                    .forEach(arr -> groupedTransactions.computeIfAbsent(Long.parseLong(arr[1]), k -> new PriorityQueue<>(Comparator.comparing(t -> t.getTimestamp()))).add(new Transaction(Long.parseLong(arr[0]), Long.parseLong(arr[1]), new BigDecimal(arr[2]), Instant.from(arr[3]))));
        } catch (Exception e) {
            System.err.println("Error reading file: " + e.getMessage());
        }

        groupedTransactions.forEach((merchantId, transactions) -> System.out.printf("Merchant ID: %d, Time taken for grouping: %.2f ms%n", merchantId, ChronoUnit.MILLIS.between(startTime, Instant.now())));
    }

    public BigDecimal calculateMaxAmount() throws InterruptedException {
        List<Transaction> transactions = new LinkedList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(FILE_PATH))) {
            reader.lines()
                    .skip(1) // skip header row
                    .map(line -> line.split(","))
                    .filter(arr -> arr.length == 4)
                    .forEach(arr -> transactions.add(new Transaction(Long.parseLong(arr[0]), Long.parseLong(arr[1]), new BigDecimal(arr[2]), Instant.from(arr[3])))
                            .filter(t -> t.getTimestamp().getEpochSecond() >= t.getTimestamp().minus(Duration.ofDays(1)).getEpochSecond())); // filter out transactions older than 1 day
        } catch (Exception e) {
            System.err.println("Error reading file: " + e.getMessage());
        }

        Map<Long, BigDecimal> maxAmounts = new ConcurrentHashMap<>();

        transactions.forEach(transaction -> maxAmounts.merge(transaction.getMerchantId(), transaction.getAmount(), (oldVal, newVal) -> oldVal.max(newVal)));

        return transactions.stream().mapToLong(t -> t.getAmount().longValue()).max()
                .filter(amount -> maxAmounts.containsKey(amount))
                .mapToObj(BigDecimal::valueOf)
                .collect(Collectors.toList())
                .get(0); // return the maximum transaction amount for a merchant
    }

    static class Transaction {
        private final Long transactionId;
        private final Long merchantId;
        private final BigDecimal amount;
        private final Instant timestamp;

        public Transaction(Long transactionId, Long merchantId, BigDecimal amount, Instant timestamp) {
            this.transactionId = transactionId;
            this.merchantId = merchantId;
            this.amount = amount;
            this.timestamp = timestamp;
        }

        public Long getTransactionId() {
            return transactionId;
        }

        public Long getMerchantId() {
            return merchantId;
        }

        public BigDecimal getAmount() {
            return amount;
        }

        public Instant getTimestamp() {
            return timestamp;
        }
    }
}
