NetMsg* createMessage(int id, size_t payloadSize, size_t minPayloadSize, size_t maxPayloadSize) {
    NetMsg* netMsg = (NetMsg*)malloc(sizeof(NetMsg));
    if (!netMsg) {
        initLog("Allocation failure");
        return NULL;
    }

    netMsg->id = id;
    netMsg->timestamp = time(NULL);
    netMsg->payload_len = payloadSize;

    if (payloadSize < minPayloadSize || payloadSize > maxPayloadSize) {
        initLog("Invalid payload size");
        free(netMsg);
        return NULL;
    }

    if (payloadSize > 0) {
        netMsg->payload = (char*)malloc(payloadSize);
        if (!netMsg->payload) {
            initLog("Allocation failure for payload");
