#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CHANNELS 100
#define MIN_BUFFER_SIZE 16
#define MAX_BUFFER_SIZE 4096
#define MAX_CONCURRENT_USERS 5
#define MAX_SOCKETS 256

typedef struct {
    int id;
    void* buffer;
    size_t buffer_size;
    pthread_rwlock_t lock;
    sem_t ref_count;
    sem_t concurrent_users;
    int socket_fd;
} DataChannel;

int setupDataTransferChannels(DataChannel channels[]) {
    for (int i = 0; i < MAX_CHANNELS && i < MAX_SOCKETS; ++i) {
        channels[i].id = i;
        // Validate buffer size
        size_t buffer_size = rand() % (MAX_BUFFER_SIZE - MIN_BUFFER_SIZE + 1) + MIN_BUFFER_SIZE;
        if (buffer_size < MIN_BUFFER_SIZE || buffer_size > MAX_BUFFER_SIZE) {
            continue;
        }

        channels[i].buffer = malloc(buffer_size);
        if (!channels[i].buffer) {
            return -1;
        }
        channels[i].buffer_size = buffer_size;

        // Initialize lock, reference count and concurrent users semaphores
        pthread_rwlock_init(&channels[i].lock, NULL);
        sem_init(&channels[i].ref_count, 0, 1);
        sem_init(&channels[i].concurrent_users, 0, MAX_CONCURRENT_USERS);

        // Connect to the remote server (assuming IPv4 and using the first available socket)
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080); // Replace with the actual port number
        if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
            free(channels[i].buffer);
            continue;
        }

        int socket_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (socket_fd == -1) {
            free(channels[i].buffer);
            continue;
        }

        if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) != 0) {
            close(socket_fd);
            free(channels[i].buffer);
            continue;
        }

        channels[i].socket_fd = socket_fd;
    }

    return 0;
}
```
