import logging
from sklearn.datasets import load_iris
from sklearn.ensemble import RandomForestClassifier, AdaBoostClassifier, GradientBoostingClassifier
from sklearn.svm import SVC
from sklearn.neural_network import MLPClassifier
from sklearn.model_selection import train_test_split
from sklearn.metrics import confusion_matrix, classification_report
import numpy as np

logger = logging.getLogger(__name__)

class ModelManager:
    def __init__(self):
        self.models = {}

    def get_model(self, name):
        if name not in self.models:
            model = eval(os.getenv("ML_MODEL_TYPE", "RandomForestClassifier"))()
            for key, val in os.environ.items():
                if key.startswith("ML_"):
                    setattr(model, key[3:], val)
            self.models[name] = model
        return self.models[name]

def train_and_predict(model_manager, X_train, y_train, X_test):
    model = model_manager.get_model("model")
    model.fit(X_train, y_train)
    predictions = model.predict(X_test)
    return predictions, confusion_matrix(y_test, predictions), classification_report(y_test, predictions)

def main():
    iris = load_iris()
    X, y = iris.data, iris.target
    X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3)
    model_manager = ModelManager()
    predictions, cm, cr = train_and_predict(model_manager, X_train, y_train, X_test)
    logger.info("Predictions: {}".format(predictions))
    logger.info("Confusion Matrix:\n{}".format(cm))
    logger.info("Classification Report:\n{}".format(cr))

if __name__ == "__main__":
    main()
