public class SensorProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(SensorProcessor.class);
    private final Map<String, RollingWindow> windows;
    private final int windowDuration;
    private final ExecutorService executor;

    public SensorProcessor(int windowDuration) {
        this.windows = new ConcurrentHashMap<>();
        this.windowDuration = windowDuration;
        this.executor = Executors.newCachedThreadPool();
    }

    public void processSensorData(String location, double timestamp, double temperature, double humidity) {
        RollingWindow window = windows.computeIfAbsent(location, k -> new RollingWindow(k, windowDuration));
        window.addDataPoint(timestamp, temperature, humidity);
    }

    public void start() {
        executor.execute(() -> {
            while (true) {
                for (RollingWindow window : windows.values()) {
                    window.calculateTrends();
                }
                try {
                    Thread.sleep(10); // Adjust as needed for real-time processing
                } catch (InterruptedException e) {
                    LOGGER.error("Thread interrupted", e);
                }
            }
        });
    }

    private class RollingWindow {
        private final String location;
        private final int windowDurationMillis;
        private final Queue<SensorDataPoint> dataQueue;
        private long startTimestamp;

        public RollingWindow(String location, int windowDuration) {
            this.location = location;
            this.windowDurationMillis = windowDuration * 1000L;
            this.dataQueue = new LinkedList<>();
            this.startTimestamp = Instant.now().toEpochMilli();
        }

        public void addDataPoint(long timestamp, double temperature, double humidity) {
            dataQueue.add(new SensorDataPoint(timestamp, temperature, humidity));
            if (System.currentTimeMillis() - startTimestamp > windowDurationMillis) {
                calculateTrends();
                dataQueue.clear();
                startTimestamp = Instant.now().toEpochMilli();
            }
        }

        private void calculateTrends() {
            long endTimestamp = startTimestamp + windowDurationMillis;
            Duration duration = Duration.ofMillis(windowDurationMillis);
            Instant currentInstant = Instant.ofEpochMilli(startTimestamp);
            Instant endInstant = currentInstant.plus(duration);
            long timeTakenMillis = Duration.between(currentInstant, endInstant).toMillis();
            LOGGER.info("Time taken for trend calculation: {} ms", timeTakenMillis);
            // Perform calculations and log results...
        }
    }

    private static class SensorDataPoint {
        public final long timestamp;
        public final double temperature;
        public final double humidity;

        public SensorDataPoint(long timestamp, double temperature, double humidity) {
            this.timestamp = timestamp;
            this.temperature = temperature;
            this.humidity = humidity;
        }
    }
}
