NFAPI_CRC_INDICATION_PDU_QUEUE_t* create_pdu_queue(size_t capacity) {
    NFAPI_CRC_INDICATION_PDU_QUEUE_t* queue = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_QUEUE_t));
    if (!queue) return NULL;

    queue->capacity = capacity;
    queue->count = 0;
    queue->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }

    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->condition, NULL);

    return queue;
}

void push_pdu_queue(NFAPI_CRC_INDICATION_PDU_QUEUE_t* queue, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->count >= queue->capacity) {
        pthread_cond_wait(&queue->condition, &queue->mutex);
    }

    uppercase_trim_replace(pdu->rx_ue_information_tag.value);
    uppercase_trim_replace(pdu->rnti.value);

    pdu->crc_indication_rel8_tag.crcflag = crc_indication(pdu);

    queue->data[queue->count++] = *pdu;

    if (queue->count == 1 && queue->capacity > 1) {
        pthread_cond_broadcast(&queue->condition);
    }

    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* pop_pdu_queue(NFAPI_CRC_INDICATION_PDU_QUEUE_t* queue) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    pthread_mutex_lock(&queue->mutex);

    while (queue->count == 0) {
        pthread_cond_wait(&queue->condition, &queue->mutex);
    }

    pdu = &(queue->data[--queue->count]);

    pthread_mutex_unlock(&queue->mutex);

    return pdu;
}

void destroy_pdu_queue(NFAPI_CRC_INDICATION_PDU_QUEUE_t* queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->condition);
    free(queue);
}
