    }

    while ((bytes_read = fread(buffer, 1, chunk_size, input)) > 0) {
        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
    }

    free(rules);
    free(buffer);

    write_file(output, output_file, &bytes_read);

    return 0;
}

