void write_file(FILE* file, const char* filename, const size_t* bytes_written) {
    FILE* output = fopen(filename, "w");
    if (!output) {
        perror("Failed to open output file");
        exit(1);
    }

    while (fwrite(*file, 1, *bytes_written, output) == *bytes_written) {
        *bytes_written = fread(*file, 1, *bytes_written, *file);
    }

    fclose(output);
}

void free_memory(char** buffer, size_t* bytes_allocated) {
    free(*buffer);
    *buffer = NULL;
    *bytes_allocated = 0;
}
