#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_THREADS 100
#define MAX_ITEMS 100000
#define TAG_LENGTH 32

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    bool CRCFLAG;
    char CRCI_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* items = NULL;
static size_t itemCount = 0;
static size_t maxItems = 0;
static pthread_mutex_t mutex;
static pthread_cond_t cond;
static pthread_attr_t attr[MAX_THREADS];
static pthread_t threads[MAX_THREADS];

void transformTag(char* tag) {
    for (size_t i = 0; i < strlen(tag); ++i) {
        if (!isalnum(tag[i])) tag[i] = '_';
    }
    tag[0] = toupper(tag[0]);
    size_t len = strlen(tag);
    while (len > 0 && isspace(tag[len - 1])) tag[--len] = '\0';
}

bool createItem(NFAPI_CRC_INDICATION_PDU_T* item) {
    transformTag((char*)&item->RX_UE_INFORMATION_TAG);
    item->RNTI = rand() % ((1 << 64) - 1);
    item->CRCI_REL8_TAG[0] = (rand() % 2 == 0) ? '1' : '0';
    return true;
}

void freeItem(NFAPI_CRC_INDICATION_PDU_T* item) {
    memset(item, 0, sizeof(*item));
}

void* createItemsThreadFunc(void* arg) {
    size_t id = (size_t)arg;
    while (true) {
        pthread_mutex_lock(&mutex);
        if (itemCount >= maxItems) {
            pthread_cond_wait(&cond, &mutex);
        }

        NFAPI_CRC_INDICATION_PDU_T* item = NULL;
        if (itemCount < maxItems) {
            item = items + itemCount++;
        }

        pthread_mutex_unlock(&mutex);

        if (item != NULL) createItem(item);
    }
    return NULL;
}

void init() {
    maxItems = MAX_ITEMS;
    items = malloc(maxItems * sizeof(*items));
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_attr_init(&attr[i]);
        pthread_create(&threads[i], &attr[i], createItemsThreadFunc, (void*)i);
    }
}

void destroy() {
    free(items);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
        pthread_attr_destroy(&attr[i]);
    }
}
```
