// Frame Transformation Function
auto transformFrame(const std::string& frame) {
    // Remove non-alphanumeric characters and convert to uppercase
    std::regex pattern("\\W+");
    auto transformedFrame = std::regex_replace(frame, pattern, "_");
    transformedFrame[0] = toupper(transformedFrame[0]);

    // Trim leading and trailing whitespace
    transformedFrame.erase(transformedFrame.begin(), std::find_if(transformedFrame.begin(), transformedFrame.end(), [](int c) { return !std::isspace(c); }));
    transformedFrame.erase(std::find(transformedFrame.rbegin(), transformedFrame.rend(), ' '), transformedFrame.rend());

    return transformedFrame;
}

// RX_FRAME_INFO Structure
struct RX_FRAME_INFO {
    std::string sequenceNumber;
    time_t timestamp;
};

// NFAPI_L2_RX_PDU_T Structure
struct NFAPI_L2_RX_PDU_T {
    RX_FRAME_INFO rxFrameInfo;
    int rrcConnectionID;
    int pduSessionID;
};

// Function to create and populate list of NFAPI_L2_RX_PDU_T structures
void createAndPopulateList(int numFrames, MemoryFragmentationMonitor& memoryFragmentationMonitor) {
    boost::pool::object_pool<NFAPI_L2_RX_PDU_T> pduPool;
    std::vector<boost::optional<NFAPI_L2_RX_PDU_T>> pdus;
    pdus.reserve(numFrames);

    boost::mutex mtx;

    // Define a lambda to execute in each thread
    auto processFrame = [&](int frameIndex) {
        NFAPI_L2_RX_PDU_T* pdu = pduPool.construct();

        std::stringstream ss;
        ss << "frame" << frameIndex;
        auto transformedSequenceNumber = transformFrame(ss.str());

        // Fill in the RX_FRAME_INFO structure with a timestamp and sequence number
        pdu->rxFrameInfo.sequenceNumber = transformedSequenceNumber;
        std::time_t now = std::time(nullptr);
        pdu->rxFrameInfo.timestamp = now;

        // Set the RRC connection ID and PDU session ID
        pdu->rrcConnectionID = frameIndex / 10;
        pdu->pduSessionID = frameIndex % 10;

        {
            boost::lock_guard<boost::mutex> lock(mtx);
            pdus.push_back(pduPool.get_weak());
        }

        memoryFragmentationMonitor.addBlock(sizeof(NFAPI_L2_RX_PDU_T));
    };

    // Use a thread pool to process frames concurrently
    std::vector<boost::thread> threads;
    for (int i = 0; i < numFrames / 10 + 1; ++i) {
        threads.push_back(boost::thread(processFrame, i * 10));
    }

    // Wait for all threads to finish executing
    for (auto& thread : threads) {
        thread.join();
    }
}

// Main Function
int main() {
    MemoryFragmentationMonitor memoryFragmentationMonitor;
    createAndPopulateList(1000, memoryFragmentationMonitor);

    std::cout << "Free memory: " << memoryFragmentationMonitor.getFreeMemory() << "\n";

    // Post-processing and analysis code goes here
}
