namespace bp = boost::posix_time;

struct Node {
    std::string str;
    int value;
    Node* next;
};

std::unique_ptr<Node> create_node(const std::vector<std::string>& stringPool) {
    auto node = std::make_unique<Node>();
    if (!node) {
        BOOST_LOG_TRIVIAL(error) << "Memory allocation failed.";
        return nullptr;
    }
    node->str = *stringPool.begin(); // Take first string from pool
    std::advance(stringPool.begin(), 1); // Move to next position in the pool for reuse
    node->next = nullptr;
    return node;
}

std::unique_ptr<Node> create_linked_list(int nodeCount, int minValue, int maxValue) {
    std::srand(time(nullptr)); // Seed random number generator
    std::vector<std::string> stringPool = {"String1", "String2", "String3"}; // Configuration parameter
    std::unique_ptr<Node> head = create_node(stringPool);
    if (!head) {
        BOOST_LOG_TRIVIAL(error) << "Memory allocation failed.";
        return nullptr;
    }
    Node* current = head.get();

    for (int i = 1; i < nodeCount; ++i) {
        std::unique_ptr<Node> newNode = create_node(stringPool);
        if (!newNode) {
            BOOST_LOG_TRIVIAL(error) << "Memory allocation failed.";
            // Free previous nodes and return error
            while (current != nullptr) {
                std::unique_ptr<Node> temp = std::move(current);
                current = temp.release();
                current->next = nullptr;
            }
            return nullptr;
        }
        int randVal = minValue + static_cast<int>(std::rand() % (maxValue - minValue + 1));
        newNode->value = randVal;
        current->next = newNode.get();
        current = newNode.release();
    }

    BOOST_LOG_TRIVIAL(info) << "Created linked list with " << nodeCount << " nodes.";

    // Integration with external logging library
    int totalSum = 0;
    int nodeCountIterator = 0;
    for (Node* currentNode = head.get(); currentNode != nullptr; currentNode = currentNode->next) {
        totalSum += currentNode->value;
        ++nodeCountIterator;
    }
    double average = static_cast<double>(totalSum) / nodeCountIterator;
    BOOST_LOG_TRIVIAL(info) << "Average integer value: " << average;

    return head;
}

```

