void create_and_populate_structures(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int N, long double* throughput) {
    // Variables for storing allocated and free blocks (optional)
    size_t allocated_blocks = 0;
    size_t free_blocks = 0;

