    pthread_t current_thread = pthread_self();
    int index = -1;

    // Create thread pool if not already created
    if (thread_pool == NULL) {
        thread_pool = malloc(THREAD_POOL_SIZE * sizeof(pthread_t));
        for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
            pthread_create(&thread_pool[i], NULL, worker_function, (void*)i);
        }
    }

    // Allocate memory for PDU structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list_local = custom_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate PDU structures in a thread-safe manner using the thread pool
    for (index = 0; index < N; ++index) {
        pdu_list_local[index].rxi_ue_information_tag = generate_random_tag();
        pdu_list_local[index].rnti = generate_random_RNTI();
        pdu_list_local[index].crc_indication_rel8_tag = generate_random_CRC_INDICATION_REL8_TAG();
        pdu_list_local[index].crcflag = (bool)generate_random_boolean();

        // Apply transformations on tag string representations
        char tag_str[MAX_TAG_LENGTH];
        convert_to_uppercase(pdu_list_local[index].rxi_ue_information_tag, tag_str);
        trim_whitespace(tag_str);
        replace_non_alphanumeric_characters(tag_str, '_');
        // Generate CRC flag based on the transformed string
        pdu_list_local[index].crcflag = calculate_CRCFLAG(tag_str);
    }

    // Notify worker threads that new tasks are available and wait for them to finish
    pthread_mutex_lock(&thread_pool_mutex);
    while (index < N) {
        pthread_cond_signal(&thread_pool_cond);
        pthread_mutex_unlock(&thread_pool_mutex);
        pthread_mutex_lock(&thread_pool_mutex);
        pthread_cond_wait(&thread_pool_cond, &thread_pool_mutex);
        index++;
    }
    pthread_mutex_unlock(&thread_pool_mutex);

    *pdu_list = pdu_list_local;

    // Calculate throughput and report memory fragmentation (optional)
    *throughput = (N / elapsed_time_since(start_profiling())) * 60;
    report_memory_fragmentation(&allocated_blocks, &free_blocks);

    stop_profiling();
}

void worker_function(void* arg) {
    // Function to process tasks from the thread pool
    int task_index = (int)arg;
    while (true) {
        // Wait for a new task or exit if no more tasks are available
        pthread_mutex_lock(&thread_pool_mutex);
        while (task_index >= MAX_TASKS || task_index < 0) {
            pthread_cond_wait(&thread_pool_cond, &thread_pool_mutex);
            if (task_index >= MAX_TASKS && task_index < 0) break;
        }
        task_index++;
        pthread_mutex_unlock(&thread_pool_mutex);

        if (task_index >= MAX_TASKS) {
            pthread_exit(NULL);
        }
    }
}
