// Function for handling key management securely
static int load_key(const char *filename, EVP_CIPHER_CTX **cipher) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return 0;

    // Read key size and initialization vector (IV) from file
    unsigned int key_size, iv_len;
    fread(&key_size, sizeof(unsigned int), 1, fp);
    fread(&iv_len, sizeof(unsigned int), 1, fp);

    // Allocate memory for the key and IV
    unsigned char *key = malloc(key_size);
    unsigned char *iv = malloc(iv_len);
    if (!key || !iv) {
        fclose(fp);
        return 0;
    }

    // Read key and IV from file
    fread(key, key_size, 1, fp);
    fread(iv, iv_len, 1, fp);
    fclose(fp);

    // Initialize cipher context
    *cipher = EVP_CIPHER_CTX_new();
    if (!*cipher) {
        free(key);
        free(iv);
        return 0;
    }

    // Set cipher algorithm and key/IV
    if (1 != EVP_EncryptInit_ex(*cipher, EVP_aes_128_cbc(), NULL)) {
        EVP_CIPHER_CTX_free(*cipher);
        free(key);
        free(iv);
        return 0;
    }
    if (1 != EVP_EncryptUpdate(*cipher, key, key_size) ||
        1 != EVP_EncryptFinal_ex(*cipher, NULL, NULL)) {
        EVP_CIPHER_CTX_free(*cipher);
        free(key);
        free(iv);
        return 0;
    }
    if (1 != EVP_CIPHER_CTX_ctrl(*cipher, EVP_CTRL_SET_IV, iv, iv_len)) {
        EVP_CIPHER_CTX_free(*cipher);
        free(key);
        free(iv);
        return 0;
    }

    return 1;
}

// Dynamic loading of digest algorithms from configuration files
void load_digest_algorithms() {
    char line[256];
    FILE *fp = fopen("config.txt", "r");
    if (!fp) return;

    while (fgets(line, sizeof(line), fp)) {
        const char* digest_alias = strtok(line, "\n");
        if (!digest_alias) continue;

        EVP_MD_CTX *ctx = EVP_MD_CTX_new();
        if (EVP_DigestInit_ex(ctx, NULL, nullptr)) { // Try to find the algorithm by alias
            const EVP_MD *md = EVP_get_digestbyname(digest_alias);
            if (md) {
                if (EVP_DigestInit_ex(ctx, md, nullptr)) {
                    EVP_add_digest(md->type, digest_alias);
                    EVP_add_digest_alias(md->type, digest_alias);
                }
            }
        }
        EVP_MD_CTX_free(ctx);
    }
    fclose(fp);
}

// Function for validating constant time execution
static int is_constant_time(const char *func, size_t n, const unsigned char *buf) {
    unsigned long start = RDTSC();
    for (size_t i = 0; i < n; ++i) buf[i] ^= (unsigned char)i;
    unsigned long end = RDTSC();
    if ((end - start) > 100 || (end - start) < 50) return 0;
    return 1;
}

// Main function for integrating multiple cryptographic primitives into a library
void initialize_cryptography() {
    // AES support for different key sizes
    load_key("aes128.key", NULL);
    load_key("aes192.key", NULL);
    load_key("aes256.key", NULL);

    // MD5, SHA1, and SHA256 support
    load_digest_algorithms();

    // Constant time execution validation
    char buf[16];
    if (!is_constant_time("AES", sizeof(buf), buf)) printf("Timing attack vulnerability in AES\n");
    if (!is_constant_time("MD5", sizeof(buf), buf)) printf("Timing attack vulnerability in MD5\n");
    // ... add constant time execution validation for other primitives here
}
