        String pageSectionId = request.getParameter("pageSectionId");
        String elementId = request.getParameter("elementId");
        String content = request.getParameter("content");

        service.updateElementContent(pageSectionId, elementId, content);
        response.sendRedirect(request.getRequestURI()); // Refresh the page
