bool unique_ue_tag(NFAPI_CRC_INDICATION_PDU_T *array, size_t array_size, size_t index, RX_UE_INFORMATION_TAG tag) {
    for (size_t i = 0; i < index; ++i) {
        if (array[i].tag == tag) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(int size) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        log_error("Out of memory");
        return NULL;
    }

    size_t elements_processed = 0;
    for (size_t i = 0; i < size; ++i) {
        RX_UE_INFORMATION_TAG tag = (RX_UE_INFORMATION_TAG)(elements_processed + 1); // Assuming that tags start from 1

        while (!unique_ue_tag(pdu_array, elements_processed, i, tag)) {
            tag = (RX_UE_INFORMATION_TAG)(rand() % 256 + 1); // Generate a new unique tag
        }

        pdu_array[i].tag = tag;
        pdu_array[i].rnti = rand();
        pdu_array[i].crc_indication.crcflag = (rand() % 2) == 0 ? true : false; // Randomly set CRCFLAG to either true or false

        elements_processed++;
        if (elements_processed >= size) {
            break;
        }
    }

    // If the size was not sufficient, reallocate and process remaining elements
    if (elements_processed < size) {
        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(pdu_array, elements_processed * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            log_error("Out of memory");
            free(pdu_array);
            return NULL;
        }
        pdu_array = temp_array;
    }

    return pdu_array;
}
