}

LTE_UL_CCCH_MESSAGE_T* create_node(int SRB_ID, const char* CCCH_MESSAGE) {
    LTE_UL_CCCH_MESSAGE_T* new_node = (LTE_UL_CCCH_MESSAGE_T*) malloc(sizeof(LTE_UL_CCCH_MESSAGE_T));
    if (!new_node) {
        log_error("Out of memory");
        return NULL;
    }
    new_node->SRB_ID = SRB_ID;
    strcpy(new_node->CCCH_MESSAGE, CCCH_MESSAGE);
    new_node->next = NULL;
    return new_node;
}

void insert_head(LTE_UL_CCCH_MESSAGE_T** head, LTE_UL_CCCH_MESSAGE_T* node) {
    if (node->SRB_ID == -1 || find_node(*head, node->SRB_ID)) { // -1 as placeholder for empty list
        log_error("Error: Duplicate SRB_ID");
        free(node);
        return;
    }
    node->next = *head;
    *head = node;
}

void insert_tail(LTE_UL_CCCH_MESSAGE_T** tail, LTE_UL_CCCH_MESSAGE_T* node) {
    if (node->SRB_ID == -1 || find_node(*tail, node->SRB_ID)) { // -1 as placeholder for empty list
        log_error("Error: Duplicate SRB_ID");
        free(node);
        return;
    }
    if (*tail) {
        (*tail)->next = node;
    }
    *tail = node;
}

bool find_node(LTE_UL_CCCH_MESSAGE_T* head, int SRB_ID) {
    for (LTE_UL_CCCH_MESSAGE_T* current = head; current != NULL; current = current->next) {
        if (current->SRB_ID == SRB_ID) return true;
    }
    return false;
}

void free_list(LTE_UL_CCCH_MESSAGE_T** head) {
    LTE_UL_CCCH_MESSAGE_T* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
