    private readonly Logger _logger = LogManager.GetCurrentClassLogger();
    private readonly Random _random = new Random(DateTime.Now.Ticks);
    private readonly SqlConnection _dbConnection;

    public Processor(IMongoDatabase mongoDb, SqlConnection dbConnection)
    {
        _mongoDb = mongoDb;
        _dbConnection = dbConnection;
    }

    public async Task<IDataReader> ProcessByteArrayAsync(byte[] data, string originalFileName)
    {
        var fileParts = originalFileName.Split('.');
        var extension = fileParts.Last();
        var fileNameSegments = fileParts.Take(fileParts.Length - 1).ToList();
        var reversedSegments = fileNameSegments.Reverse().ToList();
        var formattedSegments = string.Join("", reversedSegments.Select((s, i) => i < 3 ? s : $"{new string('0', 3 - (i + 1)).PadRight(3) + s}"));
        var newFileName = $"{formattedSegments}.temp_{extension}";
        File.WriteAllBytes(newFileName, data);

        using (var transaction = _dbConnection.BeginTransaction())
        {
            try
            {
                var record = CreateRecord();
                await CacheAndInsertToDatabaseAsync(record, newFileName);
                transaction.Commit();

                var query = $"SELECT * FROM dbo.Records WHERE FileName='{newFileName}'";
                return await ExecuteReaderAsync(query);
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to process byte array");
                transaction.Rollback();
                File.Delete(newFileName);
                throw;
            }
        }
    }

    private Record CreateRecord()
    {
        return new Record
        {
            Id = _random.Next(),
            Name = _random.Next().ToString(),
            Age = _random.Next(18, 99),
            Timestamp = DateTime.Now
        };
    }

    private async Task CacheAndInsertToDatabaseAsync(Record record, string newFileName)
    {
        var temporaryCacheCollection = _mongoDb.GetCollection<BsonDocument>("temporaryCache");
        await temporaryCacheCollection.InsertOneAsync(JsonConvert.SerializeObject(record));

        // Implement distributed cache system logic here using appropriate libraries like Redis or Hazelcast
    }

    private async Task<IDataReader> ExecuteReaderAsync(string query)
    {
        var command = new SqlCommand(query, _dbConnection);
        return await command.ExecuteReaderAsync();
    }
}

public class Record
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public DateTime Timestamp { get; set; }
}
