import java.io.*;
import java.util.*;
import java.time.*;
import java.nio.file.*;

public class SessionAnalyzer {
    private static final int SEQUENCE_NUMBER_POS = 6;
    private static final long MILLIS_PER_DAY = Duration.ofDays(1).toMillis();
    private Map<Long, HashSet<String>> sessionMap;
    private TreeSet<Long> sequenceNumbers;
    private Long lastLoginTimestamp;

    public SessionAnalyzer() {
        sessionMap = new HashMap<>();
        sequenceNumbers = new TreeSet<>();
        lastLoginTimestamp = null;
    }

    void extractSequenceNumber(String filename) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            List<String> lines = new ArrayList<>(Collections.list(reader.lines()));
            lines.sort(String::compareTo);

            if (!lines.isEmpty()) {
                String lastLine = lines.get(lines.size() - 1);
                long sequenceNumber = Long.parseLong(lastLine.substring(SEQUENCE_NUMBER_POS));
                sequenceNumbers.add(sequenceNumber);
            }
        } catch (Exception e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

    void analyzeFile(String filename) throws IOException {
        String[] lastThreeChars = new String[3];
        Arrays.fill(lastThreeChars, "");

        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            int i = 0;

            while ((line = reader.readLine()) != null) {
                lastThreeChars[i++] = line.substring(line.length() - 3);

                analyzeSession(line, lastThreeChars[i - 1]);
            }
        } catch (Exception e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

    void analyzeSession(String line, String extension) {
        String[] parts = line.split(",");
        String username = parts[0];
        String email = parts[1];
        LocalDateTime lastLogin = LocalDateTime.parse(parts[2]);

        long timestamp = lastLogin.toInstant(ZoneOffset.UTC).toEpochMilli();

        if (lastLoginTimestamp == null) {
            lastLoginTimestamp = timestamp;
        } else {
            long timeDelta = (timestamp - lastLoginTimestamp) / MILLIS_PER_DAY;

            if (timeDelta < 1) {
                compareSessions(username, email, extension);
            } else {
                lastLoginTimestamp = timestamp;
                HashSet<String> devices = sessionMap.getOrDefault(timestamp / MILLIS_PER_DAY, new HashSet<>());
                devices.add(extension);
                sessionMap.put(timestamp / MILLIS_PER_DAY, devices);
            }
        }
    }

    void compareSessions(String username, String email, String extension) {
        long currentTimestamp = System.currentTimeMillis();
        long timeDelta = (currentTimestamp - lastLoginTimestamp) / MILLIS_PER_DAY;

        HashSet<String> devices = sessionMap.getOrDefault((lastLoginTimestamp + MILLIS_PER_DAY * timeDelta) / MILLIS_PER_DAY, new HashSet<>());

        if (!devices.contains(extension)) {
            devices.add(extension);
            sessionMap.put((lastLoginTimestamp + MILLIS_PER_DAY * timeDelta) / MILLIS_PER_DAY, devices);
        }

        long comparisonTime = System.currentTimeMillis();
        // Compare sessions based on your logic here.

        System.out.println("Comparison took " + (comparisonTime - currentTimestamp) + " milliseconds.");
    }
}
