                    int email = Integer.parseInt(tokens[1]);
                    LocalDateTime loginTime = LocalDateTime.parse(tokens[2]);

                    LocalDateTime delta = Duration.between(lastLogin, loginTime).toHours();
                    if (delta.abs() <= 24) {
                        deviceCount++;
                        sessions.merge(username, 1L, Long::sum);
                    } else {
                        deviceCount = 1;
                        sessions.put(username, (long)1);
                    }
                    lastLogin = loginTime;
                }
            }
