// Define the structure
typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to read default values from a configuration file
void read_config(char* config_file, int* n, unsigned int* seed) {
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: Unable to open configuration file.\n");
        exit(1);
    }

    char line[256];
    int lines_read = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (lines_read++ == 1) { // Read default N value
            sscanf(line, "%d", n);
        } else if (lines_read == 2) { // Read default seed value
            sscanf(line, "%u", seed);
        }
    }
    fclose(fp);
}

// Function to initialize and populate the array of structures
void init_structures(int N, unsigned int seed, NFAPI_CRC_INDICATION_PDU_T** structures) {
    *structures = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize random number generator
    srand(seed);

    for (int i = 0; i < N; ++i) {
        // Set RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG with randomly generated values
        (*structures)[i].RX_UE_INFORMATION_TAG = rand() % (1 << 14);
        (*structures)[i].RNTI = rand() % ((1 << 26) - 1);
        (*structures)[i].CRC_INDICATION_REL8_TAG = rand() % ((1 << 8) - 1);
    }
}

int main(int argc, char** argv) {
    if (argc < 4) {
        printf("Usage: %s config_file N seed\n", argv[0]);
        exit(1);
    }

    int n = argc > 3 ? atoi(argv[3]) : DEFAULT_N;
    unsigned int seed = argc > 4 ? atoi(argv[4]) : DEFAULT_SEED;
    char* config_file = argv[2];

    read_config(config_file, &n, &seed);

    NFAPI_CRC_INDICATION_PDU_T* structures;
    init_structures(n, seed, &structures);

    // Further processing of the initialized array can be done here.

    free(structures);
    return 0;
}
