struct NFAPI_CRC_INDICATION_PDU_T {
    enum { RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG };

    unsigned int tag;
    unsigned int rnti;
    bool crc_indication;

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive& ar, const unsigned int version) {
        ar & tag & rnti & crc_indication;
    }
};

std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> initialize_pdus(int N, unsigned int seed = 0) {
    std::mt19937 gen(seed);
    std::uniform_int_distribution<> dis(1, static_cast<unsigned int>(NFAPI_CRC_INDICATION_PDU_T::RX_UE_INFORMATION_TAG + 1));

    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> pdus;
    pdus.reserve(N);

    for (size_t i = 0; i < N; ++i) {
        auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        pdu->tag = dis(gen);
        pdu->rnti = i % 1024; // For simplicity, we set RNTI as the index number modulo 1024. Adjust according to your requirements.
        pdu->crc_indication = (gen % 2 == 0);
        pdus.push_back(std::move(pdu));
    }

    return pdus;
}

