        for (size_t i = 0; i < capacity; ++i) {
            hashTable[std::to_string(rand() % 100)] = {i};
        }

        std::list<node> nodeList;
        for (auto& entry : hashTable) {
            const auto& str = entry.first;
            for (const auto& val : entry.second) {
                node n{new char[str.length() + 1], nodeList.end()};
                std::copy(str.begin(), str.end(), n.str);
                n.str[str.length()] = '\0';
                nodeList.splice(n.next, nodeList, &nodeList.begin());
                n.next = linkedList.end();
                linkedList.splice(linkedList.end(), nodeList, n);
            }
        }
    }

    void initializeDataStructures() {
