#include <stdio.h>
#include <stdlib.h>
#include <jansson.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    int log_level;
    char* log_format;
    char* sink_type;
    int max_log_entries_per_second;
    int concurrent_sinks;
    void* logging_struct;
} Config;

struct LogSink {
    sem_t lock;
    char* buffer;
    enum LogFormat format;
    enum AggregationMode mode;
    struct LogSink* next;
};

struct LoggingFramework {
    pthread_mutex_t framework_lock;
    struct LogSink* head;
    int concurrent_sinks_limit;
    int num_concurrent_sinks;
    sem_t sink_sem;
};

bool is_valid_config(json_t* config) {
    json_t* log_level = json_object_get(config, "log_level");
    json_t* log_format = json_object_get(config, "log_format");
    json_t* sink_type = json_object_get(config, "sink_type");
    if (!log_level || !log_format || !sink_type) return false;
    if (json_typeof(log_level) != JSON_NUMBER ||
        json_typeof(log_format) != JSON_STRING ||
        json_typeof(sink_type) != JSON_STRING) return false;
    json_t* max_entries = json_object_get(config, "max_log_entries_per_second");
    if (max_entries && (json_typeof(max_entries) == JSON_NUMBER)) {}
    json_t* sinks = json_object_get(config, "sinks");
    if (!sinks || json_typeof(sinks) != JSON_ARRAY) return false;
    return true;
}

Config* initialize_logging(json_t* config) {
    if (!is_valid_config(config)) return NULL;

    // Initialize the logging framework
    struct LoggingFramework* logging_framework = malloc(sizeof(struct LoggingFramework));
    if (!logging_framework) return false;

    pthread_mutex_init(&logging_framework->framework_lock, NULL);
    sem_init(&logging_framework->sink_sem, 0, logging_framework->concurrent_sinks_limit);
    logging_framework->head = NULL;
    logging_framework->concurrent_sinks_limit = config->u.object.count;
    logging_framework->num_concurrent_sinks = 0;

    // Initialize the log sinks
    json_t* sinks = json_object_get(config, "sinks");
    json_array_foreach(sinks, (json_t*, idx, len, obj)) {
        struct LogSink* log_sink = malloc(sizeof(struct LogSink));
        if (!log_sink) continue;

        // Initialize the log sink's properties
        sem_init(&log_sink->lock, 0, 1);
        log_sink->buffer = NULL;
        log_sink->format = PLAIN_TEXT;
        log_sink->mode = TAIL;
        log_sink->next = NULL;

        // Add the log sink to the framework
        if (!logging_framework->head) {
            logging_framework->head = log_sink;
        } else {
            struct LogSink* current = logging_framework->head;
            while (current->next != NULL) current = current->next;
            current->next = log_sink;
        }

        // Increase the number of concurrent sinks
        sem_wait(&logging_framework->sink_sem);
        logging_framework->num_concurrent_sinks++;
    }

    Config* config_struct = malloc(sizeof(Config));
    if (!config_struct) {
        // Cleanup the log sinks and framework
        struct LogSink* current = logging_framework->head;
        while (current != NULL) {
            struct LogSink* temp = current;
            current = current->next;
            free(temp);
        }
        free(logging_framework);
        return false;
    }

    config_struct->log_level = json_integer_value(json_object_get(config, "log_level"));
    config_struct->log_format = strdup(json_string_value(json_object_get(config, "log_format")));
    config_struct->sink_type = strdup(json_string_value(json_object_get(config, "sink_type")));
    if (json_object_has_member(config, "max_log_entries_per_second")) {
        config_struct->max_log_entries_per_second = json_integer_value(json_object_get(config, "max_log_entries_per_second"));
    } else {
        config_struct->max_log_entries_per_second = 0;
    }
    if (json_object_has_member(config, "concurrent_sinks")) {
        config_struct->concurrent_sinks = json_integer_value(json_object_get(config, "concurrent_sinks"));
    } else {
        config_struct->concurrent_sinks = 0;
    }
    config_struct->logging_struct = (void*) logging_framework;

    return config_struct;
}
```

