            Map<String, Integer> weaknesses = getWeaknesses(type);
            int majorCount = 0;
            int minorCount = 0;
            for (Map.Entry<String, Integer> entry : weaknesses.entrySet()) {
                if (entry.getValue() > MAJOR_WEAKNESS_THRESHOLD) {
                    majorCount++;
                } else if (entry.getValue() > MINOR_WEAKNESS_THRESHOLD) {
                    minorCount++;
