#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>

#define QUEUE_CAPACITY 10

typedef struct {
    sem_t enqueue; // Semaphore for enqueuing items
    sem_t dequeue; // Semaphore for dequeuing items
    pthread_mutex_t lock; // Mutex for protecting queue data
    int items[QUEUE_CAPACITY]; // Queue data
    size_t head, tail; // Indices indicating the current state of the queue
} Queue;

Queue* queue_create() {
    Queue *q = malloc(sizeof(Queue));
    sem_init(&q->enqueue, 0, QUEUE_CAPACITY);
    sem_init(&q->dequeue, 0, 0);
    pthread_mutex_init(&q->lock, NULL);
    q->head = q->tail = 0;
    return q;
}

void queue_destroy(Queue *q) {
    free(q);
}

bool queue_full(const Queue *q) {
    return (sem_getvalue(&q->enqueue) >= QUEUE_CAPACITY);
}

bool queue_empty(const Queue *q) {
    return (sem_getvalue(&q->dequeue) > 0);
}

void enqueue(Queue *q, int item) {
    sem_wait(&q->enqueue);
    pthread_mutex_lock(&q->lock);
    if (!queue_full(q)) {
        q->items[q->tail] = item;
        q->tail = (q->tail + 1) % QUEUE_CAPACITY;
    }
    pthread_mutex_unlock(&q->lock);
    sem_post(&q->dequeue);
}

int dequeue(Queue *q) {
    int item;
    sem_wait(&q->dequeue);
    pthread_mutex_lock(&q->lock);
    if (!queue_empty(q)) {
        item = q->items[q->head];
        q->head = (q->head + 1) % QUEUE_CAPACITY;
    }
    pthread_mutex_unlock(&q->lock);
    sem_post(&q->enqueue);
    return item;
}

char* string_append_slash(const char *str, size_t limit) {
    size_t str_len = strlen(str);
    if (str_len <= limit)
        return realloc(str, str_len + 2); // Reallocate with extra space for the slash
    else
        return NULL;
}

// Main function for testing the code
int main() {
    Queue *queue = queue_create();
    // Add some items to the queue
    enqueue(queue, 1);
    enqueue(queue, 2);
    enqueue(queue, 3);
    // Check fullness and emptiness conditions
    printf("Queue full: %s\n", queue_full(queue) ? "true" : "false");
    printf("Queue empty: %s\n", queue_empty(queue) ? "true" : "false");
    // Dequeue items from the queue
    int item1 = dequeue(queue);
    int item2 = dequeue(queue);
    int item3 = dequeue(queue);
