#include <semaphore.h>
#include <sys/select.h>

struct DataChannel {
    int id;
    char *buffer;
    size_t buffer_size;
    int ref_count;
    sem_t ref_count_lock;
    sem_t max_concurrent_use_lock;
    int max_concurrent_use;
    int socket_fd;
    time_t last_init_time;
};

struct Log {
    FILE *file;
    char *filename;
};

void log_message(struct Log *log, const char *message) {
    time_t current_time = time(NULL);
    struct tm *current_tm = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", current_tm);
    fprintf(log->file, "[%s] %s\n", timestamp, message);
}

void setupDataTransferChannels(struct DataChannel **channels, size_t num_channels, struct Log *log) {
    for (size_t i = 0; i < num_channels; ++i) {
        struct DataChannel *channel = calloc(1, sizeof(*channel));
        if (!channel) {
            perror("malloc");
            continue;
        }
        channel->id = i;
        channel->buffer_size = MINIMUM_BUFFER_SIZE;
        channel->ref_count = 0;
        sem_init(&channel->ref_count_lock, 1, 1);
        sem_init(&channel->max_concurrent_use_lock, 1, channel->max_concurrent_use);
        channel->max_concurrent_use = MAX_CONCURRENT_USE_PER_CHANNEL;
        channel->last_init_time = time(NULL);

        if ((channel->buffer = malloc(channel->buffer_size)) == NULL) {
            perror("malloc");
            free(channel);
            continue;
        }

        log_message(log, "Channel initialized: id=%d buffer_size=%zu", channel->id, channel->buffer_size);

        int socket_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (socket_fd == -1) {
            perror("socket");
            free(channel->buffer);
            free(channel);
            continue;
        }

        struct sockaddr_in remote_addr = {0};
        memset(&remote_addr, 0, sizeof(remote_addr));
        remote_addr.sin_family = AF_INET;
        remote_addr.sin_port = htons(REMOTE_SERVER_PORT);
        inet_pton(AF_INET, REMOTE_SERVER_IP, &remote_addr.sin_addr);

        if (connect(socket_fd, (struct sockaddr *)&remote_addr, sizeof(remote_addr)) == -1) {
            close(socket_fd);
            perror("connect");
            free(channel->buffer);
            free(channel);
            continue;
        }

        channel->socket_fd = socket_fd;

        *channels++ = channel;
    }
}
```

