import java.util.concurrent.TimeUnit;
import java.nio.charset.StandardCharsets;
import java.util.function.Consumer;

public class UserProfileLinkedList {
    private static final int NODE_COUNT = 1000000;
    private static final int MIN_VALUE = 0;
    private static final int MAX_VALUE = 100;
    private static final int MAX_NODE_STRING_LENGTH = 256;
    private static final Logger logger = new Logger(); // Hypothetical logging library
    private static final boolean USE_SECONDARY_LOGGER = false;
    private static final Archiver archiver = new Archiver();

    private static class Node {
        String profileData;
        int status;
        Node next;

        public Node(String profileData, int status) {
            this.profileData = new StringBuilder(Math.min(MAX_NODE_STRING_LENGTH, profileData.length()))
                    .append(profileData).toString();
            this.status = status;
            this.next = null;
        }
    }

    private static class LinkedList {
        Node head;
        Node tail;
        int nodeCount;

        public void append(Node node) {
            if (head == null) {
                head = node;
                tail = node;
            } else {
                tail.next = node;
                tail = node;
            }
            ++nodeCount;
        }
    }

    private static class ServiceTask implements Runnable {
        private final LinkedList linkedList;
        private final ConcurrentLinkedQueue<Runnable> tasks;
        private final ExecutorService executor;

        public ServiceTask(LinkedList linkedList, ConcurrentLinkedQueue<Runnable> tasks, ExecutorService executor) {
            this.linkedList = linkedList;
            this.tasks = tasks;
            this.executor = executor;
        }

        @Override
        public void run() {
            startService();
            while (!shouldStop()) {
                try {
                    TimeUnit.MILLISECONDS.sleep(new Random().nextInt(1000)); // Random delay between starts
                } catch (InterruptedException e) {}
                stopService();
            }
        }

        private void startService() {
            List<Node> nodesToCreate = new ArrayList<>(NODE_COUNT);
            for (int i = 0; i < NODE_COUNT; ++i) {
                nodesToCreate.add(null);
            }
            for (int i = 0; i < NODE_COUNT; ++i) {
                if (nodesToCreate.get(i) == null) {
                    int status = new Random().nextInt(MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
                    String profileData = "User Profile Data"; // Dynamically allocated string
                    nodesToCreate.set(i, new Node(profileData, status));
                }
            }
            LinkedList linkedList = this.linkedList;
            for (Node node : nodesToCreate) {
                if (node != null) {
                    linkedList.append(node);
                }
            }
            logStatistics();
        }

        private void stopService() {
            // Send a message to the messaging system when the service is stopped
            // ...
            this.tasks.add(() -> {
                archiver.archiveNodes(linkedList);
                for (Node node = head; node != null; node = node.next) {
                    freeMemory(node.profileData);
                    node.profileData = null;
                }
            });
        }

        private boolean shouldStop() {
            // Condition to stop the service, based on network latency or service interruptions from the logging service
            // ...
            return false;
        }
    }

    public static void main(String[] args) {
        ConcurrentLinkedQueue<Runnable> tasks = new ConcurrentLinkedQueue<>();
        ExecutorService executor = Executors.newCachedThreadPool();
        LinkedList linkedList = new LinkedList();

        ServiceTask serviceTask = new ServiceTask(linkedList, tasks, executor);
        tasks.add(serviceTask);
        executor.execute(serviceTask);
    }

    private static void freeMemory(Object obj) {
        if (obj != null) {
            if (obj instanceof Node) {
                freeMemory(((Node) obj).profileData);
            } else if (obj instanceof byte[]) {
                // Free memory for byte arrays, if necessary
            }
            System.gc();
        }
    }

    private static void logStatistics() {
        int nodeCount = linkedList.nodeCount;
        int sumStatus = 0;
        double averageStatus;

        Node currentNode = head;
        for (int i = 0; i < nodeCount; ++i) {
            sumStatus += currentNode.status;
            if (currentNode.next != null) {
                currentNode = currentNode.next;
            }
        }
        averageStatus = (double) sumStatus / nodeCount;

        byte[] profileDataBytes = currentNode.profileData.getBytes(StandardCharsets.UTF_8);
        logger.logTotalNodeCount(nodeCount);
        logger.logAverageStatus(averageStatus);
        logger.logUserProfileData(new String(profileDataBytes, StandardCharsets.UTF_8));

        if (USE_SECONDARY_LOGGER) {
            SecondaryLogger.logTotalNodeCount(nodeCount);
            SecondaryLogger.logAverageStatus(averageStatus);
            SecondaryLogger.logUserProfileData(new String(profileDataBytes, StandardCharsets.UTF_8));
        }
    }
}
