using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Serialization;
using System.Text;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json.Linq;

public class XPathQuery
{
    private readonly XmlReaderSettings _xmlReaderSettings;
    private readonly XmlSerializerSettings _xmlSerializerSettings;
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, XDocument> _cache = new Dictionary<string, XDocument>();

    public XPathQuery()
    {
        _xmlReaderSettings = new XmlReaderSettings
        {
            ConformanceLevel = ConformanceLevel.Fragment,
            Async = true,
            DtdProcessing = DtdProcessing.Parse,
            IgnoreWhitespace = true,
            IgnoreComments = true
        };

        _xmlSerializerSettings = new XmlSerializerSettings
        {
            IgnoreEmptyElements = true,
            Converters = { new XmlStringConverter() },
            AsynchronousProcessing = true
        };

        _httpClient = new HttpClient();
    }

    public async Task<List<XElement>> QueryAsync(string input, string elementName, string namespaceUri = null, params string[] attributes)
    {
        var logMessage = $"Querying for '{elementName}' in '{input}'. Namespace: '{namespaceUri}', Attributes: [{string.Join(", ", attributes)}]";
        Console.WriteLine(logMessage);

        if (_cache.TryGetValue(input, out var cachedDocument))
        {
            return QueryFromCachedDocument(cachedDocument, elementName, namespaceUri, attributes);
        }

        try
        {
            if (input.StartsWith("{")) // JSON input
            {
                var json = JToken.Parse(input);
                var xml = serializeToXml(json);
                await processDocumentAsync(xml, elementName, namespaceUri, attributes);
            }
            else // XML input
            {
                await processDocumentAsync(XDocument.Load(new StringReader(input)), elementName, namespaceUri, attributes);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return new List<XElement>();
        }
    }

    private async Task processDocumentAsync(XmlReader reader, string elementName, string namespaceUri, params string[] attributes)
    {
        var document = await XDocument.LoadAsync(reader, _xmlReaderSettings).ConfigureAwait(false);
        await QueryFromDocumentAsync(document, elementName, namespaceUri, attributes);
    }

    private async Task QueryFromDocumentAsync(XDocument document, string elementName, string namespaceUri, params string[] attributes)
    {
        var matches = document.XPathSelectElements($"{namespaceUri ?? string.Empty}:{elementName}", _xmlReaderSettings).ToList();

        if (!matches.Any())
        {
            Console.WriteLine($"No matching elements found.");
            return;
        }

        var results = QueryFromDocument(document, elementName, namespaceUri, attributes);
        await CacheResults(document, results);
    }

    private List<XElement> QueryFromCachedDocument(XDocument cachedDocument, string elementName, string namespaceUri, params string[] attributes)
    {
        return QueryFromDocument(cachedDocument, elementName, namespaceUri, attributes);
    }

    private List<XElement> QueryFromDocument(XDocument document, string elementName, string namespaceUri, params string[] attributes)
    {
        var matches = document.Root.XPathSelectElements($"{namespaceUri ?? string.Empty}:{elementName}", _xmlReaderSettings).ToList();

        if (!matches.Any()) return new List<XElement>();

        return matches.Where(x => attributes.All(a => x.Attribute(a) != null)).ToList();
    }

    private XDocument serializeToXml(JToken token, string rootName = "root")
    {
        var xmlSerializer = new XmlSerializer(token.GetType());
        using (var writer = new StringWriter())
        {
            xmlSerializer.Serialize(writer, token);
