        _cache = MemoryCache.Default;
        _cacheValidity = new ConcurrentDictionary<string, DateTime>();
    }

    private async Task<HttpResponseMessage> SendRequestAsync(string method, string url, string requestBody)
    {
        using (var client = new ChannelFactory<IExternalService>(new BasicHttpBinding(), new EndpointAddress(url)))
        {
            var proxy = client.CreateChannel();
            return await _httpClient.PostAsync(url, new StringContent(requestBody));
        }
    }

