    }

    public async Task<OperationResponse> HandleRequestAsync(string sessionId, string requestType, string resourceId)
    {
        var cacheKey = $"{requestType}_{resourceId}";
        if (_cacheValidity.TryGetValue(cacheKey, out DateTime validity) && validity > DateTime.UtcNow)
        {
            LogActivity($"Retrieved from cache: {requestType}", resourceId);
            return _cache[cacheKey];
        }

        var response = await HandleRequestInternalAsync(sessionId, requestType, resourceId);
        if (response.Success)
        {
            _cache.Insert(cacheKey, response, new CacheItemPolicy()
            {
                AbsoluteExpiration = DateTime.UtcNow.AddMinutes(10),
                Priority = CacheItemPriority.Default
            });
            _cacheValidity[cacheKey] = DateTime.UtcNow;
        }

        return response;
    }

    private async Task<OperationResponse> HandleRequestInternalAsync(string sessionId, string requestType, string resourceId)
    {
        var url = "https://external-service.com/api";
        var requestBody = JsonConvert.SerializeObject(new RequestData
        {
            SessionId = sessionId,
            Type = requestType,
            ResourceId = resourceId
        });

        var response = await SendRequestAsync("POST", $"{url}/{requestType}/{resourceId}", requestBody);
        if (!response.IsSuccessStatusCode)
        {
            LogActivity($"Error in external service: {response.StatusCode}", resourceId);
            return new OperationResponse { Success = false };
        }

        var responseData = await response.Content.ReadAsAsync<OperationResponse>();
        if (!responseData.Success)
        {
            LogActivity("External service failed to process request", resourceId);
            return responseData;
        }

        // Implement race condition management and atomic operations here using your preferred approach (e.g. lock, Interlocked, etc.)

        if (requestType == "update" && responseData.UpdatedAt > DateTime.UtcNow)
        {
            LogActivity("Race condition detected: data may be stale", resourceId);
            return HandleRequestInternalAsync(sessionId, requestType, resourceId); // Retry the operation
        }

        return responseData;
    }
}

public class RequestData
{
    public string SessionId { get; set; }
    public string Type { get; set; }
    public string ResourceId { get; set; }
}

public class OperationResponse
{
    public bool Success { get; set; }
    public DateTime UpdatedAt { get; set; } // Use this field to handle race conditions and data integrity
}
