```csharp
public class RateLimitingMiddleware : IMiddleware
{
    private readonly IRateLimiter _rateLimiter;
    private readonly ILogger<RateLimitingMiddleware> _logger;

    public RateLimitingMiddleware(IRateLimiter rateLimiter, ILogger<RateLimitingMiddleware> logger)
    {
        _rateLimiter = rateLimiter;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        var userRole = context.User.Claims.FirstOrDefault(c => c.Type == "role")?.Value;

        // Apply rate limiting based on user role and other factors
        if (!await _rateLimiter.CheckRateLimit(userRole))
        {
            _logger.LogWarning("Request denied due to rate limiting.");
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(JsonSerializer.Serialize(new { error = "Rate limit exceeded" }));
            return;
        }

        // Proceed with the request processing
        await next(context);
    }
}
