    let sidebarHtml = '<div id="sidebar" style="' + (showSidebar ? '' : 'display: none;') + '">';

    widgets.forEach((widget, index) => {
        const id = `widget-${widget.name.toLowerCase().replace(/\W+/g, '-')}`;
        let widgetHtml = '<div id="' + id + '" data-type="' + widget.type + '"></div>';

        if (renderedWidgets.has(id)) {
            const storedVersion = renderedWidgets.get(id);
            if (settingsVersion === storedVersion) return; // No need to re-render if the same version
        }

        try {
            loadedScripts = [];
            widget.dependencies.forEach((dep) => {
                const scriptTag = document.createElement('script');
                scriptTag.src = `https://cdn.example.com/widgets/${dep}.js`;
                scriptTag.onload = () => {
                    loadedScripts.push(dep);
                  if (loadedScripts.length === widget.dependencies.length) initializeWidget(id, widget);
                };
                document.head.appendChild(scriptTag);
            });
        } catch (error) {
            console.error(`Error loading dependencies for widget "${widget.name}":`, error);
        }

        sidebarHtml += widgetHtml;
    });

    if (!loadedScripts || loadedScripts.length === 0) {
        widgets.forEach((widget, index) => {
            initializeWidget(`widget-${widget.name.toLowerCase().replace(/\W+/g, '-')}`, widget);
            sidebarHtml += '<div id="' + `widget-${widget.name.toLowerCase().replace(/\W+/g, '-')}` + '" data-type="' + widget.type + '"></div>';
        });
    }

    sidebarHtml += '</div>';

    function initializeWidget(id, widget) {
        const widgetDiv = document.getElementById(id);
        if (!widgetDiv) return;

        try {
            // Validate and set the widget's settings here
            let validatedSettings = validateSettings(widget.settings);
            widget.initialize({ ...validatedSettings, id });
        } catch (error) {
            console.error(`Error initializing widget "${widget.name}":`, error);
            sidebarHtml += `<p style="color: red;">An error occurred while initializing the widget: ${error}</p>`;
            return;
        }
    }

    function validateSettings(settings) {
        // Add your validation logic here
        if (!settings || !Array.isArray(settings)) throw new Error('Invalid settings object');
        return settings;
    }

    renderedWidgets.set(id, (settingsVersion || 1));
    return sidebarHtml;
}
