    int socket;
    pthread_mutex_t health_check_lock;
    time_t last_health_check;
} DataChannel;

int setupDataTransferChannels(int max_channels, int* error_codes) {
    DataChannel channels[max_channels];
    sem_t channel_limit;
    pthread_mutex_t system_health_lock;
    int active_connections = 0;
    int total_connections = 0;
    int retry_count = 3;
    double buffer_multiplier = 1.5;
    sem_init(&channel_limit, 0, max_channels);
    pthread_mutex_init(&system_health_lock, NULL);

    for (int i = 0; i < max_channels; ++i) {
        if (sem_trywait(&channel_limit)) {
            // Channel limit reached, no new connections allowed.
            error_codes[i] = EBUSY;
            continue;
        }

        channels[i].id = i;
        channels[i].buffer_size = (size_t)pow(buffer_multiplier, active_connections);
        channels[i].buffer = malloc(channels[i].buffer_size);
        if (!channels[i].buffer) {
            error_codes[i] = ENOMEM;
            continue;
        }

        sem_init(&channels[i].ref_count, 0, 1);
        time(&channels[i].last_health_check);

        int server_addr_len = sizeof(struct sockaddr_in);
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, server_addr_len);
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(54321); // Replace with your server port
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            error_codes[i] = errno;
            continue;
        }

        if (connect(sockfd, (struct sockaddr*)&server_addr, server_addr_len) < 0) {
            close(sockfd);
            for (int j = retry_count; j > 0; --j) {
                sleep(1 << (retry_count - j));

                if (!connect(sockfd, (struct sockaddr*)&server_addr, server_addr_len)) {
                    break;
                }
            }

            if (connnect(sockfd, (struct sockaddr*)&server_addr, server_addr_len) < 0) {
                error_codes[i] = ECONNREFUSED;
                close(sockfd);
                continue;
            }
        }

        channels[i].socket = sockfd;
        ++active_connections;
        ++total_connections;

        // Log initialization details, connection status, and errors
        log_data_channel_init(i, active_connections, total_connections, error_codes[i]);
    }

    pthread_t health_check_thread;
    int health_check_interval = 60; // seconds
    pthread_create(&health_check_thread, NULL, monitor_system_health, &system_health_lock);

    return 0;
}

