    static std::mutex mtx; // Thread safety
    std::vector<std::unique_ptr<char[], std::free_delete<>>> compressedMemoryPool;

    if (searchStr.empty() || insertBeforeStr.empty()) {
        throw std::invalid_argument("Search and Insert strings must not be empty.");
    }

    auto it = messages.begin();
    Message* insertPoint = nullptr;

    // Find the first occurrence of searchStr in the list
    for (; it != messages.end(); ++it) {
        if (it->id == searchStr) {
            insertPoint = &*it;
            break;
        }
    }

    if (insertPoint == nullptr) { // Insert at the end if not found
