[' ```javascript
let matchedElements = [];
const traverse = (node, selector) => {
  if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

  if (node.matches && node.matches(selector)) {
    matchedElements.push(node);
  }

  const children = Array.from(node.children);

  // Use a Set to avoid duplicate entries due to deep recursion
  const seen = new Set();
  children.forEach((child) => {
    if (!seen.has(child)) {
      seen.add(child);
      traverse(child, selector);
    }
  });
};

const collectElements = (rootNode, selector) => {
  matchedElements = [];
  const observer = new MutationObserver(() => {
    // Clear the observer after the initial traversal to avoid infinite loops
    observer.disconnect();

    traverse(rootNode, selector);
  });

  observer.observe(rootNode, { childList: true, subtree: true });
  return matchedElements;
};
```']

