class DependencyGraph {
  constructor() {
    this.nodes = new Map();
  }

  addNode(node) {
    if (!this.nodes.has(node)) {
      this.nodes.set(node, { dependencies: [], data: null });
    }
  }

  addDependency(from, to) {
    const node = this.nodes.get(from);
    if (node && !node.dependencies.includes(to)) {
      node.dependencies.push(to);
    }
  }

  async loadAndExecute(startNode) {
    // Load dependencies first, then execute the requested file
    const queue = [startNode];

    while (queue.length) {
      const current = queue.shift();
      if (!this.nodes.has(current)) {
        this.addNode(current);
      }
      const nodeData = this.nodes.get(current).data;
      if (!nodeData) {
        try {
          nodeData = await fetchBinaryFile(current);
          this.nodes.get(current).data = nodeData;
        } catch (error) {
          console.error(`Error loading file ${current}:`, error);
        }
      }

      if (!nodeData) continue;

      queue.push(...this.nodes.get(current).dependencies.filter(dep => !this.nodes.has(dep)));
      executeBinaryFile(nodeData);
    }
  }
}
