['```java
import java.util.concurrent.*;
import java.nio.channels.*;
import javax.annotation.*;
import com.google.common.util.concurrent.*;

public class ConnectionManager {

    private final ExecutorService executor;
    private final BlockingQueue<ConnectionHandle> connectionPool;
    private final int maxConnections;
    private final long connectionTimeoutMillis;
    private final TimeUnit connectionTimeoutUnit;
    private final Function<String, Future<ConnectionHandle>> connectionProvider;
    private final BiConsumer<ConnectionHandle, Throwable> connectionHandler;

    public ConnectionManager(int maxConnections, long connectionTimeoutMillis, TimeUnit connectionTimeoutUnit, Function<String, Future<ConnectionHandle>> connectionProvider, BiConsumer<ConnectionHandle, Throwable> connectionHandler) {
        this.maxConnections = maxConnections;
        this.connectionTimeoutMillis = connectionTimeoutMillis;
        this.connectionTimeoutUnit = connectionTimeoutUnit;
        this.connectionProvider = connectionProvider;
        this.connectionHandler = connectionHandler;
        this.executor = Executors.newFixedThreadPool(maxConnections);
        this.connectionPool = new LinkedBlockingQueue<>(maxConnections);
    }

    public ConnectionHandle getConnection(@Nonnull String serverUrl) throws InterruptedException, ExecutionException {
        Future<ConnectionHandle> connectionFuture = connectionProvider.apply(serverUrl);
        ConnectionHandle connection = connectionFuture.get(connectionTimeoutMillis, connectionTimeoutUnit);
        if (connection == null) {
            // Failed to get a connection from the provider, return null or throw an exception
            throw new RuntimeException("Failed to create a connection to " + serverUrl);
        }

        if (!connectionPool.offer(connection)) {
            // The connection pool is full, add the connection to executor for processing
            executor.submit(() -> connectionPool.put(connection));
        }

        return connection;
    }

    public void shutdown() throws InterruptedException {
        executor.shutdownNow();

        while (!connectionPool.isEmpty()) {
            ConnectionHandle connection = connectionPool.take();
            connectionHandler.accept(connection, new RuntimeException("Forced shutdown"));
        }
    }
}

class ConnectionHandle {
    private final SocketChannel socket;
    // Add any performance and health monitoring logic here

    public ConnectionHandle(@Nonnull SocketChannel socket) {
        this.socket = socket;
    }

    // Implement methods for reading, writing, and closing the connection here
}
```
This code provides a basic implementation of a ConnectionManager class that manages multiple concurrent connections to a remote server using non-blocking I/O (SocketChannel) and a custom thread pool (ExecutorService). The ConnectionManager handles connection pooling, retry logic for failed connections, and graceful shutdown of resources. It also includes a simple mechanism to monitor the health and performance of each active connection.

The ConnectionHandle class represents an individual connection to the remote server, with methods for reading, writing, and closing the connection. You should extend this class and add any necessary monitoring logic for performance and health checks.']

