private val executor = Executors.newSingleThreadExecutor()

fun checkAndCreateThemeDirectory() {
    val themeDirPath = Paths.get(THEME_DIR)
    if (!Files.exists(themeDirPath)) {
        Files.createDirectories(themeDirPath)
        Files.setPosixFilePermissions(themeDirPath, java.nio.file.PosixFilePermission.OWNER_READ, java.nio.file.PosixFilePermission.OWNER_WRITE)
    }
}

fun loadTheme(themeName: String): Bitmap? {
    val themeCacheKey = "${THEME_DIR}/$themeName"
    if (themeCache.containsKey(themeCacheKey)) {
        return themeCache[themeCacheKey]
    }

    val themeFile = File(themeCacheKey)
    if (!themeFile.exists() || !themeFile.isFile || !themeFile.canRead()) {
        return null
    }

    try {
        val inputStream = FileInputStream(themeFile)
        val bitmap = BitmapFactory.decodeStream(inputStream)
        themeCache[themeCacheKey] = bitmap
        return bitmap
    } catch (e: Exception) {
        // Handle corrupted cache file recovery or cleaning here
    }

    return null
}

fun saveTheme(themeName: String, themeBitmap: Bitmap) {
    val themeCacheKey = "${THEME_DIR}/$themeName"
    File(themeCacheKey).parentFile.mkdirs()
    val outputStream = FileOutputStream(themeCacheKey)
    themeBitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream)
}

fun cleanExpiredThemes() {
    var currentSize = 0
    themeCache.forEach { (_, bitmap) ->
        if (!bitmap.isRecycled && bitmap.width > 0 && bitmap.height > 0) {
            currentSize += bitmap.byteCount
        } else {
            bitmap.recycle()
            themeCache.remove(it.key)
        }
    }

    if (currentSize > CACHE_THRESHOLD) {
        executor.submit {
            while (currentSize > CACHE_THRESHOLD) {
                var leastRecentlyUsed: MutableMap.MutableEntry<String, Bitmap>? = null
                themeCache.forEach { (key, value) ->
                    if (leastRecentlyUsed == null || System.currentTimeMillis() - it.value2 > leastRecentlyUsed!!.value2) {
                        leastRecentlyUsed = it
                    }
                }

                leastRecentlyUsed?.let { entry ->
                    val themeCacheKey = "${THEME_DIR}/${entry.key}"
                    File(themeCacheKey).delete()
                    themeCache.remove(entry.key)
                    currentSize -= entry.value.byteCount
                }
            }
        }
    }
}

fun start() {
    checkAndCreateThemeDirectory()
    cleanExpiredThemes()
}
```

This code provides a basic implementation for the specified requirements, including:

