Record* create_record_array(long *offsets, int *keys, unsigned long max_records) {
    Record *records = (Record *)malloc(max_records * sizeof(Record));
    if (!records) {
        perror("Error allocating memory for records\n");
        return NULL;
    }

    long *record_offsets = malloc((max_records + 1) * sizeof(long));
    if (!record_offsets) {
        perror("Error allocating memory for record offsets\n");
        free(records);
        return NULL;
    }

    int *record_keys = malloc(max_records * sizeof(int));
    if (!record_keys) {
        perror("Error allocating memory for record keys\n");
        free(record_offsets);
        free(records);
        return NULL;
    }

    long current_offset = 0;
    for (unsigned long i = 0; i < max_records; ++i) {
        current_offset = record_offsets[i] = current_offset + offsets[i];
        records[i].key = keys[record_keys[i] = i];

        // Generate random string within the given range.
        char c;
        for (int j = 0; j < rand() % 256; ++j) {
            c = rand() % 128 + 33;
            records[i].string[j] = c;
            records[i].string[j+1] = '\0';
        }
    }

    free(offsets);
    free(keys);
    record_offsets[max_records] = current_offset;

    return records;
}
