#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
    char str[1024];
    void* metadata; // Reference-counted pointer to additional metadata structure
} record;

typedef struct metadata_s {
    // Additional metadata structure
} metadata;

struct set {
    int id;
    size_t max_str_len;
    size_t num_records;
    record* records;
    pthread_mutex_t lock;
};

struct processed_data {
    struct set** sets; // Each set is a unique ID prefix and maximum string length
    size_t num_sets;
};

// Function to generate random number within a specified range
double rand_range(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

void* process_record_set(void* arg) {
    struct set* set = arg;
    for (size_t i = 0; i < set->num_records; ++i) {
        set->records[i].value = rand_range(-100, 100);
        // Populate the string field with random characters
        for (size_t j = 0; j < set->max_str_len; ++j)
            set->records[i].str[j] = (char)(rand() % 26 + 'a');
        set->records[i].metadata = malloc(sizeof(metadata)); // Allocate metadata structure
    }
    return NULL;
}

struct processed_data* process_record_sets(size_t num_sets, size_t max_str_len) {
    struct processed_data* result = malloc(sizeof(*result));
    result->num_sets = num_sets;
    result->sets = calloc(num_sets, sizeof(struct set*));

    for (size_t i = 0; i < num_sets; ++i) {
        struct set* set = &(result->sets[i]);
        set->id = i * 100 + 1; // Unique ID prefix and maximum string length
        set->max_str_len = max_str_len;
        set->num_records = rand() % 1000 + 1; // Number of records in each set is random
        set->records = malloc(set->num_records * sizeof(record));
        pthread_mutex_init(&set->lock, NULL);
    }

    pthread_t threads[num_sets];
    for (size_t i = 0; i < num_sets; ++i) {
        pthread_create(&threads[i], NULL, process_record_set, &(result->sets[i]));
    }

    // Wait for all threads to finish execution
    for (size_t i = 0; i < num_sets; ++i) {
        pthread_join(threads[i], NULL);
    }

    return result;
}
```

