class SessionAnalyzer {
    private int sequenceNumber;
    private long comparisonTime;
    private ConcurrentHashMap<String, LinkedHashMap<Long, Long>> sessions;
    private File file;

    public void analyzeFile(String filename) throws IOException {
        this.file = new File(filename);
        Scanner scanner = new Scanner(this.file);
        this.sequenceNumber = Integer.parseInt(scanner.nextLine());

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Future<Void>> futures = new ArrayList<>();

        try (BufferedReader reader = Files.newBufferedReader(this.file, StandardCharsets.UTF_8)) {
            LineNumberReader lineNumberReader = new LineNumberReader(reader);
            String line;
            while ((line = lineNumberReader.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length == 3) { // username, email, timestamp
                    String hashKey = getHash(parts[0]);
                    Long timestamp = Long.parseLong(parts[2]);

                    AtomicLong lastLogin = new AtomicLong();
                    ExecutorCompletionService<Void> service = new ExecutorCompletionService<>(executor);

                    Callable<Void> task = () -> {
                        if (sessions.containsKey(hashKey)) {
                            LinkedHashMap<Long, Long> deviceSessions = sessions.get(hashKey);
                            lastLogin.compareAndSet(0, deviceSessions.lastEntry().getValue());
                        }
                        return null;
                    };

                    futures.add(service.submit(task));
                }
            }

            for (Future<Void> future : futures) {
                try {
                    lastLogin = future.get().lastLogin();
                } catch (ExecutionException | InterruptedException e) {
                    e.printStackTrace();
                }
            }

            // Analyze sessions, extract sequence number and log comparison time.
        }

        executor.shutdown();
    }

    private String getHash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            BigInteger bigInt = new BigInteger(1, digest);
            String hashedHex = bigInt.toString(16);
            while (hashedHex.length() < 32) {
                hashedHex = "0" + hashedHex;
            }
            return hashedHex.substring(0, 8) + "-" + hashedHex.substring(8, 20) + "-" + hashedHex.substring(20);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return "";
        }
    }
}
