        }
        std::unique_lock<std::mutex> lck(mtx);
        // Perform your tasks on this pdu here
        lck.unlock();
    }
}

void start() {
    size_t threads = std::thread::hardware_concurrency();
    ioService.reset(new boost::asio::io_service());
    for (size_t i = 0; i < threads; ++i) {
        std::thread{worker, std::ref(*ioService)}.detach();
    }
}

void stop() {
    ioService->stop();
    for (auto& thread : std::vector<std::thread>(threads)) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}
