    public void analyzeFile(String filename) throws IOException {
        Map<Integer, LinkedHashMap<Long, Long>> userSessions = new ConcurrentHashMap<>();
        PriorityQueue<Map.Entry<Long, Long>> comparisons = new PriorityQueue<>((a, b) -> (int)(b.getValue() - a.getValue()));

        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(",");
                int userId = Integer.parseInt(parts[0]);
                long timestamp = Long.parseLong(parts[1]);

                userSessions.computeIfAbsent(userId, k -> new LinkedHashMap<>()).put(timestamp, timestamp);
                comparisons.add(new AbstractMap.SimpleEntry<>(timestamp, timestamp));
            }
        }

        long startTime = System.currentTimeMillis();
        while (!comparisons.isEmpty()) {
            Map.Entry<Long, Long> entry = comparisons.poll();
            for (Map.Entry<Integer, LinkedHashMap<Long, Long>> user : userSessions.entrySet()) {
                long current = entry.getKey();
                long previous = user.getValue().get(current);
                if (Objects.nonNull(previous) && Math.abs((current - previous) / 86400000L) <= 1) {
                    LinkedHashMap<Long, Long> sessions = user.getValue();
                    long newSessionId = sessions.get(current);
                    if (newSessionId != current) { // Multiple sessions for a single user, track them as separate sessions
                        sessions.put(current, current);
                    }
                }
            }
        }
        System.out.println("Time taken for comparisons: " + (System.currentTimeMillis() - startTime) + "ms");

