    child_pid = fork();
    if (child_pid == -1) {
        perror("fork");
        return;
    }

    if (!child_pid) {
        close(pipefd[READ_END]);
        dup2(pipefd[WRITE_END], STDOUT_FILENO);
        execl("/bin/sh", "/bin/sh", "-c", command, NULL);
