        Ok(f) => f,
        Err(e) => return Err(Box::new(e)),
    };

    let (mut reader, mut lines) = input.lines().split_at(10); // Chunk-based processing
    let chunk_size = 10;

    let log_file = match opt.output.as_deref() {
        Some("stdout") => &mut std::io::stderr(),
        Some(path) => File::create(path)?,
        None => return Err(Box::new(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Missing log output path"))),
    };

    let mut log = LogWriter::new(log_file);

    tokio::task::spawn_blocking(move || process_chunks(&mut reader, chunk_size, &opt, &mut log))
        .await
        .unwrap();

    Ok(())
}

fn print_usage() {
    // Implement detailed usage information here
}

async fn process_chunks<R: BufRead>(reader: &mut R, chunk_size: usize, opt: &Opt, log: &mut LogWriter) {
    let mut line_count = AtomicUsize::new(0);
    let mut total_matches = AtomicUsize::new(0);

    loop {
        match reader.read_line(|buf| async move { Ok::<String, std::io::Error>(buf.into_owned()) })
            .await
            .map_err(|e| e.into())
        {
            Ok(line) => {
                // Implement pattern matching, duplicate detection, progress bar, etc., here

                line_count.fetch_add(1, Ordering::Relaxed);

                if should_match(&opt.format, &line) {
                    total_matches.fetch_add(1, Ordering::Relaxed);
                }

                log.log(&line, line_count.load(Ordering::Relaxed));
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::UnexpectedEof {
                    break;
                } else {
                    return Err(Box::new(e));
                }
            }
        }

        if reader.len() < chunk_size as u64 {
            break;
        }

        let (mut reader2, lines) = reader.split_at_mut(chunk_size);
        std::mem::swap(&mut reader, reader2);
    }
}

