    RecordSet* rs = (RecordSet*)malloc(sizeof(RecordSet));
    strncpy(rs->prefix, prefix, sizeof(rs->prefix));
    rs->max_length = max_length;
    pthread_mutex_init(&rs->lock, NULL);
    rs->records = NULL;
    rs->capacity = 0;
    rs->count = 0;
    return rs;
}

MemPool* create_mem_pool(size_t size) {
    MemPool* mp = (MemPool*)malloc(sizeof(MemPool));
    mp->buffer = malloc(size);
    mp->size = size;
    mp->used = 0;
    return mp;
}

void destroy_mem_pool(MemPool* mem_pool) {
    free(mem_pool->buffer);
    free(mem_pool);
}

ProcessData* init_process_data(RecordSet* record_set, MemPool* mem_pool) {
    ProcessData* pd = (ProcessData*)malloc(sizeof(ProcessData));
    pd->record_set = record_set;
    pd->mem_pool = mem_pool;
    return pd;
}

void* process_function(void* data) {
