    ...
    return NULL;
}

RecordSet** manage_record_sets(size_t num_record_sets, RecordSet** record_sets) {
    pthread_t threads[num_record_sets];
    ProcessData* process_data[num_record_sets];
    for (int i = 0; i < num_record_sets; ++i) {
        process_data[i] = init_process_data(record_sets[i], create_mem_pool(sizeof(Record)));
    }

    for (int i = 0; i < num_record_sets; ++i) {
