['```java
import java.io.*;
import java.net.HttpURLConnection;
import java.security.*;
import java.security.cert.CertificateFactory;
import java.util.*;
import org.neo4j.graphdb.*;
import org.neo4j.graphdb.factory.GraphDatabaseFactory;

public static void processOAuthRequest(String oauthRequest) {
    GraphDatabaseService db = new GraphDatabaseFactory().newEmbeddedDatabase("test");
    try {
        HttpURLConnection connection = (HttpURLConnection) new URL(oauthRequest).openConnection();
        connection.setRequestMethod("GET");

        // Cache management
        Map<String, CachedEndpoint> cachedEndpoints = new HashMap<>();
        if (cachedEndpoints.containsKey(oauthRequest)) {
            connection = cachedEndpoints.get(oauthRequest).getConnection();
        }

        int maxRetries = 3;
        for (int i = 0; i < maxRetries; i++) {
            try {
                // Fetch private key and certificate from secure endpoint
                InputStream isKey = connection.getInputStream();
                PublicKey publicKey = KeyFactory.getInstance("RSA").generatePublic(CertificateFactory.getInstance("X.509")
                        .generateCertificate(isKey));
                InputStream isCert = connection.getInputStream();
                CertificateFactory certFactory = CertificateFactory.getInstance("X.509");
                X509Certificate cert = (X509Certificate) certFactory.generateCertificate(isCert);

                // Validate certificate integrity
                if (!cert.getPublicKey().equals(publicKey)) {
                    throw new IllegalArgumentException("Invalid certificate");
                }

                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                Certificate[] chain = new Certificate[]{cert};
                cert.getIssuerX500Principal().getName("CN")
                        .equalsIgnoreCase(cert.getSubjectX500Principal().getName("CN")) ?
                        baos.write(cert.getEncoded()) : baos.write(chain);
                baos.write((KeyPair.getPrivate().getEncoded()));

                // Generate random vertices and edges within given range based on response size
                int numVertices = (int) Math.min(Math.max(10, connection.getContentLength() / 1024), 50);
                Random r = new Random();
                for (int j = 0; j < numVertices; j++) {
                    db.execute("CREATE (v:Vertex {prop: " + r.nextInt(100) + "})");
                    List<Node> nodes = db.findNodes("Vertex", new Properties().setProperty("prop", j));
                    Node node = nodes.get(r.nextInt(nodes.size()));
                    for (int k = 0; k < r.nextInt(numVertices / 2); k++) {
                        db.execute("MATCH (a:Vertex), (b:Vertex) WHERE a <> b " +
                                "WHERE RAND() < 0.5 " +
                                "CREATE (a)-[:EDGE {prop: " + r.nextInt(100) + "}]->(b)");
                    }
                }

                // Link PEM file to nodes and edges
                String pemFile = "pem_file.pem";
                FileOutputStream fos = new FileOutputStream(pemFile);
                baos.writeTo(fos);
                db.execute("CREATE INDEX ON :Vertex (prop)");
                db.execute("LOAD CSV WITH HEADERS FROM 'file:///" + pemFile + "' AS line " +
                        "WITH tokens(line.key) AS keys, line.value AS value, keys[0] AS type, keys[1] as name " +
                        "WHERE type IN ['Certificate', 'PrivateKey'] " +
                        "CREATE (node:Vertex {name: name}) " +
                        "WITH node, value " +
                        "SET node.data = value " +
                        "RETURN node");

                // Cache management
                if (!cachedEndpoints.containsKey(oauthRequest)) {
                    cachedEndpoints.put(oauthRequest, new CachedEndpoint(connection));
                }
                break;
            } catch (Exception e) {
                System.err.println("Error while processing OAuth request: " + e.getMessage());
                if (i < maxRetries - 1) {
                    Thread.sleep(1000);
                } else {
                    throw new RuntimeException("Failed to process OAuth request after maximum retries", e);
                }
            }
        }
    } catch (IOException | InterruptedException e) {
        System.err.println("Error while establishing connection or sleeping between retries: " + e.getMessage());
    } finally {
        db.shutdown();
    }
}

class CachedEndpoint {
    private HttpURLConnection connection;

    public CachedEndpoint(HttpURLConnection connection) {
        this.connection = connection;
    }

    public HttpURLConnection getConnection() {
        return connection;
    }
}
```']

