[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <sys/types.h>
#include <openssl/sha.h>

typedef struct {
    long long timestamp;
    int id;
    int weight;
} Transaction;

typedef struct HeapNode {
    Transaction transaction;
    struct HeapNode *left, *right;
} HeapNode;

HeapNode* create_heap_node(Transaction transaction) {
    HeapNode* node = (HeapNode*) malloc(sizeof(HeapNode));
    node->transaction = transaction;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void swap(HeapNode** a, HeapNode** b) {
    HeapNode* t = *a;
    *a = *b;
    *b = t;
}

int parent(int i) {
    return (i - 1) / 2;
}

int left_child(int i) {
    return 2 * i + 1;
}

int right_child(int i) {
    return 2 * i + 2;
}

void heapify(HeapNode** nodes, int size) {
    for (int i = size / 2 - 1; i >= 0; --i)
        sift_down(nodes, i, size);
}

void sift_up(HeapNode** nodes, int i, int size) {
    if (i == 0) return;

    HeapNode* parent = nodes[parent(i)];
    if (compare(&parent->transaction, &nodes[i]->transaction) < 0)
        swap(&nodes[parent->id], &nodes[i->id]);
    sift_up(nodes, parent->id, size);
}

void sift_down(HeapNode** nodes, int i, int size) {
    HeapNode* node = nodes[i];
    int maxIndex = i;

    int lc = left_child(i);
    if (lc < size && compare(&nodes[lc]->transaction) > 0)
        maxIndex = lc;

    int rc = right_child(i);
    if (rc < size && compare(&nodes[rc]->transaction) > 0)
        maxIndex = rc;

    if (maxIndex != i) {
        swap(&nodes[i], &nodes[maxIndex]);
        sift_down(nodes, maxIndex, size);
    }
}

int compare(Transaction* a, Transaction* b) {
    return a->weighted_sum - b->weighted_sum;
}

long long current_timestamp() {
    time_t now = time(NULL);
    struct tm *local = localtime(&now);
    return (long long) mktime(local);
}

void update_transaction_window(Transaction transaction, HeapNode*** nodes, int* size) {
    while (*size > 10 && ((*nodes)[0]->timestamp < current_timestamp() - 10)) {
        pop_heap(nodes, size);
    }

    push_heap(create_heap_node(transaction), nodes, size);
    heapify(*nodes, *size);
}

Transaction find_max_weighted_sum(HeapNode* nodes) {
    return nodes[0]->transaction;
}

void pop_heap(HeapNode** nodes, int* size) {
    HeapNode* last = nodes[--(*size)];
    if (*size > 0 && (*size) == 1) {
        free(last);
        return;
    }

    nodes[0] = last;
    sift_up(nodes, 0, *size);
}

void push_heap(HeapNode* node, HeapNode** nodes, int* size) {
    nodes = (HeapNode**)realloc(nodes, sizeof(HeapNode*) * (*size + 1));
    nodes[*size] = node;
    sift_up(nodes, *size, *size + 1);
}

void process_transaction(Transaction transaction, HeapNode*** nodes, int* size) {
    update_transaction_window(transaction, nodes, size);
}

int main() {
    // ... code for computing MD5 hash of a string parameter goes here ...

    Transaction transaction = { current_timestamp(), 123456789, 50 };
    HeapNode** nodes = NULL;
    int size = 0;

    process_transaction(transaction, &nodes, &size);

    // Code for accessing the top transaction and printing its ID and weighted sum goes here.
}
```

