using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DataProcessor
{
    public class Stage
    {
        protected Action<double> ProcessFunction;
        public virtual void Process(double data) => ProcessFunction(data);

        public override string ToString() => GetType().Name;
    }

    public abstract class TransformStage : Stage
    {
        protected Func<IEnumerable<double>, IEnumerable<double>> TransformationFunction;

        public override void Process(double data)
        {
            var list = new List<double> { data };
            ProcessInternal(list);
        }

        protected abstract void ProcessInternal(List<double> data);
    }

    public class FilterStage : TransformStage
    {
        private Func<double, bool> filter;

        public FilterStage(Func<double, bool> filter) => this.filter = filter;

        protected override void ProcessInternal(List<double> data) => data.Where(filter).ToList();
    }

    public class AggregateStage : TransformStage
    {
        private Func<IEnumerable<double>, double> aggregator;

        public AggregateStage(Func<IEnumerable<double>, double> aggregator) => this.aggregator = aggregator;

        protected override void ProcessInternal(List<double> data) => aggregator(data);
    }

    public class SmoothStage : TransformStage
    {
        private Func<IEnumerable<double>, IEnumerable<double>> smoother;

        public SmoothStage(Func<IEnumerable<double>, IEnumerable<double>> smoother) => this.smoother = smoother;

        protected override void ProcessInternal(List<double> data) => smoother(data).ToList();
    }

    public class DataProcessor
    {
        private readonly List<Stage> stages;
        private readonly bool logDataFlow;

        public DataProcessor(bool logDataFlow = false)
        {
            this.stages = new List<Stage>();
            this.logDataFlow = logDataFlow;
        }

        public void AddStage(Stage stage) => stages.Add(stage);

        public void RemoveStage(Stage stage) => stages.Remove(stage);

        public void ReplaceStage(Stage oldStage, Stage newStage)
        {
            if (stages.Contains(oldStage))
                stages[stages.IndexOf(oldStage)] = newStage;
            else
                throw new Exception("The specified stage is not in the pipeline.");
        }

        public void ValidatePipeline()
        {
            var validTypes = new HashSet<Type> { typeof(FilterStage), typeof(AggregateStage), typeof(SmoothStage) };
            if (!stages.All(s => validTypes.Contains(s.GetType())))
                throw new Exception("Invalid stage configuration.");
        }

        public void Execute(IEnumerable<double> dataStream)
        {
            ValidatePipeline();

            var processedData = dataStream;
            foreach (var stage in stages)
            {
                if (logDataFlow)
                    Console.WriteLine($"Data: {string.Join(", ", processedData)} -> Stage: {stage}");

                processedData = processedData.ToList();
                foreach (var d in processedData)
                    stage.Process(d);
            }
        }

        public override string ToString()
        {
            if (stages.Count == 0) return "Empty pipeline";

            var sb = new StringBuilder("Pipeline: [");
            for (var i = 0; i < stages.Count; i++)
                sb.Append(stages[i].ToString());
            sb.Append(']');
            return sb.ToString();
        }
    }
}
```
