    if (argc != 3) {
        printf("Usage: %s input_file output_stats\n", argv[0]);
        return 1;
    }

    int file_fd = open(argv[1], O_RDONLY | O_BINARY);
    if (file_fd == -1) {
        perror("open");
        return 2;
    }

    int stats_fd = creat(argv[2], S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (stats_fd == -1) {
        perror("creat");
        close(file_fd);
        return 3;
    }

    off_t bytes_read = 0;
    char buffer[TRANSACTION_SIZE];
    while ((bytes_read = read(file_fd, buffer, TRANSACTION_SIZE)) > 0) {
        if (bytes_read != TRANSACTION_SIZE) {
