        printf("Error: Unsupported number of bits per sample.\n");
        exit(1);
    }
    data.bits_per_sample = bits_per_sample;

    data.sample_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);

