std::shared_ptr<std::list<NetworkMessage>> initializeAndModifyMessageList(
        const std::string& firstString,
        const std::string& secondString,
        const std::string& thirdString) {
    static std::shared_ptr<std::deque<NetworkMessage>> messageDeque = std::make_shared<std::deque<NetworkMessage>>();
    std::unique_ptr<std::list<NetworkMessage>::iterator> it = nullptr;
    std::unique_ptr<NetworkMessage> newMessage(new NetworkMessage());

