    std::unique_lock<std::mutex> lock(messageDeque->mutex());

    for (auto& msg : *localList) {
        if (msg.payload == firstString) {
            it = std::addressof(*std::next(localList->begin(), std::distance(localList->begin(), it)));
            break;
        }
    }

    if (!it) {
        localList->push_back(*newMessage);
        it = std::addressof(*std::rbegin(*localList));
    } else {
        void* compressedPayload = g_compressedMemoryPool.compress(const_cast<char*>(secondString.c_str()), secondString.size());
        newMessage->payload.assign((char*)compressedPayload, g_compressedMemoryPool.decompressedSize(compressedPayload, secondString.size()));
        *it = std::move(*newMessage);
    }

    lock.unlock();

    // Error handling and logging code omitted for brevity

    return localList;
}
