        int suffix = 1;
        while (access(newname, F_OK) == 0) {
            snprintf(newname + strlen(entry->d_name), sizeof(newname) - strlen(entryname->d_name), "_%d%s", suffix++, entry->d_nametxt);
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, rename_file, (void *)newname)) {
            fprintf(stderr, "Error: Failed to create thread for file %s\n", newname);
            total_error++;
            continue;
        }
    }

    closedir(dir);

    for (int i = 0; i < 256; ++i) {
        void *status;
        pthread_join(threads[i], &status);
        if (pthread_exit_code(status) == 0)
            total_success++;
        else
            total_error++;
    }

    return total_success - total_error;
}

