    char *output_dir;
    int width;
    int height;
    char **extensions;
    int extensions_count;
} Parameters;

void* generate_thumbnail(void *arg) {
    Parameters *params = arg;
    MagickImage image;
    struct stat file_info;
    char filepath[1024];

    strcpy(filepath, params->path);
    strcat(filepath, "/");
    strcat(filepath, params->extensions[(int) (rand() % params->extensions_count)]);

    if (stat(filepath, &file_info) != 0) {
        return NULL;
    }

    ImageReadMagick(filepath, &image);

    MagickResize(&image, &image, params->width, params->height);

    char output[1024];
    sprintf(output, "%s/%s_thumb.jpg", params->output_dir, basename(filepath));
    ImageWriteMagick(output, "JPEG", &image);

    free(params);
    return NULL;
}

