        struct stat file_info;
        if (stat(filepath, &file_info) == 0 && S_ISDIR(file_info.st_mode)) {
            continue;
        }

        int extension_found = -1;
        for (int i = 0; i < extensions_count; ++i) {
            if (strstr(entry->d_name, extensions[i]) != NULL) {
                extension_found = i;
                break;
            }
        }

        if (extension_found == -1) {
            continue;
        }

        params_list[num_threads] = malloc(sizeof(Parameters));
        params_list[num_threads]->path = strdup(filepath);
        params_list[num_threads]->template = strdup(template);
        params_list[num_threads]->output_dir = strdup(output_dir);
        params_list[num_threads]->width = width;
        params_list[num_threads]->height = height;
        params_list[num_threads]->extensions = extensions;
        params_list[num_threads]->extensions_count = extensions_count;
        pthread_create(&threads[num_threads], NULL, generate_thumbnail, params_list[num_threads]);
        ++num_threads;
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
