class XmlParserLock {
public:
    explicit XmlParserLock(boost::mutex& mutex) : m_mutex(mutex) {}

    template<typename Functor>
    auto with_lock(Functor functor) {
        std::unique_lock<decltype(m_mutex)> lock(m_mutex);
        return functor(lock);
    }

private:
    boost::mutex& m_mutex;
};

void parseAndModifyXmlMessageList(const std::forward_list<CustomNetworkMessage*>& messages, const std::string& xpath) {
    static boost::mutex xmlMutex;
    std::vector<std::unique_ptr<boost::property_tree::ptree>> parsedMessages;

    for (auto msg : messages) {
        XmlParserLock lock(xmlMutex);

        boost::iostreams::filtering_streambuf<boost::iostreams::compress::zlib_decompressor> decompressor;
        decompressor.push(std::ifstream(msg->payload.get(), std::ios::binary));
        boost::property_tree::read_xml(decompressor, boost::property_tree::ptree());

        auto root = boost::property_tree::get_child("", parsedMessages.back());
        BOOST_LOG_TRIVIAL(debug) << "Parsed XML: " << boost::property_tree::xml_writer_make_output(*root).write();

        auto elementIterator = root.begin();
        if (elementIterator == root.end()) {
            throw std::runtime_error("No matching XML element found");
        }

        msg->payload = std::move(std::unique_ptr<char[]>(new char[(*elementIterator).second.get_value().size() + 1]));
        std::strcpy(msg->payload.get(), (*elementIterator).second.get_value().c_str());
    }
}
