#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>
#include <log4cxx/fileappender.h>
#include <log4cxx/rollingfileappender.h>

// Define max concurrent processes and logging level
#define MAX_PROCESSES 10
sem_t semaphore; // Semaphore for process management
static int logLevel = 2; // Set desired log level (INFO: 2, DEBUG: 3)

log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("backgroundProcess"));

void log_message(int level, const char *message) {
    if (level <= logLevel) {
        time_t now;
        struct tm *tm;
        char buf[256];

        time(&now);
        tm = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

        logger->log(level, "[%s] [PID: $$] [State: $(system_state)] $message");
    }
}

void error_log(const char *message) {
    log_message(1, "ERROR: $message");
}

int background_exec(char **command) {
    pid_t pid;
    int status;

    if ((pid = fork()) < 0) {
        error_log("Failed to fork");
        return 0;
    }

    if (pid == 0) { // Child process
        setsid();
        execv(command[0], command);
        _exit(127); // Exit with error code 127 on exec failure
    } else { // Parent process
        sem_wait(&semaphore);

        if (waitpid(pid, &status, WNOHANG) <= 0 && errno != ECHILD) {
            error_log("Waitpid failed");
            sem_post(&semaphore);
            return 0;
        }

        sem_post(&semaphore);
        return WIFEXITED(status) ? WEXITSTATUS(status) == 0 ? 1 : 0 : -1; // Return exit status or error code
    }
}

// External process manager function, to be implemented separately
void adjust_process_limit(int limit);

int main() {
    sem_init(&semaphore, 0, MAX_PROCESSES);

    char *commands[][2] = {{"ls", NULL}, {"top", NULL}};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    // Initialize logging system and configure log file
    log4cxx::BasicConfigurator::getSingleton()->setRootLevel(logLevel);
    log4cxx::RollingFileAppenderPtr appender(new log4cxx::RollingFileAppender("error_log.txt"));
    appender->setMaxFileSize("10MB");
    appender->activateOptions();
    logger->addAppender(appender);

    pthread_t threads[num_commands];

    for (int i = 0; i < num_commands; ++i) {
        if (pthread_create(&threads[i], NULL, &background_exec, commands[i])) {
            error_log("Failed to create thread");
            return 1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_commands; ++i) {
        pthread_join(threads[i], NULL);
    }

    adjust_process_limit(MAX_PROCESSES + 2); // Adjust process limit after execution
    return 1;
}
