            Console.WriteLine($"An error occurred while adding and starting the website: {ex.Message}");
            return null;
        }
    }

    private static string DotNetExePath = @"C:\Program Files\dotnet\dotnet.exe"; // Replace with your dotnet executable path

    private List<DataChannel> InitializeDataChannels()
    {
        var dataChannels = new List<DataChannel>();

        for (int i = 0; i < 10; i++)
        {
            DataChannel channel = new DataChannel
            {
                Id = i,
                BufferSize = 4096, // Set buffer size limit here
                RefCount = 0
            };

            try
            {
                channel.Buffer = new byte[channel.BufferSize];
                channel.Socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
            }
            catch (OutOfMemoryException)
            {
                Console.WriteLine($"Failed to allocate memory for data buffer on channel #{channel.Id}");
                continue;
            }

            dataChannels.Add(channel);
        }

        return dataChannels;
    }
}
```
