typedef struct {
    char *username;
    char *email;
    char *password;
    char *profile_picture;
} UserProfileUpdateReq;

bool validate_user_profile_update(const char *json) {
    CURL *curl;
    CURLcode res;
    size_t len = strlen(json);
    JSON_Value *root;
    JSON_Object *obj;
    UserProfileUpdateReq req;

    root = json_parse(json);
    if (!root) {
        return false;
    }

    obj = json_value_get_object(root);

    if (!json_object_has_field(obj, "username")) {
        json_value_free(root);
        return false;
    }

    req.username = strdup(json_object_get_string(obj, "username"));
    if (strlen(req.username) < 3 || strlen(req.username) > 16 || !isalnum(*req.username)) {
        free(req.username);
        json_value_free(root);
        return false;
    }

    if (json_object_has_field(obj, "email")) {
        req.email = strdup(json_object_get_string(obj, "email"));
        if (strlen(req.email) > 254 || !regexec(&regex, req.email, 0, NULL, 0)) {
            free(req.email);
            json_value_free(root);
            return false;
        }
    } else {
        req.email = NULL;
    }

    if (json_object_has_field(obj, "password")) {
        req.password = strdup(json_object_get_string(obj, "password"));
        if (strlen(req.password) < 8 || !regexec(&password_regex, req.password, 0, NULL, 0)) {
            free(req.password);
            json_value_free(root);
            return false;
        }
    } else {
        req.password = NULL;
    }

    if (json_object_has_field(obj, "profile_picture")) {
        req.profile_picture = strdup(json_object_get_string(obj, "profile_picture"));
        res = curl_easy_init();
        if (res != CURLE_OK) {
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        CURLcode url_check_result = curl_easy_setopt(curl, CURLOPT_URL, req.profile_picture);
        if (url_check_result != CURLE_OK) {
            curl_easy_cleanup(curl);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/octet-stream");
        url_check_result = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        if (url_check_result != CURLE_OK) {
            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        size_t buffer_size = 0;
        char *buffer = NULL;
        url_check_result = curl_easy_getinfo(curl, CURLINFO_RECEIVESIZE_TOTAL, &buffer_size);
        if (url_check_result != CURLE_OK || buffer_size > 1000000) {
            curl_easy_cleanup(curl);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        url_check_result = curl_easy_getinfo(curl, CURLINFO_RECEIVESIZE_BUFFER, &buffer_size);
        buffer = malloc(buffer_size);
        if (!buffer) {
            curl_easy_cleanup(curl);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        url_check_result = curl_easy_read(curl, buffer, buffer_size, NULL);
        if (url_check_result != CURLE_OK) {
            free(buffer);
            curl_easy_cleanup(curl);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }

        url_check_result = curl_easy_cleanup(curl);
        if (url_check_result != CURLE_OK) {
            free(buffer);
            free(req.profile_picture);
            json_value_free(root);
            return false;
        }
    } else {
        req.profile_picture = NULL;
    }

    // Free allocated memory and return true if all checks passed
    json_value_free(root);
    return true;
}

const char *regex = R"((\w+)(\.\w+)*@(\w+)((\.\w+)+))";
const char *password_regex = R"((?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,})";

