using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Reflection;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Threading;

public class ConfigSetting<T>
{
    public DateTime LastModified { get; set; }
    public T Data { get; set; }
}

public class CustomDataStructure : IReadOnlyDictionary<string, object>
{
    private readonly IDictionary<string, ConfigSetting<object>> _settings;

    public CustomDataStructure(IDictionary<string, ConfigSetting<object>> settings)
    {
        _settings = settings;
    }

    public ICollection<string> Keys => _settings.Keys;

    public bool TryGetValue(string key, out object value)
    {
        if (_settings.TryGetValue(key, out var setting))
        {
            value = setting.Data;
            return true;
        }

        value = null;
        return false;
    }
}

public class ConfigLoader
{
    private readonly Dictionary<string, ConfigSetting<object>> _localCache;
    private readonly Dictionary<string, ConfigSetting<object>> _remoteCache;
    private readonly TimeSpan _cacheTimeWindow;
    private readonly JsonSerializerSettings _serializerSettings;

    public ConfigLoader(TimeSpan cacheTimeWindow)
    {
        _localCache = new Dictionary<string, ConfigSetting<object>>();
        _remoteCache = new Dictionary<string, ConfigSetting<object>>();
        _cacheTimeWindow = cacheTimeWindow;
        _serializerSettings = new JsonSerializerSettings
        {
            // Additional serialization settings...
        };
    }

    public async Task<CustomDataStructure> LoadAsync(IEnumerable<string> filePaths)
    {
        var data = new CustomDataStructure(_localCache);

        foreach (var filePath in filePaths)
        {
            try
            {
                await LoadAndUpdateCache(filePath, true);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading configuration from '{filePath}': {ex.Message}");
            }
        }

        return data;
    }

    private async Task LoadAndUpdateCache(string filePath, bool isLocal)
    {
        if (!File.Exists(filePath))
        {
            return;
        }

        lock (_localCache ?? _remoteCache)
        {
            var cachedSetting = isLocal ? _localCache : _remoteCache;
            if (cachedSetting.ContainsKey(filePath))
            {
                if (IsFileModified(filePath, cachedSetting[filePath].LastModified))
                {
                    await ReloadFromFileAsync(filePath);
                }

                return;
            }

            var config = await ReadConfigFromFileAsync(filePath);
            cachedSetting[filePath] = new ConfigSetting<object>
            {
                LastModified = DateTime.UtcNow,
                Data = config
            };
        }
    }

    private async Task<object> ReadConfigFromFileAsync(string filePath)
    {
        using var stream = File.OpenRead(filePath);
        return JsonConvert.DeserializeObject<object>(await new StreamReader(stream).ReadToEnd(), _serializerSettings);
    }

    private async Task ReloadFromFileAsync(string filePath)
    {
        var currentSetting = _localCache?[filePath] ?? _remoteCache?[filePath];
        if (currentSetting == null)
        {
            throw new InvalidOperationException($"Unable to find cached configuration for '{filePath}'.");
        }

        try
        {
            var newConfig = await ReadConfigFromFileAsync(filePath);
            currentSetting.Data = newConfig;
            currentSetting.LastModified = DateTime.UtcNow;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reloading configuration from '{filePath}': {ex.Message}");
        }
    }

    private bool IsFileModified(string filePath, DateTime lastModifiedUtc)
    {
        var currentTime = DateTime.UtcNow;
        return (currentTime - lastModifiedUtc).TotalSeconds > _cacheTimeWindow.TotalSeconds || File.GetLastWriteTimeUtc(filePath) > lastModifiedUtc;
    }
}
