using json = nlohmann::json;

class OAuthResponse {
public:
    virtual ~OAuthResponse() {}
    static void registerFactory(const std::string& id, std::function<std::unique_ptr<OAuthResponse>(json)> factory) {
        _factories[id] = factory;
    }
    static std::unique_ptr<OAuthResponse> create(const std::string& id, json j) {
        auto it = _factories.find(id);
        if (it == _factories.end()) return nullptr;
        return it->second(j);
    }
    virtual json toJson() const = 0;
    virtual bool verifyTokenValidity() const = 0;
private:
    static std::map<std::string, std::function<std::unique_ptr<OAuthResponse>(json)>> _factories;
};
std::map<std::string, std::function<std::unique_ptr<OAuthResponse>(json)>> OAuthResponse::_factories;

class AccessToken : public OAuthResponse {
public:
    std::string access_token;
    int expires_in;
    std::string token_type;
    std::string refresh_token;
    AccessToken(const json& j) : access_token(j["access_token"].get<std::string>()),
                                   expires_in(j["expires_in"].get<int>()),
                                   token_type(j["token_type"].get<std::string>()),
                                   refresh_token(j.count("refresh_token") > 0 ? j["refresh_token"].get<std::string>() : "") {}
    json toJson() const {
        json j;
        j["access_token"] = access_token;
        j["expires_in"] = expires_in;
        j["token_type"] = token_type;
        if (!refresh_token.empty())
            j["refresh_token"] = refresh_token;
        return j;
    }
    bool verifyTokenValidity() const {
        return !access_token.empty() && expires_in > 0 && token_type == "Bearer";
    }
};
OAuthResponse::registerFactory("AccessToken", std::make_function([j](json j) -> std::unique_ptr<OAuthResponse> { return std::make_unique<AccessToken>(j); });

bool verifyOAuthTokenValidity(const std::string& jsonStr) {
    auto oauth = OAuthResponse::create("AccessToken", json::parse(jsonStr));
    if (!oauth) return false;
    return oauth->verifyTokenValidity();
}
