                auto elapsedSinceLastSuccess = now - lastSuccessTime;
                if (elapsedSinceLastSuccess > 3600 * Milliseconds{1}) { // Print summary of successful and failed strategy selections every hour
                    printSummary();
                    lastSuccessTime = now;
