    if (newData->rawData.get() == nullptr) {
        std::cerr << "Error: Failed to allocate memory for new data point." << std::endl;
        syslog(LOG_ERR, "Failed to allocate memory for new data point.");
        throw std::runtime_error("Allocation failure");
    }

