        if (newData->id == matchId) {
            const auto it = std::find_if(dataStream.begin(), dataStream.end(),
                   [matchId](const CustomData& cd) { return cd.id == matchId; });

            if (it != dataStream.end()) {
                dataStream.insert(++it, *newData);
            } else {
                std::cerr << "Error: Data structure with ID " << matchId << " not found in the stream." << std::endl;
                syslog(LOG_ERR, "Data structure with ID %d not found in the stream.", matchId);
            }
        } else {
            if (newData->id > INT_MAX || newData->id < INT_MIN) {
                std::cerr << "Error: Invalid identifier for new data point." << std::endl;
                syslog(LOG_ERR, "Invalid identifier for new data point.");
                throw std::runtime_error("Invalid identifier");
