public class BackgroundTaskScheduler {
    private static final String API_URL = "https://example-api.com/token";
    private static final ExecutorService executor = Executors.newSingleThreadScheduledExecutor();
    private static ServiceConfig serviceConfig;
    private static MessagingSystem messagingSystem;

    public static void main(String[] args) {
        if (!validateJson()) return;

        Cipher ecbcipher = createCipher("ECB");
        Cipher cfbcipher = createCipher("CFB");

        Service service = new Service();
        try {
            decryptAccessToken(ecbcipher, cfbcipher, service);
        } catch (Exception e) {
            System.err.println("Failed to decrypt access token: " + e.getMessage());
            return;
        }

        if (!isValidToken(service)) {
            refreshToken(service, ecbcipher, cfbcipher);
        }

        executor.submit(() -> {
            while (true) {
                try {
                    checkForUpdates();
                    if (shouldRestartService()) {
                        stopServiceAndSendNotification();
                        startService(ecbcipher, cfbcipher);
                    }
                    Thread.sleep(serviceConfig.getExpiresIn() * 1000L);
                } catch (Exception e) {
                    System.err.println("Error in background task: " + e.getMessage());
                }
            }
        });
    }

    private static boolean validateJson() {
        try {
            ObjectMapper mapper = new ObjectMapper();
            serviceConfig = mapper.readValue(new File("config.json"), ServiceConfig.class);
            if (serviceConfig.getAccessToken() == null ||
                serviceConfig.getExpiresIn() <= 0 ||
                serviceConfig.getTokenType() == null) {
                return false;
            }
        } catch (IOException e) {
            System.err.println("Failed to parse JSON configuration: " + e.getMessage());
            return false;
        }
        return true;
    }

    private static Cipher createCipher(String mode) throws NoSuchAlgorithmException, NoSuchPaddingException {
        KeyGenerator keyGen = KeyGenerator.getInstance("DES");
        keyGen.init(8);
        SecretKey key = keyGen.generateKey();
        Cipher cipher = Cipher.getInstance(mode + "/ECB");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return cipher;
    }

    private static void decryptAccessToken(Cipher ecbcipher, Cipher cfbcipher, Service service) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(service.getAccessToken().getBytes());
        CipherInputStream cis = null;

        if ("ECB".equalsIgnoreCase(serviceConfig.getTokenType())) {
            cis = new CipherInputStream(bais, ecbcipher);
        } else if ("CFB".equalsIgnoreCase(serviceConfig.getTokenType())) {
            IvParameterSpec ivSpec = new IvParameterSpec(service.getIv().getBytes());
            cis = new CipherInputStream(bais, cfbcipher);
            cis.init();
        } else if ("Null".equalsIgnoreCase(serviceConfig.getTokenType())) {
            // Do nothing as it's already decrypted
        } else {
            throw new IllegalArgumentException("Unsupported token type: " + serviceConfig.getTokenType());
        }

