['```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    SMContext sm_context;
    char *payload;
    time_t expiration;
} Message;

typedef struct Node {
    Message *msg;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

size_t MAX_PAYLOAD_SIZE = 1024; // Set your desired max payload size here

void create_message(Message **msg, SMContext sm_context, char *payload, time_t expiration) {
    if (!payload || strlen(payload) > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Invalid message payload size\n");
        return;
    }

    *msg = malloc(sizeof(Message));
    if (!*msg) {
        perror("malloc");
        return;
    }

    (*msg)->sm_context = sm_context;
    (*msg)->payload = strdup(payload);
    if (!(*msg)->payload) {
        free(*msg);
        perror("strdup");
        return;
    }

    (*msg)->expiration = expiration;
}

void init_list() {
    pthread_mutex_init(&list_lock, NULL);
}

void add_message(Message *msg) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc");
        free(msg->payload);
        free(msg);
        return;
    }

    new_node->msg = msg;
    new_node->next = head;
    head = new_node;
}

void remove_message(Message *msg) {
    if (head == NULL) return;

    Node *current = head;
    Node **prev = &head;

    while (current != NULL) {
        if (current->msg == msg) {
            *prev = current->next;
            free(current->msg->payload);
            free(current->msg);
            free(current);
            return;
        }
        prev = &current->next;
        current = current->next;
    }
}

Message* find_nearest_expiry() {
    Message *nearest = NULL;
    time_t nearest_time = TIME_MAX;

    Node *current = head;

    while (current != NULL) {
        if (current->msg->expiration < nearest_time) {
            nearest = current->msg;
            nearest_time = current->msg->expiration;
        }
        current = current->next;
    }

    return nearest;
}

void traverse_list(void (*func)(Message *)) {
    pthread_mutex_lock(&list_lock);

    Node *current = head;
    while (current != NULL) {
        Message *msg = current->msg;
        func(msg);
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
}
```

