            double elapsed = (ts_now.tv_sec - ts.tv_sec) + (ts_now.tv_nsec - ts.tv_nsec) / 1_000_000_000;
            printf("Initialized %zu messages in %.3fs\n", i, elapsed);
        }
    }
}

