    uint64_t rnti;
    char crc_indication_rel8_tag[32];
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static sem_t mutex;
static size_t max_structures = 1000000;
static size_t max_concurrency = 100;
static size_t structures_processed = 0;

void transform(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (size_t i = 0; i < 32; ++i) {
        if (i == 0 || i == 31) continue; // skip start and end of strings
        pdu->rx_ue_information_tag[i] = isupper(pdu->rx_ue_information_tag[i]) ? pdu->rx_ue_information_tag[i] : toupper(pdu->rx_ue_information_tag[i]);
        if (isalnum(pdu->rx_ue_information_tag[i])) continue; // keep alphanumeric characters
        pdu->rx_ue_information_tag[i] = '_';
    }

    for (size_t i = 0; i < 32; ++i) {
        if (i == 0 || i == 31) continue; // skip start and end of strings
        pdu->crc_indication_rel8_tag[i] = isupper(pdu->crc_indication_rel8_tag[i]) ? pdu->crc_indication_rel8_tag[i] : toupper(pdu->crc_indication_rel8_tag[i]);
        if (isalnum(pdu->crc_indication_rel8_tag[i])) continue; // keep alphanumeric characters
        pdu->crc_indication_rel8_tag[i] = '_';
    }

    for (size_t i = 0; strlen(pdu->rx_ue_information_tag) > i; ++i) {
        if (strlen(pdu->rx_ue_information_tag) <= i + 1 || pdu->rx_ue_information_tag[i] == '\0') break;
        if (isspace(pdu->rx_ue_information_tag[i])) {
            memmove(&pdu->rx_ue_information_tag[i], &pdu->rx_ue_information_tag[i + 1], strlen(&pdu->rx_ue_information_tag[i + 1]) + 1);
        }
    }

    for (size_t i = 0; strlen(pdu->crc_indication_rel8_tag) > i; ++i) {
        if (strlen(pdu->crc_indication_rel8_tag) <= i + 1 || pdu->crc_indication_rel8_tag[i] == '\0') break;
        if (isspace(pdu->crc_indication_rel8_tag[i])) {
            memmove(&pdu->crc_indication_rel8_tag[i], &pdu->crc_indication_rel8_tag[i + 1], strlen(&pdu->crc_indication_rel8_tag[i + 1]) + 1);
        }
    }
}

void* create_structures(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    transform(pdu);
    pdu->rnti = rand() % (1 << 48); // generate unique RNTI within the allowed range
    pdu->crcflag = rand() % 2;

    sem_wait(&mutex);
    structures_processed++;
    sem_post(&mutex);

    return pdu;
}

void merge_lists(NFAPI_CRC_INDICATION_PDU_T** lists, size_t num_lists) {
    NFAPI_CRC_INDICATION_PDU_T* result = malloc(max_structures * num_lists * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) return;

    size_t total_structures = 0, unique_rnitis[max_concurrency] = {0}, rnti_counts[max_concurrency] = {0};
    for (size_t i = 0; i < num_lists; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* list = lists[i];
        size_t list_structures = 0;
        while (list && list->rnti <= (1 << 48)) {
            if (!unique_rnitis[list->rnti % max_concurrency]) {
                unique_rnitis[list->rnti % max_concurrency] = 1;
                rnti_counts[list->rnti % max_concurrency]++;
            } else {
                break; // skip duplicates
            }

            memcpy(&result[total_structures], list, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            total_structures++;
            list = list->next;
        }
    }

    result = realloc(result, total_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) return;

    for (size_t i = 0; i < total_structures; ++i) {
        memcpy(&result[i], &result[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (rnti_counts[result[i].rnti % max_concurrency] > 1) {
            // mark duplicate RNTIs with an invalid value to facilitate filtering during usage
            result[i].rnti = -1;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_structures(size_t num_structures) {
    if (num_structures > max_structures) num_structures = max_structures;

    pthread_t threads[max_concurrency];
    NFAPI_CRC_INDICATION_PDU_T* lists[max_concurrency] = {};
    for (size_t i = 0; i < max_concurrency; ++i) {
        lists[i] = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!lists[i]) return NULL;
    }

    sem_init(&mutex, 0, 1);

    for (size_t i = 0; i < max_concurrency; ++i) {
        pthread_create(&threads[i], NULL, create_structures, lists[i]);
    }

    for (size_t i = 0; i < max_concurrency; ++i) {
        pthread_join(threads[i], NULL);
    }

    merge_lists(lists, max_concurrency);

    for (size_t i = 0; i < max_concurrency; ++i) {
        free(lists[i]);
    }

    sem_destroy(&mutex);

    return structures_processed == num_structures ? merge_lists(lists, 1) : NULL;
}
