int create_thread_safe_list(THREAD_SAFE_LIST** list, size_t capacity) {
    *list = (THREAD_SAFE_LIST*)malloc(sizeof(THREAD_SAFE_LIST));
    if (!*list)
        return -1;

    memset(*list, 0, sizeof(THREAD_SAFE_LIST));

    pthread_mutex_init(&((*list)->mutex), NULL);
    (*list)->capacity = capacity;
    (*list)->count = 0;

    return 0;
}

