    if (list->count >= list->capacity || !msg || !msg->payload || msg->payload_size < MIN_PAYLOAD_SIZE || !msg->message.ueInfoTag || !msg->callback) {
        pthread_mutex_unlock(&(list->mutex));
        return -1;
    }

    list->list[list->count] = msg;
    list->count++;
    pthread_mutex_unlock(&(list->mutex));

    log_creation("Added message to thread-safe list", __TIME__, __DATE__);

    return 0;
}

void destroy_message(NFAPI_MESSAGE_STRUCT* msg) {
    if (!msg)
        return;

    free(msg->payload);
    free(msg);
}

void destroy_thread_safe_list(THREAD_SAFE_LIST* list) {
    pthread_mutex_lock(&(list->mutex));

    for (size_t i = 0; i < list->count; ++i)
        destroy_message(list->list[i]);

    free(list->list);
    free(list);
    pthread_mutex_destroy(&(list->mutex));
}
