#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    char* payload;
    size_t payload_size;
    CRC_INDICATION_REL8_TAG crc_indication;
    const char* title; // Non-null and non-empty
    void(*callback)(NFAPI_MESSAGE_T*); // Non-NULL
} NFAPI_MESSAGE;

typedef struct list_node {
    NFAPI_MESSAGE msg;
    struct list_node *next;
} ListNode;

typedef struct {
    ListNode** head;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_full, cond_empty;
    time_t timeout;
} NFAPI_LIST;

void nfapi_list_init(NFAPI_LIST* list, size_t capacity) {
    *list = (NFAPI_LIST){ .head = NULL, .capacity = capacity, .count = 0,
                          .mutex = PTHREAD_MUTEX_INITIALIZER,
                          .cond_full = PTHREAD_COND_INITIALIZER,
                          .cond_empty = PTHREAD_COND_INITIALIZER };
}

bool nfapi_message_is_valid(const NFAPI_MESSAGE* msg) {
    return msg->title && msg->callback && msg->payload && msg->payload_size > 0;
}

NFAPI_MESSAGE* create_message(RX_UE_INFORMATION_TAG tag, RNTI rnti, char* payload, size_t payload_size) {
    NFAPI_MESSAGE* message = malloc(sizeof(NFAPI_MESSAGE));
    if (!message) return NULL;

    message->tag = tag;
    message->rnti = rnti;
    message->payload = payload;
    message->payload_size = payload_size;
    message->crc_indication.crcflag = rand() % 2; // Random CRC flag

    return message;
}

int nfapi_list_push(NFAPI_LIST* list, NFAPI_MESSAGE* message) {
    if (!nfapi_message_is_valid(message)) return -1;

    ListNode** head = list->head;
    pthread_mutex_lock(&list->mutex);

    while (*head && list->count == list->capacity) {
        pthread_cond_wait(&list->cond_empty, &list->mutex);
    }

    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->msg = *message;
    new_node->next = *head;
    *head = new_node;
    list->count++;

    if (list->count == 1) {
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    pthread_cond_signal(&list->cond_full);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

