    *keys = temp_keys;

    void *temp_offsets = realloc(*offsets, new_size * sizeof(long));
    if (!temp_offsets) log_error("Failed to reallocate memory for offsets");
    *offsets = temp_offsets;

    void *temp_records = realloc(*records, new_size * sizeof(Record));
    if (!temp_records) log_error("Failed to reallocate memory for records");
