[' Here is the code for the C function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int id;
    int value;
    struct Record *next;
} Record;

typedef struct List {
    Record **records;
    long *offsets;
    int *keys;
    size_t size;
    pthread_mutex_t mutex;
} List;

List* create_list(size_t size) {
    List *list = (List*) malloc(sizeof(List));
    list->records = (Record**) calloc(size, sizeof(Record*));
    list->offsets = (long*) calloc(size, sizeof(long));
    list->keys = (int*) calloc(size, sizeof(int));
    list->size = size;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void insert(List *list, int key, int value) {
    for (size_t i = 0; i < list->size; ++i) {
        if (!list->keys[i] || list->keys[i] == key) {
            Record *new_record = (Record*) malloc(sizeof(Record));
            new_record->id = i;
            new_record->value = value;
            new_record->next = list->records[i];
            list->records[i] = new_record;
            list->keys[i] = key;
            break;
        }
    }
    pthread_mutex_lock(&list->mutex);
}

int search(List *list, int key) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->keys[i] == key) {
            Record *record = list->records[i];
            while (record != NULL) {
                if (record->id == i) return record->value;
                record = record->next;
            }
        }
    }
    return -1;
}

void destroy(List *list) {
    for (size_t i = 0; i < list->size; ++i) {
        Record *current = list->records[i];
        Record *next;
        while (current != NULL) {
            next = current->next;
            free(current);
            current = next;
        }
    }
    free(list->records);
    free(list->offsets);
    free(list->keys);
    free(list);
}
```

