void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        log_error("Out of memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void init_arrays(long** offsets, int* keys, record** records, size_t array_size, int min, int max) {
    *offsets = safe_malloc(array_size * sizeof(long));
    *keys = safe_malloc(array_size * sizeof(int));
    *records = safe_malloc(array_size * sizeof(record));

    srand(time(NULL));

    for (size_t i = 0; i < array_size; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % (max - min + 1) + min;
        (*records)[i].value = rand() % INT_MAX;
    }
}

void resize_arrays(long** offsets, int* keys, record** records, size_t* array_sizes, size_t new_size) {
    if (new_size > *array_sizes) {
        long* new_offsets = safe_malloc((new_size + 1) * sizeof(long));
        memcpy(new_offsets, *offsets, *array_sizes * sizeof(long));
        free(*offsets);
