    for (size_t i = 0; i < MAX_USERS && !feof(file); ++i) {
        User_Info user;
        fscanf(file, "%d %s %[^,],%*c ", &user.id, user.username, user.details);
        fscanf(file, "%lf %*c ", &user.age); // Assumes age is provided, otherwise ignore the value
        users[i] = user;
        usernames[i] = user.username;
        user_ids[i] = user.id;
