    for (size_t i = 0; i < MAX_USERS; ++i) {
        if (users[i].id == id)
            return &users[i];
    }
    return NULL;
}

User_Info *find_user_by_username(const char *username) {
    for (size_t i = 0; i < MAX_USERS; ++i) {
        if (!strcmp(usernames[i], username))
            return &users[i];
    }
    return NULL;
}

void free_memory() {
    for (size_t i = 0; i < MAX_USERS; ++i) {
