// Function to dynamically allocate and initialize an array of tasks
Task* initializeTasks(size_t size, int min_priority, int max_priority, size_t status_range) {
    // Validate input parameters
    if (size == 0 || min_priority > max_priority) {
        fprintf(stderr, "Invalid input: Size must be greater than zero and min_priority should be less than max_priority\n");
        return NULL;
    }

    // Allocate memory for task array and initialize all elements to zero
    Task* tasks = (Task*)malloc(size * sizeof(Task));
    if (!tasks) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    // Dynamically resize the array as needed, with a target load factor of 0.75
    size_t capacity = size;
    while (capacity < size * 1.75 && capacity < INT_MAX) {
        Task* tempTasks = (Task*)realloc(tasks, capacity * sizeof(Task));
        if (!tempTasks) {
            perror("Memory reallocation failed");
            free(tasks);
            return NULL;
        }
        tasks = tempTasks;
        capacity *= 1.75;
    }

    // Initialize each task with random priority and status values within given ranges
    for (size_t i = 0; i < size; ++i) {
        tasks[i].id = i + 1;
        tasks[i].priority = min_priority + rand() % (max_priority - min_priority + 1);
        tasks[i].status = static_cast<TaskStatus>(rand() % status_range);
    }

    return tasks;
}
```
