    pthread_mutex_lock(&list_lock);
    if (list_head == NULL) {
        list_head = new_node;
    } else {
        ListNode *current = list_head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);

    return 0; // Success
}

int remove_oldest(ListNode** head) {
    if (list_head == NULL) return -1; // List is empty

    ListNode *oldest = list_head;
    ListNode *current = list_head->next;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (time(NULL) - oldest->access_time > TIMEOUT || current->access_time > oldest->access_time) {
            oldest = current;
            current = current->next;
        } else {
            break;
        }
    }
    if (current == NULL) { // No entries to remove
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    ListNode *temp = oldest;
    current = current->next;
    free(temp->payload);
    free(temp);

    if (oldest == list_head) {
        list_head = current;
    } else {
        temp->next = NULL; // detach the node from the list
    }

    pthread_mutex_unlock(&list_lock);

    return 0; // Success
}

void purge_expired(ListNode** head) {
