    std::map<udp::endpoint, boost::asio::stream_protocol::socket> sockets;
    boost::spsc_queue<DataPoint, 1024> dataQueue;
    std::vector<std::unique_ptr<Worker>> workers;

public:
    DataPipeline(int numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(new Worker());
            boost::thread t(&DataPipeline::run, this);
            t.detach();
        }
    }

