from threading import Lock
import re

class LogEntry:
    def __init__(self, timestamp, log_entry):
        self.timestamp = timestamp
        self.log_entry = log_entry

class LogAnalyzer:
    def __init__(self, log_data=None):
        self.lock = Lock()
        self.anomaly_threshold = 5  # Set your desired anomaly threshold here
        self.user_ids = set()
        self.timestamp_cache = deque(maxlen=1024)  # Cache for timestamp conversion
        self.log_data = log_data or []

    def extractUniqueUserIds(self):
        with self.lock:
            user_id_pattern = re.compile(r'(\w+@\w+\.\w{2,})')
            users = defaultdict(int)
            for log_entry in self.log_data:
                matches = user_id_pattern.findall(log_entry.log_entry)
                for match in matches:
                    users[match] += 1
            sorted_users = sorted(users.items(), key=lambda x: x[1], reverse=True)
            return sorted_users[-anomaly_threshold - 1][1]
