typedef struct {
    int value;
    int status;
} record;

int compareKeys(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}

void initArrays(int keyCount, char **keys, size_t *offsets, int *keysArray, record **records, int *statusArray) {
    qsort(keys, keyCount, sizeof(char *), compareKeys);

    int uniqueKeys = 0;
    for (int i = 0; i < keyCount; ++i) {
        int found = 0;
        for (int j = 0; j < uniqueKeys; ++j) {
            if (!strcmp(keys[i], keysArray[j])) {
                found = 1;
                break;
            }
        }
        if (!found) {
            keysArray[uniqueKeys] = hash(keys[i]);
            uniqueKeys++;
        }
    }

    offsets = (size_t *)malloc(uniqueKeys * sizeof(size_t));
    for (int i = 0; i < uniqueKeys; ++i) {
        offsets[i] = (size_t)-1;
    }

    records = (record *)malloc(uniqueKeys * sizeof(record));
    statusArray = (int *)calloc(uniqueKeys, sizeof(int));

    srand(time(NULL));

    for (int i = 0; i < uniqueKeys; ++i) {
        int found = 0;
        for (int j = 0; j < keyCount; ++j) {
            if (!strcmp(keys[j], keysArray[i])) {
                found = 1;
                break;
            }
        }
        if (!found) continue; // Skip if the key is not in the original list.

        offsets[i] = (size_t)calloc(1, sizeof(record));
        records[i][(*offsets[i])].key = keysArray[i];
        records[i][(*offsets[i])].status = 0;
    }

    for (int i = 0; i < uniqueKeys; ++i) {
        if (!records[i][(*offsets[i])].status) {
            int randomValue = rand() % 100 + 50;
            records[i][(*offsets[i])].value = randomValue;
            records[i][(*offsets[i])].status = 1;
        }
    }
}

int hash(const char *str) {
    uint32_t hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % INT_MAX;
}

void freeArrays(size_t *offsets, record **records, int *statusArray) {
    for (int i = 0; i < offsets[uniqueKeys - 1]; ++i) {
        free(records[0] + i);
    }
    free(records);
    free(statusArray);
    free(offsets);
}
```

