    size_t max_size;
    size_t current_size;
    record *head;
    pthread_mutex_t mutex;
};

int init_records_list(struct records_list *rl, size_t max_size) {
    rl->max_size = max_size;
    rl->current_size = 0;
    rl->head = NULL;
    pthread_mutex_init(&rl->mutex, NULL);
    return 0;
}

int create_records(record **records, size_t size) {
    *records = malloc(size * sizeof(**records));
    if (!*records) {
        perror("Memory allocation failure");
        return -1;
    }
    return 0;
}

int create_offsets(long *offsets, size_t size) {
    for (size_t i = 0; i < size; ++i)
        offsets[i] = -1;
    return 0;
}

record* find_record(struct records_list *rl, int key) {
    pthread_mutex_lock(&rl->mutex);
    record *current = rl->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&rl->mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&rl->mutex);
    return NULL;
}

int insert_record(struct records_list *rl, int key, int value) {
    record *new_record = malloc(sizeof(*new_record));
    if (!new_record) {
        perror("Memory allocation failure");
        return -1;
    }
    new_record->key = key;
    new_record->value = value;
    new_record->next = NULL;

    pthread_mutex_lock(&rl->mutex);
    if (find_record(rl, key)) {
        perror("Trying to insert a duplicate key");
        free(new_record);
        pthread_mutex_unlock(&rl->mutex);
        return -1;
    }
    if (rl->current_size >= rl->max_size) {
        perror("Records list is full");
        free(new_record);
        pthread_mutex_unlock(&rl->mutex);
        return -1;
    }

    new_record->offset = ++rl->current_size;

    if (!rl->head) {
        rl->head = new_record;
    } else {
        record *current = rl->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&rl->mutex);
    return 0;
}

int delete_record(struct records_list *rl, int key) {
    record *current = rl->head;
    record *prev = NULL;

    pthread_mutex_lock(&rl->mutex);
    if (!current || current->key != key) {
        pthread_mutex_unlock(&rl->mutex);
        return -1; // Not found
    }
    prev = current;
    current = current->next;
    free(prev);
    --rl->current_size;

    while (current != NULL && current->key == key) {
        prev = current;
        current = current->next;
        free(prev);
        --rl->current_size;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&rl->mutex);
        return 0; // Deleted all occurrences of the key
    }

    prev->next = current;
    pthread_mutex_unlock(&rl->mutex);
    return -1; // Key found but not deleted because it's still in use
}
