typedef struct Record {
    int key;
    long offset;
    int value;
    struct Record *next;
} Record;

struct Container {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    FILE *log_file;
};

void log_error(const char *message, struct Container *container) {
    if (container->log_file != NULL) {
        fprintf(container->log_file, "%s\n", message);
    }
}

int init_container(struct Container **container, size_t max_size, FILE *log_file) {
    *container = malloc(sizeof(struct Container));
    if (*container == NULL) {
        log_error("Failed to allocate container memory", *container);
        return 1;
    }

    (*container)->records = NULL;
    (*container)->capacity = max_size;
    (*container)->size = 0;
    (*container)->mutex = PTHREAD_MUTEX_INITIALIZER;
    (*container)->log_file = log_file;

    return 0;
}

Record* create_record(long offset, int key) {
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        log_error("Failed to allocate record memory", container);
        return NULL;
    }

    record->offset = offset;
    record->key = key;
    record->value = rand() % 100; // Adjust the range as needed
    record->next = NULL;

    return record;
}

int insert_record(struct Container *container, Record *record) {
    pthread_mutex_lock(&container->mutex);

    if (container->size >= container->capacity) {
        pthread_mutex_unlock(&container->mutex);
        log_error("Container is full", container);
        return 1;
    }

    Record *head = container->records;
    if (head == NULL) {
        container->records = record;
    } else {
        while (head->next != NULL) {
            head = head->next;
        }
        head->next = record;
    }

    pthread_mutex_unlock(&container->mutex);
    return 0;
}

Record* find_record(struct Container *container, int key) {
    pthread_mutex_lock(&container->mutex);

    Record *head = container->records;
    while (head != NULL) {
        if (head->key == key) {
            break;
        }
        head = head->next;
    }

    pthread_mutex_unlock(&container->mutex);
    return head;
}

int delete_record(struct Container *container, int key) {
    pthread_mutex_lock(&container->mutex);

    Record *head = container->records;
    if (head == NULL) {
        pthread_mutex_unlock(&container->mutex);
        return 1; // Empty list
    }

    if (head->key == key) {
        container->records = head->next;
    } else {
        Record *prev = head;
        head = head->next;
        while (head != NULL && head->key != key) {
            prev = head;
            head = head->next;
        }
        if (head == NULL) {
            pthread_mutex_unlock(&container->mutex);
            return 1; // Key not found
        }
        prev->next = head->next;
    }

    free(head);
    pthread_mutex_unlock(&container->mutex);
    return 0;
}

void traverse_list(struct Container *container) {
    pthread_mutex_lock(&container->mutex);

    Record *head = container->records;
    while (head != NULL) {
        printf("Record: key=%d, value=%d, offset=%ld\n", head->key, head->value, head->offset);
        head = head->next;
    }

    pthread_mutex_unlock(&container->mutex);
}
