    char buffer[100];
} record;

struct data {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    int key_range;
    int buf_size;
    pthread_mutex_t lock;
    int access_count;
    bool compress;
    char *compacted_buf;
    size_t compacted_len;
};

void error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

void init_data(struct data *d, size_t num_records, int key_range, int buf_size) {
    if (num_records > SIZE_MAX/sizeof(long))
        error("Invalid number of records");

    d->offsets = malloc(num_records*sizeof(long));
    d->keys = malloc((key_range+1)*sizeof(int));
    d->records = calloc(num_records, sizeof(record));
    d->num_records = num_records;
    d->key_range = key_range;
    d->buf_size = buf_size;
    d->access_count = 0;
    d->compress = false;
    d->compacted_buf = NULL;
    d->compacted_len = 0;
    pthread_mutex_init(&d->lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        d->offsets[i] = i;
        d->keys[(i+1)%(key_range+1)] = i;
        d->records[i].value = my_random(1, INT_MAX);
        strcpy(d->records[i].buffer, "default");
    }
}

void log_access(struct data *d) {
    if (d->access_count++ % 1000 == 0)
        my_log("Buffer access: %zu", d->access_count);
}

void compress_buffer(struct data *d) {
    if (!d->compress) return;

    mlockall(MCL_CURRENT|MCL_FUTURE); // Lock memory for compaction

    // Compute new length of compacted buffer and allocate space
    size_t new_len = 0;
    char *compacted_buf = malloc((d->num_records + 1) * d->buf_size);
    for (size_t i = 0; i < d->num_records; ++i) {
        if (d->records[i].buffer[0] != '\0') {
            strcpy(compacted_buf + new_len, d->records[i].buffer);
            new_len += strlen(compacted_buf + new_len) + 1;
        }
    }

    // Free old buffer and copy compacted data back to records
    free(d->compacted_buf);
    d->compacted_buf = compacted_buf;
    d->compacted_len = new_len;
}

void update_buffer(struct data *d, size_t index) {
    if (d->records[index].buffer[0] == 'u') return;

    strcpy(d->records[index].buffer, "updated");
    log_access(d);
}

void free_data(struct data *d) {
    free(d->offsets);
    free(d->keys);
    free(d->records);
    pthread_mutex_destroy(&d->lock);
    if (d->compacted_buf) munlockall(); // Unlock memory for compaction
    free(d->compacted_buf);
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 7)
        error("Usage: ./program num_records key_range buf_size [compress] [db_host] [db_port]");

    struct data d;
    init_data(&d, atoi(argv[1]), atoi(argv[2]), atoi(argv[3]));

    bool compress = argc == 6 && !strcmp(argv[5], "on");
    if (compress) {
        d.compress = true;
        d.compacted_buf = mmap(NULL, (d.num_records + 1)*d.buf_size, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON,-1,0);
        if (d.compacted_buf == MAP_FAILED)
            error("Failed to map anonymous memory for compaction");
    }

    pthread_t threads[10]; // Change this value as needed
    int num_threads = sizeof(threads)/sizeof(pthread_t);

    for (int i = 0; i < num_threads; ++i) {
        int arg = i;
        if (pthread_create(&threads[i], NULL, accessor, &d))
            error("Failed to create thread");
    }

    // ... Implement database connection and data serialization/deserialization here ...

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL))
            error("Failed to join thread");
    }

    free_data(&d);
    return EXIT_SUCCESS;
}

void *accessor(void *arg) {
    struct data *d = arg;

    for (size_t i = 0; i < d->num_records; ++i) {
        pthread_mutex_lock(&d->lock);
        update_buffer(d, d->offsets[i%d->num_records]);
        compress_buffer(d);
        pthread_mutex_unlock(&d->lock);
    }

    return NULL;
}
