```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int keys[MAX_KEYS];
    size_t key_count;
    long offsets[MAX_OFFSETS];
    size_t offset_count;
    struct record *records;
    size_t records_capacity;
    size_t records_size;
    pthread_mutex_t mutex;
} array_manager_t;

typedef struct record {
    int metrics[MAX_METRICS];
    size_t metric_count;
} record_t;

void init_array_manager(array_manager_t *am, size_t max_offsets, size_t max_keys, size_t max_records, size_t max_metrics) {
    am->offset_count = 0;
    am->key_count = 0;
    am->records = NULL;
    am->records_capacity = 0;
    am->records_size = 0;
    am->mutex = PTHREAD_MUTEX_INITIALIZER;

    am->offsets = malloc(max_offsets * sizeof(long));
    if (!am->offsets) {
        fprintf(stderr, "Error: Out of memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    am->keys = malloc(max_keys * sizeof(int));
    if (!am->keys) {
        fprintf(stderr, "Error: Out of memory for keys\n");
        exit(EXIT_FAILURE);
    }
}

void free_array_manager(array_manager_t *am) {
    if (am->offsets) free(am->offsets);
    if (am->keys) free(am->keys);
    if (am->records) free_records(am->records, am->records_size);
}

void free_records(record_t *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].metrics) free(records[i].metrics);
    }
    free(records);
}

int insert_record(array_manager_t *am, const char *key) {
    pthread_mutex_lock(&am->mutex);

    int key_index = find_key_index(am, key);
    if (key_index != SIZE_MAX) {
        pthread_mutex_unlock(&am->mutex);
        return -1; // Key already exists
    }

    insert_key_and_offset(am, key);

    size_t record_index = am->records_size++;
    if (am->records_capacity == am->records_size) {
        grow_records(am);
    }

    record_t *record = &am->records[record_index];
    init_record(record, MAX_METRICS);

    pthread_mutex_unlock(&am->mutex);
    return record_index;
}

void delete_record(array_manager_t *am, size_t index) {
    pthread_mutex_lock(&am->mutex);

    if (index >= am->records_size || index < 0) {
        pthread_mutex_unlock(&am->mutex);
        return;
    }

    memmove(&am->records[index], &am->records[index + 1], (am->records_size - index - 1) * sizeof(record_t));
    --am->records_size;

    pthread_mutex_unlock(&am->mutex);
}

int find_key_index(const array_manager_t *am, const char *key) {
    for (size_t i = 0; i < am->key_count; ++i) {
        if (strcmp(am->keys[i], key) == 0) {
            return i;
        }
    }
    return SIZE_MAX;
}

void insert_key_and_offset(array_manager_t *am, const char *key) {
    for (size_t i = 0; i < am->key_count; ++i) {
        if (strcmp(am->keys[i], key) == 0) {
            fprintf(stderr, "Error: Duplicate key encountered\n");
            exit(EXIT_FAILURE);
        }
