        int isUnique = 1;
        for (size_t j = 0; j < unique_keys && keys[j] != i; ++j);
        if (j == unique_keys) {
            keys[unique_keys++] = i;
            offsets[i] = unique_keys;
        } else isUnique = 0;
        if (!isUnique) key_list[i] = NULL;
    }

    *records = malloc(num_records * sizeof(record *));
