    size_t len = strlen(filename);
    if (len > 255) { // Maximum allowed length for a filename is 255 characters
        printf("Error: Filename too long.\n");
        return;
    }

    int digits = (int)ceil((len + 1) / 2.0);
    char* new_filename = malloc(len + digits + 4); // Extension plus digits and null terminator
    strcpy(new_filename, filename);
    sprintf(&new_filename[len], "%0*d.txt", digits, len % 2 == 0 ? digits : digits + 1);

    if (strlen(new_filename) > 255) { // Check if the new filename exceeds maximum length
        printf("Error: New filename too long.\n");
        free(new_filename);
        return;
