    int* keys = malloc((len + 1) * sizeof(int));
    record** records = malloc(((len + 1) * digits) * sizeof(record*));
    bool* initialized = calloc(((len + 1) * digits), sizeof(bool));

    // ... Generate random values for each record's int field and ensure unique keys.

    FILE* file = fopen(new_filename, "w");
    if (!file) {
        printf("Error: Could not open file for writing.\n");
        free(new_filename);
        free(offsets);
        free(keys);
        free(records);
        free(initialized);
        return;
