#include <time.h>

typedef struct {
    long timestamp;
    int id;
    char* data;
} record;

void processAndAnalyzeFile(char* filename) {
    const int MAX_FILENAME_LENGTH = 256;
    const int MIN_DIGITS = 1;
    const int MAX_DIGITS = 6;
    const char* fileTypes[] = {"txt", "dat", "bin"};
    int fileTypeLength, extLength, digits, i, j;
    long offset[MAX_FILENAME_LENGTH];
    int keys[MAX_FILENAME_LENGTH / 2 + 1], usedKeys[MAX_FILENAME_LENGTH / 2 + 1] = {0};
    record* records;
    record* initializedRecords;
    int numRecords, currentKey, statusFlags[MAX_FILENAME_LENGTH];
    FILE* fp;
    char newFilename[MAX_FILENAME_LENGTH], temp[MAX_FILENAME_LENGTH];

    if (!(fp = fopen(filename, "r"))) return;

    // Skip the original filename, read until newline character and get the extension length.
    fgets(temp, MAX_FILENAME_LENGTH, fp);
    fileTypeLength = strlen(temp) - 1;

    // Calculate the number of digits to append to the new filename.
    extLength = strlen(fileTypes[0]);
    digits = (int)(ceil((strlen(temp) - fileTypeLength + 1) / 2.0)) + MIN_DIGITS;

    // Ensure digits are within the specified range.
    if (digits < MIN_DIGITS || digits > MAX_DIGITS) digits = MAX_DIGITS;

    // Allocate memory for arrays and dynamically allocated structures.
    memset(offset, 0, sizeof(long) * MAX_FILENAME_LENGTH);
    memset(keys, -1, sizeof(int) * (MAX_FILENAME_LENGTH / 2 + 1));
    records = malloc((digits + 1) * numRecords * sizeof(record));
    initializedRecords = malloc((digits + 1) * numRecords * sizeof(record));

    // Set the value of each record's int field to a random value within a specified range.
    for (i = 0; i < (digits + 1) * numRecords; ++i) {
        initializedRecords[i].id = rand() % 1000000;
    }

    // Fill the offset array, ensuring each key is unique and derived from a provided list of strings.
    for (i = 0, j = 0; i < MAX_FILENAME_LENGTH && fgets(temp, MAX_FILENAME_LENGTH, fp); ++i) {
        currentKey = keys[i / 2];
        if (currentKey == -1) {
            do {
                currentKey = rand() % (sizeof(fileTypes) / sizeof(char*));
            } while (usedKeys[currentKey]);
            usedKeys[currentKey] = 1;
        }
        strncpy(&offset[i], fileTypes[currentKey], extLength);
    }
    fclose(fp);

    // Construct the new filenames and modify their extensions based on the number of characters they contain.
    for (i = 0, j = 0; i < MAX_FILENAME_LENGTH && fgets(temp, MAX_FILENAME_LENGTH, fp); ++i) {
        sprintf(newFilename, "%s%0*d.%s", temp, digits, j + 1, fileTypes[currentKey]);
        strcpy(temp, newFilename);
    }
    // Initialize timestamps and unique identifiers for records that haven't been processed yet.
    for (i = 0; i < numRecords; ++i) {
        statusFlags[offset[i]] = 1;
        if (!statusFlags[offset[i + 1]]) {
            initializedRecords[j].timestamp = time(NULL);
            initializedRecords[j].id = rand() % 1000000;
            strcpy(initializedRecords[j].data, temp);
            ++j;
        }
    }

    // Free dynamically allocated memory.
    free(records);
    free(initializedRecords);
}
