typedef struct L2CAP_PSM_T {
    uint16_t psm;
    uint8_t channel_id;
    enum CONN_STATE_T { DISCONNECTED, CONNECTING, CONNECTED, DISCONNECTING } state;
    char id[10]; // Format: PSM_hex-channel_id
} L2CAP_PSM;

const uint16_t VALID_MIN_PSM = 0x0003;
const uint16_t VALID_MAX_PSM = 0x001F;

pthread_mutex_t list_mutex;
pthread_cond_t list_notfull;
pthread_cond_t list_notempty;
size_t list_capacity = 50;
size_t list_size = 0;
L2CAP_PSM* list = NULL;

void validate_psm(uint16_t psm) {
    if (psm < VALID_MIN_PSM || psm > VALID_MAX_PSM) {
        fprintf(stderr, "Invalid L2CAP PSM value: %hu\n", psm);
        exit(EXIT_FAILURE);
    }
}

void set_psm_id(L2CAP_PSM* psms, size_t index) {
    snprintf(psms[index].id, sizeof(psms[index].id), "%04X-%hu", psms[index].psm, psms[index].channel_id);
}

void* manage_l2cap_psms(void* arg) {
    L2CAP_PSM* new_psm = (L2CAP_PSM*)arg;

    pthread_mutex_lock(&list_mutex);
    while (list_size >= list_capacity) {
        pthread_cond_wait(&list_notfull, &list_mutex);
    }

    validate_psm(new_psm->psm);
    new_psm->channel_id = (rand() % 256); // For demo purposes, replace with appropriate channel allocation logic.
    new_psm->state = DISCONNECTED;
    set_psm_id(list + list_size, list_size);
    list_size++;

    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&list_notempty);

    return NULL;
}

L2CAP_PSM* populate_l2cap_psms(size_t count) {
    L2CAP_PSM* psms = malloc(count * sizeof(L2CAP_PSM));
    if (!psms) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        psms[i].psm = rand() % (VALID_MAX_PSM - VALID_MIN_PSM + 1) + VALID_MIN_PSM;
        psms[i].channel_id = 0; // Initialize as disconnected.
    }

    return psms;
}

L2CAP_PSM* process_l2cap_psms(L2CAP_PSM* psms, size_t count) {
    if (!psms || !count)
        return NULL;

    pthread_t threads[count];
    L2CAP_PSM* result = malloc(list_capacity * sizeof(L2CAP_PSM));

    for (size_t i = 0; i < count; ++i) {
        if (pthread_create(&threads[i], NULL, &manage_l2cap_psms, psms + i)) {
            perror("Thread creation error");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < count; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread join error");
            exit(EXIT_FAILURE);
        }
    }

    size_t valid_count = 0;
    for (size_t i = 0; i < list_size; ++i) {
        if (strlen(list[i].id) == sizeof(list[i].id)) { // Valid PSM ID
            memcpy(result + valid_count, list + i, sizeof(L2CAP_PSM));
            valid_count++;
        }
    }

    free(list);
    list = result;
    list_capacity = valid_count;

    return list;
}
