#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <sys/mman.h>

typedef struct {
    int psm; // PSM value
    int id;  // Channel identifier
    bool state; // Connection state
} L2CAP_PSM_T;

typedef struct CacheNode {
    L2CAP_PSM_T *data;
    struct CacheNode *prev, *next;
} CacheNode;

CacheNode* cacheHead = NULL;
CacheNode* cacheTail = NULL;
static const int MAX_CACHE_SIZE = 100;

pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

void l2cap_psm_init(L2CAP_PSM_T **psms, int num_psms) {
    *psms = malloc(num_psms * sizeof(L2CAP_PSM_T));
    if (!*psms) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_psms; ++i) {
        // Initialize each structure here
    }
}

void l2cap_psm_deinit(L2CAP_PSM_T *psms, int num_psms) {
    free(psms);
}

// Thread-safe function to get an L2CAP_PSM_T structure from the cache or create a new one if not available.
L2CAP_PSM_T* l2cap_psm_get(int psm) {
    pthread_mutex_lock(&cacheMutex);

    CacheNode *node = cacheHead;
    while (node != NULL && node->data->psm != psm) {
        node = node->next;
    }

    if (node == NULL) { // Not in the cache, create a new one
        L2CAP_PSM_T *newData = malloc(sizeof(L2CAP_PSM_T));
        if (!newData) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&cacheMutex);
            return NULL;
        }
        // Initialize the new data here

        node = mmap(NULL, sizeof(CacheNode), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (node == MAP_FAILED) {
            perror("Memory mapping failed");
            free(newData);
            pthread_mutex_unlock(&cacheMutex);
            return NULL;
        }
        node->data = newData;

        if (!cacheHead) {
            cacheHead = node;
            cacheTail = node;
        } else {
            cacheTail->next = node;
            cacheTail = node;
        }
    }

    void* fd = mmap(NULL, sysconf(_SC_PAGE_SIZE), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_FIXED | MAP_ANONYMOUS, -1, 0);
    if (fd == MAP_FAILED) {
        perror("Memory mapping failed");
        // Evict the least recently used item from the cache here
        pthread_mutex_unlock(&cacheMutex);
        return NULL;
    }

    pthread_mutex_unlock(&cacheMutex);
    return node->data;
}
```

