    public void extractSequenceNumber(String filename) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(filename))) {
            PriorityQueue<String> lines = new PriorityQueue<>(Comparator.comparingInt(l -> l.length()));
            String line;
            while ((line = br.readLine()) != null) {
                lines.add(line);
            }

            String lastLine = lines.poll(); // Get the last line from the sorted list
            Pattern pattern = Pattern.compile("\\s*(\\w+)\\s*=\\s*(\\d+)\\s*\\]");
            if (pattern.matcher(lastLine).find()) {
                String key = matcher.group(1);
                int value = Integer.parseInt(matcher.group(2));
