                LinkedList<String> sessionEntries = sessions.getOrDefault(key, new LinkedList<>());
                sessionEntries.add(lastLine);
                sessions.put(key, sessionEntries);
            }
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

