import java.io.*;
import java.util.*;
import java.text.SimpleDateFormat;
import java.lang.ThreadSafe;
import java.nio.file.Files;
import java.nio.charset.StandardCharsets;

@ThreadSafe
class SessionAnalyzer {
    private Map<String, Long> sessions = new TreeMap<>();

    void analyze(String filename) throws IOException {
        List<String> lines = Files.readAllLines(new File(filename).toPath(), StandardCharsets.UTF_8);

        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        for (String line : lines) {
            String[] parts = line.split("\\s+");
            if (parts.length >= 3) {
                String username = parts[0];
                String email = parts[1];
                long timestamp = dateFormat.parse(parts[2]).getTime();
                sessions.put(username, timestamp);
            }
        }
    }

    long extractSequenceNumber(String filename) throws IOException {
        List<String> lines = Files.readAllLines(new File(filename).toPath(), StandardCharsets.UTF_8);

        // Sort the lines and extract the sequence number from the last line
        Collections.sort(lines);
        return Long.parseLong(lines.get(lines.size() - 1).split(": ")[1]);
    }
}
