class ConfigManager {
public:
    ConfigManager(const char *filename);
    void updateAndBackup(const char *key, int newValue, const char *backupFilename);
    ~ConfigManager();
private:
    const char *_filename;
    std::unordered_map<std::string, configEntry> _configEntries;
    std::ofstream _auditLogFile;

    void parseAndOptimizeConfigFile(const char *filename);
};

ConfigManager::ConfigManager(const char *filename) : _filename(filename) {
    parseAndOptimizeConfigFile(_filename);
}

void ConfigManager::parseAndOptimizeConfigFile(const char *filename) {
    // Validate and rename the file according to specific naming convention
    char newFilename[256];
    struct stat st;
    stat(filename, &st);
    snprintf(newFilename, sizeof(newFilename), "%llu%s", st.st_mtime, getFileNameHash(filename));
    rename(filename, newFilename);
    _filename = newFilename;

    // Parse and store the configuration data
    std::ifstream file(_filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << _filename << stdstd::endl;
        return;
    }
    char line[256];
    configEntry currentEntry;
    configMode mode = NORMAL;
    while (file.getline(line, sizeof(line))) {
        if (line[0] == '#') continue; // Ignore comments

        std::stringstream ss(line);
        std::string key, valueStr;
        ss >> key >> ws >> valueStr;

        int value = std::stoi(valueStr);
        currentEntry.key = const_cast<char *>(key.c_str());
        currentEntry.value = value;
        currentEntry.mode = mode;
        _configEntries[key] = currentEntry;
    }
}

void ConfigManager::updateAndBackup(const char *key, int newValue, const char *backupFilename) {
    auto it = _configEntries.find(key);
    if (it == _configEntries.end()) {
        std::cerr << "Invalid key: " << key << stdstd::endl;
        return;
    }
    it->second.value = newValue;

    std::ofstream backupFile(backupFilename, std::ios_base::out | std::ios_base::binary);
    if (!backupFile.is_open()) {
        std::cerr << "Error opening backup file: " << backupFilename << stdstd::endl;
        return;
    }
    std::ofstream logFile(_auditLogFile.rdbuf());
    logFile << "Updating configuration key '" << key << "' from value '" << it->second.value << "' to '" << newValue << "'\n";
    backupFile << _filename << "\n" ;
    for (auto &entry : _configEntries) {
        if (strcmp(entry.first, key) == 0) continue; // Skip the updated entry
        backupFile << entry.first << ':' << entry.second.value << '\n';
    }
}

