    if (!logFile) {
        perror("Error opening log file");
        return;
    }

    size_t numEntries = 0;
    LogEntry *entries = NULL;

    struct stat st;
    if (stat(filename, &st) == -1) {
        perror("Error getting log file statistics");
        fclose(logFile);
        return;
    }

    size_t entryLength = (size_t)(3 * st.st_size / 10 + 1); // Round up to nearest integer
    entries = calloc((size_t)entryLength, sizeof(LogEntry));
    if (!entries) {
        perror("Error allocating memory for log entries");
        fclose(logFile);
        return;
