        this.connectionsByDevice = new TreeMap<>();
        this.timeWindow = timeWindow;
    }

    public void analyzeLogs(LogEntry[] entries) {
        for (LogEntry entry : entries) {
            Pid deviceId = Pid.valueOf(Integer.toString(entry.deviceId));
            Connection connection = connectionsByDevice.computeIfAbsent(deviceId, k -> new TreeMap<>());
            connection.incrementCount();
            connection.recordTimestamp(Instant.ofEpochMilli(entry.timestamp));
            connection.updateIPAddress(entry.message);
        }

        // Analyze connections, identify anomalies and log results to output file here.
    }

    public void extractStatisticalSummary() {
        Map<Pid, ConnectionSummary> summaryByDevice = new TreeMap<>();
        for (Map.Entry<Pid, Map<String, Connection>> deviceConnections : connectionsByDevice.entrySet()) {
            ConnectionSummary summary = new ConnectionSummary();
            for (Map.Entry<String, Connection> connectionEntry : deviceConnections.getValue().entrySet()) {
                summary.addConnection(connectionEntry.getValue());
            }
            summaryByDevice.put(deviceConnections.getKey(), summary);
        }

        // Calculate statistical summaries and handle exceptions gracefully here.
    }

    private static class Connection {
        private Instant firstTimestamp;
        private int count;
        private String ipAddress;

        public void incrementCount() {
            count++;
        }

        public void recordTimestamp(Instant timestamp) {
            if (firstTimestamp == null) {
                firstTimestamp = timestamp;
            }
        }

        public void updateIPAddress(String ipAddress) {
            this.ipAddress = ipAddress;
        }
    }

    private static class ConnectionSummary {
        private int count;
        private long totalResponseTime;
        private Instant earliestResponseTime;
        private Instant latestResponseTime;

        public void addConnection(Connection connection) {
            count += connection.count;
            totalResponseTime += connection.getResponseTime();
            if (earliestResponseTime == null || connection.getFirstTimestamp().isBefore(earliestResponseTime)) {
                earliestResponseTime = connection.getFirstTimestamp();
            }
            if (latestResponseTime == null || connection.getLatestTimestamp().isAfter(latestResponseTime)) {
                latestResponseTime = connection.getLatestTimestamp();
            }
        }

        public long getAverageResponseTime() {
            return totalResponseTime / count;
        }

        public long getTotalResponseTime() {
            return totalResponseTime;
        }

        public Instant getEarliestResponseTime() {
            return earliestResponseTime;
        }

        public Instant getLatestResponseTime() {
            return latestResponseTime;
        }
    }
}
