class NetworkLogAnalyzer {
    public void analyze(LogEntry[] logs, long timeWindow, String outputFilename) throws IOException {
        Map<String, List<LogEntry>> groupedLogs = new HashMap<>();

        DecimalFormat df = new DecimalFormat("#.##");
        for (LogEntry log : logs) {
            Calendar calendar = Calendar.getInstance();
            calendar.setTimeInMillis(log.timestamp * 1000);
            int year = calendar.get(Calendar.YEAR), month = calendar.get(Calendar.MONTH) + 1, day = calendar.get(Calendar.DAY_OF_MONTH);
            String key = year + "-" + month + "-" + day + "T" + df.format(calendar.getTime()) + "Z";

            groupedLogs.computeIfAbsent(key, k -> new ArrayList<>()).add(log);
        }

        PrintWriter out = new PrintWriter(new FileWriter(outputFilename));
        for (Map.Entry<String, List<LogEntry>> entry : groupedLogipsByDevice(groupedLogs)) {
            String deviceId = entry.getKey();
            List<LogEntry> logsForDevice = entry.getValue();

            out.printf("Device: %s%n", deviceId);
            out.printf("IP connections:%n");
            analyzeConnections(logsForDevice, out);
            out.printf("Average response time: %.3f seconds%n", getMeanResponseTime(logsForDevice));
            out.println();
        }
        out.close();
    }

    private void extractStatisticalSummary(LogEntry[] logs) {
        double meanResponseTime = 0, stdevResponseTime = 0;
        int count = 0;
        for (LogEntry log : logs) {
            if (log.logLevel == WARNING || log.logLevel == ERROR) {
                meanResponseTime += log.timestamp - logs[count].timestamp;
                count++;
            }
        }
        if (count > 0) {
            meanResponseTime /= count;
            stdevResponseTime = Math.sqrt(Arrays.stream(logs).filter(l -> l.logLevel == WARNING || l.logLevel == ERROR).mapToDouble(l -> (l.timestamp - meanResponseTime)).square().average().orElse(0));
        }
        System.out.printf("Mean response time: %.3f seconds, Standard deviation: %.3f seconds%n", meanResponseTime, stdevResponseTime);
    }

    private void checkForMemoryLeaks() {
        // Implement memory leak checking here
    }

    private Map.Entry<String, List<LogEntry>>[] groupsByDevice(Map<String, List<LogEntry>> logs) {
        return logs.entrySet().stream().sorted(Comparator.comparingInt(e -> e.getKey().length())).toArray(Map.Entry[]::new);
    }

    private void analyzeConnections(List<LogEntry> logs, PrintWriter out) {
        Map<String, Integer> ipToCount = new HashMap<>();
        Map<String, Long> ipToSumResponseTime = new HashMap<>();
        for (LogEntry log : logs) {
            String ip = log.message.split(" ")[1];
            ipToCount.merge(ip, 1, Integer::sum);
            ipToSumResponseTime.put(ip, ipToSumResponseTime.getOrDefault(ip, 0L) + (log.timestamp - logs.get(0).timestamp));
        }

        out.printf("Total connections: %d%n", ipToCount.values().stream().mapToInt(Integer::intValue).sum());
        out.printf("Average response time: %.3f seconds%n", ipToSumResponseTime.values().stream().mapToDouble(Double::longValue / logs.size()).average().orElse(0));
    }

    private double getMeanResponseTime(List<LogEntry> logs) {
        double sum = 0;
        for (int i = 1; i < logs.size(); ++i) {
            sum += logs.get(i).timestamp - logs.get(i - 1).timestamp;
        }
        return sum / (logs.size() - 1);
    }
}
