#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <inttypes.h>

typedef struct {
    time_t timestamp;
    enum { INFO, WARNING, ERROR, CRITICAL } logLevel;
    char message[256];
    uint64_t uniqueId;
    int deviceId;
} LogEntry;

void generateUniqueId(const char* input, size_t len, uint64_t* out) {
    const size_t hexDigits = (len > 3 ? (len / 3 + 1) : 6);
    *out = strtoull(input, NULL, 16);
    // Add version string
    for (size_t i = hexDigits; i < 16; ++i) {
        *out <<= 4;
        *out |= 'V' << (i - hexDigits - 1);
    }
}

void processAndAnalyzeNetworkLogs(const char* filename, int threshold) {
    FILE* fp = fopen(filename, "r");
    if (!fp) return;

    LogEntry entries[1 << 20]; // Reserve space for 1M log entries (adjust as needed)
    size_t numEntries = 0;

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        size_t len = strlen(line);
        if (sscanf(line, "%*c%" SCNu32 "-%*T%*c %c %n", &time_t tmp, &len) != 1 || time(&tmp) - tmp > 86400) continue;

        char level[3];
        if (sscanf(line + len, "%2s ", level) != 1) continue;

        if (level[0] >= threshold) {
            char id[len + 16]; // Reserve space for uniqueId
            memcpy(id, line, len);
            generateUniqueId(id, len, &entries[numEntries].uniqueId);
            sscanf(line + len + strlen(id), "%d %s", &entries[numEntries].deviceId, entries[numEntries].message + strlen(id));

            ++numEntries;
        }
    }

    fclose(fp);
}
