public class NetworkLogAnalyzer {
    private static final DecimalFormat TIME_FORMAT = new DecimalFormat("#.##");
    private final Map<Integer, List<LogEntry>> deviceLogs;
    private final long startTime, endTime, timeWindow;

    public NetworkLogAnalyzer(String inputFile, long start, long end) throws IOException {
        LocalDateTime dt = LocalDateTime.now();
        this.startTime = dt.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
        this.endTime = start + (end - startTime);
        this.timeWindow = TimeUnit.MILLISECONDS.convert(end - start, TimeUnit.DAYS) * 1000;
        this.deviceLogs = new HashMap<>();

        try (BufferedReader br = Files.newBufferedReader(Paths.get(inputFile))) {
