typedef struct {
    DownloadTask task;
    unsigned priority;
} PriorityDownloadTask;

// Custom buffer pool
typedef struct Buffer {
    char *data;
    size_t len;
    struct Buffer *next;
} Buffer;

BufferPool buffer_pool = {NULL, NULL};

void buffer_init() {
    buffer_pool.head = buffer_pool.tail = NULL;
}

void buffer_add(char *data, size_t len) {
    Buffer *new_buffer = malloc(sizeof(Buffer));
    new_buffer->data = data;
    new_buffer->len = len;
    new_buffer->next = NULL;

    if (buffer_pool.head == NULL) {
        buffer_pool.head = buffer_pool.tail = new_buffer;
    } else {
        buffer_pool.tail->next = new_buffer;
        buffer_pool.tail = new_buffer;
    }
}

void buffer_free(Buffer *buffer) {
    if (buffer == NULL) return;

    free(buffer->data);
    free(buffer);

    if (buffer_pool.head == buffer) {
        buffer_pool.head = buffer->next;
        if (buffer_pool.head == NULL) buffer_pool.tail = NULL;
    } else if (buffer_pool.tail == buffer) {
        buffer_pool.tail = buffer->next;
    }
}

