    : maxConcurrentRequests(maxConcurrentRequests) {}

void Http::RequestManager::addRequest(const std::string& url, const boost::beast::http::verb& method, int state) {
    // Validate the URL, encode it and create a uniqueId
    auto uniqueId = Utils::encodeUrl(url) + " " + boost::to_upper_copy(method);

    // Ensure the URL is in the whitelist and the uniqueId does not contain any potentially harmful characters
    if (!isValidUrl(url)) {
        std::cerr << "Invalid URL: " << url << std::endl;
        return;
    }

    RequestHandle* request = new (allocator.malloc()) RequestHandle();
    request->url = url;
    request->method = method;
    request->state = state;

    // Store the request and manage concurrent requests
    {
        std::unique_lock<std::mutex> lock(requestsMutex);
        if (pendingRequests.size() < maxConcurrentRequests) {
            pendingRequests.push_back(request);
        } else {
            auto it = requests.emplace(uniqueId, request).first;
            if (it != requests.end()) { // If the request was already in the map (cache hit), skip adding to pendingRequests
                lock.unlock();
                return;
            }
        }
    }
}

