use std::env;
use std::fs::{self, File};
use std::io::{BufReader, Write};
use regex::Regex;
use argparse::ArgumentParser;
use tokio::io::{AsyncReadExt, BufStream};
use tokio::sync::RwLock;
use log::{debug, error, info};
use simple_logger::{SimpleLogger, CombinedFormatter};

const LOG_FILE: &str = "analysis.log";
const RE_EMAIL: &str = r"[\w.-]+@[\w.-]+\.[a-zA-Z]{2,4}";
const RE_PHONE: &str = r"(\+\d{1,3}[-\.\s]?\d{1,4}[-\.\s]?\d{1,4}[-\.\s]?\d{1,4}|(\(\d{2,6}\)[\-\.\s]?\d{1,4}[-\.\s]?\d{1,4}[-\.\s]?\d{1,5}))+";

async fn process_file(path: &str) {
    let reader = BufReader::new(fs::File::open(path).unwrap());
    let mut total_lines = 0;
    let mut email_matches = 0;
    let mut phone_matches = 0;

    // Chunk-based processing
    let chunk_size = 1024;
    for chunk in reader.chunks(chunk_size) {
        let chunk = chunk.await.unwrap();
        total_lines += chunk.len() as u32;

        for line in chunk {
            if line.contains(RE_EMAIL) {
                email_matches += 1;
            }

            if line.contains(RE_PHONE) {
                phone_matches += 1;
            }
        }
    }

    // Thread-safe logging
    let mut log = RwLock::new([total_lines, email_matches, phone_matches]);
    tokio::task::spawn(async move {
        let mut log_data = log.write().await;
        info!("Processing statistics: total lines={}, email matches={}, phone matches={}", log_data[0], log_data[1], log_data[2]);
    });
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let parser = ArgumentParser::new("analysis")
        .reference_document_string("Reads a file and performs various analysis tasks.\n\nUsage: analysis [OPTIONS] [FILE]\n\nOptions:\n  -h, --help         Display help information.\n  -l, --logfile       Path to the log file (default: analysis.log)\n")
        .referrer_document_string("https://github.com/YourUserName/analysis-rs");
    let args = parser.parse_args_or_exit();

    if args.is_present("help") {
        println!("{}", parser.usage("<FILE>"));
        return Ok(());
    }

    // Log file handling
    SimpleLogger::new()
        .with_formatter(CombinedFormatter::default().pretty())
        .init()
        .unwrap();
    if let Some(logfile) = args.get_value_of("logfile") {
        fs::write(LOG_FILE, "").unwrap();
        let mut log_writer = BufWriter::new(File::create(logfile).unwrap());
        info!("Logging to: {}", logfile);
        std::io::copy(&mut std::iter::empty(), &mut log_writer).unwrap();
    }

    let input_path = match args.get_value_of("FILE").unwrap_or(env::args().nth(1).unwrap()) {
        Some(path) => path,
        None => {
            error!("No file specified");
            println!("{}", parser.usage("<FILE>"));
            return Ok(());
        }
    };

    process_file(&input_path).await?;

    Ok(())
}
```

