#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>

#define BUFFER_SIZE (2097152) // 2 MB
#define ENTRY_COUNT (BUFFER_SIZE / sizeof(struct log_entry))

typedef struct {
    time_t timestamp;
    int severity_level;
    char *message;
} struct log_entry;

static void* buffer;
static size_t used_size = 0;
static size_t max_used_size = BUFFER_SIZE / 4; // 70% of the allocated budget

struct log_entry* create_log_entry() {
    struct log_entry *entry = (struct log_entry*) malloc(sizeof(struct log_entry));
    entry->timestamp = time(NULL);
    entry->severity_level = rand() % 5 + 1;
    char event[32] = {"System Restart", "Disk Space Low", "Network Error"};
    entry->message = (char*) malloc(sizeof(char) * sizeof(event));
    strcpy(entry->message, event);
    return entry;
}

void log_entry_free(struct log_entry* entry) {
    free(entry->message);
    free(entry);
}

int should_log() {
    if ((used_size + sizeof(struct log_entry)) > max_used_size) {
        fprintf(stderr, "Memory usage exceeded 70% of the allocated budget.\n");
        return 1;
    }
    return 0;
}

void* get_buffer() {
    if (!buffer) {
        buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (buffer == MAP_FAILED) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }
    }
    return buffer;
}

struct log_entry* get_available_entry() {
    void *ptr = get_buffer();
    struct log_entry* entry = (struct log_entry*) ptr;
    if (should_log()) {
        return NULL;
    }
    used_size += sizeof(struct log_entry);
    return entry;
}

void deallocate_unused() {
    void *ptr = get_buffer();
    struct log_entry *current, *next;
    for (ptr = buffer; ptr < buffer + used_size; ) {
        current = (struct log_entry*) ptr;
        next = (struct log_entry*) ((char*) current + sizeof(struct log_entry));
        if (!current->message) {
            ptr = next;
            continue;
        }
        log_entry_free(current);
        used_size -= sizeof(struct log_entry);
        ptr = next;
    }
}
