                    return host;
                }
            }

            String ipDomain = Dns.getName(address); // perform reverse DNS lookup
            if (ipDomain != null) {
                if (!domainCache.asMap().containsKey(host)) {
                    domainCache.put(host, ipDomain);
                }
                return ipDomain;
            } else {
                // Handle cases where reverse DNS lookup fails...
            }
        } catch (Exception e) {
            System.err.println("Error processing URL: " + url);
            e.printStackTrace();
        }
        return host;
    }
}
