#include <time.h>
#include <sys/mman.h>

#define MAX_SESSIONS 1024
#define SESSION_BUDGET (256 * 1024)
#define SYSTEM_BUDGET (2 * 1024 * 1024)
#define MAX_MESSAGE_LENGTH 256

struct log_entry {
    time_t timestamp;
    int severity_level;
    char* message;
};

typedef struct session {
    size_t allocated;
    size_t used;
    struct log_entry* entries;
    struct session* next;
} Session;

Session* sessions = NULL;
size_t num_sessions = 0;

void* mem_pool;
size_t pool_size;
size_t pool_allocated;

int rand_range(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

char* generate_message() {
    static char messages[MAX_SESSIONS][MAX_MESSAGE_LENGTH];
    char* message = messages[num_sessions];
    snprintf(message, MAX_MESSAGE_LENGTH, "Event: %s", events[rand_range(0, sizeof(events) / sizeof(char*))]);
    return message;
}

Session* allocate_session() {
    if (pool_allocated + SESSION_BUDGET > SYSTEM_BUDGET) return NULL;

    Session* new_session = mmap(NULL, SESSION_BUDGET, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!new_session) return NULL;

    new_session->allocated = new_session->used = SESSION_BUDGET;
    new_session->entries = (struct log_entry*)((char*)new_session + sizeof(Session));
    new_session->next = sessions;
    sessions = new_session;
    num_sessions++;
    return new_session;
}

void deallocate_session(Session* session) {
    munmap((char*)session - sizeof(Session), SESSION_BUDGET);

    session->next = sessions;
    while (sessions && sessions != session) sessions = sessions->next;
    if (sessions == session) sessions = session->next;
}

void log_event(Session* session) {
    struct log_entry* entry = &session->entries[session->used++];
    entry->timestamp = time(NULL);
    entry->severity_level = rand_range(1, 6);
    entry->message = generate_message();
}

void check_memory() {
    size_t total_used = 0;
    for (Session* session = sessions; session; session = session->next) {
        if ((float)(session->used / session->allocated) > .7f) {
            printf("Warning: Session %d exceeded 70% of its allocated budget\n", num_sessions - session - 1);
        }
        total_used += session->used;
    }
    if ((float)(total_used / SYSTEM_BUDGET) > .95f) {
        printf("Warning: System memory usage is at 95%\n");
    }
}

int main() {
    srand(time(NULL));

    mem_pool = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pool_size = POOL_SIZE;
    pool_allocated = 0;

    while (true) {
        Session* session = allocate_session();
        if (!session) break;
        log_event(session);
        check_memory();
    }

    Session* current = sessions;
    while (current) {
        Session* next = current->next;
        deallocate_session(current);
        current = next;
    }
}
