public class URLProcessor {
    private final ScriptEngineManager manager = new ScriptEngineManager();
    private final ScriptContext context = new SimpleScriptContext();

    // Load custom sanitizing function using a script engine (e.g., Nashorn)
    public void loadSanitizeFunction(String script) {
        Bindings bindings = context.getBindings(ScriptContext.ENGINE_SCOPE);
        bindings.put("sanitize", new ScriptableObject() {{
            put("execute", new Function() {
                public Object call(Invocable args) throws Exception {
