                    return sanitizeUrl((String) args.getArgument(1), regex);
                }
            });
        }});
        context.setBindings(bindings, ScriptContext.ENGINE_SCOPE);
        ((SimpleScriptEngine) manager.getEngineByName("nashorn")).eval(script);
    }

    public void setCache(Cache cache) {
        this.cache = cache;
    }

    private Cache cache;

    // Configure the timeout for reverse DNS lookup
    private int dnsLookupTimeout = 5000;

    // Process a dynamic stream of URLs
    public void processUrlStream(Iterator<String> urls, boolean enableCaching) {
        if (cache != null && enableCaching) {
            CacheManager cacheManager = new CacheManager(dnsLookupTimeout);
            Runnable cacheCleaner = cacheManager.getCacheCleaner();
            Thread cacheThread = new Thread(cacheCleaner, "URL-Processor Cache Cleaner");
            cacheThread.start();

            // Use a concurrent hashmap for thread-safe access and efficient retrieval/updates
            Map<String, URLInfo> urlCache = new ConcurrentHashMap<>();
            Iterator<String> cachedUrls = cacheManager.getCache().iterator();
            while (urls.hasNext() || cachedUrls.hasNext()) {
                String nextUrl;
                if (urls.hasNext()) {
                    nextUrl = urls.next();
                } else {
                    nextUrl = cachedUrls.next();
                }

                URLInfo urlInfo = processURL(nextUrl, urlCache);
                if (cache != null && enableCaching) {
                    cacheManager.put(urlInfo);
                }
            }
        } else {
            while (urls.hasNext()) {
                String nextUrl = urls.next();
                processURL(nextUrl, new ConcurrentHashMap<>());
            }
        }
    }

    private URLInfo processURL(String url, Map<String, URLInfo> cache) {
        try {
            URI uri = new URI(url);
            String domainName = uri.getHost().toLowerCase();
            // Custom sanitizing function using a script engine (e.g., Nashorn)
            Object sanitizeFunction = context.getBindingByName("sanitize");
            Function execute = (Function) ((ScriptableObject) sanitizeFunction).getBindingValue("execute", context);
            domainName = (String) execute.call(new Object[]{ConfigUtil.SANITIZE_REGEX, domainName});

            if ("IPv4".equals(uri.getUserInfo().split(":")[0]) || "IPv6".equals(uri.getUserInfo().split(":")[0])) {
                // IP address normalization and reverse DNS lookup
                InetAddress ip = InetAddress.getByAddress(domainName.getBytes(StandardCharsets.UTF_8));
                domainName = ip.getHostAddress();
                if (ip instanceof Inet4Address) {
                    domainName = sanitizeIPv4((Inet4Address) ip);
                } else if (ip instanceof Inet6Address) {
                    domainName = sanitizeIPv6((Inet6Address) ip);
                }
                InetAddress inetAddress = InetAddress.getByName(domainName);
                String reverseDns = inetAddress.getHostName();
                // Monitor unusual patterns (e.g., too many requests from the same IP or anomalous DNS results)
                monitor(reverseDns);

                URLInfo urlInfo = new URLInfo(domainName, uri.toString());
                cache.putIfAbsent(urlInfo.getDomainName(), urlInfo);
                return urlInfo;
            } else {
                // Normalize domain name and log for monitoring
                domainName = sanitizeDomainName(domainName);
                log(String.format("Processed URL: %s", uri.toString()));
                URLInfo urlInfo = new URLInfo(domainName, uri.toString());
                cache.putIfAbsent(urlInfo.getDomainName(), urlInfo);
                return urlInfo;
            }
        } catch (URISyntaxException | IOException | ScriptException e) {
            log(String.format("Error processing URL: %s, Error: %s", url, e.getMessage()));
            throw new RuntimeException(e);
        }
    }

    // Sanitize and normalize IPv4 address (e.g., "192.168.0.1" or "123.123.123.123")
    private String sanitizeIPv4(Inet4Address ip) {
        return String.format("%s.%s.%s.%s", ip.getAddress() >> 24 & 0xFF, (ip.getAddress() >> 16) & 0xFF, (ip.getAddress() >> 8) & 0xFF, ip.getAddress() & 0xFF);
    }

    // Sanitize and normalize IPv6 address (e.g., "2001:0db8:85a3:0000:0000:8a2e:0370:7334" or "[::1]")
    private String sanitizeIPv6(Inet6Address ip) {
        StringBuilder sb = new StringBuilder();
        boolean isFirstGroup = true;
        for (int i : ip.getAddress()) {
            if (i == 0 && !isFirstGroup) {
                sb.append("::");
            } else if (sb.length() > 0) {
                sb.append(":");
            }

            String hex = Integer.toHexString(i).toUpperCase();
            while (hex.length() < 4) {
                hex = "0" + hex;
            }

            sb.append(hex);
            isFirstGroup = false;
        }
        return sb.toString();
    }

    // Custom sanitizing function for domain names
    private String sanitizeDomainName(String domain) {
        return domain.replaceAll("[^a-z0-9]", "-")
                .toLowerCase();
    }

    // Monitor unusual patterns in the processed URLs
    private void monitor(String pattern) {
        // Implement monitoring logic based on custom requirements
    }

    // Utility method to log messages for monitoring and debugging purposes
    private void log(String message) {
        System.out.println(message);
    }
}

