#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int severity_level;
    char *message;
} log_entry;

struct session {
    size_t budget;
    size_t used;
    pthread_mutex_t mutex;
    log_entry **entries;
};

typedef struct session session_t;

session_t* create_session(size_t budget) {
    session_t *session = malloc(sizeof(session_t));
    if (!session) return NULL;
    session->budget = budget;
    session->used = 0;
    pthread_mutex_init(&session->mutex, NULL);
    session->entries = calloc(budget, sizeof(log_entry *));
    return session;
}

void free_session(session_t* session) {
    for (size_t i = 0; i < session->budget; ++i)
        if (session->entries[i]) free(session->entries[i]->message);
    free(session->entries);
    free(session);
}

void log_entry_init(log_entry *entry) {
    entry->timestamp = time(NULL);
    entry->severity_level = rand() % 5 + 1;
    asprintf(&entry->message, "Event: System Restart");
}

size_t get_session_memory_usage(const session_t *session) {
    size_t usage = 0;
    for (size_t i = 0; i < session->budget; ++i) {
        if (session->entries[i]) {
            usage += sizeof(log_entry);
            usage += strlen(session->entries[i]->message) + 1;
        }
    }
    return usage;
}

void check_session_memory_usage(const session_t *session) {
    if (get_session_memory_usage(session) > 0.7 * session->budget) {
        printf("Warning: Session memory usage exceeded 70% threshold\n");
    }
}

void merge_logs(FILE *output, const session_t **sessions, size_t count) {
    if (!count) return;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    log_entry **entries = malloc(count * sizeof(log_entry *));
    size_t total_entries = 0;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&sessions[i]->mutex);
        for (size_t j = 0; j < sessions[i]->budget; ++j) {
            if (!sessions[i]->entries[j]) continue;
            entries[total_entries] = malloc(sizeof(log_entry));
            memcpy(entries[total_entries], sessions[i]->entries[j], sizeof(log_entry));
            total_entries++;
        }
        pthread_mutex_unlock(&sessions[i]->mutex);
    }

    qsort(entries, total_entries, sizeof(log_entry *), (int (*)(const void *, const void *))compare_timestamps);

    for (size_t i = 0; i < total_entries; ++i) {
        fprintf(output, "%ld: %d | %s\n", entries[i]->timestamp, entries[i]->severity_level, entries[i]->message);
        free(entries[i]->message);
        free(entries[i]);
    }

    free(entries);
    pthread_mutex_destroy(&lock);
}

int compare_timestamps(const void *a, const void *b) {
    return (*(time_t *)a - *(time_t *)b);
}

// Centralized logging manager functions omitted for brevity.
