import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class UrlProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(UrlProcessor.class);
    private static final int MAX_CACHE_SIZE = 10000;
    private static final long TIMEOUT_MS = TimeUnit.SECONDS.toMillis(5);
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private LoadingCache<String, String> domainCache;
    private Pattern sanitizePattern;
    private Set<String> allowedTlds;
    private boolean cacheEnabled;

    public UrlProcessor(Set<String> allowedTlds, boolean cacheEnabled, Pattern sanitizePattern) {
        this.allowedTlds = Collections.unmodifiableSet(allowedTlds);
        this.cacheEnabled = cacheEnabled;
        this.sanitizePattern = sanitizePattern;

        if (cacheEnabled) {
            domainCache = CacheBuilder.newBuilder()
                    .maximumSize(MAX_CACHE_SIZE)
                    .expireAfterAccess(TIMEOUT_MS)
                    .build((key, callable) -> lookupDomainNameAsync(key));
        }
    }

    public void processUrls(List<String> urls) {
        CompletionService<Void> completionService = new ExecutorCompletionService<>(executor);

        for (String url : urls) {
            Callable<Void> task = () -> processUrl(url);
            completionService.submit(task);
        }

        while (!completionService.isTerminated()) {
            Future<Void> future = completionService.take();
            try {
                future.get();
            } catch (ExecutionException | InterruptedException e) {
                LOGGER.error("Error processing URL: {}", url, e);
            }
        }
    }

    private Void processUrl(String url) {
        try {
            URI uri = new URI(url);
            String domain = sanitizeDomainName(uri.getHost());

            if (!isAllowedTld(domain)) {
                throw new IllegalArgumentException("URL has an unallowed top-level domain: " + domain);
            }

            String normalizedDomain;
            if (uri.getScheme().equalsIgnoreCase("http")) {
                normalizedDomain = normalizeHttpUrl(url);
            } else if (uri.getScheme().equalsIgnoreCase("https")) {
                normalizedDomain = normalizeHttpsUrl(url);
            } else {
                throw new IllegalArgumentException("URL scheme is not supported: " + uri.getScheme());
            }

            if (!isIpAddress(normalizedDomain)) {
                if (cacheEnabled) {
                    domain = domainCache.getUnchecked(domain);
                } else {
                    domain = lookupDomainNameSync(normalizedDomain);
                }
            } else {
                domain = normalizedDomain;
            }

            LOGGER.info("Processed URL: {}, Domain: {}", url, domain);
        } catch (URISyntaxException e) {
            LOGGER.error("Error processing URL: {}", url, e);
        }

        return null;
    }

    // Implement methods for sanitizeDomainName, isAllowedTld, normalizeHttpUrl, normalizeHttpsUrl, lookupDomainNameSync and lookupDomainNameAsync here.
}
```

