    private void startReverseDnsLookup(String host, Runnable onProcessed) {
        if (cachingEnabled && cache.containsKey(host)) {
            handleCachedResult(cache.get(host), onProcessed);
        } else {
            OkHttpClient client = new OkHttpClient();
            Request request = new Request.Builder()
                    .url("https://api.external-dns-service.com/reverse_lookup?hostname=" + host)
                    .build();

            callWithTimeout(client, request).enqueue(new Callback() {
                @Override
                public void onFailure(Call call, IOException e) {
                    handleError(e);
                    onProcessed.run();
                }

                @Override
