int setupDataTransferChannels(DataChannel** channels, size_t num_channels) {
    *channels = malloc(num_channels * sizeof(DataChannel));
    if (!*channels) {
        perror("Memory allocation failed");
        return 1;
    }

    for (size_t i = 0; i < num_channels; ++i) {
        channels[i].id = i;
        channels[i].buffer_size = MIN_BUFFER_SIZE; // Replace with your predefined limits
