            free(channels);
            return 1;
        }
        sem_init(&channels[i].ref_count, 0, 0); // Initializing ref count to 0

        if (num_channels - i < MAX_CHANNELS_PER_PROCESS) { // Limit the number of channels per process
            break;
        }
    }

    static pthread_mutex_t md5_mutex = PTHREAD_MUTEX_INITIALIZER;
    JNIEXPORT jstring JNICALL Java_YourPackageName_MD5(JNIEnv *env, jobject this, jstring input) {
        const char* cInput = (*env)->GetStringUTFChars(env, input, NULL);
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, cInput, strlen(cInput));
        MD5_Final(digest, &ctx);
        (*env)->ReleaseStringUTFChars(env, input, cInput);

        jcharArray result = (*env)->NewCharArray(env, MD5_DIGEST_LENGTH * 2 + 1);
        for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            pthread_mutex_lock(&md5_mutex);
            jchar c = ('0' <= digest[i] && digest[i] <= '9') ? (jchar)(digest[i] + '0') : (('a' <= digest[i] && digest[i] <= 'f') ? (jchar)(digest[i] - 8 + 'a') : '?');
            pthread_mutex_unlock(&md5_mutex);
            (*env)->SetCharArrayRegion(env, result, i * 2, 2, &c);
        }

        return result;
    }

    int sockfd, port = SOCKET_PORT;
    for (size_t i = 0; i < num_channels && i < MAX_CHANNELS_PER_PROCESS; ++i) {
        if ((sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)) == -1) {
            perror("Socket creation error");
            continue; // Move to the next channel and create a new socket, in case of an error
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(port);
        inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr);

        if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
            perror("Connection error");
            close(sockfd);
            continue; // Move to the next channel and create a new socket, in case of an error
        }

        char md5_hash[MD5_DIGEST_LENGTH * 2 + 1];
        JNIEnv* env = NULL;
        JavaVM* jvm = JNI_CreateJavaVM(&env);
        JClass class = (*env)->FindClass(env, "YourPackageName/YourClassName"); // Replace with the actual package and class name
        jobject instance = (*jvm)->GetCreatedJavaVMs()[0]->GetEnv(jvm, JNI_VERSION_1_8);
        jstring input = (*env)->NewStringUTF(env, "channel-id"); // Replace 'channel-id' with the unique channel identifier
        jstring hashedInput = Java_YourPackageName_MD5(env, instance, input);
        const char* cHash = (*env)->GetStringUTFChars(env, hashedInput, NULL);
        memcpy(md5_hash, cHash, sizeof(md5_hash));
        (*env)->ReleaseStringUTFChars(env, hashedInput, cHash);
        Java_CleanUpJavaVM(jvm);

        // Store the MD5 hash and socket descriptor in the DataChannel structure
    }

    return 0;
}
