    int severity_level;
    char *message;
} log_entry;

struct session {
    size_t budget;
    size_t used;
    pthread_t thread;
    sem_t mem_lock;
    log_entry *entries;
};

struct logging_manager {
    struct session **sessions;
    size_t num_sessions;
    size_t max_sessions;
    sem_t sessions_lock;
    sem_t log_file_lock;
    FILE *log_file;
    gzFile compressed_log;
    char *compression_buffer;
};

void log_event(struct session *session) {
    struct log_entry entry = {time(NULL), rand() % 6 + 1, malloc(sizeof(char) * 20)};
    snprintf(entry.message, sizeof(entry.message), "System Restart", "Disk Space Low", "Network Error");

    sem_wait(&session->mem_lock);
    if (session->used + sizeof(log_entry) > session->budget * 0.7) {
        fprintf(stderr, "Warning: Session exceeded 70% of memory budget\n");
    }
    session->used += sizeof(log_entry);
    memcpy(&session->entries[session->used - sizeof(log_entry)], &entry, sizeof(log_entry));
    sem_post(&session->mem_lock);
}

void* session_function(void *arg) {
    struct session *session = arg;
    while (session->used < session->budget) {
        log_event(session);
    }
    free(session->entries);
    fprintf(stderr, "Session completed. Memory usage: %zu bytes\n", session->used);
    return NULL;
}

void create_session(struct logging_manager *manager, size_t budget) {
    if (manager->num_sessions >= manager->max_sessions) {
        fprintf(stderr, "Error: Cannot create new session. Maximum number of sessions reached\n");
        return;
    }

    struct session *session = mmap(NULL, sizeof(struct session), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (session == MAP_FAILED) {
        perror("Error: Failed to allocate memory for new session");
        return;
    }

    session->budget = budget;
    session->used = 0;
    pthread_create(&session->thread, NULL, session_function, session);
    sem_init(&session->mem_lock, 0, 1);
    manager->sessions[manager->num_sessions++] = session;
}

