void init_mempool() {
    int budget = max_memory / 4; // reserve 25% for system overhead
    void* p = mmap(NULL, budget, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (p == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    mempool = p;
}

void* alloc(size_t size) {
    pthread_mutex_lock(&mem_lock);
    if (memory_usage + size > max_memory * 0.75) {
        printf("Warning: Memory usage exceeded 75% of budget\n");
    }
    void* ptr = mempool;
    memory_usage += size;
    num_allocations++;
    capacity += size;
    pthread_mutex_unlock(&mem_lock);
    return ptr + (memory_usage - capacity);
}

void free(void *ptr) {
    pthread_mutex_lock(&mem_lock);
    memory_usage -= capacity;
    num_allocations--;
    capacity = 0;
    pthread_mutex_unlock(&mem_lock);
    munmap(ptr - (memory_usage), capacity);
}

