class LogEntry {
    Instant timestamp;
    int severityLevel;
    String message;

    public LogEntry(Instant timestamp, int severityLevel, String message) {
        this.timestamp = timestamp;
        this.severityLevel = severityLevel;
        this.message = message;
    }
}

class Session {
    private final Semaphore semaphore;
    private final double budget;
    private final List<LogEntry> logEntries;
    private long allocatedMemory;

    public Session(double budget) {
        this.semaphore = new Semaphore(budget * 1024 * 1024); // initializing semaphore for budget
        this.logEntries = new ArrayList<>();
        this.budget = budget;
        this.allocatedMemory = 0;
        initializeLogEntryArray();
    }

    public void start() {
        try {
            semaphore.acquire();
            allocateMemoryForNewEntry();
            runSessionTasks(); // replace with your session tasks
        } finally {
            semaphore.release();
        }
    }

    public void stop() {
        sendMessageToMessagingSystem();
    }

    private void initializeLogEntryArray() {
        int capacity = (int) Math.ceil(budget * 1024 / LogEntry.class.getHeaderSize()); // calculate array capacity based on budget
        for (int i = 0; i < capacity; i++) {
            logEntries.add(new LogEntry(Instant.now(), new Random().nextInt(5) + 1, generateMessage()));
        }
    }

    private void allocateMemoryForNewEntry() {
        allocatedMemory += LogEntry.class.getHeaderSize() + LogEntry.class.getName().length() + 64; // approximately 64 bytes for message length and overheads
        if (allocatedMemory > budget * 0.7) {
            System.out.println("Warning: Session exceeded 70% of memory quota.");
        }
    }

    private String generateMessage() {
        List<String> eventTypes = Arrays.asList("System Restart", "Disk Space Low", "Network Error");
        return eventTypes.get(new Random().nextInt(eventTypes.size()));
    }
}

class LoggingManager {
    private final ConcurrentHashMap<Integer, Session> sessions;
    private final Path consolidatedLogFile;

    public LoggingManager(Path consolidatedLogFile) {
        this.sessions = new ConcurrentHashMap<>();
        this.consolidatedLogFile = consolidatedLogFile;
    }

    public void startSession() {
        int sessionId = new Random().nextInt();
        Session session = new Session(1.5);
        sessions.put(sessionId, session);
        Thread thread = new Thread(() -> {
            try {
                while (!session.semaphore.tryAcquireNanos(1000000000)) { // try to acquire semaphore for 1 second with a nano-timeout
                    Thread.sleep(new Random().nextInt(100)); // add random delay before retrying
                }
                session.start();
            } catch (InterruptedException e) {
                System.out.println("Error starting session: " + e.getMessage());
            }
        });
        thread.start();
    }

    public void mergeLogs() {
        // Implement the customizable consolidation logic here
    }
}
