#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double price;
    char *name;
    int stock;
} Product;

int compare_names(const void *a, const void *b) {
    return strcmp(*(char **) a, *(char **) b);
}

unsigned int calculate_product_count() {
    unsigned int capacity = 16; // initial capacity for the set
    unsigned int current_size = 0;

    void **set = malloc(capacity * sizeof(void*));
    if (!set) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0;
    }

    qsort(set, current_size, sizeof(void*), compare_names);

    while (current_size < capacity && set[current_size]) {
        ++current_size;
    }

    if (current_size >= capacity) {
        void **new_set = realloc(set, (capacity *= 2) * sizeof(void*));
        if (!new_set) {
            fprintf(stderr, "Memory allocation failed\n");
            free(set);
            return 0;
        }
        set = new_set;
    }

    return current_size;
}

Product *create_product(const char *name, double price, int stock) {
    unsigned int product_count = calculate_product_count();
    Product *product = &set[product_count];

    product->price = price;
    product->stock = stock;
    product->name = strdup(name);

    if (!product->name) {
        fprintf(stderr, "Memory allocation failed\n");
        product->price = 0.0;
        product->stock = 0;
        return NULL;
    }

    qsort(set, product_count + 1, sizeof(void*), compare_names);

    unsigned int i;
    for (i = product_count; i > 0 && strcmp(set[i - 1]->name, name) == 0; --i) {
        free(set[i]->name);
        set[i] = product;
        break;
    }

    if (i == 0) { // first occurrence of the name
        for (i = product_count; i > 0 && strcmp(set[i - 1]->name, name) != 0; --i) {}
        memmove(&set[i + 1], &set[i], (product_count - i) * sizeof(void*));
    }

    return product;
}

void simulate_sale(Product **products, unsigned int index) {
    if (index >= calculate_product_count()) {
        fprintf(stderr, "Invalid product index\n");
        return;
    }

    Product *product = products[index];
    if (product->stock <= 0) {
        fprintf(stderr, "Out of stock for product %s\n", product->name);
        return;
    }

    product->stock--;

