#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_PRODUCTS 10000
#define TOTAL_STOCK_LIMIT 100000
#define SALES_PER_SECOND 1000

typedef struct {
    double price;
    char* name;
    int stock;
} Product;

int total_stock = 0;
double total_revenue = 0.0;
Product products[MAX_PRODUCTS];

// Function to check if a product with the given name already exists in the array
bool product_exists(char* name) {
    for (int i = 0; i < total_stock; ++i) {
        if (!strcmp(products[i].name, name)) return true;
    }
    return false;
}

// Function to safely copy the product name into allocated memory
void str_copy(char* dest, const char* src, size_t size) {
    for (size_t i = 0; i < size && src[i]; ++i) {
        dest[i] = src[i];
    }
    dest[size] = '\0';
}

// Function to dynamically allocate memory for a product structure and initialize its fields
Product* new_product(double price, const char* name, int stock) {
    Product* product = (Product*) malloc(sizeof(Product));
    if (!product) return NULL;

    product->price = price;
    size_t len = strlen(name) + 1;
    product->name = (char*) malloc(len);
    if (!product->name) {
        free(product);
        return NULL;
    }
    str_copy(product->name, name, len);
    product->stock = stock;
    total_stock++;
    return product;
}

// Function to simulate a sale and update the inventory accordingly
bool sell_product(Product* product, int quantity) {
    if (quantity <= 0) return false;

    int available_stock = product->stock;
    if (available_stock < quantity) {
        printf("Sale canceled: Insufficient stock.\n");
        return false;
    }

    total_revenue += product->price * quantity;
    product->stock -= quantity;
    total_stock -= quantity;
    return true;
}

// Function to report the current state of the inventory
void inventory_report() {
    printf("\nInventory:\nTotal Stock: %d\nTotal Revenue: %.2f\n", total_stock, total_revenue);
}

// Function to add a product to the inventory if it doesn't already exist and the total stock does not exceed the limit
Product* add_product(double price, const char* name, int stock) {
    if (total_stock + stock > TOTAL_STOCK_LIMIT) return NULL;

    if (product_exists(name)) return NULL;

    Product* product = new_product(price, name, stock);
    if (!product) return NULL;

    products[total_stock] = *product;
    return product;
}
```

