log_entry* create_log_session(size_t budget, size_t* current_usage) {
    log_entry* log = malloc(sizeof(log_entry));
    if (!log) return NULL;

    log->timestamp = time(NULL);
    log->severity_level = rand_severity();
    log->message = create_message();

