// Data structure for logging sessions
typedef struct session_list {
    log_entry* head;
    log_entry* tail;
    size_t total_memory;
} session_list;

session_list* create_session_list() {
    session_list* list = malloc(sizeof(session_list));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->total_memory = 0;

    return list;
}

void add_log_entry(session_list* list, log_entry* entry) {
    if (!list || !entry) return;

    // Append the log entry to the end of the list
    if (!list->head) {
        list->head = entry;
        list->tail = entry;
    } else {
        list->tail->next = entry;
        list->tail = entry;
    }

    // Update total memory usage for the list
    list->total_memory += sizeof(log_entry) + strlen(entry->message) + 1;
}
