void* malloc_aligned(size_t size, size_t align) {
    void *ptr = malloc(size + align - 1);
    if (!ptr) return NULL;
    memset((char *)ptr + align - 1, '\0', align);
    return (void *)(((long)ptr + align - 1) & ~(align - 1));
}

DataChannel* create_data_channel() {
