    Config *cfg = mmap(NULL, sizeof(Config), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (cfg == MAP_FAILED) {
        perror("Failed to map config");
        goto cleanup;
    }
    memcpy(cfg, &config, sizeof(Config));

    // Initialize offsets and keys arrays
