    for (size_t i = 0; i < config.num_records; ++i) {
        records[i].offset = current_offset++;
        records[i].key = keys[i] = i % config.key_range;
    }

    // Implement data processing, logging, and concurrency support here

cleanup:
    munmap(cfg, sizeof(Config));
    free(keys);
    free(records);
    free(offsets);
