void compress(const std::string& inData, std::string& outData) {
    uLong adler = 1;
    uLong buf;

    while (inData.length() > 5556) {
        buf = inData.substr(0, 5556).c_str();
        adler = zlibAdler32(adler, buf, strlen(buf));
        inData.erase(0, 5556);
