    uLongf totalIn = inData.length();
    compressBound(totalIn, Z_DEFAULT_COMPRESSION, compressedData.capacity());
    compressedData.resize(compressedData.capacity());
    uLongf totalOut = deflateInit2(&compresser, Z_DEFAULT_COMPRESSION, Z_DEFLATE_FINISH, MAX_WBITS + 15, MAX_MEM_LEVEL, Z_DEFLETE_STRATEGY);
    totalIn += deflateInit(&compresser, Z_DEFAULT_COMPRESSION);
