import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonProcessingException;

import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

public class JsonHandler {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final Map<String, FactoryFunction> factoryFunctions = new HashMap<>();

    public String toJson(Object obj) {
        try {
            return objectMapper.writeValueAsString(obj);
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to convert object to JSON", e);
        }
    }

    public <T> T fromJson(String json, Class<T> clazz) {
        try {
            return objectMapper.readValue(json, clazz);
        } catch (IOException e) {
            throw new RuntimeException("Failed to convert JSON string to object", e);
        }
    }

    public static void registerFactoryFunction(String id, FactoryFunction factoryFunction) {
        factoryFunctions.put(id, factoryFunction);
    }

    public static JsonHandler createInstance(String id) throws InstantiationException, IllegalAccessException, InvocationTargetException, NoSuchMethodException {
        FactoryFunction factoryFunction = factoryFunctions.get(id);
        if (factoryFunction == null) {
            throw new IllegalArgumentException("Invalid ID provided");
        }
        return factoryFunction.createInstance();
    }

    public interface FactoryFunction {
        JsonHandler createInstance() throws InstantiationException, IllegalAccessException, InvocationTargetException, NoSuchMethodException;
    }
}
