import java.util.concurrent.Executors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class JsonHandler {
    private static final Logger LOGGER = LoggerFactory.getLogger(JsonHandler.class);

    private static final Map<String, Method> FACTORY_METHODS = new ConcurrentHashMap<>();
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final Gson GSON = new Gson();
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();

    public void loadFactories(String configFile) {
        try (FileReader reader = new FileReader(configFile)) {
            // Parse configuration file and load factory methods dynamically
            // Handle invalid or incomplete entries gracefully
        } catch (IOException e) {
            LOGGER.error("Error loading factories: ", e);
        }
    }

    public void addFactory(String id, Class<? extends JsonHandler> clazz, Method factoryMethod) {
        FACTORY_METHODS.putIfAbsent(id, factoryMethod);
    }

    public <T extends JsonHandler> T createFromJson(String json, Class<T> clazz) throws IOException, IllegalAccessException, InvocationTargetException, InstantiationException {
        JsonNode node = OBJECT_MAPPER.readTree(json);
        return (T) EXECUTOR.submit(() -> createFromJson(node, clazz)).get();
    }

    private <T extends JsonHandler> T createFromJson(JsonNode node, Class<T> clazz) throws IOException, IllegalAccessException, InvocationTargetException, InstantiationException {
        for (Map.Entry<String, Method> entry : FACTORY_METHODS.entrySet()) {
            if (entry.getValue().getAnnotation(Override.class) != null && entry.getKey().equals(node.get("id").asText())) {
                return entry.getValue().invoke(null, OBJECT_MAPPER, node);
            }
        }
        // Handle case when no factory method is found for the given id

        throw new IllegalArgumentException("No factory method found for id: " + node.get("id").asText());
    }

    public String toJson(Object object) {
        return GSON.toJson(object);
    }
}
