#define MAX_RECORDS 100000
#define MAX_MEMORY (1024 * 1024) // 1 MB
#define WARNING_THRESHOLD (0.75 * MAX_MEMORY)
#define MIN_VALUE -1000000
#define MAX_VALUE 1000000

typedef struct {
    int key;
    long offset;
    int value;
} Record;

Record* create_record();
void destroy_record(Record* record);
void init_memory(size_t* keys_len, size_t* offsets_len);
void deinit_memory(size_t keys_len, size_t offsets_len);

// Function for managing memory allocation and initialization of a collection of records
Record* manage_records(size_t* keys_len, size_t* offsets_len) {
    // Allocate memory for the arrays
    init_memory(keys_len, offsets_len);

    // Initialize records with random values and track their sizes
    *keys_len = 0;
    *offsets_len = 0;
    while (get_memory_usage() < MAX_MEMORY) {
        Record* record = create_record();
        (*keys_len)++;
        (*offsets_len)++;
    }

    // Monitor memory usage every 5 seconds and log a warning if exceeding the threshold
    const int interval = 5;
    while (get_memory_usage() < MAX_MEMORY && *keys_len > 0) {
        usleep(interval * 1000000); // Sleep for 5 seconds

        if ((double)(get_memory_usage()) / (double)MAX_MEMORY >= WARNING_THRESHOLD) {
            printf("Warning: Memory usage exceeded %f percentage of the allocated budget.\n", WARNING_THRESHOLD * 100);
        }
    }

    // Deallocate memory at function exit to prevent memory leaks
    deinit_memory(*keys_len, *offsets_len);

    return NULL;
}

// Function for creating a record with random value within the specified range
Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (record != NULL) {
        record->key = rand() % MAX_VALUE + MIN_VALUE;
        record->offset = get_memory_usage();
        record->value = rand() % MAX_VALUE + MIN_VALUE;
    }
    return record;
}

// Function for destroying a record and freeing its memory
void destroy_record(Record* record) {
    if (record != NULL) {
        free(record);
    }
}

// Function for initializing the key and offset arrays with zeroed-out memory
void init_memory(size_t* keys_len, size_t* offsets_len) {
    int* keys = mmap(NULL, *keys_len * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (keys == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    long* offsets = mmap(NULL, *offsets_len * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (offsets == MAP_FAILED) {
        perror("mmap failed");
        free(keys);
        exit(EXIT_FAILURE);
    }

    *keys_len = 0;
    *offsets_len = 0;
}

// Function for deinitializing the key and offset arrays, freeing their memory, and removing them from the system
void deinit_memory(size_t keys_len, size_t offsets_len) {
    munmap(NULL, keys_len * sizeof(int));
    munmap(NULL, offsets_len * sizeof(long));
}

// Function for calculating the current memory usage in bytes
size_t get_memory_usage() {
    // Calculate memory usage considering allocated and used memory blocks
    // Adjust this calculation according to your system's specific needs
    return mmap(NULL, 0, PROT_NONE, MAP_PRIVATE | MAP_ANON, -1, 0) - getpagesize();
}
