worker* create_worker(size_t task_count) {
    worker* worker = malloc(sizeof(worker));
    worker->tasks = malloc(task_count * sizeof(task));

    for (size_t i = 0; i < task_count; ++i) {
        worker->tasks[i].payload = malloc(sizeof(long));
        worker->tasks[i].priority = rand() % task_count;
    }

    worker->count = task_count;
    return worker;
}

void free_worker(worker* worker) {
    for (size_t i = 0; i < worker->count; ++i)
        free(worker->tasks[i].payload);
    free(worker->tasks);
    free(worker);
}
