typedef struct {
    uint32_t timestamp;
    float value;
    char status_flag;
    int identifier;
} data_chunk;

void* generate_data(void* arg) {
    int *idx = (int*)arg;
    while (1) {
        data_chunk* dc = &((*arr_dc)[*idx]);
        dc->timestamp = time(NULL);
        dc->value = (rand() / (float)RAND_MAX) * 0.1f + 0.9f;
        dc->status_flag = (rand() % 2 == 0) ? 'S' : 'F';
        dc->identifier = *idx++;

        if (pthread_mutex_lock(&mutex)) {
            perror("Error locking mutex");
            exit(1);
        }
        // Flush data to disk if necessary
        if (time(NULL) - dc->timestamp > 600) {
            flush_data();
            dc->timestamp = time(NULL);
        }
        pthread_mutex_unlock(&mutex);
        usleep(100000); // Simulate some work
    }
}

void flush_data() {
    static const char *filename = "data.bin";
    int fd;
    void *mmaped_addr;
    size_t num_elements = sizeof(arr_dc[0]) / sizeof(data_chunk);

    if ((fd = open(filename, O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR)) == -1) {
        perror("Error opening file");
        return;
    }

    ftruncate(fd, num_elements * sizeof(data_chunk));
    mmaped_addr = mmap(NULL, num_elements * sizeof(data_chunk), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mmaped_addr == MAP_FAILED) {
        perror("Error mapping file");
        close(fd);
        return;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        memcpy((char*)mmaped_addr + i * sizeof(data_chunk), &arr_dc[i], sizeof(data_chunk));
    }

    msync(mmaped_addr, num_elements * sizeof(data_chunk), MS_SYNC);
    munmap(mmaped_addr, num_elements * sizeof(data_chunk));
    close(fd);
}

void init() {
    arr_d = (double*)malloc(NUM_D * sizeof(double));
    if (!arr_d) {
        perror("Error allocating double array");
        exit(1);
    }

    arr_c = (char*)malloc(NUM_C * sizeof(char));
    if (!arr_c) {
        perror("Error allocating char array");
        free(arr_d);
        exit(1);
    }

    arr_dc = (data_chunk*)malloc(NUM_DC * sizeof(data_chunk));
    if (!arr_dc) {
        perror("Error allocating data_chunk array");
        free(arr_c);
        free(arr_d);
        exit(1);
    }

    arr_sc = (int*)malloc(NUM_SC * sizeof(int));
    if (!arr_sc) {
        perror("Error allocating int array");
        free(arr_c);
        free(arr_d);
        free(arr_dc);
        exit(1);
    }

    pthread_mutex_init(&mutex, NULL);
}

int main() {
    init();
    // Start worker threads
    pthread_t workers[NUM_WORKERS];
    for (int i = 0; i < NUM_WORKERS; ++i) {
        int* idx = malloc(sizeof(int));
        *idx = i;
        if (pthread_create(&workers[i], NULL, generate_data, idx)) {
            perror("Error creating thread");
            exit(1);
        }
    }

    // Wait for worker threads to finish
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }

    free(arr_c);
    free(arr_d);
    free(arr_dc);
    free(arr_sc);
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

