typedef struct Project {
    Resource* resource;
    // Other project-specific members...
} Project;

typedef struct Team {
    int size;
    int capacity;
    Project** projects;
} Team;

// Dynamically allocate and initialize an array of project structures
Project* create_project(Resource* resource) {
    Project* project = (Project*) malloc(sizeof(Project));
    project->resource = resource;
    // Initialize other project-specific members...
    return project;
}

// Dynamically allocate and initialize an array of team structures
Team* create_team() {
    Team* team = (Team*) malloc(sizeof(Team));
    team->size = 0;
    team->capacity = 0;
    team->projects = NULL;
    return team;
}

// Function to ensure that the total budget across all projects managed by a team does not exceed a specified threshold
int is_valid_team(Team* team, double budget_threshold) {
    double total_budget = 0.0;

    for (int i = 0; i < team->size; ++i) {
        Project* project = team->projects[i];
        if (project && project->resource)
            total_budget += project->resource->budget;
    }

    return (total_budget <= budget_threshold);
}

// Dynamic team resizing and task rebalancing when a project is added or removed
void resize_team(Team* team, int new_capacity) {
    Project** new_projects = (Project**)realloc(team->projects, new_capacity * sizeof(Project*));

    if (new_projects != NULL) {
        team->projects = new_projects;
        team->capacity = new_capacity;
    }
}

void add_project_to_team(Team* team, Project* project) {
    resize_team(team, team->size + 1);
    team->projects[team->size++] = project;
}

void remove_project_from_team(Team* team, int index) {
    if (index < 0 || index >= team->size)
        return;

    for (int i = index + 1; i < team->size; ++i)
        team->projects[i - 1] = team->projects[i];

    team->projects[--team->size] = NULL;
}

// Efficiently free all allocated memory when the project management system is shut down
void free_project(Project* project) {
    if (!project || !project->resource)
        return;

    free(project->resource->description);
    free(project->resource);
    free(project);
}

void free_team(Team* team) {
    for (int i = 0; i < team->size; ++i)
        free_project(team->projects[i]);

    free(team->projects);
    free(team);
}
