typedef struct {
    int id;
    void* buffer;
    size_t buffer_size;
    int ref_count;
    int sockfd;
    pthread_mutex_t mutex;
} DataChannel;

void initDataChannel(DataChannel* channel, int id, size_t buffer_size);
void freeDataChannel(DataChannel* channel);
int setupConnection(const char* host, int port);
unsigned char* md5_hash(const char* str);

// Implement the function
void setupDataTransferChannels(int max_channels) {
    DataChannel channels[max_channels];
    for (int i = 0; i < max_channels; ++i) {
        initDataChannel(&channels[i], i, BUFFER_SIZE);
        if (setupConnection(HOST, PORT) == -1) {
            freeDataChannel(&channels[i]);
            --max_channels;
        }
    }
    // Dynamic scaling logic based on real-time network conditions goes here
}

void initDataChannel(DataChannel* channel, int id, size_t buffer_size) {
    if (!(channel->buffer = malloc(buffer_size))) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    channel->id = id;
    channel->buffer_size = buffer_size;
    channel->ref_count = 0;
    channel->sockfd = -1;
    pthread_mutex_init(&channel->mutex, NULL);
}

void freeDataChannel(DataChannel* channel) {
    if (channel->buffer) free(channel->buffer);
    close(channel->sockfd);
    pthread_mutex_destroy(&channel->mutex);
}

int setupConnection(const char* host, int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    inet_pton(AF_INET, host, &serv_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) == -1) {
        perror("connect");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

unsigned char* md5_hash(const char* str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    unsigned char* result = malloc(MD5_DIGEST_LENGTH);
    if (!result) {
        perror("malloc");
        return NULL;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(digest, &ctx);

    memcpy(result, digest, MD5_DIGEST_LENGTH);
    return result;
}
```

