#include <unistd.h>

#define MAX_QUERIES 10
#define CACHE_SIZE 512
#define TIMEOUT (5 * NANOSECOND)

struct query {
    struct hostent he;
    u_char ip[sizeof(u_long)];
    bool resolved;
};

struct cache {
    struct query cache[CACHE_SIZE];
    size_t head, tail;
};

struct dns_query {
    const char *hostname;
    int fd;
    ssize_t len;
    void (*cb)(struct dns_query *, int, struct hostent *);
};

static struct cache dns_cache;
static ev_loop *loop = NULL;

void dns_resolve_cb(struct dns_query *dq, int err, struct hostent *he) {
    if (err == 0 && he != NULL) {
        memcpy(dq->ip, he->h_addr_list[0], sizeof(u_long));
        dq->he = *he;
        dq->resolved = true;
    }

    ev_timer *timer = &dq->timer;
    if (err || !dq->resolved) {
        ev_timer_stop(loop, timer);
        free(dq->hostname);
        free(dq);
    }
}

void dns_query_free(struct dns_query *dq) {
    if (dq->hostname) free(dq->hostname);
    if (dq->fd != -1) close(dq->fd);
}

void dns_insert_cache(const char *hostname, struct hostent he) {
    memcpy(&dns_cache.cache[dns_cache.head], &he, sizeof(struct hostent));
    dns_cache.head = (dns_cache.head + 1) % CACHE_SIZE;
}

struct dns_query *dns_get_from_cache(const char *hostname) {
    for (size_t i = dns_cache.tail; i != dns_cache.head; i = (i + 1) % CACHE_SIZE) {
        if (!strcmp(hostname, dns_cache.cache[i].he.h_name)) {
            struct query *query = &dns_cache.cache[i];
            if (query->resolved) return (struct dns_query *)query;
        }
    }
    return NULL;
}

int main(void) {
    // Initialize ev_loop and other necessary resources
    loop = ev_default_loop(0, 0);

    // Implement the logic for adding DNS queries, handling query events, resolving IP addresses, caching, etc.

    ev_run(loop, 0);

    ev_loop_destroy(loop);
    return 0;
}
```

