typedef struct _Query {
    char hostname[256];
    u_char ip[sizeof(struct in_addr)];
    bool resolved;
    time_t timestamp;
} Query;

typedef struct _Cache {
    Query cache[CACHE_SIZE];
    size_t head, tail;
} Cache;

Cache g_cache;
pthread_mutex_t g_cache_lock = PTHREAD_MUTEX_INITIALIZER;

void add_to_cache(const char* hostname, const u_char* ip) {
    pthread_mutex_lock(&g_cache_lock);
    g_cache.cache[g_cache.head].hostname[0] = '\0';
    strcpy(g_cache.cache[g_cache.head].hostname, hostname);
    memcpy(g_cache.cache[g_cache.head].ip, ip, sizeof(struct in_addr));
    g_cache.cache[g_cache.head].resolved = true;
    g_cache.cache[g_cache.head].timestamp = time(NULL);
    if ((g_cache.head + 1) % CACHE_SIZE == g_cache.tail) {
        g_cache.tail = (g_cache.tail + 1) % CACHE_SIZE;
    }
    pthread_mutex_unlock(&g_cache_lock);
}

u_char* get_from_cache(const char* hostname) {
    Query query;
    pthread_mutex_lock(&g_cache_lock);
    for (size_t i = g_cache.head; i != g_cache.tail; i = (i + 1) % CACHE_SIZE) {
        memcpy(&query, &g_cache.cache[i], sizeof(Query));
        if (!strcmp(query.hostname, hostname) && query.resolved) {
            pthread_mutex_unlock(&g_cache_lock);
            return query.ip;
        }
    }
    pthread_mutex_unlock(&g_cache_lock);
    return NULL;
}

