Record* get_record(int key) {
    sem_wait(&cacheLock);
    struct CacheEntry *entry = (struct CacheEntry*)bsearch((const void*)&key, (void*)cache, cacheSize / sizeof(*entry), sizeof(*entry), compare_keys);
    if (entry != NULL) return &entry->record;
    sem_post(&cacheLock);

    // Not in cache, create new record and add to cache if necessary
    Record *newRecord = malloc(sizeof(Record));
    generate_random_record(newRecord);

    sem_wait(&cacheLock);
    if (cacheSize + sizeof(*entry) > maxCacheSize) {
