import java.io.File;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class HashUtility {
    private static final Logger LOGGER = Logger.getLogger(HashUtility.class.getName());
    private static Properties properties;
    private static Map<String, Map<String, String>> hashCache = new ConcurrentHashMap<>();
    private static SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    static {
        try {
            File propFile = new File("hash-utility.properties");
            properties = new Properties();
            properties.load(propFile);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error loading properties file.", e);
        }
    }

    private HashUtility() {} // Prevent instantiation

    public static String generateMD5(String input) {
        validateInput(input);
        return computeHash(MessageDigest.getInstance("MD5"), input, "MD5");
    }

    public static String generateSHA256(String input) {
        validateInput(input);
        return computeHash(MessageDigest.getInstance("SHA-256"), input, "SHA-256");
    }

    private static void validateInput(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }
    }

    private static String computeHash(MessageDigest digest, String input, String algorithm) {
        String key = getRateLimitingKey(algorithm);
        synchronized (key) {
            limitRateLimiting(key);
            String cachedHash = hashCache.getOrDefault(input, new HashMap<>()).getOrDefault(algorithm);
            if (cachedHash != null) {
                return cachedHash;
            }
        }
        byte[] hashedBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        BigInteger bigInt = new BigInteger(1, hashedBytes);
        String hashedHex = bigInt.toString(16);
        while (hashedHex.length() < 64) {
            hashedHex = "0" + hashedHex;
        }
        return hashedHex;
    }

    private static void limitRateLimiting(String key) {
        long currentTimeMillis = System.currentTimeMillis();
        long remainingTimeMillis = getRateLimitResetInterval() - (currentTimeMillis - getLastRequestTime(key));
        if (remainingTimeMillis > 0) {
            try {
                TimeUnit.MILLISECONDS.sleep(remainingTimeMillis);
            } catch (InterruptedException e) {
                LOGGER.log(Level.WARNING, "Sleep interrupted during rate limiting.", e);
            }
        }
        setLastRequestTime(key, currentTimeMillis);
    }

    private static long getRateLimitResetInterval() {
        return Long.parseLong(properties.getProperty("rate_limit_reset_interval", "60000")); // Default to 1 minute
    }

    private static void setLastRequestTime(String key, long currentTimeMillis) {
        File propFile = new File("hash-utility.properties");
        try (java.io.PrintWriter out = new java.io.PrintWriter(propFile)) {
            out.printf("%s.last_request_time=%d\n", key, currentTimeMillis);
            out.flush();
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error writing last request time to properties file.", e);
        }
    }

    private static long getLastRequestTime(String key) {
        Properties properties = new Properties();
        try {
            properties.load(new FileReader("hash-utility.properties"));
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error reading properties file.", e);
        }
        return properties.getLongProperty(key + ".last_request_time", 0);
    }

    private static String getRateLimitingKey(String algorithm) {
        return dateFormatter.format(new Date()) + "_" + algorithm;
    }
}
```

This code snippet includes methods for generating MD5 and SHA-256 hashes, input validation, rate limiting, logging, hash caching, and basic configuration through a properties file. However, it does not include the actual integration with an external logging service or any unit tests.']

