        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty.");
        }

        validateRateLimiting();

        String hash = CACHE.getOrDefault(input, computeHash(MessageDigest.getInstance("SHA-256"), input));
        logEvent("SHA-256", hash);
        return hash;
    }

