        long currentTime = System.currentTimeMillis();
        long intervalStart = currentTime - (60 * 1000); // 1 minute
        if (CACHE.size() > 10) { // adjust this threshold based on your requirements
            long remainingRequests = (60 * 1000) - (currentTime - intervalStart);
            if (remainingRequests > 0) {
                try {
                    Thread.sleep(remainingRequests);
                } catch (InterruptedException e) {
                    LOGGER.log(Level.SEVERE, "Thread interrupted during rate limiting", e);
                }
            }
        }
    }

    private void logEvent(String algorithm, String hash) {
        String requestId = DATE_FORMAT.format(new Date()) + "-" + System.currentTimeMillis();
        LOGGER.log(Level.INFO, "{0} hash: {1}", new Object[]{requestId, hash});
