import java.util.concurrent.atomic.AtomicLong;

public final class SecureHashUtil {
    private static final ConcurrentMap<String, byte[]> cache = new ConcurrentHashMap<>();
    private static final Deque<Runnable> taskQueue = new LinkedList<>();
    private static final ScheduledExecutorService executor = Executors.newScheduledThreadPool(4);
    private static final AtomicLong rateLimiter = new AtomicLong();

    public byte[] md5(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty.");
        }
        byte[] hash = cache.computeIfAbsent(input, this::computeMd5);
        return hash;
    }

    public byte[] sha256(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty.");
        }
        byte[] hash = cache.computeIfAbsent(input, this::computeSha256);
        return hash;
    }

    private void addTask(Runnable task) {
        synchronized (taskQueue) {
            if (!rateLimiter.getAndIncrement() % 1000L == 0) {
                // Allow tasks to queue up during periods of high load or user activity
                taskQueue.addLast(task);
            } else {
                // Execute the task immediately if rate limit allows
                executor.execute(task);
            }
        }
    }

    private void executeTasks() {
        Runnable task;
        while ((task = taskQueue.poll()) != null) {
            try {
                task.run();
            } catch (Exception e) {
                // Log and handle exceptions gracefully
            } finally {
                rateLimiter.decrementAndGet();
            }
        }
    }

    // Implement logging and caching mechanisms, performance monitoring, and other required features here...
}
