typedef struct user_session {
    char session_id[32];
    time_t last_activity_time;
    enum { ACTIVE, INACTIVE, SUSPENDED } current_status;
    size_t data_pointer_size;
    void* data_pointer;
} user_session;

#define SESSION_MAX_SIZE (1024 * 1024) // Max session size is 1 MB
#define SESSION_MAX_BUDGET (0.7 * SESSION_MAX_SIZE) // 70% of budget for a session

struct session_manager {
    user_session* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void init_session_manager(struct session_manager* sm, size_t max_sessions) {
    sm->capacity = max_sessions;
    sm->count = 0;
    sm->sessions = malloc(sizeof(user_session) * max_sessions);
    pthread_mutex_init(&sm->mutex, NULL);
}

void destroy_session_manager(struct session_manager* sm) {
    if (sm->sessions != NULL) {
        for (size_t i = 0; i < sm->capacity; ++i) {
            if (sm->sessions[i].data_pointer != NULL) free(sm->sessions[i].data_pointer);
        }
        free(sm->sessions);
        pthread_mutex_destroy(&sm->mutex);
    }
}

struct session_manager global_session_manager; // Global session manager instance

// Message queue for inter-process communication
mqd_t mq_id;

void* allocate_session(struct session_manager* sm) {
    user_session* session;
    pthread_mutex_lock(&sm->mutex);
    if (sm->count < sm->capacity && sm->sessions[sm->count].data_pointer == NULL) {
        session = &sm->sessions[sm->count];
        session->last_activity_time = time(NULL);
        session->current_status = RAND_MAX % 3;
        session->data_pointer_size = rand() % SESSION_MAX_SIZE + 1;
        session->data_pointer = malloc(session->data_pointer_size);
        ++sm->count;
    } else {
        session = NULL;
    }
    pthread_mutex_unlock(&sm->mutex);
    return session;
}

void check_memory_usage() {
    size_t used_memory = 0;
    for (size_t i = 0; i < global_session_manager.count; ++i) {
        if (global_session_manager.sessions[i].data_pointer != NULL &&
            global_session_manager.sessions[i].data_pointer_size > SESSION_MAX_BUDGET) {
            used_memory += global_session_manager.sessions[i].data_pointer_size;
        }
    }

    if (used_memory / (double)global_session_manager.count > 0.7 * SESSION_MAX_SIZE) {
        fprintf(stderr, "Warning: Exceeded 70% of session memory budget\n");
    }
}
```

