```cpp
#include <deque>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <future>

class QueueManager {
private:
    std::map<std::string, std::deque<std::packaged_task<void()>>> tasksByRegion;
    std::mutex mtx;
    std::condition_variable cv;
    int numThreads = 10;

public:
    QueueManager(int numThreads) : numThreads(numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            std::thread([this]() { this->processTasks(); }).detach();
        }
    }

    template<typename PacketType>
    void enqueue(const PacketType& packet) {
        auto it = tasksByRegion.find(packet.region());
        if (it == tasksByRegion.end()) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this, packet]() { return tasksByRegion.count(packet.region()) > 0; });
            it = tasksByRegion.find(packet.region());
        }

        auto task = std::packaged_task<void()>([packet]() { processPacket<PacketType>(packet); });
        it->second.push_back(std::move(task));
        task.get_future().wait(); // Trigger the execution of the task
    }

private:
    template<typename PacketType>
    void processTasks() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.notify_one();

            auto it = tasksByRegion.begin();
            if (it == tasksByRegion.end()) {
                lock.unlock();
                std::this_thread::yield();
                continue;
            }

            auto task = it->second.front();
            it->second.pop_front();
            lock.unlock();

            task.reset(); // Reset the task to make it ready for reuse
            task.get_future().wait(); // Trigger the execution of the task
        }
    }

    template<typename PacketType>
    void processPacket(const PacketType& packet) {
        // Implement the logic for processing a packet of type PacketType here.
    }
};
