#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *str;
    int priority;
} Node;

typedef struct MemoryManager {
    Node **nodes;
    size_t capacity;
    size_t used;
    size_t maxMemory;
    double memoryThreshold;
    pthread_mutex_t lock;
} MemoryManager;

void sort(Node *array, size_t size) {
    qsort(array, size, sizeof(Node), (int (*)(const void*, const void*))compareNodes);
}

int compareNodes(const void *a, const void *b) {
    return ((Node*)a)->priority - ((Node*)b)->priority;
}

MemoryManager *createMemoryManager(size_t initialCapacity, size_t maxMemory) {
    MemoryManager *mm = malloc(sizeof(MemoryManager));
    mm->nodes = calloc(initialCapacity, sizeof(Node*));
    mm->capacity = initialCapacity;
    mm->used = 0;
    mm->maxMemory = maxMemory;
    mm->memoryThreshold = 0.7 * maxMemory;
    mm->lock = PTHREAD_MUTEX_INITIALIZER;
    return mm;
}

void* addNode(void *manager) {
    MemoryManager *mm = (MemoryManager*)manager;
    pthread_mutex_lock(&mm->lock);
    if (mm->used + 1 > mm->capacity) {
        size_t newCapacity = mm->capacity * 2;
        Node **newNodes = realloc(mm->nodes, newCapacity * sizeof(Node*));
        if (!newNodes) {
            pthread_mutex_unlock(&mm->lock);
            return NULL;
        }
        mm->nodes = newNodes;
        mm->capacity = newCapacity;
    }

    Node *node = malloc(sizeof(Node));
    node->str = NULL;
    node->priority = 0;
    mm->nodes[mm->used] = node;
    mm->used++;

    pthread_mutex_unlock(&mm->lock);
    return node;
}

void freeNode(void *node) {
    if (!node) return;
    free((((Node*)node)->str));
    free(node);
}

void freeMemoryManager(MemoryManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    for (size_t i = 0; i < manager->used; ++i) {
        freeNode(manager->nodes[i]);
    }
    free(manager->nodes);
    free(manager);
}

void logWarning(const char *message) {
    printf("WARNING: %s\n", message);
}

void checkMemoryUsage(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t totalSize = 0;
    for (size_t i = 0; i < manager->used; ++i) {
        if (!manager->nodes[i]->str || !manager->nodes[i]) continue;
        totalSize += strlen(manager->nodes[i]->str) + 1;
    }
    pthread_mutex_unlock(&manager->lock);

    double memoryUsage = (double)totalSize / manager->maxMemory * 100;
    if (memoryUsage > manager->memoryThreshold) {
        logWarning("Memory usage exceeded the threshold.");
    }
}

Node** getSortedNodes(MemoryManager *manager) {
    checkMemoryUsage(manager);
    pthread_mutex_lock(&manager->lock);
    sort(manager->nodes, manager->used);
    pthread_mutex_unlock(&manager->lock);
    return manager->nodes;
}
