    struct dns_cache* cache = malloc(sizeof(struct dns_cache));
    cache->capacity = 10;
    cache->size = 0;
    cache->expire_time = evutil_time();

    // Add your hostnames to a list or array here, and call the DNS resolver for each one
    struct dns_query queries[20];

    for (int i = 0; i < 20; ++i) {
        strcpy(queries[i].hostname, "example.com"); // Replace with your hostnames
        queries[i].ev = event_new(base, -1, EV_PERSIST, dns_resolve_callback, &queries[i]);
        event_dns_buffer_init(&buffer);
        event_dns_buffer_set_host(&buffer, queries[i].hostname);
        event_dns_buffer_start(base, &queries[i].ev->data, &buffer);
    }

    event_base_dispatch(base);

    // Don't forget to clean up and free resources here
    event_free(queries);
    event_base_free(base);
    free(cache);

    return 0;
}

void dns_resolve_callback(evutil_socket_t, short event, void *arg) {
    struct dns_query* query = arg;
    if (event & EV_TIMEOUT) {
        // Handle timeout here
    } else {
        evdns_buffer_t* buffer = (evdns_buffer_t*)query->ev->data;
        int status = event_dns_buffer_get_status(buffer);

        if (status == EVDNS_STILLTRYING || status == EVDNS_SUCCESS) {
            // Cache hit or resolved IP found, handle accordingly
            ip_address* resolved_ip = &query->resolved_ip;
            memcpy(&resolved_ip->addr, event_dns_buffer_get_ip(buffer), sizeof(struct in6_addr));
            dns_cache_insert(query);
        } else {
            // Handle error here
        }
    }
}
