            byte[] digestBytes = mac.doFinal(text.getBytes(StandardCharsets.UTF_8));
            hash = new BigInteger(1, digestBytes);
            hashCache.putIfAbsent(text, hash);
        }

        return hash;
    }

    // Implement the remaining functionality as per your requirements, handling concurrency, rate limiting, logging, caching, etc.
}
