#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
} Record;

struct ParsingContext {
    size_t offsetCapacity, offsetSize;
    long *offsets;
    size_t keyCapacity, keySize;
    int *keys;
    size_t recordCapacity, recordSize;
    Record **records;
    FILE *file;
    pthread_mutex_t mutex;
};

Record* parseCSV(char const *filename, size_t offsetCapacity, size_t keyCapacity, size_t recordCapacity, int minValue, int maxValue) {
    struct ParsingContext ctx = {0};
    ctx.offsetCapacity = offsetCapacity;
    ctx.keyCapacity = keyCapacity;
    ctx.recordCapacity = recordCapacity;
    ctx.minValue = minValue;
    ctx.maxValue = maxValue;

    ctx.offsets = (long*)malloc(offsetCapacity * sizeof(long));
    ctx.keys = (int*)malloc(keyCapacity * sizeof(int));
    ctx.records = (Record**)calloc(recordCapacity, sizeof(Record*));

    ctx.file = fopen(filename, "r");
    if (!ctx.file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return NULL;
    }

    ctx.offsetSize = 0;
    ctx.keySize = 0;
    ctx.recordSize = 0;

    pthread_mutex_init(&ctx.mutex, NULL);

    int lineNumber = 1;
    char buffer[4096];
    size_t readBytes;

    while ((readBytes = fgets(buffer, sizeof(buffer), ctx.file))) {
        if (lineNumber == 1) continue; // Skip header row

        char *token = strtok(buffer, ",");
        long offset = atol(token);
        Record *record = NULL;

        pthread_mutex_lock(&ctx.mutex);
        if (ctx.recordSize >= ctx.recordCapacity) {
            ctx.recordCapacity *= 2;
            Record **newRecords = realloc(ctx.records, ctx.recordCapacity * sizeof(Record*));
            if (!newRecords) {
                fprintf(stderr, "Failed to resize records array\n");
                break;
            }
            ctx.records = newRecords;
        }
        record = &ctx.records[ctx.recordSize++];
        pthread_mutex_unlock(&ctx.mutex);

        token = strtok(NULL, ",");
        if (!token) {
            fprintf(stderr, "Error parsing line %d: missing key\n", lineNumber);
            continue;
        }
        record->key = atoi(token);

        pthread_mutex_lock(&ctx.mutex);
        if (ctx.keySize >= ctx.keyCapacity) {
            ctx.keyCapacity *= 2;
            int *newKeys = realloc(ctx.keys, ctx.keyCapacity * sizeof(int));
            if (!newKeys) {
                fprintf(stderr, "Failed to resize keys array\n");
                break;
            }
            ctx.keys = newKeys;
        }
        ctx.keys[ctx.keySize++] = record->key;

        pthread_mutex_lock(&ctx.mutex);
        if (ctx.offsetSize >= ctx.offsetCapacity) {
            ctx.offsetCapacity *= 2;
            long *newOffsets = realloc(ctx.offsets, ctx.offsetCapacity * sizeof(long));
            if (!newOffsets) {
                fprintf(stderr, "Failed to resize offsets array\n");
                break;
            }
            ctx.offsets = newOffsets;
        }
        ctx.offsets[ctx.offsetSize++] = offset;

        record->value = rand() % (maxValue - minValue + 1) + minValue;
        pthread_mutex_unlock(&ctx.mutex);
    }

    fclose(ctx.file);

    return ctx.records;
}

void freeData(Record **records, size_t recordCount) {
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i]);
    }
    free(records);

    free(records[recordCount]); // Free the last element to release extra memory
}
```

This function reads a CSV file, parses it efficiently using a context structure and dynamic memory allocation for arrays. It sets each record's value to a random integer within the specified range and handles potential errors. The function is thread-safe due to the use of a mutex lock to synchronize access to shared data structures. Memory is released when the function completes using the provided `freeData` function.']

