    Record** list = record_set->list;

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&record_set->mutex);
        return -1;
    }

    new_record->value = value;
    new_record->next = NULL;

    for (size_t i = 0; i < record_set->max_size; ++i) {
        if (!list[i]) {
            list[i] = new_record;
            break;
        }
    }

    pthread_mutex_unlock(&record_set->mutex);
    return 0;
}

Record* find_record(RecordSet* record_set, int key) {
    pthread_mutex_lock(&record_set->mutex);
    Record** list = record_set->list;

    for (size_t i = 0; i < record_set->max_size; ++i) {
        Record* current = list[i];
        while (current != NULL) {
            if (current->value == key) {
                break;
            }
            current = current->next;
        }
    }

    pthread_mutex_unlock(&record_set->mutex);
    return current;
}

int delete_record(RecordSet* record_set, int key) {
    pthread_mutex_lock(&record_set->mutex);
    Record** list = record_set->list;

    for (size_t i = 0; i < record_set->max_size; ++i) {
        Record* current = list[i];
        Record* previous = NULL;

        while (current != NULL) {
            if (current->value == key) {
                if (previous) {
                    previous->next = current->next;
                } else {
                    list[i] = current->next;
                }
                free(current);
                break;
            }
            previous = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&record_set->mutex);
    return 0;
}
