    char* payload;
    size_t payload_size;
    const char* title;
    long offset;
    int key;
} list_t;

typedef struct record {
    time_t timestamp;
    int value;
    list_t* parent;
} record_t;

list_t* init_list(int max_entries, size_t payload_size, const char* title, void (*callback)(struct record*), int min_value, int max_value) {
    list_t *list = (list_t*)malloc(sizeof(list_t));
    if (!list) return NULL;

    list->max_entries = max_entries;
    list->payload_size = payload_size;
    list->title = title;
    list->callback = callback;

    pthread_mutex_init(&(list->lock), NULL);
    sem_init(&(list->write_sem), 0, 1);
    sem_init(&(list->read_sem), 0, max_entries);

    list->current_size = 0;
    list->payload = (char*)malloc(payload_size * max_entries);
    if (!list->payload) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_list(list_t* list) {
    pthread_mutex_destroy(&(list->lock));
    sem_destroy(&(list->write_sem));
    sem_destroy(&(list->read_sem));
    free(list->payload);
    free(list);
}

record_t* create_record(int value, list_t* parent) {
    record_t *record = (record_t*)malloc(sizeof(record_t));
    if (!record) return NULL;

    record->parent = parent;
    record->timestamp = time(NULL);
    record->value = value < parent->min_value ? parent->min_value : (value > parent->max_value ? parent->max_value : value);

    return record;
}

int add_record(list_t* list, record_t* record) {
    pthread_mutex_lock(&(list->lock));

    if (list->current_size >= list->max_entries) {
        pthread_mutex_unlock(&(list->lock));
        return -1; // List is full.
    }

    // Fill the payload with a random value, replace this with your custom logic.
    for (int i = list->current_size; i < list->current_size + list->payload_size; ++i) {
        record->parent->payload[i] = rand() % 256;
    }

    memcpy((void*)(record + list->current_size), (void*)record, sizeof(record_t));
    record->parent->offset[list->current_size] = list->current_size;
    record->parent->key[list->current_size] = record->value;
    ++(list->current_size);

    pthread_mutex_unlock(&(list->lock));

    if (list->callback) {
        list->callback(record);
    }

    return 0; // Success.
}

