    size_t result = strlen(str);
    iconv(list->conv, &const char*[1], &(const char**)&str, NULL, NULL, ICONV_NOCHANGE);
    result += iconv(list->conv, NULL, NULL, &(char*)NULL, &(size_t*)&result, ICONV_NOCHANGE);
    return result * encoding_multiplier;
}

void add_task(struct TaskList* list, const char* description, int priority, double estimated_completion_time) {
    pthread_mutex_lock(&list->mutex);

    if (get_task_description_size(description) > (0.6 * list->memory_stats.total_allocated)) {
        if (list->log_func)
            list->log_func("Memory warning: Task description exceeds 60% memory budget");
    }

    size_t task_size = sizeof(Task) + get_task_description_size(description);
    if (list->capacity * sizeof(Task) + list->count * task_size > list->memory_stats.total_allocated) {
        size_t new_capacity = list->capacity * 2;
        Task* new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }

    Task* task = &list->tasks[list->count];
    task->description = malloc(get_task_description_size(description));
    if (!task->description) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    iconv(list->conv, &const char*[1], &(const char**)&description, &(task->description), NULL);
    task->priority = priority;
    task->estimated_completion_time = estimated_completion_time;

    list->memory_stats.total_used += task_size;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void sort_tasks(struct TaskList* list) {
    qsort(list->tasks, list->count, sizeof(Task), (int (*)(const void*, const void*))comparator);
}

int comparator(const void* task1, const void* task2) {
    return ((const Task*)task1)->priority - ((const Task*)task2)->priority;
}

Task* get_next_task(struct TaskList* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    Task* task = &list->tasks[0];
    memcpy(task, &list->tasks[--list->count], sizeof(Task));
    free(list->tasks[list->count].description);
    list->memory_stats.total_used -= (sizeof(Task) + get_task_description_size(task->description));
    pthread_mutex_unlock(&list->mutex);

    return task;
}

void cleanup(struct TaskList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->tasks[i].description);
    }
    free(list->tasks);
    iconv_close(list->conv);
    pthread_mutex_destroy(&list->mutex);
}
```']

