import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.Materialized;
import org.apache.kafka.streams.kstream.Produced;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import io.micrometer.core.instrument.MeterRegistry;
import lombok.extern.log4j.Log4j2;

@Log4j2
public class JsonProcessor {

    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static void main(String[] args) {
        // Create and configure Kafka Streams application
        StreamsBuilder builder = new StreamsBuilder();

        // Define the source and sink topics, serde configurations
        Serde<String> stringSerde = Serdes.String();
        Serde<JsonNode> jsonNodeSerde = JsonNodeSerde.serdeWith(stringSerde);

        // Create a KStream from the source topic
        KStream<String, JsonNode> stream = builder.stream("source-topic")
                                                .transformValues(()-> new MyTransformer(), ()-> jsonNodeSerde)
                                                .toStream()
                                                .peek((key, value) -> log.debug("Processed message: {}", key + ":" + value))
                                                .to("sink-topic", Produced.with(stringSerde, jsonNodeSerde));

        // Start the Kafka Streams application
        KafkaStreams streams = new KafkaStreams(builder, config);
        Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
        streams.start();
    }

    static class MyTransformer {
        @SuppressWarnings("unchecked")
        public void transform(KTable<String, JsonNode> table) {
            KStream<String, Number> numericStream = table.filter((key, value) -> value.isContainer() && !value.isEmpty())
                                                       .mapValues(value -> (Number) value.get("fieldName"))
                                                       .filter((key, value) -> value != null);
            numericStream.aggregate(
                    () -> 0d,
                    (key, aggregate, value) -> aggregate + value,
                    Materialized.as("aggregated-state")
            ).toStream()
                .peek((key, value) -> log.debug("Aggregated result: {}", key + ":" + value))
                .to("result-topic", Produced.with(stringSerde, stringSerde));
        }
    }

    static class JsonNodeSerde implements Serde<JsonNode> {

        private static final JsonNodeSerde SERDE = new JsonNodeSerde();

        public JsonNodeSerde() {
            // Configure serializer and deserializer
        }

        @Override
        public Serializer<JsonNode> serializer() {
            return SERIALIZER;
        }

        @Override
        public Deserializer<JsonNode> deserializer() {
            return DESERIALIZER;
        }

        static final Serializer<String> SERIALIZER = new StringSerializer<>(SERDE.deserializer());
        static final Deserializer<JsonNode> DESERIALIZER = new JsonDeserializer<>(objectMapper);
    }
}
