[' **C Solution:**

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t memory_used = 0;
static const size_t max_memory = 1 * (1024 * 1024);
static const double threshold = 0.8;
static Record* records = NULL;
static pthread_cond_t records_avail = PTHREAD_COND_INITIALIZER;
static pthread_t init_thread, monitor_thread;

void initRecord(Record* record) {
    record->offset = (long) rand() * 1000000 + time(NULL);
    record->key = rand() % 1000000;
    record->value = rand() % 100 + 1;
}

void* initRecordsWorker(void* arg) {
    size_t chunk_size = max_memory / (sizeof(Record) * 4);
    Record* chunk = malloc(chunk_size * sizeof(Record));
    if (!chunk) return NULL;
    for (int i = 0; i < chunk_size; ++i) initRecord(&chunk[i]);
    pthread_mutex_lock(&mem_lock);
    size_t new_memory_used = memory_used + chunk_size * sizeof(Record);
    pthread_mutex_unlock(&mem_lock);
    if (new_memory_used > threshold * max_memory) {
        free(chunk);
        printf("Memory limit exceeded! Exiting...\n");
        pthread_exit(NULL);
    }
    for (size_t i = 0; i < chunk_size; ++i) records = realloc(records, sizeof(Record) * (records ? ((size_t) records - chunk) + chunk_size : chunk_size));
    memcpy(records + (records ? (sizeof(Record) * ((size_t) records - chunk)) : 0), chunk, chunk_size * sizeof(Record));
    free(chunk);
    pthread_cond_signal(&records_avail);
    pthread_exit(NULL);
}

void* memoryMonitorWorker(void* arg) {
    while (1) {
        sleep(5);
        pthread_mutex_lock(&mem_lock);
        double usage_ratio = memory_used / (double) max_memory;
        pthread_mutex_unlock(&mem_lock);
        if (usage_ratio > threshold) printf("Memory usage exceeded the threshold! Exiting...\n");
    }
}

Record* createRecords(size_t count) {
    if (pthread_create(&init_thread, NULL, &initRecordsWorker, NULL)) return NULL;
    if (pthread_create(&monitor_thread, NULL, &memoryMonitorWorker, NULL)) return NULL;

    pthread_cond_wait(&records_avail, &mem_lock);
    Record* result = malloc(count * sizeof(Record));
    memcpy(result, records, count * sizeof(Record));
    free(records);

    void* retval;
    if (pthread_join(init_thread, &retval)) return NULL;
    if (pthread_join(monitor_thread, &retval)) return NULL;

    return result;
}
