    private static final ConcurrentHashMap<String, byte[]> CACHE = new ConcurrentHashMap<>();
    private static Counter hashRequests;
    private static Tracer tracer;

    public SecureHashUtils(MeterRegistry meterRegistry, Tracer tracer) {
        this.tracer = tracer;
        this.hashRequests = meterRegistry.counter("hash.requests");
    }

    public byte[] getMD5Hash(String input) {
