        String key = createUniqueKey(input);
        hashRequests.increment();
        byte[] cacheValue = CACHE.get(key);
        if (cacheValue != null) return cacheValue;
        OkHttpClient client = new OkHttpClient();
        MediaType mediaType = MediaType.parse("application/x-www-form-urlencoded");
        RequestBody body = RequestBody.create(mediaType, "input=" + input);
        Request request = new Request.Builder()
            .url("https://hasher.example.com")
            .post(body)
            .build();
        Future<Response> future = client.newCall(request).submit();
        Response response = null;
        try {
            response = future.get(10, TimeUnit.SECONDS);
            if (!response.isSuccessful()) throw new IOException("Unexpected code " + response.code());
            return response.body().bytes();
        } catch (ExecutionException | InterruptedException | IOException e) {
            LOGGER.log(Level.WARNING, "Error while generating MD5 hash", e);
            return null;
        } finally {
            if (response != null && !response.isRedirection()) response.close();
        }
    }

    public byte[] getSHA256Hash(String input) {
        // Similar implementation for SHA-256, with the appropriate hashing algorithm used.
    }

    private String createUniqueKey(String input) {
        return FormatUtils.MD5.toString(System.currentTimeMillis() + ":" + input).substring(0, 8);
    }
}
