    for (int i = 0; i < numSessions + numDataChannels; ++i) {
        offsets[i] = currentOffset++;
        keys[i] = currentOffset % maxKeyRange;
        records[i].key = keys[i];
        records[i].buffer = malloc(BUFFER_SIZE);
        memset(records[i].buffer, DEFAULT_STRING, BUFFER_SIZE);
    }

    // Concurrently manage sessions and data channels using pthreads
    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; ++i) {
        int rc = pthread_create(&threads[i], NULL, manageSessionAndDataChannel, &cache, &offsets, &keys, &records);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(-1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup resources
    lrucache_free(cache);
    free(offsets);
    free(keys);
    for (int i = 0; i < numSessions + numDataChannels; ++i) {
