    node->prev = NULL;
    node->next = NULL;

    if (!cache->lru) {
        cache->lru = node;
    } else {
        struct lru_node *last = cache->lru;
        while (last->next) last = last->next;
        last->next = node;
        node->prev = last;
    }
}

void* lru_cache_get(struct lru_cache *cache, size_t index) {
