        void *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(data, cache->lru->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cache->lru = cache->lru->prev;
        cache->nodes[index] = cache->lru;
    }
    return cache->nodes[index];
}

void lru_cache_free(struct lru_cache *cache) {
    struct lru_node *node = cache->lru;
    while (node) {
        struct lru_node *next = node->next;
        free(node);
        node = next;
    }
}

