struct mempool {
    void *start;
    size_t size;
    size_t allocated;
};

void mempool_init(struct mempool *pool, size_t size) {
    pool->size = size;
    pool->allocated = 0;
    pool->start = mmap(NULL, pool->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void *mempool_get(struct mempool *pool) {
    if (pool->allocated < pool->size) {
        return pool->start + pool->allocated;
    }
    msync(pool->start, pool->size, MS_ASYNC);
    pool->start = mremap(pool->start, 2 * pool->size, pool->size, MAP_FIXED | MAP_PRIVATE);
    pool->allocated -= pool->size;
    return pool->start + pool->allocated;
}

void mempool_put(struct mempool *pool, void *ptr) {
    if (ptr >= pool->start && ptr < pool->start + pool->size) {
        pool->allocated++;
    }
}

