MemBlock *mem_pool = NULL;
sem_t mem_mutex;
size_t mem_capacity = 0;
size_t mem_used = 0;

void *custom_malloc(size_t size) {
    if (mem_used + size > mem_capacity) {
        // Extend the memory pool if needed
        MemBlock *new_block = mmap(NULL, size + sizeof(MemBlock), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_block == MAP_FAILED) {
            return NULL;
        }
        new_block->capacity = size;
        new_block->mem = (char *)new_block + sizeof(MemBlock);
        new_block->next = mem_pool;
        mem_pool = new_block;
        mem_capacity += size;
    }

    void *result = (void *)((char *)mem_pool - mem_used);
    mem_used += size;
    return result;
}

void custom_free(void *ptr) {
    if (!ptr || !mem_pool) {
        return;
