#include <stdbool.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    int line_count;
    int word_count;
    bool unique_words;
    char *output_file;
} Args;

void print_usage(char *program_name) {
    printf("Usage: %s [options] <input_file|comma_separated_list> \n", program_name);
    printf("\nOptions:\n");
    printf("  -h, --help            Display this help and exit.\n");
    printf("  -V, --version          Print version information and exit.\n");
    printf("  --manpage             Display comprehensive usage and examples.\n");
    printf("  -cs                   Compress the output by only displaying unique words and their frequency.\n");
    printf("  -o output_file        Specify an output file to save the results. Default: stdout\n");
    printf("  -v                    Enable verbose mode for detailed logging.\n");
}

void parse_arguments(int argc, char **argv, Args *args) {
    static struct option long_options[] = {
        {"help", no_argument, NULL, 'h'},
        {"manpage", no_argument, NULL, 'M'},
        {"version", no_argument, NULL, 'V'},
        {"compress", no_argument, NULL, 'c'},
        {"output-file", required_argument, NULL, 'o'},
        {"verbose", no_argument, NULL, 'v'},
        {0}
    };
    int opt;
    bool help = false;
    bool manpage = false;
    bool version = false;
    args->unique_words = false;
    args->output_file = NULL;

    while ((opt = getopt_long(argc, argv, "hMVcvo:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                help = true;
                break;
            case 'M':
                manpage = true;
                break;
            case 'V':
                version = true;
                break;
            case 'c':
                args->unique_words = true;
                break;
            case 'o':
                args->output_file = optarg;
                break;
            case 'v':
                // Enable verbose logging here if needed
                break;
            default:
                print_usage(argv[0]);
                exit(1);
        }
    }

    if (help || manpage || version) {
        return;
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: Missing input file.\n");
        print_usage(argv[0]);
        exit(1);
    }

    args->line_count = 0;
    args->word_count = 0;
}

int main(int argc, char **argv) {
    Args args;
    parse_arguments(argc, argv, &args);

    if (manpage) {
        // Display comprehensive usage and examples here
        return 0;
    }

    int fd = -1;
    if (!args.output_file) {
        fd = STDOUT_FILENO;
    } else {
        mode_t mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;
        int flags = O_CREAT | O_WRONLY | O_TRUNC;
        fd = open(args.output_file, flags, mode);
        if (fd == -1) {
            perror("Error opening output file");
            return 1;
        }
    }

    for (int i = optind; i < argc; ++i) {
        int file_fd = open(argv[i], O_RDONLY, 0);
        if (file_fd == -1) {
            perror("Error opening input file");
            continue;
        }

        char buffer[4096];
        ssize_t bytes_read;
        while ((bytes_read = read(file_fd, buffer, sizeof(buffer))) > 0) {
            for (ssize_t i = 0; i < bytes_read; ++i) {
                if (buffer[i] == '\n') {
                    ++args.line_count;
                }
                char c = buffer[i];
                if (c == ' ') {
                    if (!args.unique_words || !isprint(c)) {
                        ++args.word_count;
                    }
                }
            }

            if (fd != STDOUT_FILENO) {
                write(fd, buffer, bytes_read);
            }
        }

        close(file_fd);
    }

    if (fd != STDOUT_FILENO) {
        ftruncate(fd, 0);
        fprintf(fd, "Total lines: %d\n", args.line_count);
        fprintf(fd, "Total words: %d\n", args.word_count);
        close(fd);
    } else {
        printf("Total lines: %d\n", args.line_count);
        printf("Total words: %d\n", args.word_count);
    }

    return 0;
}
```

