```java
import org.apache.commons.codec.digest.DigestUtils;
import com.google.common.cache.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.atomic.AtomicLong;

public final class StringHasher {
    private static Cache<String, String> stringCache = CacheBuilder.newBuilder()
            .maximumSize(10_000) // Adjust the cache size as needed
            .expireAfterAccess(5, TimeUnit.MINUTES)
            .removalListener((key, oldValue, newValue) -> System.out.println("Removed key: " + key))
            .build();
    private static final AtomicLong sequenceNumber = new AtomicLong();

    public String generateMd5(String input) {
        String hashed = stringCache.getIfPresent(input);
        if (hashed == null) {
            Lock lock = new ReentrantLock();
            long sequenceNumberValue = sequenceNumber.getAndIncrement();
            try {
                if (!lock.tryLock(100, TimeUnit.MILLISECONDS)) { // Adjust timeouts as needed
                    return DigestUtils.md5Hex(input);
                }
                hashed = stringCache.getIfPresent(input);
                if (hashed == null) {
                    hashed = DigestUtils.md5Hex(input);
                    stringCache.put(input, hashed);
                }
            } finally {
                lock.unlock();
            }
        }
        return hashed;
    }
}
```

