    private static final Logger LOGGER = LoggerFactory.getLogger(ImageProcessor.class);
    private final LoadingCache<String, BufferedImage> cache;

    public ImageProcessor() {
        int cacheSize = 10_000; // Adjust according to memory constraints and expected usage
        CacheLoader<String, BufferedImage> loader = (key) -> loadImage(key);
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(cacheSize)
                .expireAfterAccess(10, TimeUnit.MINUTES) // Adjust according to image lifespan and usage patterns
                .build(loader);
    }

    private BufferedImage loadImage(String key) {
        try {
            return ImageIO.read(Paths.get(key));
        } catch (IOException e) {
            LOGGER.error("Error loading image: {}", key, e);
            throw new RuntimeException("Failed to load image", e);
        }
    }

    public BufferedImage resize(BufferedImage image, int width, int height) {
        Image tmp = image.getScaledInstance(width, height, Image.SCALE_SMOOTH);
        return (BufferedImage) tmp.getSubimage(0, 0, width, height);
    }

    public BufferedImage applyFilter(BufferedImage image, Filter filter) {
        // Implement your preferred filtering algorithm here
    }

    public void saveImage(BufferedImage image, String outputKey) throws IOException {
        ImageIO.write(image, "jpg", new File(outputKey));
    }

    public BufferedImage getFromCache(String key) {
        return cache.getIfPresent(key);
    }

    public void processImage(String inputKey, String outputKey, Consumer<BufferedImage> processingFunction) throws IOException {
        Executors.newCachedThreadPool().submit(() -> {
            BufferedImage image = getFromCache(inputKey);
            if (image == null) {
                image = loadImage(inputKey);
            }
            processingFunction.accept(image);
            saveImage(image, outputKey);
        });
    }

    public interface Filter {
        void applyFilter(BufferedImage image);
    }
}
```

