#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

#define MAX_RECORDS 10000
#define MAX_MEMORY (2 * 1024 * 1024)
#define MEMORY_THRESHOLD (MAX_MEMORY * 0.75 / 100)

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

static void* memory_pool = NULL;
static size_t pool_size = 0;
static size_t num_records = 0;
static FILE* log_file;

void* malloc_custom(size_t size) {
    if (memory_pool && pool_size - size > MEMORY_THRESHOLD) {
        void* result = memory_pool;
        memory_pool += size;
        return result;
    }
    return malloc(size);
}

void free_custom(void* ptr, size_t size) {
    if (ptr && memory_pool < pool_size) {
        memory_pool -= size;
    } else {
        free(ptr);
    }
}

void check_memory() {
    if ((size_t)(memory_pool - __builtin_addressof(memory_pool)) + num_records * sizeof(Record) > MEMORY_THRESHOLD) {
        fprintf(log_file, "Error: Memory usage exceeded threshold\n");
    }
}

void init_data_structures() {
    long* offsets = malloc_custom(MAX_RECORDS * sizeof(long));
    int* keys = malloc_custom(MAX_RECORDS * sizeof(int));
    double* values = malloc_custom(MAX_RECORDS * sizeof(double));
    Record* records = malloc_custom(MAX_RECORDS * sizeof(Record));

    memory_pool += (MAX_RECORDS * sizeof(Record) + 3 * MAX_RECORDS * sizeof(void*)) & ~7;
    pool_size -= (MAX_RECORDS * sizeof(Record) + 3 * MAX_RECORDS * sizeof(void*));

    log_file = fopen("log.txt", "w+");

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < MAX_RECORDS && num_records < MAX_RECORDS; ++i) {
        records[num_records].key = rand() % 100 + 1;
        records[num_records].offset = offsets[num_records] = i;
        records[num_records].value = 0.0;
        ++num_records;
        check_memory();
    }
}

void serialize(const char* filename) {
    FILE* file = fopen(filename, "wb");
    fwrite(offsets, sizeof(long), num_records, file);
    fwrite(keys, sizeof(int), num_records, file);
    fwrite(values, sizeof(double), num_records, file);
    fwrite(records, sizeof(Record), num_records, file);
    fclose(file);
}

void deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    fread(offsets, sizeof(long), num_records, file);
    fread(keys, sizeof(int), num_records, file);
    fread(values, sizeof(double), num_records, file);
    fread(records, sizeof(Record), num_records, file);
    fclose(file);
}

void cleanup() {
    free_custom(memory_pool, pool_size);
    fclose(log_file);
}
```']

