struct list {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T structures[MAX_STRUCTURES];
    int count;
    sem_t mutex; // Protects the array and count from concurrent access
};

void transform(char* str) {
    if (str && strlen(str) > 0) {
        size_t len = strlen(str);
        for (size_t i = 0; i < len; ++i) {
            if (isdigit(str[i])) {
                str[i] = toupper(str[i]);
            } else if (!isspace(str[i]) && str[i] != '_') {
                str[i] = '_';
            }
        }
        str[0] = toupper(str[0]); // Ensure the first character is uppercase
        while (strlen(str) > 0 && isspace(str[strlen(str) - 1])) {
            str[strlen(str) - 1] = '\0';
        }
    }
}

struct list* init_list() {
    struct list* list = malloc(sizeof(struct list));
    if (list) {
        sem_init(&list->mutex, 0, 1); // Initialize the mutex
        list->count = 0;
    }
    return list;
}

void push(struct list* list, NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T data) {
    sem_wait(&list->mutex); // Acquire the mutex before modifying the array
    if (list->count < MAX_STRUCTURES) {
        memcpy(&(list->structures[list->count]), &data, sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T));
        list->count++;
    }
    sem_post(&list->mutex); // Release the mutex after modifying the array
}

struct list* process_list(struct list* list) {
    struct list* result = malloc(sizeof(struct list));
    if (result) {
        sem_init(&result->mutex, 0, 1); // Initialize the mutex
        result->count = 0;
    }

    for (int i = 0; i < list->count; ++i) {
        sem_wait(&list->mutex); // Acquire the mutex to access the array

        NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T* data = &(list->structures[i % list->count]);

        char rnti_str[MAX_STRING_LENGTH];
        snprintf(rnti_str, sizeof(rnti_str), "%d", data->rnti);
        transform(rnti_str);
        data->rnti = atoi(rnti_str);

        char rrc_ue_id_str[MAX_STRING_LENGTH];
        snprintf(rrc_ue_id_str, sizeof(rrc_ue_id_str), "%u", data->rrc_ue_id);
        transform(rrc_ue_id_str);
        data->rrc_ue_id = strtoul(rrc_ue_id_str, NULL, 10);

        // Perform other necessary transformations on the configuration parameters here

        sem_post(&list->mutex); // Release the mutex

        sem_wait(&result->mutex); // Acquire the result mutex to add data to the new list
        memcpy(&(result->structures[result->count]), data, sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T));
        result->count++;
        sem_post(&result->mutex); // Release the result mutex
    }

    free(list); // Deallocate the old list
    return result;
}
