#include <stdbool.h>
#include <inttypes.h>

typedef struct {
    uint64_t identifier;
    double value;
} item;

typedef struct node {
    item data;
    struct node *next;
} Node;

Node* find(Node** head, uint64_t id) {
    for (Node* current = *head; current != NULL; current = current->next) {
        if (current->data.identifier == id)
            return current;
    }
    return NULL;
}

void push(Node** head, item new_item) {
    Node* new_node = malloc(sizeof(Node));
    new_node->data = new_item;
    new_node->next = *head;
    *head = new_node;
}

void load_from_file(Node** head, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    while (!feof(file)) {
        item current_item;
        fread(&current_item.identifier, sizeof(current_item.identifier), 1, file);
        fread(&current_item.value, sizeof(current_item.value), 1, file);

        Node* existing = find(head, current_item.identifier);
        if (existing == NULL) {
            push(head, current_item);
        } else {
            existing->data.value = current_item.value;
        }
    }

    fclose(file);
}

void add_item(Node** head, item new_item) {
    Node* new_node = malloc(sizeof(Node));
    new_node->data = new_item;
    new_node->next = *head;
    *head = new_node;

    Node* current = *head;
    while (current->next != NULL && current->next->data.identifier == new_item.identifier) {
        current = current->next;
    }

    if (current->next != NULL) {
        current->next->data.value = new_item.value;
    }
}

void free_collection(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
