#include <openssl/err.h>

typedef struct {
    uint64_t identifier;
    double value;
} item;

struct collection {
    size_t size;
    item* data;
};

void init_collection(struct collection*, const char*, const char*, const char*);
void add_item(struct collection*, uint64_t, double);
void free_collection(struct collection*);
int read_and_decrypt(FILE*, unsigned char**, size_t*, const char*, const char*, const char*);
void cleanup_openssl();

struct collection* load_items(const char* encrypted_filename, const char* key, const char* iv, const char* padding) {
    struct collection* coll = malloc(sizeof(struct collection));
    if (!coll) return NULL;
    coll->size = 0;
    coll->data = NULL;

    unsigned char *decrypted_data = NULL;
    size_t decrypted_data_len = 0;
    if (!read_and_decrypt(fopen(encrypted_filename, "rb"), &decrypted_data, &decrypted_data_len, key, iv, padding)) {
        free(coll);
        return NULL;
    }

    item* data = malloc(decrypted_data_len / sizeof(item));
    if (!data) {
        free(decrypted_data);
        free(coll);
        return NULL;
    }

    memcpy(data, decrypted_data, decrypted_data_len);
    free(decrypted_data);

    init_collection(coll, encrypted_filename, data, sizeof(item));
    return coll;
}

void init_collection(struct collection* coll, const char* filename, item* items, size_t size) {
    coll->size = 0;
    coll->data = malloc(size);
    if (!coll->data) {
        free(items);
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        coll->data[i].identifier = items[i].identifier;
        coll->data[i].value = items[i].value;
        if (coll->size == coll->data[i].identifier) {
            coll->data = realloc(coll->data, (coll->size + 1) * sizeof(item));
        }
        if (coll->data[i].identifier == coll->size) {
            ++coll->size;
        }
    }
}

void add_item(struct collection* coll, uint64_t identifier, double value) {
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->data[i].identifier == identifier) {
            coll->data[i].value = value;
            return;
        }
    }

    coll->data = realloc(coll->data, ((coll->size + 1) * sizeof(item)));
    for (size_t i = coll->size; i > identifier; --i) {
        coll->data[i] = coll->data[i - 1];
    }
    coll->data[identifier].identifier = identifier;
    coll->data[identifier].value = value;
    ++coll->size;
}

void free_collection(struct collection* coll) {
    free(coll->data);
    free(coll);
}

int read_and_decrypt(FILE *file, unsigned char **buf, size_t *len, const char *key, const char *iv, const char *padding) {
    AES_KEY aes_key;
    EVP_CIPHER_CTX* ctx;

    if (!AES_set_encrypt_key(key, 128, &aes_key)) {
        ERR_print_errors_fp(stderr);
        return 0;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return 0;

    if (1 != EVP_CipherInit_ex(ctx, &aes_key, iv, NULL, EVP_cipher_iv_length(EVP_aes_256_cbc()), 1)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    size_t buffer_size = *len = 0;
    unsigned char* buffer = NULL;
    while (1) {
        int more = fread(buffer + buffer_size, 1, sizeof(unsigned char), file);
        if (!more) break;
        buffer_size += more;
        int padding_len;
        if (EVP_CipherUpdate(ctx, buffer + buffer_size - EVP_MAX_BLOCK_LENGTH, &padding_len) <= 0 ||
            EVP_Final_ex(ctx, buffer + buffer_size, &padding_len) <= 0) {
            ERR_print_errors_fp(stderr);
            break;
        }
        buffer_size += padding_len;
    }

    *buf = malloc(buffer_size);
    if (!*buf) return 0;
    memcpy(*buf, buffer, buffer_size);

    EVP_CIPHER_CTX_free(ctx);
    cleanup_openssl();
    return 1;
}

void cleanup_openssl() {
    ERR_free_strings();
    EVP_cleanup();
}
