    char email[256];
    time_t last_login;
} UserProfile;

struct hash_entry {
    uint64_t key;
    pthread_mutex_t lock;
    size_t offset;
};

void hash_init(struct hash_entry* table, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        table[i].key = i * UINT64_C(5381);
        pthread_mutex_init(&table[i].lock, NULL);
    }
}

size_t hash_function(const void* key) {
    const char* str_key = key;
    uint64_t hash = UINT64_C(5381);
    for (size_t i = 0; str_key[i]; ++i)
        hash += (hash << 5) + hash + str_key[i];
    return hash % INT_MAX;
}

void* load_csv_data(const char* file, size_t* data, size_t max_size) {
    FILE* fp = fopen(file, "r");
    if (!fp) return NULL;

    size_t count = 0;
    *data = mmap(NULL, max_size * sizeof(int), PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    if (*data == MAP_FAILED) {
        fclose(fp);
        return NULL;
    }

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        int value = atoi(line);
        if (count < max_size)
            (*data)[count++] = value;
    }
    fclose(fp);
    msync(*data, count * sizeof(int), MS_SYNC);

    return *data;
}

void processUserSessions(const char* input_file, const char* output_file, const char* transformation_rules) {
    FILE* fp_input = fopen(input_file, "rb");
    if (!fp_input) {
        fprintf(stderr, "Error: Unable to open input file.\n");
        return;
    }

    size_t num_profiles = 0;
    fseek(fp_input, 0, SEEK_END);
    num_profiles = ftell(fp_input) / sizeof(UserProfile);
    rewind(fp_input);

    UserProfile* profiles = malloc(num_profiles * sizeof(UserProfile));
    fread(profiles, num_profiles * sizeof(UserProfile), 1, fp_input);

    struct hash_entry table[INT_MAX / 2];
    hash_init(table, sizeof(table) / sizeof(struct hash_entry));

    size_t* data;
    if (!(data = load_csv_data("random_values.csv", num_profiles))) {
        fprintf(stderr, "Error: Unable to load random values.\n");
        return;
    }

    clock_t start = clock();
    size_t distinct_sessions = 0;
    for (size_t i = 0; i < num_profiles; ++i) {
        struct hash_entry* entry = &table[data[i]];
        pthread_mutex_lock(&entry->lock);

        size_t index = entry->offset;
        if (index == i) {
            ++distinct_sessions;
            entry->offset = -1;
        } else if (index != -1) {
            UserProfile* previous_profile = &profiles[index];
            time_t diff = difftime(previous_profile->last_login, profiles[i].last_login);
            if (diff < 24 * 60 * 60) {
                entry->offset = i;
            }
        }

        pthread_mutex_unlock(&entry->lock);
    }
    clock_t end = clock();

    FILE* fp_output = fopen(output_file, "w");
    fprintf(fp_output, "Distinct user sessions: %zu\n", distinct_sessions);
    fprintf(fp_output, "Time taken for session comparison (ms): %f\n", (float)(end - start) / CLOCKS_PER_SEC * 1000.0);

    free(profiles);
    munmap(data, num_profiles * sizeof(int));
    fclose(fp_input);
    fclose(fp_output);
}
