        int c = getopt_long(argc, argv, optstring, long_options, &option_index);
        if (c == -1)
            break;

        switch (c) {
            case 'h':
                help = true;
                break;
            case 'c':
                unique = true;
                break;
            case 'o':
                output_file = optarg;
                output_specified = true;
                break;
            case 'v':
                verbose = true;
                break;
