        printf("  -o outfile       Specify an output file to save the processed results (default: stdout)\n");
        printf("  -v               Enable verbose mode for detailed logging\n");
        return 0;
    }

    Summary **summaries = malloc(sizeof(Summary *) * argc - optind);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t i;
    for (i = optind; i < argc; ++i) {
        sumarries[i - optind] = process_file(argv[i], unique, &mutex);
    }

    pthread_t threads[num_threads];

    #pragma omp parallel num_threads(num_threads)
    {
        size_t thread_index = omp_get_thread_num();
        for (size_t i = 0; i < argc - optind; ++i) {
            size_t j = (thread_index + i) % (argc - optind);
            pthread_create(&threads[thread_index], NULL, process_summary, sumarries[j]);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!output_specified) {
        for (size_t i = 0; i < argc - optind; ++i) {
            print_summary(summaries[i]);
        }
    } else {
        save_summary(output_file, summaries[0]);
    }

    free(summaries);
    return 0;
}

