// Function to process a single file
void processFile(const string& filename, unordered_map<string, int>& wordCount, mutex* wordCountMutex) {
    ifstream file(filename);
    string line;
    int lineCount = 0;
    while (getline(file, line)) {
        ++lineCount;
        istringstream iss(line);
        string word;
        while (iss >> word) {
            unique_lock<mutex> lock(*wordCountMutex);
            ++wordCount[word];
        }
    }
}

// Main function for the program
int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Display comprehensive usage and examples")
        ("c,compress", "Compress the output to include only unique words along with their frequency")
        ("o,output_file", po::value<string>()->default_value("summary.txt"), "Specify an output file to save the processed results")
        ("v,verbose", "Enable verbose mode for detailed logging")
        ("threads,t", po::value<int>()->default_value(std::thread::hardware_concurrency()), "Number of threads")
    ;

    po::variables_map vm;
    store(parse_command_line(argc, argv, desc), vm);
    notify(vm);

    if (vm.count("help")) {
        cout << desc << endl;
        return 0;
    }

    bool compress = vm["compress"].as<bool>();
    string outputFile = vm["output_file"].as<string>();
    int verbose = vm["verbose"].as<int>();
    int threads = vm["threads"].as<int>();

    vector<string> filenames;
    boost::filesystem::path p(argv[0]);
    for (int i = 1; i < argc; ++i) {
        filenames.push_back(argv[i]);
    }

    // Load files concurrently using provided number of threads
    unordered_map<string, int> wordCount;
    mutex wordCountMutex;

    vector<future<void>> tasks;
    for (const auto& filename : filenames) {
        tasks.push_back(async(launch::async, processFile, filename, ref(wordCount), &wordCountMutex));
    }

    // Wait for all tasks to complete
    for (auto& task : tasks) {
        task.get();
    }

    // Generate the summary report and output it to a file or stdout based on options
    ofstream outFile(outputFile);
    ostream* os = &outFile ? outFile : cout;
    *os << "Summary Report:" << endl;
    *os << "Total lines: " << wordCount.size() << endl;

    if (!compress) {
        for (const auto& element : wordCount) {
            *os << element.first << ": " << element.second << endl;
        }
    } else {
        unordered_map<string, int> uniqueWordCount;
        mutex uniqueWordCountMutex;

        // Re-process the data to compute only unique words and their frequencies
        tasks.clear();
        for (const auto& filename : filenames) {
            tasks.push_back(async(launch::async, processFile, filename, ref(uniqueWordCount), &uniqueWordCountMutex));
        }

        // Wait for all tasks to complete and generate the final report
        for (auto& task : tasks) {
            task.get();
        }

        *os << "Unique words and their frequencies:" << endl;
        for (const auto& element : uniqueWordCount) {
            *os << element.first << ": " << element.second << endl;
        }
    }

    return 0;
}
