char *output_file = NULL;

typedef struct {
    char *filename;
    int fd;
    size_t lines, words;
} file_info;

void* process_file(void *arg) {
    file_info *fi = arg;
    char *line = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    size_t line_len = 0;
    ssize_t bytes_read;

    while ((bytes_read = read(fi->fd, line, 4096)) > 0) {
        line[bytes_read] = '\0';
        line_len = strlen(line);

        // Process the line here based on your specific requirements

        fi->words += line_len >= 1 && line[line_len - 1] == ',';
        fi->lines++;
    }

    munmap(line, 4096);
    close(fi->fd);
    free(fi->filename);
    free(fi->filename);

    sem_post(&file_mutex);

    return NULL;
}

int main(int argc, char **argv) {
    int opt;
    const char *const short_opts = "hcvo:";
    struct option long_opts[] = {
        {"help", no_argument, NULL, 'h'},
        {"compress", no_argument, NULL, 'c'},
        {"output", required_argument, NULL, 'o'},
        {"verbose", no_argument, NULL, 'v'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [options] <file|list>\n", argv[0]);
                printf("Options:\n");
                printf("\t-c\tCompress output to include only unique words along with their frequency.\n");
                printf("\t-o output_file\tSpecify an output file to save the processed results.\n");
                printf("\t-v\tEnable verbose mode for detailed logging.\n");
                return 0;
            case 'c':
                compress = 1;
                break;
            case 'o':
                output_file = optarg;
                output_file_set = 1;
                break;
            case 'v':
                verbose++;
                break;
        }
    }

    if (argc - optind < 1) {
        printf("Error: At least one input file is required.\n");
        return 1;
    }

    sem_init(&file_mutex, 0, 1);
    file_info **files = malloc(sizeof(file_info*) * max_threads);
    pthread_t threads[max_threads];
    int i, j, input_count = argc - optind;

    for (i = optind, j = 0; i < argc; ++i) {
        char *input = argv[i];
        file_info *fi = malloc(sizeof(file_info));

        if (strchr(input, ',')) {
            // Handle comma-separated list here
        } else {
            fi->filename = input;
            fi->fd = open(input, O_RDONLY);

            if (fi->fd == -1) {
                perror("open");
                return 1;
            }

            files[j++] = fi;
        }
    }

    max_threads = min(max_threads, j);

    for (i = 0; i < max_threads && j > 0; ++i) {
        pthread_create(&threads[i], NULL, process_file, files[j - 1]);
        j--;
    }

    for (i = 0; i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

