typedef struct NFAPI_MESSAGE_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    char* payload;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_MESSAGE;

typedef struct PayloadTransformer_args {
    const char* str;
    size_t* payload_len;
} PayloadTransformer_args;

void PayloadTransformer(const void* args) {
    PayloadTransformer_args* arg = (PayloadTransformer_args*)args;
    size_t len = 0;
    char* transformed_payload = NULL;

    // Transform payload string and calculate new length
    for (size_t i = 0; arg->str[i]; ++i) {
        if (isalnum(arg->str[i])) {
            len++;
        } else if (len > 0) {
            transformed_payload = realloc(transformed_payload, len + 1);
            transformed_payload[len++] = '_';
        }
    }

    // Append the original string with transformed characters
    transformed_payload = realloc(transformed_payload, len + arg->str_len);
    strncpy(transformed_payload, arg->str, arg->str_len);

    // Trim whitespace and convert to uppercase
    for (size_t i = 0; transformed_payload[i]; ++i) {
        if (!isspace(transformed_payload[i])) {
            transformed_payload[i] = toupper((unsigned char)transformed_payload[i]);
        } else {
            memmove(transformed_payload, transformed_payload + i, strlen(transformed_payload + i) + 1);
            i--;
        }
    }

    *arg->payload_len = len;
}

void init_tag(RX_UE_INFORMATION_TAG* tag) {
    // Initialize RX_UE_INFORMATION_TAG fields
    memset(tag, 0, sizeof(*tag));
    tag->present = NFAPI_RANDOM_ACCESS;
}

void init_rnti(RNTI* rnti) {
    // Initialize RNTI fields
    memset(rnti, 0, sizeof(*rnti));
    rnti->rnti = 12345678; // Set a valid RNTI value
}

NFAPI_MESSAGE* create_message(const RX_UE_INFORMATION_TAG tag, const RNTI rnti, const char* payload) {
    NFAPI_MESSAGE* msg = (NFAPI_MESSAGE*)malloc(sizeof(*msg));
    if (!msg) {
        return NULL;
    }

    init_tag(&msg->tag);
    init_rnti(&msg->rnti);

    PayloadTransformer_args transform_arg = {
        .str = payload,
        .payload_len = &msg->payload_len
    };
    pthread_t thread;
    pthread_create(&thread, NULL, PayloadTransformer, &transform_arg);
    pthread_join(thread, NULL);

    msg->payload = (char*)realloc(msg->payload, *msg->payload_len);
    if (!msg->payload) {
        free(msg);
        return NULL;
    }

    init_crc_tag(&msg->crc_tag, true); // Set CRCFLAG to randomly determined

    return msg;
}

NFAPI_MESSAGE** create_messages(unsigned int N, unsigned int batch_size) {
    unsigned int batches = (N + batch_size - 1) / batch_size;
    NFAPI_MESSAGE** messages = (NFAPI_MESSAGE**)calloc(batches, sizeof(*messages));

    for (unsigned int i = 0; i < batches; ++i) {
        unsigned int start = i * batch_size;
        unsigned int end = std::min((i + 1) * batch_size, N);

        messages[i] = (NFAPI_MESSAGE*)calloc(end - start, sizeof(*messages[0]));

        for (unsigned int j = start; j < end; ++j) {
            create_message(RX_UE_INFORMATION_TAG, RNTI, "some random payload");
        }
    }

    return messages;
}

void free_messages(NFAPI_MESSAGE** messages, unsigned int batches) {
    for (unsigned int i = 0; i < batches; ++i) {
        free(messages[i]);
    }
    free(messages);
}
