        NFAPI_MESSAGE_T* new_pool = realloc(message_pool, sizeof(NFAPI_MESSAGE_T) * (count + MESSAGE_POOL_SIZE));
        if (!new_pool) {
            perror("Realloc failed for message pool expansion");
            return false;
        }
        message_pool = new_pool;
    }

    message_count = count;
    return true;
}

NFAPI_MESSAGE_T* get_message() {
    if (message_count == 0) {
        printf("No more messages available in the pool.\n");
        return NULL;
    }

    --message_count;
    return &((NFAPI_MESSAGE_T*)message_pool)[message_count];
}

bool release_message(NFAPI_MESSAGE_T* message) {
    if (message_count >= MESSAGE_POOL_SIZE) {
        fprintf(stderr, "Message pool is full. Cannot free messages.\n");
        return false;
    }

    ++message_count;
    memset(message, 0, sizeof(NFAPI_MESSAGE_T));
    return true;
}

bool validate_payload(size_t length) {
    return length <= MAX_PAYLOAD_LENGTH;
}

void* allocate_payload(size_t length) {
    void *payload = malloc(length);
    if (!payload) {
        perror("Malloc failed for payload");
        return NULL;
    }
    memset(payload, 0, length);
    return payload;
}

bool update_message(NFAPI_MESSAGE_T* message, const RX_UE_INFORMATION_TAG rx_ue_information_tag, uint32_t rnti, size_t payload_length) {
    if (!validate_payload(payload_length)) {
        perror("Invalid payload length");
        return false;
    }

    message->rx_ue_information_tag = rx_ue_information_tag;
    message->rnti = rnti;
    message->payload_length = payload_length;
    if (message->payload) {
        free(message->payload);
    }
    message->payload = allocate_payload(payload_length);
    if (!message->payload) {
        perror("Malloc failed for updated payload");
        return false;
    }

    return true;
}
```

This implementation provides a scalable memory pool for up to 10,000 messages with a dynamic scaling strategy. The function `initialize_message_list()` handles the initial allocation and potential expansion of the message pool. It also ensures that the payload size is validated against predefined limits. Memory allocations are optimized through pool reuse via the `release_message()` function, and the implementation includes error handling for insufficient memory or invalid payload sizes.

The code is modular, with clear separation of concerns, and can be easily integrated into an existing data processing pipeline. It aims to minimize overhead in high-load scenarios while providing robustness and maintainability for future enhancements and integration with other modules.']

