#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <iconv.h>
#include <curl/curl.h>

struct file_data {
    char *filename;
    size_t lines;
    struct stat st;
};

void *process_file(void *data) {
    struct file_data *fd = data;
    char *line = NULL;
    size_t line_len = 0;
    ssize_t read_len;
    iconv_t cd;
    iconv_t id;
    char *input_encoding = getenv("INPUT_ENCODING");
    char output_encoding[] = "UTF-8";

    icontxt src_ctx, dst_ctx;

    iconv_open(&cd, input_encoding, &src_ctx);
    iconv_open(&id, output_encoding, &dst_ctx);

    int fd_input = open(fd->filename, O_RDONLY);
    if (fd_input < 0) {
        perror("open");
        return NULL;
    }

    while ((read_len = getline(&line, &line_len, fd_input)) != -1) {
        size_t len = read_len;
        char *newline = strchr(line, '\n');
        if (newline) len--;

        line[len] = 0;

        srcctx.icd.inbuf = line;
        srcctx.icd.inbytesleft = len;

        while (srcctx.icd.inbytesleft > 0) {
            char outbuf[ICONV_MAX_OUTPUT_SIZE];
            ssize_t outlen = ICONV_MAX_OUTPUT_SIZE;
            ssize_t r = iconv(&id, &srcctx.icd, NULL, outbuf, &outlen);
            if (r > 0) {
                fd->lines++;
                // Process the word here
            } else {
                fprintf(stderr, "iconv error: %s\n", strerror(errno));
                return NULL;
            }
        }
    }

    close(fd_input);

    free(line);
    free(fd->filename);
    iconv_close(cd);
    iconv_close(id);

    return fd;
}

int main(int argc, char **argv) {
    int opt;
    const char *output_file = NULL;
    bool compress = false, verbose = false;

    struct file_data *files = NULL;
    size_t num_files = 0;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"compress", no_argument, 0, 'c'},
        {"output-file", required_argument, 0, 'o'},
        {"verbose", no_argument, 0, 'v'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hco:v", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage:\n%s [OPTION]... FILE...\n\n"
                       "Options:\n"
                       "-c, --compress    Compress output with unique words only.\n"
                       "-o OUTPUT_FILE, --output-file=OUTPUT_FILE\n"
                           "          Set the output file for the processed results.\n"
                       "-v, --verbose     Enable verbose logging.\n", argv[0]);
                return 0;
            case 'c':
                compress = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'v':
                verbose = true;
                break;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: No input files provided.\n");
        return 1;
    }

    for (size_t i = optind; i < argc; ++i) {
        struct stat st;
        int fd_input = open(argv[i], O_RDONLY);

        if (fstat(fd_input, &st) == 0) {
            size_t new_size = num_files + 1;
            struct file_data *new_files = realloc(files, sizeof(struct file_data) * new_size);
            if (!new_files) {
                fprintf(stderr, "Memory allocation error.\n");
                return 1;
            }
            files = new_files;

            files[num_files].filename = argv[i];
            files[num_files].lines = 0;
            if (fstat(fd_input, &files[num_files].st) < 0) {
                perror("fstat");
                return 1;
            }
            num_files++;
        } else {
            fprintf(stderr, "Error: Cannot open file %s.\n", argv[i]);
            return 1;
        }
    }

    pthread_t threads[num_files];

    for (size_t i = 0; i < num_files; ++i) {
        int rc = pthread_create(&threads[i], NULL, process_file, &files[i]);
        if (rc) {
            fprintf(stderr, "Error: Failed to create thread for file %s.\n", files[i].filename);
            return 1;
        }
    }

    for (size_t i = 0; i < num_files; ++i) {
        void *result;
        pthread_join(threads[i], &result);

        if (!compress) {
            printf("File %s: %zu lines, %zu words\n", files[i].filename, files[i].lines, /* Word count computation here */);
        }
    }

    if (output_file && !compress) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("fopen");
            return 1;
        }

        for (size_t i = 0; i < num_files; ++i) {
            fprintf(out, "File %s: %zu lines, %zu words\n", files[i].filename, files[i].lines, /* Word count computation here */);
        }

        fclose(out);
    } else if (compress) {
        // Compress output generation here
    }

    free(files);
    return 0;
}
