void lte_rrcnas_message_init() {
    if (curr_session >= 0 && curr_session < session_max - 1) {
        printf("Error: Maximum number of sessions exceeded\n");
        return;
    }

    if (curr_session == -1) {
        srand(time(NULL));
        curr_session++;
        session_count++;
        memset(messages[curr_session], 0, sizeof(struct LTE_RRCNAS_Message)*session_max);
    }
}

void lte_rrcnas_message_free() {
    if (curr_session == -1) return;

    memset(messages[curr_session], 0, sizeof(struct LTE_RRCNAS_Message)*session_max);
    curr_session = -1;
}

void lte_rrcnas_message_generate(Message_ID message_id) {
    if (curr_session == -1) return;

    int i;
    for (i = 0; i < session_max && messages[curr_session][i].nas_transaction_id != UINT32_MAX; ++i);

    if (i >= session_max) {
        printf("Error: Maximum number of messages per session exceeded\n");
        return;
    }

    messages[curr_session][i].message_type = NMT_NAS_MESSAGE;
    messages[curr_session][i].message_id = message_id;
    messages[curr_session][i].security_algorithm_suite = SAS_A3 + (rand() % (MAX_SAS - 1)); // Ensure uniqueness across the session
    messages[curr_session][i].nas_transaction_id = ++msg_counter[message_id];
}

int lte_rrcnas_get_messages_sent(Message_ID message_id) {
    if (curr_session == -1) return 0;

    return msg_counter[message_id];
}
