struct memory_pool {
    size_t capacity;
    NFAPI_MESSAGE_T **messages;
    semaphore_t free_slots;
    pthread_mutex_t lock;
};

void *memory_pool_allocate(struct memory_pool *pool) {
    sem_wait(&pool->free_slots);
    pthread_mutex_lock(&pool->lock);
    NFAPI_MESSAGE_T *message = pool->messages[pool->capacity - 1];
    pool->capacity--;
    pthread_mutex_unlock(&pool->lock);
    return message;
}

void memory_pool_free(struct memory_pool *pool, void *message) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_MESSAGE_T *msg = (NFAPI_MESSAGE_T *)message;
    free(msg->payload);
    msg->payload = NULL;
    memset(msg, 0, sizeof(NFAPI_MESSAGE_T));
    pool->messages[pool->capacity++] = msg;
    sem_post(&pool->free_slots);
    pthread_mutex_unlock(&pool->lock);
}

