#include <openssl/md5.h>
#include <boost/asio/io_service.hpp>
#include <boost/asio/deadline_timer.hpp>
#include <boost/log/trivial.hpp>
#include <boost/filesystem.hpp>
#include <boost/noncopyable.hpp>
#include <atomic>
#include <mutex>
#include <unordered_map>

class SecureLoggingHasher : private boost::noncopyable {
public:
    explicit SecureLoggingHasher(const std::string& logFilePath, int maxLogSizeBytes = 1000000, int maxLogEntries = 1000)
        : ioService_(boost::asio::io_service()),
          timer_(ioService_),
          logFileRotator_(logFilePath, maxLogSizeBytes, maxLogEntries),
          logLevel_(BOOST_LOG_TRIVIAL_DEBUG),
          rateLimiter_(60),
          hashCache_(),
          logBuffer_() {
        startAsyncLogging();
    }

    std::string md5(const std::string& str) {
        if (str.empty()) throw std::invalid_argument("String cannot be empty");
        return hashCache_[str + "md5"];
    }

    std::string sha256(const std::string& str) {
        if (str.empty()) throw std::invalid_argument("String cannot be empty");
        return hashCache_[str + "sha256"];
    }

    void setLogLevel(boost::log::trivial::level level) { logLevel_ = level; }

    void log(boost::log::trivial::level level, const std::string& message) {
        if (message.empty()) throw std::invalid_argument("Message cannot be empty");
        logBuffer_[level].push_back(message);
    }

private:
    boost::asio::io_service ioService_;
    boost::asio::deadline_timer timer_;
    boost::filesystem::path logFileRotator_;
    boost::log::trivial::level logLevel_;
    std::atomic<int> rateLimiter_;
    std::unordered_map<std::string, std::string> hashCache_;
    boost::mutex mutex_;
    std::vector<std::deque<std::string>> logBuffer_;

    void startAsyncLogging() {
        auto work = [this]() {
            boost::this_thread::sleep(boost::chrono::seconds(1));
            asyncFlushLogs();
        };
        timer_.expires_from_now(boost::posix_time::seconds(1));
        timer_.async_wait([this, work](const boost::system::error_code& ec) {
            if (!ec) {
                work();
                startAsyncLogging();
            }
        });
    }

    void asyncFlushLogs() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& log : logBuffer_) {
            if (!log.empty()) {
                auto levelStr = boost::log::trivial::to_string(log[0].getLevel());
                std::ostringstream os;
                os << levelStr << ": " << log[0].message() << '\n';
                BOOST_LOG_TRIVIAL(levelStr) << log[0].message();
                logFileRotator_.sink() << os.str();
                log.erase(log.begin());
            }
        }
    }
};

#include <boost/test/unit_test.hpp>
BOOST_AUTO_TEST_SUITE(SecureLoggingHasherTest)

BOOST_AUTO_TEST_CASE(hashing) {
    SecureLoggingHasher hasher;
    BOOST_CHECK_EQUAL(hasher.md5("hello"), "d41d8cd98f00b204e9800998ecf8427e");
    BOOST_CHECK_EQUAL(hasher.sha256("hello"), "a9"
                      "4a6e7e45671faa61799cc4efb348cbae0822cefe1b3a532c95b99640c8d898c");
    // Add more tests as needed for edge cases or different inputs.
}

BOOST_AUTO_TEST_CASE(logging) {
    SecureLoggingHasher hasher;
    hasher.log(boost::log::trivial::DEBUG, "This is a debug message.");
    hasher.log(boost::log::trivial::INFO, "This is an info message.");
    // Add more tests as needed for edge cases or different log levels and messages.
}

BOOST_AUTO_TEST_SUITE_END()
