typedef struct {
    pid_t thread_id;
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    LTE_UE_Context* contexts;
} ContextList;

struct LTE_UE_Context {
    uint64_t ue_id;
    char config[MAX_CONFIG_LENGTH];
    time_t last_update;
};

void init_context(LTE_UE_Context* context) {
    memset(context->config, 0, MAX_CONFIG_LENGTH);
    context->last_update = time(NULL);
}

void validate_and_preprocess(char* config, size_t length) {
    if (length > MAX_CONFIG_LENGTH - 1) return; // Truncate or handle overflow appropriately

    for (size_t i = 0; i < length; ++i) {
        char c = config[i];
        if (isalpha(c)) continue;
        config[i] = '_';
    }

    for (size_t i = 0; i < length; ++i) {
        config[i] = toupper((unsigned char)config[i]);
        config[i] = trim_whitespace(config[i]);
    }
}

ContextList* create_context_list() {
    ContextList* list = malloc(sizeof(ContextList));
    list->capacity = 100;
    list->size = 0;
    list->contexts = calloc(list->capacity, sizeof(LTE_UE_Context));

    for (size_t i = 0; i < list->capacity; ++i) {
        init_context(&list->contexts[i]);
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_context_list(ContextList* list) {
    free(list->contexts);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_ue_context(ContextList* list, uint64_t ue_id, char* config) {
    validate_and_preprocess(config, strlen(config));

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].ue_id == ue_id) {
            memcpy(&(list->contexts[i].config), config, strlen(config));
            list->contexts[i].last_update = time(NULL);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
    }

    if (list->size == list->capacity) {
        resize_context_list(list, list->capacity * 2); // Implement resize_context_list function here
    }

    LTE_UE_Context* new_context = &list->contexts[list->size];
    init_context(new_context);
    new_context->ue_id = ue_id;
    memcpy(&(new_context->config), config, strlen(config));
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// The following functions handle logging and error handling as needed.
