namespace bs = boost::serialization;
using namespace std;
using namespace boost::log;

class DataObject {
public:
    int id;
    int version;
    boost::container::flat_map<string, string> metadata;
    uint64_t hash;

    template<class Archive> void serialize(Archive& ar, const unsigned int) {
        ar & id & version & metadata & hash;
    }

    DataObject() {}
    DataObject(int i, int v, const boost::container::flat_map<string, string>& m, uint64_t h) : id(i), version(v), metadata(m), hash(h) {}
};

class DataManager {
private:
    unordered_map<int, unique_ptr<DataObject>> data;
    mutex mtx;
    atomic<int> nextId{0};
    atomic<int> objectCount{0};
    int maxObjects{500};
    string logFile="data_manager.log";
    boost::asio::steady_timer timer;

    void createObject(DataObject& obj) {
        auto id = nextId++;
        obj.id = id;
        obj.hash = validateHash(obj);
        objectCount++;
        if (objectCount > maxObjects) purgeOldObjects();
        logDetails(id, obj.version, obj.metadata, obj.hash);
    }

    void logDetails(int id, int version, const boost::container::flat_map<string, string>& metadata, uint64_t hash) {
        try {
            ofstream file(logFile, ios::app);
            if (file.is_open()) {
