    pthread_mutex_t mutex;
    pthread_cond_t not_empty, not_full;
} threadsafe_queue_t;

void init_queue(threadsafe_queue_t *q) {
    q->data = malloc(MAX_QUEUE_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!q->data) {
        perror("Failed to allocate memory for queue");
        exit(EXIT_FAILURE);
    }
    q->head = q->tail = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
}

void enqueue(threadsafe_queue_t *q, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&q->mutex);

    while (q->tail - q->head == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&q->not_full, &q->mutex);
    }

    memcpy(&q->data[q->tail], &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->tail = (q->tail + 1) % MAX_QUEUE_SIZE;

    if (q->head == q->tail) {
        pthread_cond_signal(&q->not_empty);
    }

    pthread_mutex_unlock(&q->mutex);
}

