    pthread_mutex_lock(&q->mutex);

    while (q->head == q->tail) {
        pthread_cond_wait(&q->not_empty, &q->mutex);
    }

    memcpy(&ret, &q->data[q->head], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->head = (q->head + 1) % MAX_QUEUE_SIZE;

    if ((q->tail - 1) == q->head) {
        pthread_cond_signal(&q->not_full);
    }

    pthread_mutex_unlock(&q->mutex);
    return ret;
}

void create_and_populate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pdus[i].rx_ue_information.length = rand() % 128 + 1;
        pdus[i].rnti.length = sizeof(RNTI);
        pdus[i].crc_indication_rel8.length = sizeof(CRC_INDICATION_REL8_TAG) - sizeof(uint32_t);
        pdus[i].crc_indication_rel8.crcflag = (rand() >> 16) & 0xFFFF;
    }
}

void validate_crc(const NFAPI_CRC_INDICATION_PDU_T* pdu, const uint8_t* payload, size_t length) {
    uint32_t calculated_crc = 0;
    for (size_t i = 0; i < length; ++i) {
        calculated_crc = (calculated_crc >> 16) ^ ((calculated_crc & 0xFFFF) * 0x04C11DB7 + (payload[i] << 18 | payload[i] >> 16));
    }

    if (pdu->crc_indication_rel8.crcflag != calculated_crc) {
        fprintf(stderr, "Invalid CRC for PDU: 0x%lX\n", calculated_crc);
    }
}

void* producer(void *arg) {
    threadsafe_queue_t *q = arg;
    NFAPI_CRC_INDICATION_PDU_T pdus[128];

    create_and_populate_pdu(pdus, 128);
    while (1) {
        enqueue(q, pdus[rand() % 128]);
        sleep(1);
    }
    return NULL;
}

void* consumer(void *arg) {
    threadsafe_queue_t *q = arg;
    size_t count = 0;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue(q);
        validate_crc(&pdu, &pdu.rx_ue_information.data[0], pdu.rx_ue_information.length);
        ++count;
    }
    return NULL;
}

int main() {
    threadsafe_queue_t q;
    init_queue(&q);

    pthread_t producers[4];
    pthread_t consumer;

    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&producers[i], NULL, producer, &q)) {
            perror("Failed to create producer thread");
            return EXIT_FAILURE;
        }
    }

    if (pthread_create(&consumer, NULL, consumer, &q)) {
        perror("Failed to create consumer thread");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 4; ++i) {
        pthread_join(producers[i], NULL);
    }
    pthread_join(consumer, NULL);

    free(q.data);
    return EXIT_SUCCESS;
}
```
This code creates a thread-safe queue to store the generated structures and handles concurrent access safely using Pthreads. The function `create_and_populate_pdu()` generates the required structures, while the `producer()` and `consumer()` functions simulate multiple producer and consumer threads. The main function initializes the queue, creates and starts the necessary threads, and finally cleans up the memory when all threads have finished.']

