        size_t compressedSize = compress(msg.payload.get(), msg.payload->size());
        if (compressedPool.capacity() < compressedSize) {
            compressedPool.resize(compressedPool.size() * 2);
        }
        std::copy(compress(msg.payload.get(), msg.payload->size()), compress(msg.payload.get(), msg.payload->size()) + compressedSize, std::back_inserter(compressedPool));
    }
    mtx.unlock();

    return result;
}
