import os
import json
import argparse
from concurrent.futures import ThreadPoolExecutor

def parse_json(file):
    events = {}
    try:
        with open(file) as f:
            data = json.load(f)
            for event in data:
                if event not in events:
                    events[event] = 1
                else:
                    events[event] += 1
    except Exception as e:
        print(f"Error parsing {file}: {e}")
    return events

def summarize_events(events, freq=5):
    most_common = dict(sorted(events.items(), key=lambda item: item[1], reverse=True)[:freq])
    return {k: v for k, v in events.items() if k not in most_common}

def process_directory(dir_path, output_file, verbose, frequency):
    processed = {}

    def worker(file):
        events = parse_json(file)
        processed.update(events)

    files = [os.path.join(dir_path, f) for f in os.listdir(dir_path) if os.path.isfile(os.path.join(dir_path, f))]

    with ThreadPoolExecutor(max_workers=min(len(files), 8)) as executor:
        executor.map(worker, files)

    summary = summarize_events(processed, frequency)
    if output_file:
        with open(output_file, 'w') as f:
            json.dump(summary, f)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('directories', nargs='*', help='Directories containing log files (can be comma-separated)')
    parser.add_argument('--help', action='store_true', help='Display comprehensive usage and examples')
    parser.add_argument('-s', type=int, default=5, help='Summarize only the most frequent event types (default: 5)')
    parser.add_argument('-o', '--output_file', help='Specify an output file to save the processed results')
    parser.add_argument('-v', action='store_true', help='Enable verbose mode for detailed logging')

    args = parser.parse_args()

    if args.help:
        parser.print_help(sys.stderr)
        return

    if not args.directories:
        print(__doc__)
        parser.print_help()
        return

    process_directory(*args.directories, args.output_file, args.v, args.s)

if __name__ == "__main__":
    main()
```
