            boost::property_tree::ptree pt;
            read_xml(boost::iostreams::istream<std::ifstream>(entry), pt); // Parse XML log file

            std::string locale = pt.get<std::string>("LogFile.Locale");
            std::time_t fileTimestamp = pt.get<std::time_t>("LogFile.Timestamp");
            int numActiveUsers = pt.get<int>("LogFile.NumActiveUsers");

            // Convert timestamp to C++ tm structure based on the specified locale

            std::ifstream logFile(entry);
            boost::iostreams::filtering_streambuf<boost::iostreams::input> isb;
            if (numActiveUsers > 1) {
                isb.push(boost::iostreams::zlib_compressor()); // Compress log file if more than one active user
                isb.push(logFile);
            } else {
                isb.push(logFile);
            }
            std::istream is(&isb);

            std::vector<logEntry> logEntries;
            log.clear(); // Clear logging string for each new file

            logEntries.reserve(1024); // Reserve memory for efficient allocation

            // Parse log entries, validate integrity, and set fields accordingly

            int keyLength = determineEncryptionKeyLength(isb); // Determine encryption key length based on file size
            std::unique_ptr<uint8_t[]> key = generateEncryptionKey(keyLength); // Generate encryption key

            while (true) {
                message newMessage;
                // Parse next log entry and create a new message if valid

                if (!newMessage) continue; // Skip invalid entries

                if (newMessage->maxPayloadSize < newMessage->payload->length()) {
                    truncateMessage(newMessage); // Truncate message if it exceeds the max payload size
                }

                AES_KEY aesKey;
                AES_set_encrypt_key((const unsigned char*)key.get(), 128, &aesKey); // Initialize AES encryption context

                std::unique_ptr<char[]> encryptedPayload(new char[newMessage->payload->length()]); // Allocate enough for the encrypted payload and null terminator
                encrypt(reinterpret_cast<uint8_t*>(encryptedPayload.get()), reinterpret_cast<const uint8_t*>(newMessage->payload), &aesKey); // Encrypt message payload
                newMessage->payload = std::move(encryptedPayload);

                encryptedMessages.emplace_back(std::move(newMessage));
            }
        }
    }

    return encryptedMessages;
}
