    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* hash_function(const void* key) {
    const uint32_t key_as_uint = *(const uint32_t*)key;
    return (uint64_t)(key_as_uint ^ (key_as_uint >> 32));
}

int create_pdus(size_t N, uint32_t max_rnti, uint32_t seed) {
    if (!N || max_rnti == 0) return -1; // Handle edge cases

    pthread_mutex_lock(&mutex);

    size_t allocated_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(allocated_size);
    if (!pdus) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Seed random number generator
    srand(seed);

    void* hashed_keys[max_rnti];
    size_t used = 0;

    for (size_t i = 0; i < N && used < N; ++i) {
        uint32_t rnti = rand() % max_rnti; // Generate RNTI value

        // Use custom hash function to check for uniqueness of RNTI values
        uint64_t hashed_key = hash_function((const void*)&rnti);
        if (used < max_rnti && bsearch(&hashed_key, hashed_keys, used, sizeof(uint64_t), hash_function) == NULL) {
            pdus[i].RNTI = rnti;
            // Generate random CRCFLAG for each structure
            pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;
            hashed_keys[used++] = &hashed_key;
        } else {
            --i; // Re-try with the next RNTI value if it's not unique
        }
    }

    if (used != N) {
        free(pdus);
        perror("Not enough unique RNTIs generated");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize CRC_INDICATION_REL8_TAG.CRNTI and CRC_INDICATION_REL8_TAG.CC using external library
    for (size_t i = 0; i < N; ++i) {
        crc_indication_pdu_init(&pdus[i].CRC_INDICATION_REL8_TAG);
        // Assuming the library has a function to set CRNTI and CC fields securely and efficiently
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}
