2. Java Class: TransactionManager

```java
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.locks.Condition;
import java.sql.*;
import java.time.Instant;

class TransactionManager {
    private static final int DEFAULT_TRANSACTION_ARRAY_SIZE = 10;
    private Connection connection;
    private Transaction[] transactions;
    private int transactionCount;
    private ReentrantLock lock;
    private Condition notFull, notEmpty;

    public TransactionManager(Connection connection) {
        this.connection = connection;
        this.transactions = new Transaction[DEFAULT_TRANSACTION_ARRAY_SIZE];
        this.lock = new ReentrantLock();
        this.notFull = lock.newCondition();
        this.notEmpty = lock.newCondition();
    }

    public void enqueueTransaction(Transaction transaction) {
        lock.lock();
        try {
            while (transactionCount == transactions.length) {
                notFull.await();
            }
            transactions[transactionCount++] = transaction;
            notEmpty.signalAll();
        } catch (InterruptedException e) {
            // Handle interruptions gracefully
        } finally {
            lock.unlock();
        }
    }

    public Transaction dequeueTransaction() {
        lock.lock();
        try {
            while (transactionCount == 0) {
                notEmpty.await();
            }
            Transaction transaction = transactions[--transactionCount];
            notFull.signalAll();
            return transaction;
        } catch (InterruptedException e) {
            // Handle interruptions gracefully
        } finally {
            lock.unlock();
        }
    }

    // ... Implement other TransactionManager methods, including logging, performance monitoring, error handling and database operations
}
