    array->length = 0;
    array->messages = malloc(capacity * sizeof(NFAPI_MESSAGE_T));
    if (!array->messages) {
        fprintf(stderr, "Failed to allocate memory for message array.\n");
        exit(1);
    }
    array->deinit = deinit;
}

void resize_message_array(MESSAGE_ARRAY_T *array, size_t new_capacity) {
    if (new_capacity <= array->length) {
        fprintf(stderr, "New capacity is smaller than the current number of messages.\n");
        exit(1);
    }

    NFAPI_MESSAGE_T *new_messages = realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!new_messages) {
        fprintf(stderr, "Failed to resize message array.\n");
        exit(1);
    }
    array->messages = new_messages;
    array->capacity = new_capacity;
}

void push_message(MESSAGE_ARRAY_T *array, NFAPI_MESSAGE_T msg) {
    if (array->length >= array->capacity) resize_message_array(array, array->capacity * 2);
    array->messages[array->length] = msg;
    array->length++;
}

void free_message_array(MESSAGE_ARRAY_T *array) {
    for (size_t i = 0; i < array->length; ++i) {
        array->deinit(&array->messages[i]);
    }
    free(array->messages);
}
