static pthread_mutex_t message_list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_MESSAGE_T* message_list = NULL;
static size_t message_count = 0;
static size_t max_messages = 16;
static char log_file[256] = "log.txt";

void* add_message(NFAPI_MESSAGE_T* msg) {
    pthread_mutex_lock(&message_list_mutex);
    if (message_count == max_messages) {
        NFAPI_MESSAGE_T** new_list = realloc(message_list, sizeof(NFAPI_MESSAGE_T) * (max_messages + 16));
        if (!new_list) {
            fprintf(stderr, "Error: Out of memory\n");
            pthread_mutex_unlock(&message_list_mutex);
            return NULL;
        }
        message_list = new_list;
        max_messages += 16;
    }
    message_list[message_count++] = *msg;
    pthread_mutex_unlock(&message_list_mutex);
    return msg->payload;
}

