    if (!buffer) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    log_successful_allocation(size, buffer);
    return buffer;
}

void log_successful_allocation(size_t size, const void* ptr) {
    FILE* log = fopen(log_file, "a");
    if (log) {
        fprintf(log, "Successfully allocated %zu bytes at %p\n", size, ptr);
        fclose(log);
    }
}

size_t rename_files_in_directory(const char* dir) {
    DIR* dp = opendir(dir);
    if (!dp) {
        fprintf(stderr, "Error: Unable to open directory %s\n", dir);
        return 0;
    }

    struct dirent* entry;
    size_t successes = 0, failures = 0;
    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_name[0] == '.') continue; // Ignore hidden files and directories

        char base[256], ext[8];
        strncpy(base, entry->d_name, sizeof(base) - 1);
        strrchr(base, '.');
        if (strrchr(base, '.') != NULL) {
            strncpy(ext, strchr(base, '.'), sizeof(ext) - 1);
            // Calculate unique identifier length based on base name
            size_t uid_len = calculate_uid_length(base);
            char time_str[19];
            strftime(time_str, sizeof(time_str), "%Y%m%d_%H%M%S", localtime(&time(NULL)));
            char new_name[256] = {0};
            snprintf(new_name, sizeof(new_name), "%s_%s%llu_%s", time_str, base, (unsigned long long)pthread_self(), ext);

            int count = 0;
            char* fileName = new_name;
            while (access(fileName, F_OK)) {
                count++;
                snprintf(fileName + strlen(fileName), sizeof(new_name) - strlen(fileName), "_%d", count);
            }

            if (rename(entry->d_name, fileName) != 0) {
                fprintf(stderr, "Error: Unable to rename %s to %s\n", entry->d_name, fileName);
                failures++;
            } else {
                successes++;
            }
        }
    }
    closedir(dp);
    return successes + failures;
}

