void run() {
    auto memoryUsage = getrusage(RUSAGE_SELF, nullptr);
    const int memoryCap = static_cast<int>((memoryUsage->ru_maxrss / getpagesize()) * 1024);
    if (memoryUsage->ru_maxrss > MEMCAP_THRESHOLD) {
        std::cerr << "Warning: Exceeded maximum memory usage threshold of " << MEMCAP_THRESHOLD << " bytes.\n";
    }

    createAndPopulateStructures();
    workQueueMutex.lock();
    workQueue.push_back(CRCIndicationList{std::move(structures)});
    workQueueMutex.unlock();

    for (int i = 0; i < MAX_THREADS; ++i) {
        threads.emplace_back(processStructures, std::ref(workQueue));
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

int main() {
    run();
    return 0;
}
