typedef struct _mem_block {
    void* start;
    size_t size;
    struct _mem_block* next;
} mem_block;

custom_memory_pool mem_pool;

void initialize_mem_pool(size_t size) {
    mem_pool.start = calloc(1, size);
    mem_pool.end = mem_pool.start + size;
    mem_pool.free_list = NULL;
}

void* custom_malloc(size_t size) {
    if (size > mem_pool.end - mem_pool.free_list) {
        // Handle out-of-memory here
    }

    mem_block* block = mem_pool.free_list;
    void* result = block->start;
    block->start += size;
    block->size -= size;

    if (block->size == 0) {
        block->next = mem_pool.free_list;
        mem_pool.free_list = block;
    }

    return result;
}

