Packet *packet_sequence_numbers = mmap(NULL, MAX_PACKETS * sizeof(Packet), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
Packet *timestamps = mmap(NULL, MAX_PACKETS * sizeof(Packet), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
size_t *payload_sizes = calloc(MAX_PACKETS, sizeof(size_t));
double *data_transfer_rates = calloc(MAX_CONNECTIONS, sizeof(double));
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

