    connection->Connection_ID = generate_connection_id();
    connection->Session_Start_Time = 0;
    connection->Data_Transfer_Limit = data_transfer_limit;
    connection->Num_Packets = 0;
    connection->Packet_List = NULL;
    return connection;
}

void add_packet(Connection_Record *connection, uint32_t sequence_number, uint64_t timestamp, size_t payload_size) {
    if (sequence_number == 0 || payload_size > MAX_PAYLOAD_SIZE || num_packets >= MAX_PACKETS) {
        log_error("Invalid packet parameters or maximum packets limit reached");
        return;
    }

    Packet *packet = (Packet *)memory_pool != NULL ? memory_pool : calloc(1, sizeof(Packet));
    if (packet == NULL) {
        log_error("Memory allocation failure");
        return;
    }

    packet->Sequence_Number = sequence_number;
    packet->Timestamp = timestamp;
    packet->Payload_Size = payload_size;

    // Implement handling for duplicate sequence numbers here

    pthread_mutex_lock(&memory_lock);
    packet_sequence_numbers[num_packets] = *packet;
    timestamps[num_packets] = timestamp;
    payload_sizes[num_packets] = payload_size;
    connection->Packet_List = num_connections > 0 ? realloc(connection->Packet_List, (num_connections + 1) * sizeof(Packet)) : calloc((num_connections + 1), sizeof(Packet));
    if (connection->Packet_List == NULL) {
        log_error("Memory allocation failure");
        free(packet);
        pthread_mutex_unlock(&memory_lock);
        return;
    }
    connection->Packet_List[num_connections] = *packet;
    num_packets++;
    data_transfer_rates[connection - connections] += payload_size;
    pthread_mutex_unlock(&memory_lock);
}

void check_memory_usage() {
