Protocol* get_available_protocols() {
    static Protocol protocols[] = {
        { "TCP", tcp_handle_packet, NULL },
        { "UDP", udp_handle_packet, NULL },
        { "SCTP", sctp_handle_packet, NULL },
        // Add more protocols as needed
    };
    int supported_protocols = 0;
    for (int i = 0; i < sizeof(protocols) / sizeof(Protocol); ++i) {
        int sockfd = socket(AF_INET, protocols[i].name[0] == 'U' ? SOCK_DGRAM : SOCK_STREAM, IPPROTO_PROTOCOL_NUM(protocols[i].name));
        if (sockfd == -1) {
            // Protocol not supported, remove it from the list
            memmove(&protocols[supported_protocols], &protocols[supported_protocols + 1], sizeof(Protocol) * (sizeof(protocols) / sizeof(Protocol) - supported_protocols));
        } else {
            close(sockfd); // Close the socket, no need for further use
            supported_protocols++;
        }
    }

    Protocol* protocol_list = malloc(supported_protocols * sizeof(Protocol));
    memcpy(protocol_list, &protocols[0], supported_protocols * sizeof(Protocol));

    // Dynamically load configuration settings for each supported protocol
    for (int i = 0; i < supported_protocols; ++i) {
        char config_filename[32];
        snprintf(config_filename, sizeof(config_filename), "protos/%s_cfg.so", protocols[i].name);
        void* handle = dlopen(config_filename, RTLD_LAZY);
        if (handle) {
            protocol_list[i].config = dlsym(handle, "get_config");
        } else {
            perror("dlopen");
            // Handle error here
        }
    }

    return protocol_list;
}

