typedef struct {
    int Connection_ID;
    int Socket;
    sockaddr_in IP;
    int Client_Port;
} TCP_Connection;

struct MemoryPool {
    void *memory;
    size_t allocated;
    size_t capacity;
};

void* mempool_alloc(struct MemoryPool *pool, size_t size) {
    if (pool->capacity - pool->allocated < size) return NULL;
    void *result = pool->memory + pool->allocated;
    pool->allocated += size;
    return result;
}

void mempool_free(struct MemoryPool *pool, void *ptr) {
    if (ptr >= pool->memory && ptr < pool->memory + pool->capacity)
        pool->allocated -= (char *)ptr - (char *)pool->memory;
}

struct MemoryPool ip_mempool = {.memory = malloc(1024 * 1024), .capacity = 1024 * 1024};
struct MemoryPool port_mempool = {.memory = malloc(sizeof(int) * 65536), .capacity = sizeof(int) * 65536};
TCP_Connection connections[1000];
pthread_mutex_t connections_lock;
int num_connections = 0;

void init_mempools() {
    memset(ip_mempool.memory, 0, ip_mempool.capacity);
    memset(port_mempool.memory, 0, port_mempool.capacity);
}

int generate_connection_id() {
    int id;
    do {
        id = rand();
    } while (num_connections >= 10000 || (num_connections > 0 && connections[num_connections - 1].Connection_ID == id));
    return id;
}

void create_connection(int socket, const sockaddr *client_addr) {
    int client_port = *(int *)port_mempool.memory;
    memcpy(&connections[num_connections].IP, client_addr, sizeof(sockaddr));
    connections[num_connections].Client_Port = client_port;
    connections[num_connections].Connection_ID = generate_connection_id();
    connections[num_connections++].Socket = socket;
    port_mempool.memory += sizeof(int);
}

void add_to_log() {
    if (num_connections * 1024 / ip_mempool.capacity > 75)
        fprintf(stderr, "Memory usage exceeded 75% of the allocated budget\n");
}

// Serialize and deserialize functions not shown due to space constraints
