void append_protocol(struct dynamic_list* list, struct protocol_entry* entry) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(struct protocol_entry*));
    }
    list->entries[list->size++] = entry;
}

void update_protocol(struct dynamic_list* list, int id, struct protocol_entry* new_entry) {
    for (int i = 0; i < list->size; ++i) {
        if (list->entries[i]->id == id) {
            free(list->entries[i]);
            append_protocol(list, new_entry);
            break;
        }
    }
}

