#include <limits.h>

// Custom Memory Pool
typedef struct MemPool {
    void* memory;
    size_t allocated, used, capacity;
} MemPool;

MemPool createMemPool(size_t initialCapacity) {
    MemPool pool = {NULL, 0, initialCapacity};
    pool.memory = calloc(initialCapacity, sizeof(void*));
    if (!pool.memory) {
        fprintf(stderr, "Failed to allocate memory for MemPool\n");
        exit(EXIT_FAILURE);
    }
    return pool;
}

void freeMemPool(MemPool* pool) {
    if (pool->memory) {
        free(pool->memory);
        pool->memory = NULL;
        pool->allocated = pool->used = 0;
    }
}

void* reallocOrMalloc(MemPool* pool, size_t size) {
    if (pool->used + size <= pool->capacity - pool->allocated) {
        memmove((char*)pool->memory + pool->used, NULL, pool->used * sizeof(void*));
        return (char*)pool->memory + pool->used += size;
    } else {
        void* newMemory = realloc(pool->memory, pool->capacity + size);
        if (!newMemory) {
            fprintf(stderr, "Failed to realloc or malloc memory for MemPool\n");
            exit(EXIT_FAILURE);
        }
        memmove((char*)newMemory + pool->used, (char*)pool->memory, pool->used * sizeof(void*));
        pool->capacity += size;
        return (char*)newMemory + pool->used;
    }
}

