typedef struct {
    const char *name;
    void (*handler)(const char *, const char *);
    void *params;
} LoggingFramework;

LoggingFramework *load_loggers(const char *config_file) {
    static LoggingFramework loggers[1024];
    int count = 0, line_num = 0;
    FILE *fp;
    char buffer[256], *token;

    if (!(fp = fopen(config_file, "r"))) {
        perror("Error opening config file");
        return NULL;
    }

    while (fgets(buffer, sizeof(buffer), fp)) {
        line_num++;
        token = strtok(buffer, "\n");
        if (!token) continue;

        // Extract framework name
        token = strtok(NULL, " \t\r\f,");
        if (!token) {
            fprintf(stderr, "Line %d: Missing logging framework name\n", line_num);
            continue;
        }

        // Check for supported frameworks
        LoggingFramework *framework = &loggers[count++];
        framework->name = strdup(token);
        framework->handler = NULL;

        token = strtok(NULL, " \t\r\f,");
        if (!token) {
            fprintf(stderr, "Line %d: Missing logging handler function\n", line_num);
            continue;
        }

        // Validate handler function
        void (*handler)(const char *, const char *) = (void (*)(const char *, const char *)) dlsym(RTLD_DEFAULT, token);
        if (!handler) {
            fprintf(stderr, "Line %d: Unsupported logging handler '%s'\n", line_num, token);
            continue;
        }

        framework->handler = handler;

        // Parse parameters (if any)
        token = strtok(NULL, "\r\f");
        if (token) {
            void *params = malloc(strlen(token));
            memcpy(params, token, strlen(token));
            framework->params = params;
        }
    }

    fclose(fp);
    loggers[count] = NULL; // Mark end of array
    return &loggers[0];
}

// Example logging handler implementation
void log_to_console(const char *message, const char *params) {
    printf("%s\n", message);
}
