#define MAX_SESSIONS 100
#define MAX_MESSAGES_PER_SESSION 1000
#define MAX_RECORDS 10000
#define MEMORY_BUDGET 2 * (1024 * 1024) // 2 MB
#define RANDOM_SEED_RANGE 1000000
#define MAX_MESSAGE_SIZE 100
#define MESSAGE_ID_MAX 65536 // Max 16-bit unsigned int

typedef struct LTE_RRCNAS_Message {
    NAS_Message_Type nas_message_type;
    Message_ID message_id;
    Security_Algorithm_Suite security_algorithm_suite;
    NAS_Transaction_ID transaction_id;
    NFAPI_MESSAGE_T* payload;
} LTE_RRCNAS_Message;

typedef struct record {
    int value;
    long offset;
    double measurement;
} Record;

static void* memory_pool = NULL;
static size_t memory_pool_capacity = 0;
static size_t memory_pool_used = 0;
static size_t records_count = 0;
static unsigned int sessions[MAX_SESSIONS] = {0};
static LTE_RRCNAS_Message* messages[MAX_SESSIONS][MAX_MESSAGES_PER_SESSION];
static Record data_array[MAX_RECORDS];
static size_t memory_usage;

void initMemoryPool(size_t capacity) {
    if (memory_pool != NULL) return;
    memory_pool = malloc(capacity);
    memory_pool_capacity = capacity;
    memory_pool_used = 0;
}

void* memAlloc(size_t size) {
    if (memory_pool_used + size > memory_pool_capacity - MEMORY_BUDGET * 0.75) {
        printf("Error: Memory usage exceeded limit\n");
        return NULL;
    }
    void* result = memory_pool + memory_pool_used;
    memory_pool_used += size;
    return result;
}

void memFree(void* ptr) {
    if (ptr >= memory_pool && ptr < memory_pool + memory_pool_capacity) {
        memory_pool_used -= (char*)ptr - (char*)memory_pool;
    }
}

int generateSession() {
    int session_id = 0;
    while (sessions[session_id]) session_id++;
    sessions[session_id] = 1;
    return session_id;
}

void initDataArray(Record* array, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        Record* record = array + i;
        record->value = rand() % RANDOM_SEED_RANGE;
        record->offset = (long)i;
        record->measurement = 0.0;
    }
}

void generateMessages(int session_id, size_t count) {
    if (session_id >= MAX_SESSIONS || sessions[session_id] == 0) return;
    for (size_t i = 0; i < count && messages[session_id][i] == NULL; ++i) {
        LTE_RRCNAS_Message* message = memAlloc(sizeof(LTE_RRCNAS_Message));
        if (!message) return;
        message->nas_message_type = rand() % 100 + 1;
        message->message_id = rand() % MESSAGE_ID_MAX;
        for (size_t j = 0; j < RANDOM_SEED_RANGE && messages[session_id][i]->message_id == message->message_id; ++j);
        if (j >= RANDOM_SEED_RANGE) continue; // Ensure unique Message ID within the same session

        message->security_algorithm_suite = rand() % 10 + 1;
        message->transaction_id = rand() % 100000;

        NFAPI_MESSAGE_T* payload = memAlloc(sizeof(NFAPI_MESSAGE_T));
        if (!payload) continue;

        payload->rnti = rand() % 1000000 + 1;
        payload->rx_ue_information_tag = rand() % 256;

        // Allocate a buffer for the payload data
        size_t payload_size = rand() % MAX_MESSAGE_SIZE + 1;
        payload->payload = memAlloc(payload_size);
        if (!payload->payload) continue;

        memset(payload->payload, rand() % 256, payload_size);

        messages[session_id][i] = message;
    }
}

void serializeDataStructureToFile(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    size_t session_count = 0;
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i]) session_count++;
    }

    fwrite(&session_count, sizeof(size_t), 1, file);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (!sessions[i]) continue;
        fwrite(&i, sizeof(int), 1, file);
        size_t message_count = 0;
        for (size_t j = 0; j < MAX_MESSAGES_PER_SESSION && messages[i][j]; ++j) message_count++;
        fwrite(&message_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < message_count; ++j) {
            const LTE_RRCNAS_Message* msg = messages[i][j];
            fwrite(msg, sizeof(LTE_RRCNAS_Message), 1, file);
        }
    }
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        const Record* record = data_array + i;
        fwrite(record, sizeof(Record), 1, file);
    }

    fclose(file);
}
```

