```c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <string.h>

typedef void* (*hash_func_t)(const char*, const void*, size_t);
typedef void* (*cipher_func_t)(const char*, const void*, size_t, void**);

struct crypt_info {
    const char *name;
    hash_func_t hash_func;
    cipher_func_t cipher_func;
    const void *params; // platform-specific params
    bool supported;
};

typedef struct crypt_info* crypt_info_t;

// Load a shared object and resolve the given symbol.
void* load_symbol(const char *so_name, const char *sym_name) {
    void *handle = dlopen(so_name, RTLD_LAZY);
    if (!handle) return NULL;
    return dlsym(handle, sym_name);
}

// Load a list of cryptographic functions from shared objects.
crypt_info_t load_crypt_funcs(const char *so_names[]) {
    int i = 0;
    for (const char *so : so_names) {
        void *handle = dlopen(so, RTLD_LAZY);
        if (!handle) continue;

        crypt_info_t info = malloc(sizeof(struct crypt_info));
        info->name = so;
        info->hash_func = load_symbol(so, "hash_func");
        if (info->hash_func) {
            info->supported = true;
            i++;
        } else {
            info->supported = false;
            free(info);
        }

        // Repeat this pattern for cipher functions and other necessary info.
    }

    crypt_info_t list = malloc((i + 1) * sizeof(struct crypt_info));
    memcpy(list, info, i * sizeof(struct crypt_info));
    list[i]->supported = false; // Indicate the end of the list.
    return list;
}
```

