void process_integers(IntArray *array, const int *buffer, size_t n) {
    pthread_mutex_lock(&array->lock);
    if (array->size + n > array->capacity) {
        resize_array(array, array->size + n);
    }

    int *end = array->data + array->size;
    size_t i;
    for (i = 0; i < n && (array->size + i) < array->capacity; ++i) {
        if (!isvalid_int(buffer[i])) {
            log_error("Invalid integer: %d", buffer[i]);
