        int val = buffer[i];
        if (array->filter && !(val >= array->min && val <= array->max)) {
            log_info("Filtered out: %d", val);
            continue;
        }
        *end++ = val;
        array->size++;
    }

    pthread_mutex_unlock(&array->lock);
}

void resize_array(IntArray *array, size_t new_capacity) {
    int *new_data = mmap(NULL, new_capacity * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_data == MAP_FAILED) {
        log_error("Memory allocation failed");
        return;
    }
    memmove(new_data, array->data, array->size * sizeof(int));
    munmap(array->data, array->capacity * sizeof(int));
    array->data = new_data;
    array->capacity = new_capacity;
}

