                         [current_msg](const auto& msg) { return msg->message_id == current_msg->message_id; }) != current_session_->cend()) {
            throw std::runtime_error("Duplicate message ID detected.");
        }

        current_msg->nas_message_type = /* initialize nas_message_type here */ ;
        current_msg->message_id = ++current_message_counter_;

        auto security_alg_it = security_algorithms_.find(current_msg->message_id);
