    std::unique_ptr<uint8_t[]> payload;
    size_t payload_length;

    void generate_random_payload(size_t len) {
        if (len > 0) {
            payload.reset(new uint8_t[len]);
            std::fill((void*)payload.get(), (void*)(payload.get() + len), rand());
            payload_length = len;
        }
    }

    std::string generate_md5_hash() const {
        unsigned char digest[EVP_MAX_MD_SIZE];
        EVP_MD_CTX ctx;
        EVP_MD_init(&ctx, EVP_sha256());
        EVP_MD_update(&ctx, (const unsigned char*)payload.get(), payload_length);
        EVP_MD_final( &ctx, digest, NULL );
        return b64encode((const uint8_t *)digest, EVP_MAX_MD_SIZE);
    }

    bool validate_checksum(const std::string& checksum) const {
        if (checksum.empty()) return false;
        auto decoded_bytes = b64decode((const char*)checksum.c_str());
        if (!decoded_bytes) return false;
        unsigned char digest[EVP_MAX_MD_SIZE];
        EVP_MD_CTX ctx;
        EVP_MD_init(&ctx, EVP_sha256());
        EVP_MD_update(&ctx, (const unsigned char*)payload.get(), payload_length);
        EVP_MD_final( &ctx, digest, NULL );
        return memcmp(digest, decoded_bytes.get(), sizeof(digest)) == 0;
    }
};

