#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_RX_FRAME_INFO_T;

typedef struct hashNode {
    NFAPI_RX_FRAME_INFO_T frame;
    struct hashNode *next;
} HashNode;

struct hashTable {
    unsigned int size;
    HashNode **table;
};

unsigned int hashFunction(unsigned int key, unsigned int tableSize) {
    return key % tableSize;
}

HashNode* createNode(NFAPI_RX_FRAME_INFO_T frame) {
    HashNode *newNode = (HashNode *)malloc(sizeof(HashNode));
    newNode->frame = frame;
    newNode->next = NULL;
    return newNode;
}

void resizeTable(struct hashTable *table, unsigned int newSize) {
    struct hashTable tempTable;
    tempTable.size = newSize;
    tempTable.table = (HashNode **)malloc(newSize * sizeof(HashNode*));

    for (unsigned int i = 0; i < newSize; ++i)
        tempTable.table[i] = NULL;

    unsigned int minSize = (tempTable.size > table->size)? table->size : tempTable.size;

    for (unsigned int i = 0; i < minSize; ++i) {
        if (table->table[i]) {
            HashNode *current = table->table[i];
            while(current != NULL) {
                unsigned int newHash = hashFunction(current->frame.RNTI, tempTable.size);
                HashNode *newNode = createNode(current->frame);
                newNode->next = tempTable.table[newHash];
                tempTable.table[newHash] = newNode;
                current = current->next;
            }
        }
    }

    free(table->table);
    table->table = tempTable.table;
    table->size = tempTable.size;
