void addFrame(struct hashTable *table, NFAPI_RX_FRAME_INFO_T frame) {
    unsigned int index = hashFunction(frame.RNTI, table->size);

    if (!table->table[index])
        table->table[index] = createNode(frame);
    else {
        HashNode *current = table->table[index];
        while (current != NULL) {
            if (current->frame.RNTI == frame.RNTI) {
                current->frame = frame;
                return;
            }
            current = current->next;
        }
    }

    resizeTable(table, table->size * 2);
    addFrame(table, frame);
}

NFAPI_RX_FRAME_INFO_T* getFrameByRNTI(struct hashTable *table, uint16_t rnti) {
    unsigned int index = hashFunction(rnti, table->size);
    HashNode *current = table->table[index];

    while (current != NULL) {
        if (current->frame.RNTI == rnti)
            return &current->frame;
        current = current->next;
    }

    return NULL;
}

void setCRCFlag(struct hashTable *table, uint16_t rnti, uint8_t crcflag) {
    NFAPI_RX_FRAME_INFO_T* frame = getFrameByRNTI(table, rnti);

    if (frame != NULL)
        frame->CRCFLAG = crcflag;
}

void printFrames(struct hashTable *table) {
    for (unsigned int i = 0; i < table->size; ++i) {
        HashNode *current = table->table[i];

        while (current != NULL) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", current->frame.RX_UE_INFORMATION_TAG, current->frame.RNTI, current->frame.CRC_INDICATION_REL8_TAG, current->frame.CRCFLAG);
            current = current->next;
