// Helper function to calculate a hash value based on RNTI
unsigned long rnti_hash(RNTI rnti) {
    unsigned long hash = 5381; // Magic prime number for hash calculation, can be optimized further
    int c;

    while (rnti != 0) {
        c = (int)(rnti & 0xff);
        rnti >>= 8;
        hash += hash * 33 + c;
    }

    return hash % chm->hash_size;
}

