    pthread_mutex_lock(&chm->lock);

    unsigned long index = rnti_hash(frame->rnti);
    chm_node_t *bucket = chm->bucket[index];
    chm_node_t **prev = &chm->bucket[index];

    while (bucket != NULL) {
        if (bucket->data.rnti == frame->rnti) { // Found the matching RNTI, update the data
            bucket->data = *frame;
            break;
        }
        prev = &bucket->next;
        bucket = bucket->next;
    }

    if (bucket == NULL) { // Didn't find the matching RNTI, add a new one
        bucket = malloc(sizeof(chm_node_t));
        if (bucket == NULL) {
            log_error("Memory allocation failed while adding frame.");
            pthread_mutex_unlock(&chm->lock);
            return;
        }
        memcpy(&bucket->data, frame, sizeof(NFAPI_RX_FRAME_INFO_T));
        *prev = bucket;
    }

    // If the number of frames exceeds a certain threshold, reclaim memory by removing the least recently used frames (LRU)
    if (chm->num_frames > MAX_FRAMES) {
        unsigned long least_recently_used_index = 0;
        chm_node_t *lru_node = NULL;

        for (unsigned long i = index + 1; i < chm->hash_size; ++i) {
            bucket = chm->bucket[i];
            if (bucket != NULL) {
                least_recently_used_index = i;
                lru_node = bucket;
            }
        }

        // Remove the LRU node and update the least recently used index counter
        *prev = lru_node->next;
        free(lru_node);
        chm->num_frames--;
    }

    pthread_mutex_unlock(&chm->lock);
}

