public:
    CustomAllocator(size_t maxBufferSize, size_t compressedPoolSize)
        : maxBufferSize_(maxBufferSize), compressedPoolSize_(compressedPoolSize), pool_{} {}

    void* allocate(std::size_t size) {
        if (size <= maxBufferSize_) {
            return operator new(size);
        }
        auto it = pool_.find(size);
        if (it != pool_.end()) {
            void* data = it->second;
            pool_.erase(it);
            return data;
        }
        // Compress existing data to make space in the compressed pool
        compressPool();
        auto newData = operator new(size);
        pool_[size] = newData;
        return newData;
    }

    void deallocate(void* p, std::size_t) {
        auto size = static_cast<std::size_t>(std::distance(pool_.begin(), std::find(pool_.begin(), pool_.end(), p)));
        pool_.erase(size);
    }

private:
