```java
import java.util.*;
import java.time.Instant;

class SensorReading {
    Instant timestamp;
    double temperature;
    double humidity;
    String location;
}

public class SensorDataProcessor {

    private Map<String, Double> averageTemperatures = new HashMap<>();
    private Map<String, Double> averageHumidities = new HashMap<>();
    private long lastUpdateTime;

    public void process(SensorReading reading) {
        if (System.currentTimeMillis() - lastUpdateTime > 60000) { // Update every minute
            updateAverages(reading.getLocation());
            lastUpdateTime = System.currentTimeMillis();
        }
    }

    private void updateAverages(String location) {
        if (!averageTemperatures.containsKey(location)) {
            averageTemperatures.put(location, 0.0);
            averageHumidities.put(location, 0.0);
        }

        double temperature = averageTemperatures.getOrDefault(location, 0.0) + reading.temperature;
        double humidity = averageHumidities.getOrDefault(location, 0.0) + reading.humidity;

        averageTemperatures.put(location, temperature / (averageTemperatures.get(location) + 1));
        averageHumidities.put(location, humidity / (averageHumidities.get(location) + 1));
    }

    public double getAverageTemperatureForLocation(String location) {
        return averageTemperatures.getOrDefault(location, 0.0);
    }

    public double getAverageHumidityForLocation(String location) {
        return averageHumidities.getOrDefault(location, 0.0);
    }
}
