#define MAX_PAYLOAD_SIZE 1024 // Maximum payload size per structure
#define NUM_STRUCTURES 100 // Number of structures to initialize

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    void* payload;
    size_t payload_size;
} NFAPI_MESSAGE_T;

// Global variables for thread safety and statistics
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;
int success_count = 0;
int failure_count = 0;
sem_t message_queue_sem; // Semaphore to control access to the message queue

void* allocate_and_validate_payload(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!ptr) {
        perror("mmap");
        return NULL;
    }

    if (size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Payload size exceeds the maximum allowed size.\n");
        munmap(ptr, size);
        return NULL;
    }

    return ptr;
}

void init_message_list() {
    NFAPI_MESSAGE_T* messages = (NFAPI_MESSAGE_T*)calloc(NUM_STRUCTURES, sizeof(NFAPI_MESSAGE_T));

    if (!messages) {
        perror("calloc");
        return;
    }

    pthread_t allocation_threads[NUM_STRUCTURES];
    sem_t payload_semaphores[NUM_STRUCTURES];

    for (size_t i = 0; i < NUM_STRUCTURES; ++i) {
        sem_init(&payload_semaphores[i], 0, 0);
        pthread_create(&allocation_threads[i], NULL, allocate_and_validate_payload_wrapper, &i);
    }

    for (size_t i = 0; i < NUM_STRUCTURES; ++i) {
        void* payload = NULL;
        pthread_join(allocation_threads[i], NULL);

        if (payload) {
            messages[i].payload = payload;
            messages[i].payload_size = MAX_PAYLOAD_SIZE;
            success_count++;
        } else {
            failure_count++;
        }

        sem_destroy(&payload_semaphores[i]);
    }

    // Initialize and configure message queue system here

    pthread_mutex_lock(&stats_lock);
    printf("Initialized %d messages, success rate: %.2f%%\n", NUM_STRUCTURES, (double)success_count / NUM_STRUCTURES * 100.0);
    pthread_mutex_unlock(&stats_lock);
}

void* allocate_and_validate_payload_wrapper(void* arg) {
    size_t i = *(size_t*)arg;
    sem_wait(&payload_semaphores[i]); // Wait for the payload to be allocated by another thread

    void* payload = allocate_and_validate_payload(MAX_PAYLOAD_SIZE);
    if (payload) {
        sem_post(&payload_semaphores[(size_t)(arg + 1) % NUM_STRUCTURES]); // Notify the next thread to continue allocation
    }

    return payload;
}
