// Custom logging macro
#define LOG(msg) do { printf("[Log]: " msg "\n"); } while (0)

enum TaskStatus { TASK_PENDING, TASK_IN_PROGRESS, TASK_COMPLETED };
typedef struct UnionData {
    union {
        double d;
        char* c;
    } u;
} UnionData;

typedef struct Task {
    int id;
    enum TaskStatus status;
    int priority;
    UnionData data;
} Task;

// Dynamic resizing function using a custom binomial doubling algorithm
void* realloc_smart(void* ptr, size_t old_size, size_t new_size) {
    void* new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL && old_size < new_size) {
        LOG("Failed to allocate memory: " strerror(errno));
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

Task* initTasks(int num_tasks, int min_priority, int max_priority, int status_dist[], int* total_size) {
    Task* tasks = malloc(sizeof(Task));
    if (!tasks) {
        LOG("Failed to allocate memory for task list.");
        exit(EXIT_FAILURE);
    }
    *total_size = 1;

    int bits = 0;
    while ((1 << (bits + 1)) <= num_tasks) ++bits;
    size_t initial_capacity = (1 << bits) - 1;

    Task** temp_tasks = malloc(sizeof(Task*) * initial_capacity);
    if (!temp_tasks) {
        LOG("Failed to allocate memory for temporary task array.");
        exit(EXIT_FAILURE);
    }

    tasks->id = 0;
    tasks->status = TASK_PENDING;
    tasks->priority = min_priority;
    tasks->data.d = 0.0; // Default data type is double
    temp_tasks[0] = tasks;
    int filled = 1;

    for (int i = 1; i <= num_tasks; ++i) {
        int next_index = (filled + 1) & ((1 << bits) - 1);
        if (!temp_tasks[next_index]) {
            temp_tasks[next_index] = malloc(sizeof(Task));
            if (!temp_tasks[next_index]) {
                LOG("Failed to allocate memory for task.");
                exit(EXIT_FAILURE);
            }
            tasks = temp_tasks[next_index];
        }

        int status = status_dist[(i - 1) % ARRAY_SIZE(status_dist)];
        tasks->id = i;
        tasks->status = (enum TaskStatus)status;
        tasks->priority = rand() % (max_priority - min_priority + 1) + min_priority;

        // Populate the data union with a double or char* based on status distribution
        if (status == TASK_IN_PROGRESS || status == TASK_COMPLETED) {
            tasks->data.c = malloc(sizeof(char) * rand() % 50 + 1);
            if (!tasks->data.c) {
                LOG("Failed to allocate memory for char data.");
                exit(EXIT_FAILURE);
            }
            sprintf(tasks->data.c, "Random Data");
        } else {
            tasks->data.d = (double)rand();
        }

        ++filled;
        if (filled == initial_capacity || i == num_tasks) {
            size_t new_capacity = (initial_capacity * 2 > num_tasks) ? initial_capacity * 2 : num_tasks + 1;
            temp_tasks = realloc_smart(temp_tasks, sizeof(Task*) * initial_capacity, sizeof(Task*) * new_capacity);
        }
        tasks++;
    }

    free(temp_tasks);
    *total_size = filled;
    return tasks;
}

// Custom memory deallocation function
void deallocTasks(Task* tasks, int total_size) {
    for (int i = 0; i < total_size; ++i) {
        if (tasks[i].data.c) free(tasks[i].data.c);
        free(&tasks[i]);
    }
    free(tasks);
}
```

In this example, the function `initTasks()` dynamically allocates and initializes an array of Task structures based on user-provided parameters. It uses a custom resizing algorithm (binomial doubling) to minimize memory fragmentation and optimize time complexity. The `realloc_smart()` function is used for efficient dynamic resizing, handling both success and failure scenarios.

The code also implements error handling for potential memory allocation failures, utilizing a custom logging mechanism to track issues. It supports dynamic resizing if the initial allocation size proves inadequate. Additionally, it handles different data types (double and char*) within the UnionData union efficiently during initialization.']

