} NFAPI_RX_FRAME_INFO_T;

static pthread_mutex_t frames_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutexattr_t mutex_attr;
static size_t total_frames = 0;
static clock_t start, end;

void init_mutex_attr() {
    pthread_mutexattr_init(&mutex_attr);
    pthread_mutexattr_settype(&mutex_attr, PTHREAD_MUTEX_RECURSIVE);
}

NFAPI_RX_FRAME_INFO_T* create_frame_info(size_t capacity) {
    NFAPI_RX_FRAME_INFO_T* frame = (NFAPI_RX_FRAME_INFO_T*)malloc(sizeof(NFAPI_RX_FRAME_INFO_T));
    if (!frame) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    frame->capacity = capacity;
    frame->size = 0;
    frame->symbols = (NFAPI_RX_SYMBOL_T*)calloc(capacity, sizeof(NFAPI_RX_SYMBOL_T));
    if (!frame->symbols) {
        free(frame);
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    return frame;
}

void reset_summary() {
    total_frames = 0;
    start = end = clock();
}

void increment_frames() {
    pthread_mutex_lock(&frames_mutex);
    total_frames++;
    pthread_mutex_unlock(&frames_mutex);
}

size_t get_total_frames() {
    size_t frames;
    pthread_mutex_lock(&frames_mutex);
    frames = total_frames;
    pthread_mutex_unlock(&frames_mutex);
    return frames;
}

void destroy_frame_info(NFAPI_RX_FRAME_INFO_T* frame) {
    free(frame->symbols);
    free(frame);
}

void report() {
    clock_t elapsed = end - start;
    double avg_time = (double)elapsed / CLOCKS_PER_SEC / total_frames;
    printf("\nSummary Report:\n");
    printf("Total Frames: %ld\n", total_frames);
    printf("Average Symbol Processing Time: %.6fs\n", avg_time);
}

void* process_frame(NFAPI_RX_FRAME_INFO_T* frame) {
    // Perform symbol processing here
    ++frame->size;
    if (frame->size >= frame->capacity) {
        frame->capacity *= 2;
        frame->symbols = realloc(frame->symbols, frame->capacity * sizeof(NFAPI_RX_SYMBOL_T));
        if (!frame->symbols) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }
    }

    increment_frames();

    return NULL;
}

void initialize_frames(NFAPI_RX_FRAME_INFO_T** frames, size_t n) {
    *frames = (NFAPI_RX_FRAME_INFO_T*)malloc(n * sizeof(NFAPI_RX_FRAME_INFO_T));
    if (!*frames) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; ++i) {
        (*frames)[i] = create_frame_info(1000);
    }
}
