#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

typedef struct {
    FAPI_MESSAGE_T message;
    pthread_mutex_t payload_mutex;
    size_t payload_size;
    void* payload;
} threadsafe_message_t;

sem_t message_queue_semaphore;

void threadsafe_message_init(threadsafe_message_t* msg, RX_UE_INFORMATION_TAG tag, uint32_t rnti, size_t payload_size) {
    if (!msg || payload_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Invalid input: message or payload size is invalid\n");
        return;
    }

    msg->message.rnti = rnti;
    msg->message.ue_information_tag = tag;

    pthread_mutex_init(&msg->payload_mutex, NULL);
    msg->payload_size = payload_size;
    msg->payload = mmap(NULL, payload_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (msg->payload == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&msg->payload_mutex);
        return;
    }
}

void threadsafe_message_enqueue(threadsafe_message_t* msg) {
    sem_post(&message_queue_semaphore);
}

int threadsafe_message_dequeue(threadsafe_message_t** msg, size_t* payload_size, void** payload) {
    int ret;
    pthread_mutex_lock(&message_queue_semaphore);

    while (true) {
        if (!message_queue.empty()) {
            threadsafe_message_t* next = message_queue.front();
            message_queue.pop();
            ret = 0;
            break;
        } else {
            ret = sem_wait(&message_queue_semaphore);
            if (ret != 0 && errno != EINTR) {
                perror("sem_wait failed");
                return -1;
            }
        }
    }

    *msg = next;
    *payload_size = next->message.payload_size;
    *payload = next->payload;
    free(next);

    pthread_mutex_unlock(&message_queue_semaphore);
    return 0;
}
