extern sem_t messageQueueSemaphore; // Assumed to be initialized elsewhere for the message queue system

// Define lock-free ring buffer for concurrent allocation and validation processes
struct LockFreeList {
    std::atomic<size_t> head, tail;
    std::list<RFAPI_MESSAGE_T> messages;
};

void initLockFreeList(LockFreeList* lf) {
    lf->head.store(0);
    lf->tail.store(0);
}

RFAPI_MESSAGE_T* getNextMessageFromLockFreeList(LockFreeList* lf) {
    size_t head = lf->head;
    while (lf->messages.empty() && !lf->head.compare_exchange_weak(&head, head + 1)) {}
    RFAPI_MESSAGE_T* message = &lf->messages[head];
    if (!message || message->payloadSize > MAX_PAYLOAD_SIZE) {
        // Handle allocation failure or payload size validation failures here.
    }
    return message;
}

void putMessageToLockFreeList(LockFreeList* lf, RFAPI_MESSAGE_T* message) {
    size_t tail = lf->tail;
    while (lf->messages.size() == MAX_LOCK_FREE_LIST_SIZE && !lf->tail.compare_exchange_weak(&tail, tail + 1)) {}
    lf->messages[tail] = *message;
}

void initMessages(int N, const char* logOutput) {
    LockFreeList lockFreeList;
    initLockFreeList(&lockFreeList);

    // Configure logging levels and output destinations based on logOutput parameter.

    std::atomic<unsigned int> successCount(0), failureCount(0);
    pthread_mutex_t statsLock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        RFAPI_MESSAGE_T* message = getNextMessageFromLockFreeList(&lockFreeList);
        if (!message) continue; // Skip if allocation failure.

        message->RX_UE_INFORMATION_TAG = generateUEInformationTag(); // Replace with your function to generate UE information tag.
        message->RNTI = generateRNTI(); // Replace with your function to generate RNTI.

        // Allocate payload buffer and validate its size here.

        putMessageToLockFreeList(&lockFreeList, message);
    }

    sem_post(&messageQueueSemaphore); // Signal the message queue system that messages are ready for processing.

    pthread_mutex_lock(&statsLock);
    printf("Message initialization success count: %u\n", successCount);
    printf("Message initialization failure count: %u\n", failureCount);
    pthread_mutex_unlock(&statsLock);
}
