pthread_mutex_t packets_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t new_packet_cond = PTHREAD_COND_INITIALIZER;
int num_packets = 0, num_errors = 0;
Packet packets[MAX_PACKETS];

void *packet_handler(void *arg) {
    while (true) {
        pthread_mutex_lock(&packets_mutex);
        // Wait for a new packet if none is available or all threads are waiting
        while (!num_packets && pthread_mutex_trylock(&new_packet_cond))
            pthread_cond_wait(&new_packet_cond, &packets_mutex);

        // If no packets were found, exit the loop
        if (!num_packets) {
            pthread_mutex_unlock(&packets_mutex);
            break;
        }

        Packet *packet = &packets[--num_packets];
        // Process packet and release lock
        process_packet(packet);
        pthread_mutex_unlock(&packets_mutex);
    }
}

void process_packet(Packet *packet) {
    // Trim and uppercase string fields, replace non-alphanumeric characters with underscores
    for (char **field = (char **)&packet->src; field <= (char *)&packet->protocol; ++field) {
        if (*field) {
            size_t len = strlen(*field);
            char *new_field = malloc(len + 1);
            memcpy(new_field, *field, len);
            for (size_t i = 0; i < len; ++i)
                new_field[i] = toupper((unsigned char)new_field[i]);
            new_field[len] = '\0';
            memmove(*field, new_field, strlen(new_field));
            free(new_field);
        }
    }

    // Handle any malformed packets here, e.g., by discarding them and incrementing num_errors
}

void add_packet(Packet *packet) {
    pthread_mutex_lock(&packets_mutex);
    if (num_packets < MAX_PACKETS) {
        memcpy(&packets[num_packets++], packet, sizeof(Packet));
        // Signal any waiting threads that a new packet is available
        pthread_cond_signal(&new_packet_cond);
    } else {
        free(packet); // Discard the packet and avoid memory leaks
    }
    pthread_mutex_unlock(&packets_mutex);
}
