[' Here is a simplified version of the requested C function using a custom hash table and pthread_mutex for thread-safety. Note that this code does not include unit tests, but you can write them separately. Also, it assumes the use of stdlib functions like `malloc`, `free`, `time`, and `rand`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    time_t timestamp;
} Record;

struct HashTable {
    unsigned long size;
    unsigned long capacity;
    Record** data;
    pthread_mutex_t lock;
};

unsigned long hash(const void* key) {
    const unsigned long m = 1e9 + 37;
    unsigned long h = (key % m);
    return h < m ? h : h - m;
}

Record* find_or_create(struct HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(&key) % table->size;
    Record* record = table->data[index];
    if (!record) {
        record = malloc(sizeof(Record));
        record->offset = 0;
        record->key = key;
        record->timestamp = time(NULL);
        table->data[index] = record;
    } else {
        Record* temp = record;
        while (temp->key != key) temp = temp->next;
        if (!temp->next) {
            temp->next = malloc(sizeof(Record));
            temp->next->offset = 0;
            temp->next->key = key;
            temp->next->timestamp = time(NULL);
        }
    }
    pthread_mutex_unlock(&table->lock);
    return record;
}

void check_memory_usage(struct HashTable* table, size_t budget) {
    size_t used_memory = 0;
    pthread_mutex_lock(&table->lock);
    for (unsigned long i = 0; i < table->size; ++i) {
        Record* record = table->data[i];
        while (record) {
            used_memory += sizeof(Record);
            record = record->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
    if (used_memory * 100 / budget >= 85) {
        printf("Warning: Memory usage reached 85% of the budget.\n");
    } else if (used_memory * 100 / budget > 90) {
        fprintf(stderr, "Critical error: Memory usage exceeded 90% of the budget.\n");
        exit(EXIT_FAILURE);
    }
}

void resize_table(struct HashTable* table, size_t new_capacity) {
    Record** old_data = table->data;
    table->size = new_capacity;
    table->capacity = new_capacity;
    table->data = calloc(new_capacity, sizeof(Record*));
    for (unsigned long i = 0; i < old_data->size; ++i) {
        Record* record = old_data[i];
        while (record) {
            Record* temp = record;
            record = record->next;
            find_or_create(table, temp->key);
            memcpy(temp, find_or_create(table, temp->key), sizeof(Record));
            free(temp);
        }
    }
    free(old_data);
}

void init_hash_table(struct HashTable* table, size_t initial_capacity) {
    table->size = initial_capacity;
    table->capacity = initial_capacity;
    table->data = calloc(initial_capacity, sizeof(Record*));
    if (table->data == NULL) {
        fprintf(stderr, "Error: Failed to initialize hash table.\n");
        exit(EXIT_FAILURE);
    }
    table->lock = PTHREAD_MUTEX_INITIALIZER;
}
```

You can use this function as follows:

```c
int main() {
    struct HashTable table;
    init_hash_table(&table, 10);

    const size_t budget = 10 * (1ULL << 20); // Set your desired memory budget here
    check_memory_usage(&table, budget);

    // Add records using predefined strings as keys
    char* strings[] = {"example1", "example2", "example3"};
    for (int i = 0; i < sizeof(strings) / sizeof(char*); ++i) {
        find_or_create(&table, atoi(strings[i]));
    }

    check_memory_usage(&table, budget);

    // Your code to handle memory usage and dynamic resizing here

    return 0;
}
```']

