    pthread_mutex_t lock; // Mutex for thread-safety
    queue_node_t* head; // Head of the queue
    queue_node_t* tail; // Tail of the queue
};
typedef struct thread_queue thread_queue_t;

thread_queue_t* create_queue() {
    thread_queue_t* queue = malloc(sizeof(thread_queue_t));
    if (!queue) {
        return NULL; // Handle error gracefully
    }
    sem_init(&queue->not_empty, 0, 0);
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = queue->tail = NULL;
    return queue;
}

