    node->data = data;
    node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->tail) {
        queue->tail->next = node;
        queue->tail = node;
    } else {
        queue->head = queue->tail = node;
    }
    sem_post(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU* dequeue(thread_queue_t* queue) {
    pthread_mutex_lock(&queue->lock);
