typedef struct {
    uint32_t timestamp;
    float value;
    char status;
} data_chunk;

struct memory_manager {
    size_t capacity;
    size_t num_elements;
    data_chunk* chunks;
    pthread_mutex_t mutex;
};

void init_memory_manager(struct memory_manager* manager, size_t max_capacity) {
    manager->capacity = max_capacity;
    manager->num_elements = 0;
    manager->chunks = malloc(max_capacity * sizeof(data_chunk));
    if (!manager->chunks) {
        perror("Memory allocation error");
        return;
    }
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void push_chunk(struct memory_manager* manager, data_chunk chunk) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->num_elements >= manager->capacity) {
        free(manager->chunks[0]); // Free the oldest element
        memmove(manager->chunks, &manager->chunks[1], sizeof(data_chunk) * --manager->num_elements);
    }

    manager->chunks[manager->num_elements++] = chunk;
    pthread_mutex_unlock(&manager->mutex);
}

// Function to generate a random float within the specified range
float randf(float min, float max) {
    return (rand()/(RAND_MAX+1.0))*(max-min)+min;
}

// Probability of generating a success or failure based on the given threshold
int probabalistic_success(double threshold) {
    return rand() / (RAND_MAX + 1.0) < threshold;
}

void* thread_func(void* arg) {
    struct memory_manager* manager = arg;

    while (true) {
        // Acquire the lock to prevent race conditions
        pthread_mutex_lock(&manager->mutex);

        data_chunk chunk;
        chunk.timestamp = time(NULL);
        chunk.value = randf(-100, 100);
        chunk.status = probabalistic_success(0.5) ? 'S' : 'F';

        push_chunk(manager, chunk);

        pthread_mutex_unlock(&manager->manager->mutex);
    }
}

void periodically_cleanup(struct memory_manager* manager, size_t interval_seconds) {
    // Implement a mechanism to periodically clean up unused 'struct data_chunk' objects
    // This example demonstrates using a sleep-and-check loop. You may want to use a more efficient method in production code.
    time_t now;
    while (true) {
        sleep(interval_seconds);
        pthread_mutex_lock(&manager->mutex);

        size_t i, j = 0;
        for (i = 0; i < manager->num_elements; ++i) {
            if (!is_chunk_recently_used(manager->chunks[i])) {
                data_chunk temp = manager->chunks[j++];
                memmove(&manager->chunks[i], &manager->chunks[j], sizeof(data_chunk) * (manager->num_elements - i));
                --manager->num_elements;
                free(temp);
            }
        }

        pthread_mutex_unlock(&manager->mutex);
    }
}
