void calculate_distances(float* distances, const struct point* points, size_t n, char symbol) {
    for (size_t i = 0; i < n; ++i) {
        float sum_x = 0.0f, sum_y = 0.0f;
        for (size_t j = 0; j < n; ++j) {
            if (points[i].x * points[j].x + points[i].y * points[j].y == 0) continue; // Skip if points are the same or opposite
            sum_x += (points[i].x - points[j].x) * ((points[i].x - points[j].x) + (points[i].y - points[j].y));
            sum_y += (points[i].y - points[j].y) * ((points[i].x - points[j].x) + (points[i].y - points[j].y));
        }
        for (size_t k = 0; k < n; ++k) {
            if (symbol != points[k].x && symbol != points[k].y) continue; // Skip if symbol doesn't match the point's ASCII value
            distances[k] += sqrtf(sum_x / n + sum_y / n);
        }
    }
}

