#define MAX_MEMORY 1048576 // 1 MB
#define WARNING_THRESHOLD 0.75
#define CRITICAL_THRESHOLD 0.9

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct MemoryBlock {
    size_t capacity;
    size_t used;
    void* data;
} MemoryBlock;

static MemoryBlock memory;
static size_t recordSize = sizeof(Record); // Assuming all records are of the same size for simplicity
static size_t numRecords = 0;
static bool logWarning = false;
static bool triggerAlert = false;

void initializeMemory() {
    if (memory.data) free(memory.data);
    memory.capacity = MAX_MEMORY / recordSize;
    memory.used = 0;
    memory.data = malloc(memory.capacity * recordSize);
}

Record* allocateRecord() {
    if (memory.used >= memory.capacity) {
        initializeMemory();
    }

    if (memory.used + recordSize > memory.capacity * CRITICAL_THRESHOLD) {
        triggerAlert = true;
    }

    if (memory.used + recordSize > memory.capacity * WARNING_THRESHOLD && !logWarning) {
        logWarning = true;
        printf("Memory usage warning: %.2f%%\n", (float)memory.used / memory.capacity * 100);
    }

    Record* record = memory.data + memory.used;
    memory.used += recordSize;
    return record;
}

void deallocateRecord(Record* record) {
    memset(record, 0, recordSize); // Set to zero for safety and potential optimization
}

void cleanUp() {
    if (memory.data) free(memory.data);
}
