typedef struct _MemoryManager {
    Record* records;
    size_t capacity;
    size_t used;
    size_t max_capacity;
    double warning_threshold;
    double critical_threshold;
} MemoryManager;

void init_memory_manager(MemoryManager* manager, size_t initial_capacity) {
    manager->records = calloc(initial_capacity, sizeof(Record));
    manager->capacity = initial_capacity;
    manager->used = 0;
    manager->max_capacity = initial_capacity;
    manager->warning_threshold = (double)manager->max_capacity * 0.75;
    manager->critical_threshold = (double)manager->max_capacity * 0.90;
}

void add_record(MemoryManager* manager, Record* record) {
    if (manager->used + 1 > manager->max_capacity) {
        manager->max_capacity *= 2;
        manager->records = realloc(manager->records, manager->max_capacity * sizeof(Record));
    }

    manager->records[manager->used++] = *record;
}

void delete_record(MemoryManager* manager, size_t index) {
    if (index >= manager->used || index < 0)
        return;

    free(manager->records[index].extra_data);
    memmove(&manager->records[index], &manager->records[index + 1], --manager->used * sizeof(Record));
}

void deallocate_memory_manager(MemoryManager* manager) {
    size_t i;
    for (i = 0; i < manager->used; ++i) {
        free(manager->records[i].extra_data);
    }
    free(manager->records);
}

void log_memory_usage(const MemoryManager* manager) {
    if (manager->used / (double)manager->max_capacity >= manager->warning_threshold)
        printf("Warning: Memory usage is at %f%%, consider increasing memory budget.\n", manager->used / (double)manager->max_capacity * 100.0);
    else if (manager->used / (double)manager->max_capacity >= manager->critical_threshold)
        printf("Critical: Memory usage is at %f%%, potential memory exhaustion.\n", manager->used / (double)manager->max_capacity * 100.0);
}
