        fprintf(stderr, "Error: Failed to map the file\n");
        fclose(file);
        return;
    }

    size_t numRecords = fileSize / AES_BLOCKSIZE;
    item **items = malloc(numRecords * sizeof(item*));
    int *keys = calloc(numRecords, sizeof(int));
    long *offsets = malloc((numRecords + 1) * sizeof(long));

    offsets[0] = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        AES_CBC_decrypt(&aesKey, records[i].data, records[i].data, iv, records[offsets[i] % (numRecords - 1)].data);

        item *item = malloc(sizeof(item));
        item->identifier = *(uint64_t*)records[i].data;
        item->value = *(double*)(records[i].data + sizeof(uint64_t));

        int currentKey = -1;
        for (int j = 0; j < i; ++j) {
            if (items[j]->identifier == item->identifier) {
                items[j]->value = item->value;
                currentKey = keys[j];
                break;
            }
            currentKey = keys[j];
        }

        if (currentKey == -1) {
            items[i] = item;
            keys[i] = currentKey + 1;
            offsets[i + 1] = offsets[i] + sizeof(item);
        } else {
            free(item);
        }
    }

    // Implement further functionalities such as adding new items, updating existing items, and freeing allocated memory here.

    munmap(records, fileSize);
    fclose(file);
}
