} LTE_RRCNAS_Message;

typedef struct Session {
    pthread_mutex_t mutex;
    int num_messages;
    size_t capacity;
    size_t length;
    LTE_RRCNAS_Message* messages;
} Session;

Session* create_session() {
    Session* session = malloc(sizeof(Session));
    pthread_mutex_init(&session->mutex, NULL);
    session->num_messages = 0;
    session->capacity = 1;
    session->length = 0;
    session->messages = calloc(session->capacity, sizeof(LTE_RRCNAS_Message));
    return session;
}

void resize_session(Session* session) {
    void* new_memory = realloc(session->messages, session->capacity * 2 * sizeof(LTE_RRCNAS_Message));
    if (new_memory != NULL) {
        session->messages = new_memory;
        session->capacity *= 2;
    } else {
        fprintf(stderr, "Failed to resize session\n");
        exit(EXIT_FAILURE);
    }
}

LTE_RRCNAS_Message* get_message(Session* session) {
    pthread_mutex_lock(&session->mutex);
    if (session->num_messages >= session->capacity) {
        resize_session(session);
    }
    LTE_RRCNAS_Message* message = &session->messages[session->length];
    memset(message, 0, sizeof(LTE_RRCNAS_Message));
    message->record.tv_sec = (long)time(NULL);
    message->record.tv_nsec = (long)time(NULL) * 1_000_000_000 + (long)nanoseconds();
    session->length++;
    pthread_mutex_unlock(&session->mutex);
    return message;
}

int is_duplicate(Session* session, LTE_RRCNAS_Message* candidate) {
    for (size_t i = 0; i < session->length; ++i) {
        if (session->messages[i].message_id == candidate->message_id &&
            session->messages[i].nas_transaction_id == candidate->nas_transaction_id &&
            memcmp(&session->messages[i].record, &candidate->record, sizeof(struct timespec)) == 0) {
            return true;
        }
    }
    return false;
}

LTE_RRCNAS_Message* generate_message(Session* session, enum NAS_Message_Type nas_message_type, uint32_t message_id, uint16_t security_algorithm_suite) {
    LTE_RRCNAS_Message* message = get_message(session);
    do {
        message->nas_message_type = nas_message_type;
        message->message_id = (uint32_t)(rand() * UINT32_MAX + 1); // Use XORShift RNG to minimize collisions
        message->security_algorithm_suite = security_algorithm_suite;
    } while (is_duplicate(session, message));
    return message;
}

void free_message(LTE_RRCNAS_Message* message) {
    // No-op in this implementation as memory is managed by the Session struct
}

void free_session(Session* session) {
    free(session->messages);
    free(session);
}
