// Function to dynamically allocate memory for arrays and records
void* init_arrays(size_t max_records, size_t range, size_t limit) {
    // Validate inputs
    if (max_records == 0 || range <= 0 || limit <= 0) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    long *offsets = mmap(NULL, max_records * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offsets == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    int *keys = malloc(max_records * sizeof(int));
    if (!keys) {
        perror("malloc failed");
        munmap(offsets, max_records * sizeof(long));
        return NULL;
    }

    struct record *records = malloc(max_records * sizeof(struct record));
    if (!records) {
        free(keys);
        munmap(offsets, max_records * sizeof(long));
        perror("malloc failed");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offsets, keys and records within specified limits
    for (size_t i = 0; i < max_records && limit > 0; ++i) {
        keys[i] = rand() % range;
        records[i].value = rand() % range;
        if (keys[i] >= limit) limit -= keys[i];
    }

    // Set the first element as an offset for the next array allocation
    offsets[0] = sizeof(long) + sizeof(int) * max_records + sizeof(struct record) * max_records;

    // Prepare the callback function to process records asynchronously
    process_callback process_func = <YOUR_ASYNCHRONOUS_PROCESSING_FUNCTION>;

    // Process each record asynchronously within the limit
    for (size_t i = 0; i < max_records && limit > 0; ++i) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, process_func, &records[i])) {
            perror("pthread_create failed");
            free(keys);
            munmap(offsets, max_records * sizeof(long));
            free(records);
            return NULL;
        }
        limit--;
    }

    return &mutex;
}
