void trim_and_sanitize(char* str) {
    char* start = str;
    while (*str && *str == ' ') ++str;
    if (*str) strcpy(start, str);
    size_t len = strlen(start);
    for (size_t i = len - 1; i > 0; --i) {
        if (!isalnum(start[i])) start[i] = '\0';
        else break;
    }
    for (char* cur = start, *next = start + strlen(cur); cur < next; ++cur) {
        if (*cur >= 'A' && *cur <= 'Z') *cur += ('a' - 'A');
    }
}

NFAPI_RRC_CONTAINER_T* nfapi_rrc_container_create(size_t capacity) {
    NFAPI_RRC_CONTAINER_T* container = malloc(sizeof(NFAPI_RRC_CONTAINER_T));
    if (!container) return NULL;
    container->list = calloc(capacity, sizeof(NFAPI_RRC_DATA));
    if (!container->list) {
        free(container);
        return NULL;
    }
    container->capacity = capacity;
    container->size = 0;
    sem_init(&container->mutex, 0, 1);
    sem_init(&container->notifier, 0, 0);
    return container;
}

void nfapi_rrc_container_destroy(NFAPI_RRC_CONTAINER_T* container) {
    if (!container) return;
    free(container->list);
    sem_destroy(&container->mutex);
    sem_destroy(&container->notifier);
    free(container);
}

void nfapi_rrc_data_transform(NFAPI_RRC_DATA* data) {
    if (!data || !data->config.measurementReports || !data->config.bandwidthParts) return;
    for (size_t i = 0, len = sizeof(data->config.measurementReports) / sizeof(data->config.measurementReports[0]); i < len; ++i) {
        trim_and_sanitize((char*)&data->config.measurementReports[i].reportType);
        trim_and_sanitize((char*)&data->config.measurementReports[i].reportValue);
    }
    for (size_t i = 0, len = sizeof(data->config.bandwidthParts) / sizeof(data->config.bandwidthParts[0]); i < len; ++i) {
        trim_and_sanitize((char*)&data->config.bandwidthParts[i].bandwidthPartID);
    }
}

void nfapi_rrc_container_add(NFAPI_RRC_CONTAINER_T* container, const NFAPI_RRC_DATA* data) {
    if (!container || !data) return;

    sem_wait(&container->mutex);

    if (container->size >= container->capacity) {
        // handle overflow - resize the container or implement a queue system.
    }

    memcpy(container->list + container->size, data, sizeof(NFAPI_RRC_DATA));
    nfapi_rrc_data_transform(container->list + container->size);
    ++container->size;
    sem_post(&container->mutex);
    sem_post(&container->notifier);
}

void nfapi_rrc_container_remove(NFAPI_RRC_CONTAINER_T* container, size_t index) {
    if (!container || index >= container->size) return;

    sem_wait(&container->mutex);

    if (index < container->size - 1) memmove(container->list + index, container->list + index + 1, (container->size - index - 1) * sizeof(NFAPI_RRC_DATA));
    --container->size;
    sem_post(&container->mutex);
    sem_post(&container->notifier);
}

void nfapi_rrc_container_notify(NFAPI_RRC_CONTAINER_T* container) {
    if (!container) return;
    sem_wait(&container->notifier);
    sem_post(&container->notifier);
}

NFAPI_RRC_DATA* nfapi_rrc_container_get(const NFAPI_RRC_CONTAINER_T* container, size_t index) {
    if (!container || index >= container->size) return NULL;

    sem_wait(&container->mutex);
    NFAPI_RRC_DATA* data = container->list + index;
    sem_post(&container->mutex);
    nfapi_rrc_data_transform(data);
    return data;
}
```
