typedef struct {
    long offset;
    int key;
    int is_compressed;
    void* data; // Either uncompressed or compressed record data
} record;

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t num_records = 0;
record* uncompressed_data = NULL;
record* compressed_data = NULL;
int* metadata_flags = NULL;
long* offsets = NULL;
int* keys = NULL;
char delimiter = ','; // Default to comma as delimiter
z_stream stream;

void csv_read(const char* filename, int compression_flag) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    char c, prev_c = '\n';
    size_t record_count = 0;

    // Initialize decompression stream
    inflateInit2(&stream, MAX_WBITS + 16 + MAX_MEM_LEVELS);

    while ((c = fgetc(file)) != EOF) {
        if (prev_c == delimiter && c != delimiter) {
            record_count++;
        }
        prev_c = c;
    }

    rewind(file);

    pthread_mutex_lock(&memory_lock);

    num_records = record_count;
    uncompressed_data = (record*)realloc(uncompressed_data, num_records * sizeof(record));
    compressed_data = (record*)realloc(compressed_data, num_records * sizeof(record));
    metadata_flags = (int*)calloc(num_records, sizeof(int));
    offsets = (long*)calloc(num_records + 1, sizeof(long));
    keys = (int*)calloc(num_records, sizeof(int));

    pthread_mutex_unlock(&memory_lock);

    size_t record_index = 0;
    int current_compression = compression_flag;

    while ((c = fgetc(file)) != EOF) {
        if (prev_c == delimiter && c != delimiter) {
            // Read offset and key values
            fscanf(file, "%ld%d", &offsets[record_index], &keys[record_index]);

            // Read compression flag
            char compress_char;
            if (fscanf(file, ",%c", &compress_char) != 1) {
                fprintf(stderr, "Error reading comma or compression flag: %s\n", filename);
                break;
            }
            current_compression = compress_char == 'y' || compress_char == 'Y';

            // Read record value (uncompressed)
            int random_value = rand() % 1000000; // Modify this range as needed
            if (current_compression) {
                // Decompress data using zlib library
                stream.next_in = &random_value;
                stream.avail_in = 1;
                char decompressed_data[4];
                stream.next_out = decompressed_data;
                stream.avail_out = sizeof(decompressed_data);
                inflate(&stream, Z_SYNC_FLUSH);
                uncompressed_data[record_index].data = malloc(stream.total_out);
                memcpy(uncompressed_data[record_index].data, decompressed_data, stream.total_out);
            } else {
                uncompressed_data[record_index].data = &random_value;
            }

            // Set compression flag and increment record index
            compressed_data[record_index].is_compressed = current_compression;
            record_index++;
        }
        prev_c = c;
    }

    fclose(file);
    inflateEnd(&stream);

    // Update offset and key arrays for the last record
    offsets[record_index] = ftell(file);
    keys[record_index - 1] = rand() % 1000000;
}

