#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    long *offset;
    int key;
    int active;
} Record;

void init_memory(size_t *arr_long, size_t *arr_int, Record **records, size_t *capacity, size_t *length) {
    *arr_long = malloc(*capacity * sizeof(long));
    *arr_int = malloc(*capacity * sizeof(int));
    *records = calloc(*capacity, sizeof(Record));
    *length = 0;
}

void custom_hash(char str[], int *hash) {
    for (size_t i = 0; i < strlen(str); ++i)
        *hash = (*hash << 5) + *(*hash + 1) + (*str++);
}

int compare_keys(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

void free_memory(size_t arr_long, size_t arr_int, size_t num_records) {
    free((void*)arr_long);
    free((void*)arr_int);
    free((void*)records);
}

void mark_inactive(Record *records, size_t num_records, int condition) {
    for (size_t i = 0; i < num_records; ++i) {
        if (condition(records[i].key))
            records[i].active = 0;
    }
}

void init_data(size_t capacity, size_t *arr_long, size_t *arr_int, Record **records, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < capacity; ++i) {
        records[i].offset = arr_long + i;
        records[i].key = *arr_int + i;
        *arr_int += 1;
        records[i].active = 1;
    }

    for (size_t i = 0; i < capacity; ++i)
        (*arr_long)[i] = rand() % (max - min + 1) + min;

    qsort(*records, capacity, sizeof(Record), compare_keys);
}

int main(void) {
    size_t arr_long_capacity = 100;
    size_t arr_int_capacity = 100;
    Record *records;
    size_t arr_long_length = 0;
    size_t arr_int_length = 0;

