#pragma once
#include <deque>
#include <mutex>
#include <memory>

template<typename T>
class SafeDeque {
private:
    std::deque<T> deq;
    std::mutex mutex;
public:
    void push_back(const T& item) {
        std::unique_lock<std::mutex> lock(mutex);
        deq.push_back(item);
    }

    const T& front() {
        std::unique_lock<std::mutex> lock(mutex);
        return deq.front();
    }

    void pop_front() {
        std::unique_lock<std::mutex> lock(mutex);
        deq.pop_front();
    }
};

class ListManager {
