2. **Data Caching (Cache.h/.cpp)**

```cpp
#pragma once
#include <unordered_map>
#include <mutex>

template<typename T>
class LruCache {
private:
    int capacity;
    std::unordered_map<T, int> cache;
    std::unordered_map<T, T> data;
    std::mutex mutex;
    int currentSize = 0;
public:
    explicit LruCache(int capacity) : capacity(capacity) {}

    T get(const T& key) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.count(key)) {
            int& accessCount = cache[key];
            data[key] = doGet(key);
            ++accessCount;
            auto it = cache.begin();
            std::advance(it, currentSize - capacity);
            for (; it != cache.end(); ) {
                if (--accessCount[it->first] <= 0) {
                    data.erase(it->first);
                    cache.erase(it);
                    ++it;
                }
                else break;
            }
            currentSize = cache.size();
            return data[key];
        }
        return T();
    }

    virtual T doGet(const T& key) const = 0;
};
```

