int processAndAnalyzeItemCollection(const char *filename, const unsigned char *key, const unsigned char *iv, int padding) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return 1;
    }

    size_t len = filesize(file);
    if (strlen(filename) > 100 || strlen(filename + len - 3) < 3 || strlen(filename + len - 3) > 4) {
        fprintf(stderr, "Invalid filename format\n");
        fclose(file);
        return 2;
    }

    char *ext = filename + len - 3;
    if (strcmp(ext, ".txt") != 0 && strcmp(ext, ".log") != 0) {
        fprintf(stderr, "Invalid file extension\n");
        fclose(file);
        return 2;
    }

    char new_filename[10 + len];
    snprintf(new_filename, sizeof(new_filename), "%.*s%0*d.%s", (int)strlen(filename), filename, (int)ceil((len - 3) / 2.), getpid(), ext);

    void *data = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (data == MAP_FAILED) {
        fprintf(stderr, "Error mapping memory: %s\n", strerror(errno));
        fclose(file);
        return 1;
    }

    AES_KEY aes_key;
    AES_set_encrypt_key(key, padding, &aes_key);
    unsigned char *decrypted = malloc(len);
    if (!AES_cbc_decrypt((const unsigned char*)data, decrypted, len, &aes_key, iv, NULL)) {
        fprintf(stderr, "Error during AES decryption: %s\n", ERR_get_error());
        free(decrypted);
        munmap(data, len);
        fclose(file);
        return 1;
    }

    size_t offset = 0;
    size_t num_items = 0;
    item *items = malloc(sizeof(item));
    int *keys = malloc(sizeof(int));
    long *offsets = malloc(sizeof(long));

    for (size_t i = 0; i < len; ) {
        const size_t record_len = *(const uint32_t*)(decrypted + i);
        if (!record_len) break;

        const size_t item_offset = offset + i;
        const size_t key_index = (size_t)(*(const int*)(decrypted + i + sizeof(uint32_t)));

        if (key_index >= num_items) {
            keys = realloc(keys, ++num_items * sizeof(int));
            items = realloc(items, ++num_items * sizeof(item));
            offsets = realloc(offsets, ++num_items * sizeof(long));
        }

        keys[key_index] = (int)(*(const int*)(decrypted + i + sizeof(uint32_t) + sizeof(int)));
        items[key_index].identifier = *(const uint64_t*)(decrypted + i + sizeof(uint32_t) + sizeof(int) * 2);
        items[key_index].value = *(const double*)(decrypted + i + sizeof(uint32_t) + sizeof(int) * 3);

        offsets[key_index] = item_offset;
        i += record_len;
    }

    // Process the items, ensuring uniqueness of identifiers...

    free(decrypted);
    munmap(data, len);
    fclose(file);

    return 0;
}
