public byte[] GenerateFilename(byte[] data) {
    // Calculate the length of the original file name
    int len = data.Length - 3;

    // Calculate the number of digits and ensure it doesn't exceed 10
    int numDigits = (len > 6) ? (len / 2 + 1) : (len + 1);
    if (numDigits > 10) {
        numDigits = 10;
    }

    // Generate a new filename based on the given criteria
    StringBuilder builder = new StringBuilder();
    builder.Append(new string(data, 0, len));
    builder.AppendFormat("{0:D{1}}", getpid(), numDigits);
    builder.Append(new string(data, data.Length - 3, 3));

    return System.Text.Encoding.ASCII.GetBytes(builder.ToString());
}
