// Structure for a record
struct Record {
    uint64_t timestamp;
    int key;
    int field;
    long offset;
};

// Custom memory pool allocator
class MemoryPool {
private:
    static constexpr size_t MEMORY_BUDGET = 1048576; // 1 MB
    static constexpr double CRITICAL_THRESHOLD = 0.95;
    static constexpr int MIN_RECORDS = 128;
    static vector<Record> pool;
    static mutex mtx;
    static int seed;

public:
    // Initialize the memory pool with initial records and set the random seed
    static void init() {
        auto now = chrono::steady_clock::now().count();
        seed = now;
        pool.reserve(MIN_RECORDS);
        for (int i = 0; i < MIN_RECORDS; ++i) {
            Record r;
            r.timestamp = now;
            r.key = hash<string>()(to_string(i));
            pool.push_back(r);
        }
    }

    // Allocate a record from the memory pool
    static Record* allocate() {
        if (pool.empty()) {
            resize();
        }
        unique_lock<mutex> lock(mtx);
        Record* r = &pool.back();
        pool.pop_back();
        r->offset = nextOffset();
        return r;
    }

    // Free a record back to the memory pool
    static void free(Record* r) {
        unique_lock<mutex> lock(mtx);
        r->key = hash<string>()(to_string(pool.size()));
        pool.push_back(*r);
    }

private:
    // Hash function for keys
    static long nextOffset() {
        return hash<int>()(hash<string>()(to_string(thread::get_id())) ^ seed++) % MEMORY_BUDGET;
    }

    // Periodically check memory usage and log a warning if it exceeds 95% of the budget, and raise an error if it exceeds the critical threshold
    static void resize() {
        static thread checker([]() {
            while (true) {
                this_thread::sleep_for(chrono::seconds(10));
                if ((double)pool.size() / MEMORY_BUDGET > CRITICAL_THRESHOLD) {
                    cerr << "Memory usage exceeded critical threshold!" << endl;
                    abort();
                } else if ((double)pool.size() / MEMORY_BUDGET > 0.9) {
                    cerr << "Warning: Memory usage has reached 95% of the budget." << endl;
                }
            }
        });
        checker.detach();
    }
};

// Helper function to validate a JSON string representing an OAuth2 access token response
bool validateAccessTokenResponse(const json& j) {
    if (!j.is_object()) {
        return false;
    }
    auto it = j.find("access_token");
    if (it == j.end()) {
        return false;
    }
    if (it->second.empty() || it->second.type() != json::value_t::string) {
        return false;
    }
    it = it->second.find("expires_in");
    if (it == j.end()) {
        return false;
    }
    if (it->second.type() != json::value_t::number_unsigned) {
        return false;
    }
    int expiresIn = it->second.get<int>();
    if (expiresIn <= 0 || !j.count("token_type")) {
        return false;
    }
    if (j["token_type"] != "Bearer") {
        return false;
    }
    // Optional refresh_token field
    json::const_iterator refreshTokenIt = j.find("refresh_token");
    if (refreshTokenIt != j.end() && refreshTokenIt->second.type() != json::value_t::string) {
        return false;
    }
    return true;
}

// Main function to manage memory for an array of records
void manageRecords(vector<Record*>& records, const vector<string>& keys) {
    MemoryPool::init();
    for (const auto& key : keys) {
        Record* r = MemoryPool::allocate();
        r->key = hash<string>()(key);
        r->field = rand() % 100; // Random field value
        records.push_back(r);
    }
}
