#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    double value;
} Record;

struct MemoryMonitor {
    size_t total_allocated;
    size_t limit;
    time_t last_check;
};

void* randomize(void* arg) {
    Record* record = (Record*)arg;
    const int min_val = 100;
    const int max_val = 999;
    record->key = rand() % (max_val - min_val + 1) + min_val;
    return NULL;
}

void* load_data(const char* filename, size_t* offsets, size_t* keys, double* values, size_t* records, struct MemoryMonitor* monitor) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    size_t line_num = 0;
    enum FileType { CSV, BINARY } file_type = CSV; // Set based on configuration

    void* buffer;
    size_t buffer_size = 4096;
    size_t total_read = 0;

    pthread_t thread_id;
    Record record;

    while (1) {
        size_t read = fread(&buffer, 1, buffer_size, file);
        if (feof(file)) break;
        total_read += read;

        if (file_type == CSV && line_num == 0) { // Skip header row in CSV format
            line_num++;
            continue;
        }

        if (read < buffer_size) {
            buffer_size = read + 1;
        }

        pthread_create(&thread_id, NULL, randomize, &record);
        pthread_join(thread_id, NULL);

        offsets[line_num] = total_read - buffer_size;
        keys[line_num] = record.key;
        values[line_num] = record.value;
        records[line_num++] += 1;

        if (monitor->total_allocated + sizeof(Record) > monitor->limit * 0.8) {
            printf("Warning: Memory usage exceeded 80% of the limit\n");
        }
        monitor->total_allocated += sizeof(Record);
    }

    fclose(file);
    free(buffer);
    return records;
}

size_t* initialize_data(const char* filename, size_t memory_limit_mb, int min_val, int max_val) {
    struct MemoryMonitor monitor = { .total_allocated = 0, .limit = memory_limit_mb * (1024 * 1024), .last_check = time(NULL) };
    size_t offsets[500000], keys[500000], values[500000];
    size_t records[1] = { 0 };

    load_data(filename, offsets, keys, values, records, &monitor);

    // Release all allocated memory when the function completes
    free(values);
    free(keys);
    free(offsets);

    return records;
}
```

This code defines a function that initializes three arrays and an array of record structures, reads data from an external binary file (or CSV file, depending on the configuration), handles potential I/O errors, ensures data integrity, monitors memory usage, and supports thread-safety. The function dynamically allocates memory based on a specified limit and initializes each 'record' structure with a random number within a specified range using a seed generated from the current time in microseconds.

To optimize for both small and large datasets, the buffer size is adjusted dynamically during data loading. The function also provides a mechanism to release all allocated memory when the function completes. Keep in mind that this code snippet only serves as an outline and requires proper error handling, testing, and integration with your larger system.']

