    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, strlen(data));
    MD5_Final(digest, &ctx);
    return *((int*)digest);
}

int establishConnection(int id) {
    int socketDescriptor;
    const char* server[] = {"127.0.0.1", "example.com"}; // Define your server configurations here
    struct sockaddr_in serverAddress;

    if ((socketDescriptor = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        logError("Socket creation error");
        return -1;
    }

    memset(&serverAddress, 0, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(80); // Define the port number here
    inet_pton(AF_INET, server[id % 2], &serverAddress.sin_addr);

    if (connect(socketDescriptor, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) == -1) {
        logError("Connection error");
        close(socketDescriptor);
        return -1;
    }

    dataChannels[id].socketDescriptor = socketDescriptor;
    return 0;
}

int main() {
    initArrays();

    srandom((unsigned)time(NULL));

    for (size_t i = 0; i < MAX_USERS; ++i) {
        records[0][i] = i * sizeof(long);
        records[1][i] = random() % 100 + 1;

        dataChannels[i].id = i;
        dataChannels[i].buffer = malloc(BUFFER_LIMIT);
        dataChannels[i].refCount = 0;
        checkMemory();
    }

    for (size_t i = 0; i < MAX_USERS; ++i) {
        int hash = md5sum((char*)&dataChannels[i].id);
        char handshakeData[64] = {0}; // Define the initial handshake data here
