    void (*process)(void*, const char*);
} worker_t;

typedef struct task {
    int id;
    enum { FILE, STRING } type;
    union {
        char* filepath;
        char* str;
    };
    char* result;
    size_t size;
    pthread_mutex_t lock;
} task_t;

