pthread_cond_t memory_cond;
size_t total_memory = 0;

void* task_queue(void* arg) {
    // Implement priority-based scheduling and dequeuing tasks here
}

void* worker(void* data) {
    worker_t* w = data;
    while (1) {
        pthread_mutex_lock(&w->queue->lock);
        task_t* t = pthread_queue_pop(w->queue);
        pthread_mutex_unlock(&w->queue->lock);

        if (!t) break; // Exit the worker loop if no more tasks are available

        // Process the task and store the result in 't->result'
        w->process(t, t->type == FILE ? t->file : t->str);
    }

    free(w->queue);
    free(w);
    return NULL;
}

void submit_task(enum task_type type, const char* data, size_t size) {
    if (total_memory + size > 0.7 * getpagesize() * (1LL << 20)) // 70% of the system's total available memory
        fprintf(stderr, "Warning: Memory usage is close to the threshold.\n");

    for (int i = 0; i < MAX_TASKS; ++i) {
        if (!tasks[i].id && total_memory + tasks[i].size <= 0.7 * getpagesize() * (1LL << 20)) {
            tasks[i].id = tasks_count++;
            tasks[i].type = type;
            tasks[i].size = size;

            switch (type) {
                case FILE:
                    tasks[i].file = strdup(data);
                    break;
                case STRING:
                    tasks[i].str = strdup(data);
                    break;
            }

            pthread_mutex_init(&tasks[i].lock, NULL);
            total_memory += size;

            worker_t* w = &workers[tasks[i].id - 1];
            void** queue_ptr = &w->queue;

            // Acquire the memory lock to ensure exclusive access to memory management
            pthread_mutex_lock(&memory_lock);

            if (!*queue_ptr) { // Allocate and initialize a task queue if needed
                *queue_ptr = malloc(sizeof(pthread_queue_t));
                pthread_queue_init(*queue_ptr);
            }

            pthread_mutex_unlock(&memory_lock);

            pthread_queue_push(*queue_ptr, &tasks[i]);
        }
    }
}

