typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

void init_log(const char *filename) {
    FILE *log = fopen(filename, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
    }
}

bool read_crcflag(uint32_t *crcflag) {
    int fd = open(CRCFLAG_FILE, O_RDONLY);
    if (fd == -1) return false;

    struct stat file_stat;
    if (fstat(fd, &file_stat) == -1) {
        close(fd);
        return false;
    }

    void *buf = malloc(file_stat.st_size);
    if (!buf) {
        close(fd);
        return false;
    }

    ssize_t bytes_read = read(fd, buf, file_stat.st_size);
    if (bytes_read != file_stat.st_size) {
        free(buf);
        close(fd);
        return false;
    }

    *crcflag = *(uint32_t *)buf;
    free(buf);
    close(fd);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* init_structures(size_t n) {
    if (n > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Number of structures exceeds the maximum allowed value.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!structures) {
        fprintf(stderr, "Error: Failed to allocate memory for structures.\n");
        return NULL;
    }

    uint32_t crcflag = 0;
    if (!read_crcflag(&crcflag)) {
        free(structures);
        return NULL;
    }

    init_log("init.log");

    for (size_t i = 0; i < n; ++i) {
        structures[i].rx_ue_info = (RX_UE_INFORMATION_TAG){ .value = i };
        structures[i].rnti = i * 13;
        structures[i].crc_indication.value = crcflag ^ i;
        fprintf(init_log, "Initialized structure %lu with RNTI: %u and CRCFLAG: %u\n", i, structures[i].rnti, structures[i].crc_indication.value);
    }

    return structures;
}
