#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <semaphore.h>
#include <stdbool.h>
#include <string.h>
#include "user_session.h" // Custom user session management system header

typedef struct {
    pid_t thread_id;
    time_t creation_time;
    char title[MAX_TITLE_LENGTH];
    int key;
    void (*callback)(void*);
    size_t payload_size;
    char *payload;
    session_t session;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    sem_t lock;
    pthread_mutex_t data_lock;
    record *data;
} record_list;

record_list* create_record_list(size_t capacity) {
    record_list *list = malloc(sizeof(record_list));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    sem_init(&list->lock, 0, 1);
    pthread_mutex_init(&list->data_lock, NULL);
    list->capacity = capacity;
    list->count = 0;
    list->data = calloc(capacity, sizeof(record));
    if (!list->data) {
        perror("Failed to allocate memory for data array");
        free(list);
        return NULL;
    }

    return list;
}

void destroy_record_list(record_list* list) {
    sem_destroy(&list->lock);
    pthread_mutex_destroy(&list->data_lock);
    free(list->data);
    free(list);
}

int add_record_to_list(record_list *list, char *title, int key, void (*callback)(void*), size_t payload_size, char *payload, session_t session) {
    if (!list || !title || !payload || strlen(title) >= MAX_TITLE_LENGTH || !callback || payload_size > MAX_PAYLOAD_SIZE || session.id == NULL || strlen(session.id) <= 0) {
        return -1; // Invalid arguments
    }

    if (list->count == list->capacity) {
        // Trim the oldest entries to make space for new ones
        size_t oldest_index = 0;
        sem_wait(&list->lock);
        pthread_mutex_lock(&list->data_lock);

        time_t current_time = time(NULL);
        for (size_t i = 0; i < list->capacity; ++i) {
            if (current_time - list->data[i].creation_time > SESSION_TIMEOUT) {
                // Session has expired, remove the record from the list
                free(list->data[oldest_index].payload);
                free(list->data[oldest_index]);
                memmove(&list->data[i], &list->data[i+1], (list->count - i - 1) * sizeof(record));
                --list->count;
            } else if (current_time - list->data[i].creation_time > list->data[oldest_index].creation_time) {
                oldest_index = i;
            }
        }
        pthread_mutex_unlock(&list->data_lock);
        sem_post(&list->lock);
    }

    // Add new record to the list
    record *new_record = realloc(list->data + list->count, ((list->count+1) * sizeof(record)));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        return -1; // Memory allocation failure
    }

    sem_wait(&list->lock);
    pthread_mutex_lock(&list->data_lock);

    new_record[list->count].thread_id = getpid();
    new_record[list->count].creation_time = time(NULL);
    strcpy(new_record[list->count].title, title);
    new_record[list->count].key = key;
    new_record[list->count].callback = callback;
    new_record[list->count].payload_size = payload_size;
    new_record[list->count].payload = malloc(payload_size);
    if (!new_record[list->count].payload) {
        perror("Failed to allocate memory for record's payload");
        free(new_record + list->count);
        sem_post(&list->lock);
        pthread_mutex_unlock(&list->data_lock);
        return -1; // Memory allocation failure
    }
    memcpy(new_record[list->count].payload, payload, payload_size);
    new_record[list->count].session = session;

    ++list->count;

    pthread_mutex_unlock(&list->data_lock);
    sem_post(&list->lock);

    return 0; // Success
}

// Other necessary functions for reading, updating, and removing records from the list, logging, and handling other requirements
