#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h> // for posix_memalign
#include <pthread.h>
#include <zlib.h> // optional: for decompression

typedef struct { float x, y; } Point;
typedef enum StatusType { LOW, MEDIUM, HIGH } StatusType;
typedef enum LogLevel { INFO, WARNING, ERROR, DEBUG } LogLevel;
typedef struct Event { time_t timestamp, priority; StatusType status; } Event;
typedef struct LogEntry { char message[256]; time_t timestamp; LogLevel level; } LogEntry;

void json_load(const char *filename, size_t *array_sizes, void **arrays, int compress) {
    gzFile fp = compress ? gzdopen(fopen(filename, "rb"), zlib_decompress) : fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    size_t allocated = 0;
    size_t max_entries = 50 * 1000 * 1000; // up to 50 million records

    double *doubles = NULL;
    char *strings = NULL;
    Point *points = NULL;
    Event *events = NULL;
    LogEntry *log_entries = NULL;

    LogEntry entry;
    time_t start = time(NULL), end = start + 86400; // timestamp range validation

    while (fread(&entry, sizeof(LogEntry), 1, fp) > 0 && allocated < max_entries) {
        if (entry.timestamp < start || entry.timestamp >= end) continue;

        size_t new_allocated = allocated + 1;
        if (!posix_memalign((void **)&doubles, 64, sizeof(double)*new_allocated)) {
            doubles += new_allocated - allocated;
            allocated = new_allocated;
        } else {
            fprintf(stderr, "Out of memory\n");
            break;
        }

        if (!posix_memalign((void **)&strings, 64, sizeof(char)*MAX_STRING_LENGTH*new_allocated)) {
            strings += new_allocated * MAX_STRING_LENGTH;
        } else {
            fprintf(stderr, "Out of memory\n");
            break;
        }

        if (!posix_memalign((void **)&points, 16, sizeof(Point)*new_allocated)) {
            points += new_allocated;
        } else {
            fprintf(stderr, "Out of memory\n");
            break;
        }

        if (!posix_memalign((void **)&events, 16, sizeof(Event)*new_allocated)) {
            events += new_allocated;
        } else {
            fprintf(stderr, "Out of memory\n");
            break;
        }

        if (!posix_memalign((void **)&log_entries, 16, sizeof(LogEntry)*new_allocated)) {
            log_entries += new_allocated;
        } else {
            fprintf(stderr, "Out of memory\n");
            break;
        }

        // Truncate message and assign values to arrays
        strncpy(strings + allocated * MAX_STRING_LENGTH, entry.message, MAX_STRING_LENGTH);
        doubles[allocated] = entry.timestamp;
        points[allocated].x = entry.level;
        points[allocated].y = entry.timestamp; // This assumes the timestamp is the y coordinate for Point struct
        events[allocated].timestamp = entry.timestamp;
        events[allocated].priority = (entry.level < INFO) ? LOW : MEDIUM;
        events[allocated].status = (entry.level >= DEBUG) ? HIGH : MEDIUM;
        log_entries[allocated] = entry;

        printf("[LOG ENTRY] Timestamp: %ld, Level: %d, Message: %.*s\n",
               entry.timestamp, (int)entry.level, (int)MAX_STRING_LENGTH, strings + allocated * MAX_STRING_LENGTH);
    }

    if (compress) gzclose(fp); else fclose(fp);

    pthread_mutex_destroy(&mutex);
    array_sizes[0] = doubles ? allocated : 0;
    array_sizes[1] = strings ? allocated * MAX_STRING_LENGTH : 0;
    array_sizes[2] = points ? allocated : 0;
    array_sizes[3] = events ? allocated : 0;
    array_sizes[4] = log_entries ? allocated : 0;

    if (doubles) munmap(doubles, sizeof(double)*allocated);
    if (strings) munmap(strings, MAX_STRING_LENGTH*allocated);
    if (points) munmap(points, sizeof(Point)*allocated);
    if (events) munmap(events, sizeof(Event)*allocated);
    if (log_entries) munmap(log_entries, sizeof(LogEntry)*allocated);
}
```
