struct NFAPI_MESSAGE_T {
    int RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
};

struct NR_RRCNAS_Message {
    NAS_Message_Type nas_message_type;
    Message_ID message_id;
    Security_Algorithm_Suite security_algorithm_suite;
    NAS_Transaction_ID nas_transaction_id;
    std::vector<NFAPI_MESSAGE_T> payload;
};

class MemoryPool {
public:
    MemoryPool(size_t capacity) : buffer_(std::make_unique<char[]>(capacity)), cur_pos_(buffer_.get()) {}
    char* allocate(size_t size) {
        if (cur_pos_ + size > buffer_.get() + buffer_->size()) throw std::runtime_error("Memory exhaustion");
        auto start = cur_pos_;
        cur_pos_ += size;
        return start;
    }
    void deallocate(char* ptr) {
        if (ptr < buffer_.get() || ptr >= cur_pos_) throw std::runtime_error("Invalid pointer");
        cur_pos_ = ptr;
    }
private:
    std::unique_ptr<char[]> buffer_;
    char* cur_pos_;
};

class RRCNAS {
public:
    RRCNAS(size_t maxMessages) : session_(std::make_unique<NR_RRCNAS_Message>()), msgIdGen_(0), pool_(maxMessages * sizeof(NR_RRCNAS_Message)), capacity_(maxMessages) {}
    void addMessage(const NFAPI_MESSAGE_T& payload, const NAS_Transaction_ID& transaction_id) {
        auto it = messages_.find(transaction_id);
        if (it != messages_.end()) {
            it->second.payload.emplace_back(payload);
            return;
        }

        session_->nas_transaction_id = transaction_id;
        session_->message_id = ++msgIdGen_;
        session_->security_algorithm_suite = generateSecurityAlgorithmSuite();
        session_->payload.emplace_back(payload);

        messages_[transaction_id] = std::move(*session_);
    }

    void reportSentMessages() const {
        int count = 0;
        for (const auto& msg : messages_) {
            count += msg.second.payload.size();
        }
        std::cout << "Total number of messages sent: " << count << "\n";
    }

private:
    Security_Algorithm_Suite generateSecurityAlgorithmSuite() const {
        // Implement your unique suite generation logic here
    }

    void checkMemoryUsage() const {
        if (static_cast<double>(pool_.used_memory()) / pool_.max_size() > 0.75) {
            std::cerr << "Error: Memory usage exceeded 75% of the allocated budget\n";
        }
    }

    static std::mt19937 seedGen;
    std::unique_ptr<NR_RRCNAS_Message> session_;
    int msgIdGen_;
    MemoryPool pool_;
    size_t capacity_;
    std::map<NAS_Transaction_ID, NR_RRCNAS_Message> messages_;
};

std::mt19937 RRCNAS::seedGen(static_cast<unsigned int>(std::time(0)));
