typedef struct {
    double size;
    char *filename;
    time_t modification_time;
} file_info;

file_info* read_directory(char *path, size_t *num_files) {
    DIR *dir = opendir(path);
    if (!dir) {
        perror("Failed to open directory");
        exit(1);
    }

    struct dirent *entry;
    size_t num_entries = 0;
    file_info *file_infos = NULL;

    while ((entry = readdir(dir)) != NULL) {
        num_entries++;
    }

    rewinddir(dir);

    file_infos = malloc(num_entries * sizeof(file_info));
    if (!file_infos) {
        perror("Failed to allocate memory for file_infos");
        closedir(dir);
        exit(1);
    }

    size_t i = 0;
    while ((entry = readdir(dir)) != NULL) {
        struct stat st;
        char filepath[1024];
        strcpy(filepath, path);
        strcat(filepath, "/");
        strcat(filepath, entry->d_name);

        if (lstat(filepath, &st) == -1) {
            perror("Failed to get file stats");
            closedir(dir);
            free(file_infos);
            exit(1);
        }

        file_infos[i].size = st.st_size;
        file_infos[i].filename = strdup(entry->d_name);
        file_infos[i].modification_time = st.st_mtime;
        i++;
    }

    closedir(dir);
    *num_files = num_entries;
    return file_infos;
}

void free_file_info(file_info *file_infos, size_t num_files) {
    for (size_t i = 0; i < num_files; ++i) {
        free(file_infos[i].filename);
    }
    free(file_infos);
