    if (!file_paths) {
        perror("Failed to allocate memory for file paths");
        free(large_doubles);
        free_file_info(file_infos, num_files);
        exit(1);
    }

    struct file_info **file_infos_ptrs = malloc(num_files * sizeof(struct file_info*));
    if (!file_infos_ptrs) {
