#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <atomic>

typedef struct {
    char identifier[256];
    double value;
} StructElement;

typedef struct {
    StructElement* elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    std::atomic<bool> resize_needed{ false };
} DataStruct;

DataStruct double_data, char_data, struct_data;

void resize(DataStruct* ds) {
    if (ds->resize_needed.load()) {
        size_t new_capacity = ds->capacity * 2;
        StructElement* new_array = (StructElement*)realloc(ds->elements, new_capacity * sizeof(StructElement));
        if (!new_array) {
            printf("Out of memory\n");
            return;
        }
        memmove(&new_array[ds->count], ds->elements + ds->count, (ds->capacity - ds->count) * sizeof(StructElement));
        ds->elements = new_array;
        ds->capacity *= 2;
        ds->resize_needed.store(false);
    }
}

bool add_identifier(DataStruct* ds, const char* identifier) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (!strcmp(ds->elements[i].identifier, identifier)) {
            return false;
        }
    }

    pthread_mutex_lock(&ds->lock);
    resize(ds);
    strcpy(ds->elements[ds->count].identifier, identifier);
    ds->count++;
    pthread_mutex_unlock(&ds->lock);

    return true;
}

bool find_and_update(DataStruct* ds, const char* identifier, double value) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (!strcmp(ds->elements[i].identifier, identifier)) {
            ds->elements[i].value = value;
            return true;
        }
    }
    return false;
}

void insert_batch(DataStruct* ds, size_t count, StructElement* elements) {
    pthread_mutex_lock(&ds->lock);
    resize(ds);
    memcpy(ds->elements + ds->count, elements, count * sizeof(StructElement));
    ds->count += count;
    pthread_mutex_unlock(&ds->lock);
}

// External dependencies for logging and configuration management
void log_event(const char* message) { ... } // Replace with actual function call

void init() {
    double_data.elements = NULL;
    char_data.elements = NULL;
    struct_data.elements = NULL;

    double_data.capacity = 10;
    char_data.capacity = 10;
    struct_data.capacity = 10;

    double_data.count = 0;
    char_data.count = 0;
    struct_data.count = 0;

    pthread_mutex_init(&double_data.lock, NULL);
    pthread_mutex_init(&char_data.lock, NULL);
    pthread_mutex_init(&struct_data.lock, NULL);
}
