<?php

class PasswordUpdater {
    private $identityProviders;
    private $passwordValidator;
    private $cache;
    private $db;
    private $logger;
    private $rateLimiter;

    public function __construct(
        array $identityProviders,
        PasswordValidator $passwordValidator,
        Cache $cache,
        Database $db,
        Logger $logger,
        RateLimiter $rateLimiter
    ) {
        $this->identityProviders = $identityProviders;
        $this->passwordValidator = $passwordValidator;
        $this->cache = $cache;
        $this->db = $db;
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->rateLimiter->canUpdatePassword()) {
            throw new TooManyRequestsException();
        }

        $cacheKey = 'password_update:' . $userId;
        if ($this->cache->has($cacheKey)) {
            return $this->cache->get($cacheKey); // Return cached result, if available
        }

        try {
            $authenticatedUser = $this->authenticate($userId);
            $validPassword = $this->validatePasswordStrength($newPassword);

            if (!$validPassword) {
                throw new InvalidPasswordException();
            }

            $this->db->beginTransaction();

            try {
                $this->updateUserPassword($authenticatedUser, $newPassword);
                $this->notifyAlternativeUpdateChannels($authenticatedUser);
                $this->db->commit();

                $this->cache->save($cacheKey, true, 600); // Cache result for future requests
                return true;
            } catch (\Exception $e) {
                $this->db->rollback();

                if ($e instanceof TransientErrorException) {
                    sleep(pow(2, $e->getRetryAttempt())); // Exponential backoff
                    return $this->updatePassword($userId, $newPassword);
                }

                throw $e;
            }
        } catch (\Exception $e) {
            $this->logger->logError($e->getMessage());
            throw new UnxpectedErrorException();
        }
    }

    private function authenticate($userId) {
        foreach ($this->identityProviders as $provider) {
            try {
                return $provider->authenticate($userId);
            } catch (\Exception $e) {
                // Handle provider specific errors and continue with next provider
            }
        }

        throw new AuthenticationFailedException();
    }

    private function validatePasswordStrength($newPassword) {
        return $this->passwordValidator->validate($newPassword);
    }

    private function updateUserPassword($user, $newPassword) {
        // Update user password in database using the given user object and new password
    }

    private function notifyAlternativeUpdateChannels($user) {
        // Send email or SMS notifications to user for alternative password update options
    }
}
