```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/types.h>
#include <time.h>

typedef struct file_info {
    double size;
    char *filename;
    time_t modification_time;
} FileInfo;

void* process_file(void *arg);
sem_t sem;

int main() {
    DIR *dir = opendir("."); // Current directory
    struct dirent *entry;
    double *numbers, *file_sizes;
    char **file_paths, **file_names;
    FileInfo *files;
    int num_files = 0, i;

    sem_init(&sem, 0, MAXTHREADS); // Set the maximum number of threads here

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        struct stat st;
        stat(entry->d_name, &st);

        // Skip directories and other non-regular files
        if (S_ISDIR(st.st_mode))
            continue;

        num_files++;
    }
    rewinddir(dir); // Rewind the directory stream for counting all entries

    numbers = malloc(num_files * sizeof(double));
    file_sizes = malloc(num_files * sizeof(double));
    file_paths = malloc(num_files * sizeof(char*));
    file_names = malloc(num_files * sizeof(char*));
    files = malloc(num_files * sizeof(FileInfo));

    int thread_ids[MAXTHREADS];

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        struct stat st;
        stat(entry->d_name, &st);

        // Skip directories and other non-regular files
        if (S_ISDIR(st.st_mode))
            continue;

        file_paths[num_files - 1] = strdup(entry->d_name);
        pthread_t thread_id;
        thread_ids[num_files - 1] = num_files - 1;
        pthread_create(&thread_id, NULL, process_file, &thread_ids);
        num_files--;
    }
    closedir(dir);

    for (i = 0; i < num_files; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    // Process the collected file information and clean up memory

    free(numbers);
    free(file_sizes);
    free(file_paths);
    free(file_names);
    free(files);
    return 0;
}

void* process_file(void *arg) {
    int thread_id = *(int *)arg;
    struct dirent *entry;
    double size;
    char path[1024], name[1024];

    DIR *dir = opendir("."); // Current directory
    strncpy(path, ".", sizeof(path));
    strncat(path, "/", sizeof(path) - strlen(path));
    strncpy(name, file_paths[thread_id], sizeof(name));

    sem_wait(&sem); // Acquire the semaphore before accessing shared resources

    struct stat st;
    if (stat(path, &st)) {
        printf("Error reading path %s\n", path);
        free(file_paths[thread_id]);
        return NULL;
    }

    size = st.st_size;
    strcpy(files[thread_id].filename, name);
    files[thread_id].modification_time = st.st_mtime;
    files[thread_id].size = size;

    sem_post(&sem); // Release the semaphore after updating the shared resource
}
```

