#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "log_metrics.h" // External dependency for logging and metrics tracking

typedef struct {
    char name[64];
    enum config_type type;
    void* params;
    pthread_mutex_t lock;
} Config;

typedef struct {
    int id;
    Config* config;
    int* dependencies;
    size_t num_dependencies;
    pthread_mutex_t lock;
} Task;

static Config* configs = NULL;
static size_t num_configs = 0;
static size_t config_capacity = 16;
static size_t config_threshold = 32;

static Task* tasks = NULL;
static size_t num_tasks = 0;
static size_t task_capacity = 16;
static size_t task_threshold = 32;

void config_add(const char* name, enum config_type type, void* params) {
    if (num_configs >= config_capacity) {
        reallocate_configs();
    }

    pthread_mutex_init(&configs[num_configs].lock, NULL);

    strcpy(configs[num_configs].name, name);
    configs[num_configs].type = type;
    configs[num_configs].params = params;

    size_t i;
    for (i = 0; i < num_configs; ++i) {
        if (strcmp(configs[i].name, name) == 0) {
            log_error("Duplicate configuration name: %s", name);
            free(params);
            return;
        }
    }

    ++num_configs;
}

void task_add(int id, Config* config, int* dependencies, size_t num_dependencies) {
    if (num_tasks >= task_capacity) {
        reallocate_tasks();
    }

    pthread_mutex_init(&tasks[num_tasks].lock, NULL);

    tasks[num_tasks].id = id;
    tasks[num_tasks].config = config;
    tasks[num_tasks].dependencies = dependencies ? malloc(num_dependencies * sizeof(int)) : NULL;
    if (dependencies) {
        memcpy(tasks[num_tasks].dependencies, dependencies, num_dependencies * sizeof(int));
    }
    tasks[num_tasks].num_dependencies = num_dependencies;

    task_mark_as_dependent(id, dependencies, num_dependencies);
    ++num_tasks;
}

Config* find_config_by_name(const char* name) {
    size_t i;
    for (i = 0; i < num_configs; ++i) {
        if (strcmp(configs[i].name, name) == 0) {
            return &configs[i];
        }
    }
    return NULL;
}

void update_config_params(const char* name, void* params) {
    Config* config = find_config_by_name(name);
    if (config != NULL) {
        pthread_mutex_lock(&config->lock);
        free(config->params);
        config->params = params;
        pthread_mutex_unlock(&config->lock);
    }
}

void reallocate_configs() {
    if (num_configs >= config_threshold) {
        size_t new_capacity = config_capacity * 2;
        Config* temp = realloc(configs, new_capacity * sizeof(Config));
        if (!temp) {
            log_error("Out of memory while resizing config array");
            return;
        }
        configs = temp;
        memset(&configs[config_capacity], 0, (new_capacity - config_capacity) * sizeof(Config));
        config_capacity = new_capacity;
    }
}

void reallocate_tasks() {
    if (num_tasks >= task_threshold) {
        size_t new_capacity = task_capacity * 2;
        Task* temp = realloc(tasks, new_capacity * sizeof(Task));
        if (!temp) {
            log_error("Out of memory while resizing task array");
            return;
        }
        tasks = temp;
        memset(&tasks[task_capacity], 0, (new_capacity - task_capacity) * sizeof(Task));
        task_capacity = new_capacity;
    }
}

void task_mark_as_dependent(int id, int* dependencies, size_t num_dependencies) {
    // Implement thread-safe dependency tracking by iterating through tasks with locks
    pthread_mutex_lock(&tasks[id].lock);
    Task* task = &tasks[id];
    if (task->dependencies) {
        size_t i;
        for (i = 0; i < num_dependencies; ++i) {
            Task* dependent = find_task_by_id(dependencies[i]);
            if (dependent != NULL) {
                pthread_mutex_lock(&dependent->lock);
                // Add dependency between the tasks by incrementing the number of dependencies for both tasks
                ++dependent->num_dependencies;
                pthread_mutex_unlock(&dependent->lock);
            }
        }
    }
    pthread_mutex_unlock(&task->lock);
}
```

