#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/sockio.h>
#include <net/if.h>
#include <string.h>

typedef struct {
    int rnti;
    uint32_t qos;
    int sockfd;
} Session;

void configure_qos(int sockfd, uint32_t dscp) {
    // Set DSCP value for QoS
    char buf[256];
    struct ifreq ifr;
    snprintf(buf, sizeof(buf), "/dev/net/tun%d", sockfd);
    strcpy(ifr.ifr_name, buf);
    ioctl(sockfd, SIOCETHTOOL, &ifr);
    ifr.ifr_ifru.ieee80211_key.dsoc = htons((uint16_t)(dscp << 3));
    ioctl(sockfd, SIOCS80211TXQOS, &ifr);
}

int init_session(int *n_sessions, int *socket_array, int *rnti) {
    if (*n_sessions >= UINT16_MAX / sizeof(Session)) {
        perror("Too many sessions");
        return -1;
    }

    Session *session = &((Session*)socket_array)[*n_sessions];
    session->rnti = *rnti++;
    session->qos = 0; // Default QoS value
    session->sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_RAW);
    if (session->sockfd == -1) {
        perror("Error creating socket");
        return -1;
    }

    configure_qos(session->sockfd, session->qos);
    *n_sessions += 1;

    return 0;
}

void release_resources(int sockfd) {
    close(sockfd);
}

// Function to handle session disconnection gracefully
bool handle_disconnect(int *socket_array, int *n_sessions, int rnti) {
    for (size_t i = 0; i < *n_sessions; ++i) {
        if (((Session*)socket_array)[i].rnti == rnti) {
            release_resources(((Session*)socket_array)[i].sockfd);
            memmove(&((Session*)socket_array)[i], &((Session*)socket_array)[*n_sessions-1], sizeof(Session));
            *n_sessions -= 1;
            return true;
        }
    }
    return false;
}
```']

