#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

struct memory_monitor {
    size_t allocated_bytes;
    size_t limit_bytes;
    double warning_threshold;
};

void* read_csv(const char *filename, struct memory_monitor *memory_monitor) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t line_size = 0;
    char *line = NULL;
    ssize_t read;

    int keys = 0;
    long offsets[100000]; // Assume this is enough for your use case
    record data[100000];

    while ((read = getdelim(&line, &line_size, ',', file)) != EOF) {
        pthread_mutex_lock(&lock);
        if (memory_monitor->allocated_bytes + (size_t)(read+1) > memory_monitor->limit_bytes * 0.75) {
            fprintf(stderr, "Warning: Memory usage exceeded 75% of allocated budget\n");
        }
        memory_monitor->allocated_bytes += read + sizeof(long) + sizeof(record);
        pthread_mutex_unlock(&lock);

        sscanf(line, "%ld,%*[^\n]\n", &offsets[keys]);
        data[keys].value = rand() % 100; // Modify this to your desired range
        keys++;
    }

    free(line);
    fclose(file);
    pthread_mutex_destroy(&lock);

    return malloc(sizeof(long) * keys + sizeof(record) * keys);
}

void memory_monitor_init(struct memory_monitor *memory_monitor, size_t limit_bytes) {
    memory_monitor->allocated_bytes = 0;
    memory_monitor->limit_bytes = limit_bytes;
    memory_monitor->warning_threshold = (double)memory_monitor->limit_bytes * 0.75;
}

void memory_monitor_log() {
    printf("Total allocated memory: %.2f MB\n", (float)memory_monitor->allocated_bytes / (1024 * 1024));
}
