['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

struct DataManager {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t used;
};

void generateFilename(char *base, char *extension, char *output) {
    size_t len = strlen(base);
    strncpy(output, strrev(strchr(base, '.') + 1), len - (strlen(base) - len)); // Extract last part before dot
    sprintf(output + strlen(output), "%d", (int)(strlen(output) + 5)); // Add leading zeros based on length
    strcat(output, extension);
    strrev(output); // Reverse the entire string
}

struct DataManager *createDataManager(size_t memoryLimitMB) {
    struct DataManager *dm = malloc(sizeof(struct DataManager));
    dm->capacity = memoryLimitMB * (1024 * 1024); // Convert MB to bytes
    dm->used = 0;
    dm->offsets = calloc((dm->capacity / sizeof(long)), sizeof(long));
    dm->keys = calloc((dm->capacity / sizeof(int)), sizeof(int));
    dm->records = malloc(sizeof(Record) * (dm->capacity / sizeof(Record)));

    pthread_mutex_init(&dm->mutex, NULL);
    return dm;
}

void destroyDataManager(struct DataManager *dm) {
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->mutex);
    free(dm);
}

int readCSVFile(FILE *file, struct DataManager *dm) {
    int key;
    long offset;
    Record record;
    while (fscanf(file, "%ld,%d,%*[^\n]", &offset, &key) == 2) {
        if (dm->used + sizeof(long) + sizeof(int) + sizeof(Record) > dm->capacity - dm->used)
            return -1; // Memory exceeded
        dm->offsets[dm->used] = offset;
        dm->keys[dm->used] = key;
        record.value = rand() % 100 + 1; // Random value within range (1-100)
        memcpy(&(dm->records[dm->used]), &record, sizeof(Record));
        dm->used += sizeof(long) + sizeof(int) + sizeof(Record);
    }
    return 0;
}

void* loadData(void *dataManagerVoid) {
    struct DataManager *dm = (struct DataManager *)dataManagerVoid;
    char filename[256];
    generateFilename("data", "csv", filename); // Generate a new filename
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: Unable to open file\n");
        return NULL;
    }
    int error = readCSVFile(file, dm);
    fclose(file);
    if (error < 0) {
        printf("Error: Memory limit exceeded\n");
        return NULL;
    }
    return NULL;
}

void monitorMemoryUsage(struct DataManager *dm) {
    static time_t lastMonitor = 0;
    time_t currentTime = time(NULL);
    if (currentTime - lastMonitor >= 5) {
        double memoryUsage = ((double) dm->used / (double) dm->capacity) * 100.0;
        if (memoryUsage > 75.0)
            printf("Warning: Memory usage exceeded 75% of the limit\n");
        lastMonitor = currentTime;
    }
}
```

This code provides a basic implementation for the given task. It creates a `DataManager` struct to handle the data and includes functions for creating, destroying, loading data into it, and monitoring memory usage. The function to generate a new filename is also implemented. Keep in mind that this code does not include thread synchronization when multiple threads are accessing the data simultaneously, which should be handled by using appropriate locking mechanisms like pthread_mutex_lock() and pthread_mutex_unlock(). Also, error handling may need further refinement depending on specific use cases.']

