#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h> // for malloc_usable_size() and mmap()

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int *ids;
    double *values;
    struct record *records;
    size_t num_elements;
    sem_t lock; // Fine-grained locks for each record set
} NFAPI_CRC_INDICATION_PDU_T;

// Lock-free memory pool management
typedef struct mem_block {
    void *data;
    size_t size;
    struct mem_block *next;
} MemBlock;

void init_mem_pool(MemBlock **head, size_t initial_size) {
    if (*head) return;

    *head = malloc(sizeof(MemBlock));
    if (!*head) return;
    memset(*head, 0, sizeof(**head));

    (*head)->data = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (MAP_FAILED == (*head)->data) {
        free(*head);
        *head = NULL;
        return;
    }

    (*head)->size = initial_size;
}

void* mem_pool_alloc(MemBlock **head, size_t size) {
    MemBlock *current = *head;
    void *result = NULL;

    while (current != NULL && current->next != NULL) {
        if (current->next->size >= size) {
            result = current->next->data;
            current->next->size -= size;
            current->next = current->next->next;
            break;
        }
        current = current->next;
    }

    if (!result) {
        MemBlock *new_block = malloc(sizeof(MemBlock));
        if (MAP_FAILED == new_block) return NULL;

        new_block->size = size;
        new_block->data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (MAP_FAILED == new_block->data) {
            free(new_block);
            return NULL;
        }

        if (*head) {
            new_block->next = *head;
            *head = new_block;
        } else {
            *head = new_block;
        }

        result = new_block->data;
    }

    return result;
}

// Thread-safe processing function
void process_record(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t index) {
    // Convert string representations to uppercase, trim leading or trailing whitespace, and replace non-alphanumeric characters with underscores
    char temp[1024];
    strncpy(temp, pdus[index]->crc_indication.string_representation, sizeof(temp));
    for (size_t i = 0; temp[i] != '\0'; ++i) {
        if (!isalnum(temp[i])) {
            temp[i] = '_';
        }
    }
    strcpy(pdus[index]->crc_indication.string_representation, temp);

    // Generate CRC flag
    pdus[index]->crc_indication.CRCFLAG = (rand() % 2) ? 1 : 0;
}

// Function to create and manage the NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRHC_INDICATION_PDU_T* create_pdu_list(size_t num_pdus) {
    if (num_pdus > 100) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (!pdus) return NULL;

    MemBlock mem_pool_head;
    init_mem_pool(&mem_pool_head.next, 1048576); // 1 MB for large datasets

    pthread_t threads[num_pdus];
    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].ids = mem_pool_alloc(&mem_pool_head.next, sizeof(int) * 10);
        pdus[i].values = mem_pool_alloc(&mem_pool_head.next, sizeof(double) * 10);
        pdus[i].records = calloc(10, sizeof(struct record));
        sem_init(&pdus[i].lock, 0, 1);
    }

    // Parallelize processing using pthreads
    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_create(&threads[i], NULL, process_record, &pdus[i]);
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup and deallocate memory resources
    free(mem_pool_head.next);
    free(pdus);

    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
}
