#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char *description;
    int priority;
    struct task *next;
} Task;

typedef struct {
    time_t timestamp;
    Task *task;
} Event;

typedef struct {
    size_t capacity;
    size_t head;
    size_t tail;
    Event events[1024]; // Adjust capacity as needed
} CircularBuffer;

CircularBuffer cb;
Task *taskListHead = NULL;
Event *eventQueue = NULL;

void init() {
    cb.capacity = 1024;
    cb.head = cb.tail = 0;
    taskListHead = NULL;
}

Task* createTask(char *description, int priority) {
    Task *task = malloc(sizeof(Task));
    if (!task) return NULL;
    task->description = description;
    task->priority = priority;
    task->next = NULL;
    return task;
}

Event* createEvent(Task *task) {
    Event *event = malloc(sizeof(Event));
    if (!event) return NULL;
    event->timestamp = time(NULL);
    event->task = task;
    return event;
}

void enqueueEvent(Event *event) {
    // Handle edge case: null pointers and overflow condition in the eventQueue
    if (event == NULL || eventQueue == NULL) return;

    // Double the capacity of the event queue when it reaches its limit
    if ((cb.head + 1) % cb.capacity == cb.tail) {
        Event *newQueue = realloc(eventQueue, sizeof(Event) * (2 * cb.capacity));
        if (!newQueue) return;
        eventQueue = newQueue;
        cb.capacity *= 2;
    }

    // Insert the event into the queue at the end
    event->next = eventQueue + (cb.tail + 1) % cb.capacity;
    eventQueue[cb.tail] = event;
    cb.tail = (cb.tail + 1) % cb.capacity;
}

void log(const char *message) {
    // Handle edge case: overflow condition in the circular buffer
    if (cb.head == ((cb.tail + 1) % cb.capacity)) return;

    cb.events[cb.head].timestamp = time(NULL);
    cb.events[cb.head].message = message;
    cb.head = (cb.head + 1) % cb.capacity;
}

void processTasks() {
    Task *currentTask = taskListHead;
    while (currentTask != NULL) {
        // Process the current task, populating the event queue and circular buffer
        log(currentTask->description);
        enqueueEvent(createEvent(currentTask));

        // Advance to the next task in the linked list
        Task *nextTask = currentTask->next;
        free(currentTask);
        currentTask = nextTask;
    }
}
