#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_STRUCTURES 200
#define BUFFER_SIZE (2 * 1024 * 1024) // 2 MB

typedef struct log_entry {
    time_t timestamp;
    int severity_level;
    char* message;
} log_entry;

struct log_manager {
    log_entry* structures;
    size_t used;
    size_t capacity;
    pthread_mutex_t mutex;
};

void trim(char* str) {
    char* start = str;
    for (; *str != '\0'; ++str) {}
    for (str--; str >= start && *str == ' '; --str) {}
    memmove(start, str, sizeof(*start));
    *(start + strlen(start)) = '\0';
}

int random(int max) {
    return rand() % max;
}

char* generate_message() {
    static const char* events[] = { "System Restart", "Disk Space Low", "Network Error" };
    return strdup(events[random(3)]);
}

void sanitize(char** str, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (*(*str + i) >= 'a' && *(*str + i) <= 'z') {
            *(*str + i) -= 32;
        } else if (*(*str + i) >= 'A' && *(*str + i) <= 'Z' || *(*str + i) >= '0' && *(*str + i) <= '9' || *(*str + i) == '_') {
            // Valid character, do nothing
        } else {
            **str = '_';
        }
    }
    (*str)[len] = '\0';
}

struct log_manager* create_log_manager() {
    struct log_manager* manager = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (manager == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    struct log_manager m = { .structures = manager, .used = 0, .capacity = BUFFER_SIZE / sizeof(log_entry), .mutex = PTHREAD_MUTEX_INITIALIZER };
    return &m;
}

void destroy_log_manager(struct log_manager* manager) {
    munmap(manager->structures, manager->capacity);
}

int add_log_entry(struct log_manager* manager, const char* timestamp, int severity, const char* message) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->used + 1 > manager->capacity / MAX_STRUCTURES) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // No more space available
    }

    log_entry* entry = (log_entry*)((char*)manager->structures + manager->used * sizeof(log_entry));

    time(&entry->timestamp);
    entry->severity_level = severity;

    size_t len = strlen(message) + 1;
    entry->message = (char*)((char*)manager->structures + manager->used * sizeof(log_entry)) + sizeof(log_entry);
    trim(message);
    sanitize(&entry->message, len);
    memcpy(entry->message, message, len);

    ++manager->used;
    pthread_mutex_unlock(&manager->mutex);

    // Periodically check memory usage and log a warning if it exceeds 70% of the allocated budget
    if ((double)manager->used / manager->capacity > 0.7) {
        printf("Warning: Memory usage is at %.2f%%\n", (double)manager->used / manager->capacity * 100);
    }

    return 0; // Successful addition
}

void run_log_manager(struct log_manager* manager) {
    while (true) {
        for (int i = 0; i < MAX_STRUCTURES; ++i) {
            char timestamp[32], message[128];
            snprintf(timestamp, sizeof(timestamp), "%ld", manager->structures[i].timestamp);
            snprintf(message, sizeof(message), "%s (%d): %s", timestamp, manager->structures[i].severity_level, manager->structures[i].message);
            printf("%s\n", message);
        }

        // Sleep for a random amount of time to simulate varying input sizes and potential data corruption
        usleep(random(1000000));
    }
}

int main() {
    struct log_manager* manager = create_log_manager();
    pthread_t thread;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        add_log_entry(manager, "", random(5), generate_message());
    }

    pthread_create(&thread, NULL, run_log_manager, manager);

    while (true) {} // Keep the main thread running to prevent program termination
}
