["```python
import argparse
import json
import os
from concurrent.futures import ThreadPoolExecutor
import logging

def parse_json(filepath):
    try:
        with open(filepath, 'r') as f:
            data = json.load(f)
            # Your custom JSON event extraction logic here
            event_type = data['event']['type']
            return event_type
    except FileNotFoundError:
        logging.error(f'File not found: {filepath}')
    except json.JSONDecodeError:
        logging.error(f'Malformed JSON: {filepath}')

def summarize_events(event_types, min_frequency):
    event_freq = {}
    for event in event_types:
        if event not in event_freq:
            event_freq[event] = 0
        event_freq[event] += 1
    frequent_events = {k: v for k, v in event_freq.items() if v >= min_frequency}
    return frequent_events

def process_directory(directory, output_file):
    logging.info(f'Processing directory: {directory}')
    event_types = []
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.json'):
                event_types.append(parse_json(os.path.join(root, file)))
    return summarize_events(event_types, min_frequency)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('directories', nargs='*', help='Directories or comma-separated paths containing JSON log files')
    parser.add_argument('--help', action='store_true', help='Display comprehensive usage and examples')
    parser.add_argument('-s', dest='summary_threshold', type=int, default=3, help='Summarize only the most frequent event types, excluding less common ones (default: 3)')
    parser.add_argument('-o', '--output_file', type=str, help='Specify an output file to save the processed results')
    parser.add_argument('-v', action='store_true', help='Enable verbose mode for detailed logging')
    args = parser.parse_args()

    if args.help:
        parser.print_help()
        return

    logging.basicConfig(level=logging.DEBUG if args.v else logging.INFO)

    results = {}

    with ThreadPoolExecutor() as executor:
        for directory in args.directories or ['.']:  # If no directories are provided, process current directory
            future = executor.submit(process_directory, directory, args.output_file)
            results[directory] = future.result()

    if args.output_file:
        with open(args.output_file, 'w') as f:
            json.dump(results, f, indent=2)

if __name__ == '__main__':
    main()
```

