#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct item {
    int identifier;
    char descriptor;
    float value;
};

struct collection {
    int id_capacity, id_size;
    int *ids;

    size_t desc_capacity, desc_size;
    char *descriptors;
    pthread_mutex_t desc_lock;

    size_t items_capacity, items_size;
    struct item *items;
    pthread_mutex_t items_lock;
};

struct collection *create_collection() {
    struct collection *coll = malloc(sizeof(struct collection));
    coll->id_capacity = 10;
    coll->id_size = 0;
    coll->ids = calloc(coll->id_capacity, sizeof(int));

    coll->desc_capacity = 256;
    coll->descriptors = malloc(coll->desc_capacity);
    pthread_mutex_init(&coll->desc_lock, NULL);

    coll->items_capacity = 10;
    coll->items = calloc(coll->items_capacity, sizeof(struct item));
    pthread_mutex_init(&coll->items_lock, NULL);
    return coll;
}

void resize_descriptors(struct collection *coll) {
    if (coll->desc_size == coll->desc_capacity) {
        coll->desc_capacity *= 2;
        coll->descriptors = realloc(coll->descriptors, coll->desc_capacity);
    }
}

bool unique_descriptor(struct collection *coll, char descriptor) {
    for (size_t i = 0; i < coll->desc_size; ++i) {
        if (coll->descriptors[i] == descriptor) {
            return false;
        }
    }
    return true;
}

bool find_descriptor(struct collection *coll, char descriptor, size_t *index) {
    pthread_mutex_lock(&coll->desc_lock);
    for (size_t i = 0; i < coll->desc_size; ++i) {
        if (coll->descriptors[i] == descriptor) {
            *index = i;
            pthread_mutex_unlock(&coll->desc_lock);
            return true;
        }
    }
    pthread_mutex_unlock(&coll->desc_lock);
    return false;
}

void insert(struct collection *coll, int id, char descriptor, float value) {
    if (coll->id_size == coll->id_capacity) {
        coll->id_capacity *= 2;
        coll->ids = realloc(coll->ids, coll->id_capacity * sizeof(int));
    }

    resize_descriptors(coll);

    if (!unique_descriptor(coll, descriptor)) {
        return;
    }

    coll->ids[coll->id_size] = id;
    coll->descriptors[coll->desc_size] = descriptor;

    pthread_mutex_lock(&coll->items_lock);
    if (coll->items_size == coll->items_capacity) {
        coll->items_capacity *= 2;
        coll->items = realloc(coll->items, coll->items_capacity * sizeof(struct item));
    }

    struct item *item = &coll->items[coll->items_size];
    item->identifier = id;
    item->descriptor = descriptor;
    item->value = value;
    ++coll->items_size;
    pthread_mutex_unlock(&coll->items_lock);
}

bool update(struct collection *coll, char descriptor, float value) {
    size_t index;
    if (!find_descriptor(coll, descriptor, &index)) {
        return false;
    }

    pthread_mutex_lock(&coll->items_lock);
    struct item *item = &coll->items[index];
    item->value = value;
    pthread_mutex_unlock(&coll->items_lock);

    return true;
}
```

