// Memory pool for efficient allocation and deallocation of NFAPI_MESSAGE_T structures.
typedef struct MemPool {
    size_t capacity;
    size_t count;
    NFAPI_MESSAGE_T *buf;
} MemPool;

MemPool mempool;

// Hash table for quick lookups of `Message_ID` uniqueness.
tbb::concurrent_hash_map<Message_ID, bool> message_ids;

// Queue-based mechanism to manage the processing order of messages.
tbb::priority_queue<NR_RRCNAS_Message> message_queue;

// Session structure.
struct Session {
