// Custom memory pool initialization.
void mempool_init(size_t capacity) {
    mempool.capacity = capacity;
    mempool.count = 0;
    mempool.buf = mmap(NULL, capacity * sizeof(NFAPI_MESSAGE_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

// Custom memory pool allocation.
NFAPI_MESSAGE_T* mempool_alloc() {
    if (mempool.count < mempool.capacity) {
        return mempool.buf + mempool.count++;
    }
    void *temp = mmap(NULL, mempool.capacity * sizeof(NFAPI_MESSAGE_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (temp == MAP_FAILED) {
        return NULL;
    }
    memcpy(temp, mempool.buf, mempool.capacity * sizeof(NFAPI_MESSAGE_T));
    mempool.buf = temp;
    mempool.count = 0;
    return mempool.buf + mempool.count++;
}

// Custom memory pool deallocation.
void mempool_dealloc(NFAPI_MESSAGE_T *ptr) {
    if (ptr >= mempool.buf && ptr < mempool.buf + mempool.capacity) {
        --mempool.count;
        return;
    }
    munmap(mempool.buf, mempool.capacity * sizeof(NFAPI_MESSAGE_T));
}

// Function to create a new session and return its ID.
int create_session(size_t max_messages) {
    Session *session = calloc(1, sizeof(Session));
    if (!session) {
        return 0;
    }
    pthread_mutex_init(&session->session_mutex, NULL);
    session->session_id = -1;
    session->num_messages = 0;
    session->max_messages = max_messages;
    session->messages = calloc(max_messages, sizeof(NR_RRCNAS_Message));
    if (!session->messages) {
        free(session);
        return 0;
    }

    // Initialize the memory pool for NFAPI_MESSAGE_T structures.
    mempool_init(1024);

    return session->session_id = ++global_session_count;
}

// Function to send a message to the specified session.
void send_message(int session_id, const NAS_Message_Type nas_message_type, const Message_ID message_id, const uint32_t security_algorithm_suite, const NAS_Transaction_ID transaction_id, const size_t payload_size, const char *payload) {
    Session *session = get_session(session_id);
    if (!session) {
        return;
    }

    pthread_mutex_lock(&session->session_mutex);

    // Validate the payload size against predefined limits.
    if (payload_size > MAX_PAYLOAD_SIZE) {
        pthread_mutex_unlock(&session->session_mutex);
        return;
    }

    // Ensure no two messages in the same session have the same `Message_ID`.
    if (message_ids.find(message_id)) {
        pthread_mutex_unlock(&session->session_mutex);
        return;
    }

    // Calculate a uniquely generated `Security_Algorithm_Suite` for the message.
    session->current_security_algorithm_suite = (session->current_security_algorithm_suite + 1) % SESSION_SECURITY_ALGORITHM_SUITE_MODULO;

    NR_RRCNAS_Message *msg = mempool_alloc();
    if (!msg) {
        pthread_mutex_unlock(&session->session_mutex);
        return;
    }

    msg->nas_message_type = nas_message_type;
    msg->message_id = message_id;
    msg->security_algorithm_suite = session->current_security_algorithm_suite;
    msg->transaction_id = transaction_id;
    msg->payload_size = payload_size;
    msg->payload = strdup(payload);
    if (!msg->payload) {
        mempool_dealloc(msg);
        pthread_mutex_unlock(&session->session_mutex);
        return;
    }

    // Set up the NFAPI_MESSAGE_T structures for the user-defined payload.
    NFAPI_MESSAGE_T *nfapi_messages = msg->nfapi_messages = mempool_alloc();
    if (!nfapi_messages) {
        free(msg->payload);
        mempool_dealloc(msg);
        pthread_mutex_unlock(&session->session_mutex);
        return;
    }

    // Configure the NFAPI_MESSAGE_T structures.
    for (size_t i = 0; i < payload_size / sizeof(NFAPI_MESSAGE_T); ++i) {
        nfapi_messages[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_XXX; // Replace with appropriate value.
        nfapi_messages[i].rnti = session->rnti + i; // Replace with appropriate value.
    }

    // Add the message to the queue for processing.
    message_queue.push(msg);

    // Increment the number of messages in this session and update the hash table.
    ++session->num_messages;
    message_ids[message_id] = true;

    pthread_mutex_unlock(&session->session_mutex);
}

// Function to report the total number of messages sent in a completed session.
size_t get_total_messages(int session_id) {
    Session *session = get_session(session_id);
    if (!session) {
        return 0;
    }

    pthread_mutex_lock(&session->session_mutex);
    size_t total_messages = session->num_messages;
    pthread_mutex_unlock(&session->session_mutex);

    // Release resources when the session is terminated.
    if (total_messages == session->max_messages) {
        free(session->messages);
        free(session);
    }

    return total_messages;
}
