// Customizable hash function based on Jenkins one-at-a-time hashing algorithm
unsigned long hash(const char *str, unsigned long seed) {
    unsigned long hash = seed;
    unsigned long c;

    while ((c = *str++)) {
        hash += c;
        hash += (hash << 10);
        hash ^= (hash >> 6);
    }

    hash += (hash << 3);
    hash ^= (hash >> 11);
    hash += (hash << 15);

    return hash;
}

#define BUFFER_SIZE 1024
Record *records = NULL;
unsigned long records_capacity = 0, records_size = 0;
const unsigned long memory_budget = (1ul * 1024ul * 1024ul); // 1 MB
unsigned long memory_used = 0;

void init() {
    if (!records) {
        records = mmap(NULL, BUFFER_SIZE * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

        if (records == MAP_FAILED) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }
