void resize() {
    Record *new_records = mmap(NULL, records_capacity + BUFFER_SIZE * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (new_records == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
