            records[index].key = strlen(str);
            records[index].timestamp = ((unsigned long)time(NULL) * 1000 + gethrtime()) & ULONG_MAX;
            ++records_size;

            if (memory_used + sizeof(Record) > memory_budget) {
                perror("Error: Memory usage exceeded the budget");
                exit(EXIT_FAILURE);
            }

            return;
        }
    }

    resize();
    add_record(str);
}

void free_memory() {
    if (records)
        munmap(records, records_size * sizeof(Record));
}
