#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h> // For memory usage monitoring on Linux systems

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

struct HashTable {
    size_t capacity;
    size_t size;
    Record* records;
    pthread_mutex_t lock;
};

unsigned long hash(const char* str, size_t length) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < length; ++i)
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    return hash % capacity;
}

void* allocate_memory(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr, size_t size) {
    if (munmap(ptr, size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

struct HashTable* create_hashtable(size_t capacity) {
    struct HashTable* table = allocate_memory(sizeof(struct HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->records = allocate_memory(capacity * sizeof(Record));
    table->lock = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

int add_record(struct HashTable* table, const char* key) {
    Record* record = &table->records[hash(key, strlen(key))];
    pthread_mutex_lock(&table->lock);

    // Handle duplicates by skipping existing records
    while (record->key != 0) {
        if (!strcmp(record->key, key)) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Duplicate key encountered
        }
        record++;
        if ((record - table->records) >= table->capacity) {
            pthread_mutex_unlock(&table->lock);
            return -2; // Table overflow; resize required
        }
    }

    record->key = strdup(key);
    record->offset = table->size++;
    record->timestamp = (double)(uint64_t)time(NULL) * 1e6;
    pthread_mutex_unlock(&table->lock);

    return 0; // Successfully added the key
}

void log_warning(const char* message) {
    fprintf(stderr, "[WARNING] %s\n", message);
}

void monitor_memory() {
    size_t total_memory = getpagesize() * (getpagesize() / 64); // Assume 64-bit architecture and page size of 4KB
    double memory_budget;
    double current_memory;

    FILE* memfile = fopen("/proc/self/meminfo", "r");
    if (memfile) {
        char line[256];
        while (fgets(line, sizeof(line), memfile)) {
            if (!strncmp(line, "MemTotal:", 8)) {
                sscanf(line, "MemTotal: %lf kB", &memory_budget);
                memory_budget *= 1e3; // Convert from kB to GB
            }
        }
        fclose(memfile);

        memfile = fopen("/proc/self/meminfo", "r");
        if (memfile) {
            char line[256];
            double total_used, used;
            while (fgets(line, sizeof(line), memfile)) {
                if (!strncmp(line, "MemUsed:", 7)) {
                    sscanf(line, "MemUsed: %lf kB", &total_used);
                    total_used *= 1e3; // Convert from kB to GB
                } else if (!strncmp(line, "Shared:", 6)) {
                    sscanf(line, "Shared: %lf kB", &used);
                    used *= 1e3; // Convert from kB to GB
                    total_used -= used;
                }
            }
            fclose(memfile);

            current_memory = total_used / memory_budget * 100.0;
        } else {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    } else {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (current_memory >= 90.0)
        log_warning("Memory usage exceeded 90% of the budget.");
}

void destroy_hashtable(struct HashTable* table) {
    pthread_mutex_destroy(&table->lock);
    free_memory(table, sizeof(struct HashTable));

    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = &table->records[i];
        if (record->key != NULL)
            free(record->key);
    }
    free_memory(table->records, table->capacity * sizeof(Record));
}
```

This code defines a dynamic array of records that can be used to store the specified data. The `hash()` function generates a hash value for the given key based on the given string and its length. The `add_record()` function handles adding new records to the table, managing potential duplicates and table overflow, and maintaining the timestamp for each record.

The `create_hashtable()` function initializes a new hashtable with the specified capacity, while the `destroy_hashtable()` function frees all allocated memory when the hashtable is no longer needed. The `log_warning()` function logs warning messages for various conditions, and the `monitor_memory()` function periodically checks the system's memory usage to ensure it does not exceed a specified budget.']

