    Record* record = mmap(NULL, sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!record) return NULL;

    pthread_mutex_init(&record->mutex, NULL);
    record->count = 0;
    record->capacity = 0;
    record->structures = NULL;

    return record;
}

Session* create_session() {
    // Allocate memory for the session and initialize mutex
    Session* session = mmap(NULL, sizeof(Session), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!session) return NULL;

    pthread_mutex_init(&session->mutex, NULL);
    session->count = 0;
    session->capacity = 0;
    session->messages = NULL;

    return session;
}

void free_record(Record* record) {
    if (record == NULL || record->structures == NULL) return;

    free(record->structures);
    pthread_mutex_destroy(&record->mutex);
    munmap(record, sizeof(Record));
}

void free_session(Session* session) {
    if (session == NULL || session->messages == NULL) return;

    free(session->messages);
    pthread_mutex_destroy(&session->mutex);
    munmap(session, sizeof(Session));
}

