['```java
import java.io.File;
import java.nio.file.Files;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class FileMetadata {
    public static String processFiles(List<String> filePaths) throws InterruptedException, ExecutionException {
        Map<File, Long> fileSizes = new HashMap<>();
        Map<File, Instant> lastModifiedTimestamps = new HashMap<>();

        // Use ForkJoinPool for parallel processing with optimal thread count based on available processors
        int coreCount = Runtime.getRuntime().availableProcessors();
        ExecutorService executor = Executors.newWorkStealingPool(coreCount);

        filePaths.forEach(executor::submit(() -> {
            File file = new File(filePath);
            try {
                fileSizes.put(file, Files.size(file.toPath()));
                lastModifiedTimestamps.put(file, file.lastModified());
            } catch (Exception e) {
                // Ignore exceptions for specific files and continue processing the rest
            }
        }));

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        Map<String, Object> report = new HashMap<>();
        report.put("totalFiles", fileSizes.keySet().size());
        report.put("fileSizes", fileSizes.entrySet().stream()
            .collect(Collectors.toMap(Map.Entry::getKey, entry -> entry.getValue() / 1024.0))); // Convert byte to KB for readability in the report
        report.put("lastModifiedTimestamps", lastModifiedTimestamps.entrySet().stream()
            .map(entry -> Instant.ofEpochMilli(entry.getValue().toMillis())).collect(Collectors.toList()));

        return new GsonBuilder().setPrettyPrinting().create().toJson(report);
    }
}
```
In this example, I used a ForkJoinPool for parallel processing which is highly efficient and adaptive to the number of available processors. Also, I've optimized performance for large datasets by only converting file sizes to KB when generating the report and using Instant instead of Date to minimize memory usage while handling timestamps. To make the output readable, I used Gson library to convert Java objects into a JSON string, but it is not included in this code snippet as per your request.']

