```cpp
#include <iostream>
#include <map>
#include <vector>
#include <boost/circular_buffer.hpp>
#include <boost/random.hpp>
#include <mutex>
#include <thread>

struct NR_RRCNAS_Message {
    NAS_Message_Type messageType;
    Message_ID messageId;
    Security_Algorithm_Suite securityAlgorithm;
    NAS_Transaction_ID transactionId;
    std::vector<NFAPI_MESSAGE_T> payloadBuffers;
};

class Interface {
public:
    Interface(int maxMessages, int maxInterfaces) : maxMessages_(maxMessages), maxInterfaces_(maxInterfaces), msgQueue_(maxMessages_) {}
    void enqueueMessage(const NR_RRCNAS_Message& message);
    int getTotalMessages() const;
    ~Interface();
private:
    boost::circular_buffer<NR_RRCNAS_Message> msgQueue_;
    const int maxMessages_;
    const int maxInterfaces_;
    static std::map<Security_Algorithm_Suite, int> algorithmMap; // Singleton for unique Algorithm generation
    mutable std::mutex mtx;
};

std::map<Security_Algorithm_Suite, int> Interface::algorithmMap;

void Interface::enqueueMessage(const NR_RRCNAS_Message& message) {
    // Validate message parameters and ensure no duplicate Message_IDs
    std::lock_guard<std::mutex> lock(mtx);
    if (message.messageId == -1 || messageQueue_.size() >= maxMessages_ || algorithmMap.find(message.securityAlgorithm) != algorithmMap.end()) {
        return;
    }

    // Generate unique Security_Algorithm_Suite
    auto it = algorithmMap.emplace(message.securityAlgorithm, 0).first;
    ++it->second;
    message.securityAlgorithm = it->first;

    // Assign a valid NAS_Transaction_ID and add the message to the queue
    message.transactionId = msgQueue_.size();
    msgQueue_.push_back(message);
}

int Interface::getTotalMessages() const {
    std::lock_guard<std::mutex> lock(mtx);
    return msgQueue_.size();
}

Interface::~Interface() {
    // Clean up resources here when the interface is terminated
