import akka.actor.ActorSystem;
import akka.stream.Materializer;
import akka.stream.javadsl.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import okhttp3.*;
import com.google.common.cache.*;

public class FileMetadataExtractor {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private final Cache<String, FileMetadata> fileCache = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .maximumSize(1000)
            .build();

    public String getSummaryReport(List<String> filePaths, ActorSystem system) throws IOException {
        Materializer materializer = ActorMaterializer.create(system);
        Source<FileMetadata, NotUsed> source = FileIO.source(filePaths, OkHttp.createHttp())
                .flatMapConcat({file ->
                    fileCache.getAsync(file.getPath(), () -> fetchFileMetadata(file))
                            .onComplete(() -> fileCache.invalidate(file.getPath()))
                })
                .map(metadata -> new SummaryReportItem(metadata.getFilePath(), metadata.getSize(), metadata.getLastModified()))
                .grouped(100)
                .toMat(Sink.seq(), Keep.right())
                .run(materializer);

        List<SummaryReportItem> summaryItems = source.toList().toCompletableFuture().get();
        String summaryJson = objectMapper.writeValueAsString(new SummaryReport(summaryItems));
        return summaryJson;
    }

    private FileRequest fetchFileMetadata(SourceFile file) throws IOException {
        Request request = new Request.Builder()
                .url("https://your-api-endpoint/metadata?filePath=" + file.getPath())
                .build();
        try (Response response = HttpUrlConnection.open(request)) {
            if (!response.isSuccessful()) throw new IOException("Error fetching metadata: " + response.getMessage());
            return objectMapper.readValue(response.getInputStream(), FileRequest.class);
        }
    }
}

public class SummaryReportItem {
    private String filePath;
    private long size;
    private long lastModified;

    // Getters and setters
}

public class SummaryReport {
    private List<SummaryReportItem> items;

    // Getters and setters
}
