typedef struct Record {
    char *str;
    int key;
} Record;

typedef struct DataEntry {
    Record *rec;
    size_t index;
} DataEntry;

int hash(const char *str, size_t len) {
    uint32_t hash = 5381;
    for (size_t i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + str[i];
    return hash % INT_MAX;
}

DataEntry **allocate_data(size_t size) {
    DataEntry **arr = malloc(sizeof(DataEntry *) * size);
    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for index array.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; ++i)
        arr[i] = NULL;
    return arr;
}

Record *allocate_record(char *str, int key) {
    Record *rec = malloc(sizeof(Record));
    if (!rec) {
        fprintf(stderr, "Failed to allocate memory for Record.\n");
        exit(EXIT_FAILURE);
    }
    rec->str = strdup(str);
    if (!rec->str) {
        fprintf(stderr, "Failed to duplicate the string.\n");
        free(rec);
        exit(EXIT_FAILURE);
    }
    rec->key = key;
    return rec;
}

void populate_data(DataEntry **arr, size_t size, char **strings, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Record *rec = allocate_record(strings[i], hash(strings[i], strlen(strings[i])));
        DataEntry *entry = malloc(sizeof(DataEntry));
        if (!entry) {
            fprintf(stderr, "Failed to allocate memory for DataEntry.\n");
            free(rec->str);
            free(rec);
            exit(EXIT_FAILURE);
        }
        entry->rec = rec;
        entry->index = hash(strings[i], strlen(strings[i]));
        if (arr[entry->index]) {
            DataEntry *temp = arr[entry->index];
            while (temp->index != INT_MAX) {
                ++entry->index;
                temp = arr[entry->index];
            }
        }
        arr[entry->index] = entry;
    }
}

void free_data(DataEntry **arr, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (!arr[i]) continue;
        DataEntry *entry = arr[i];
        free(entry->rec);
        free(entry);
    }
    free(arr);
}
