#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct DataEntry {
    void* key;
    char** record;
} DataEntry;

unsigned int hash(const unsigned char *data, size_t len) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data, len);
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_Final(digest, &ctx);
    return *(unsigned int*)&digest;
}

int allocate_memory(size_t size, DataEntry** entries, void*** indices, char*** record_array) {
    *entries = malloc(size * sizeof(DataEntry));
    if (!*entries) {
        fprintf(stderr, "Error allocating memory for entries\n");
        return 1;
    }

    *indices = malloc(size * sizeof(void*));
    if (!*indices) {
        fprintf(stderr, "Error allocating memory for indices\n");
        free(*entries);
        return 1;
    }

    *record_array = malloc(size * MAX_RECORD_LENGTH * sizeof(char));
    if (!*record_array) {
        fprintf(stderr, "Error allocating memory for record array\n");
        free(*entries);
        free(*indices);
        return 1;
    }

    return 0;
}

void clean_up(DataEntry** entries, void** indices, char** record_array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free((*entries)[i].record);
        free((*(indices)+i));
    }
    free(*entries);
    free(*indices);
    free(*record_array);
}

int manage_memory(size_t size, char** key_strings, char** record_strings) {
    DataEntry* entries;
    void* indices[size];
    char* record_array;

    if (allocate_memory(size, &entries, &indices, &record_array))
        return 1;

    for (size_t i = 0; i < size; ++i) {
        entries[i].key = malloc(sizeof(void*));
        if (!entries[i].key) {
            fprintf(stderr, "Error allocating memory for key\n");
            clean_up(&entries, &indices, &record_array, size);
            return 1;
        }

        entries[i].record = malloc((MAX_RECORD_LENGTH + 1) * sizeof(char));
        if (!entries[i].record) {
            fprintf(stderr, "Error allocating memory for record\n");
            clean_up(&entries, &indices, &record_array, size);
            return 1;
        }

        *entries[i].key = (void*)hash((unsigned char*)key_strings[i], strlen(key_strings[i]));
        strcpy(entries[i].record, record_strings[i]);
        indices[(unsigned long)*entries[i].key] = &entries[i];
    }

    // Main function continues here with proper usage of the allocated resources.

    clean_up(&entries, &indices, &record_array, size);
    return 0;
}
```

This code defines a `DataEntry` structure containing pointers to a dynamically allocated `Record` structure and an integer key. The `hash()` function computes the MD5 hash of the string content within each `Record`. The `allocate_memory()` function manages dynamic memory allocation for an array of `DataEntry` structures, as well as an index array that maps each `DataEntry` to its corresponding `Record`.

The `manage_memory()` function initializes the memory, populates the `DataEntry` structures with the given key and record strings, and computes their keys using the MD5 hash. The error handling ensures proper cleanup when encountering issues during memory allocation or hashing.']

