```python
import json
import math
import time
from typing import List, Dict, Union

class DataProcessor:
    def __init__(self, file: str, time_window: int):
        self.file = file
        with open(self.file) as f:
            self.data = json.load(f)
        self.time_window = time_window
        self.timestamps = []
        self.values = []

    def validate_json(self):
        # Validate JSON structure and filter out corrupted entries
        for item in self.data:
            if not isinstance(item, dict) or 'timestamp' not in item or 'value' not in item:
                continue
            try:
                timestamp = float(item['timestamp'])
                value = float(item['value'])
            except ValueError:
                continue
            self.timestamps.append(timestamp)
            self.values.append(value)

    def rolling_average(self):
        average = [0.0] * (len(self.timestamps) + self.time_window - 1)
        window = slice((self.time_window - 1) // 2, len(self.timestamps), 1)
        for i in range(len(average)):
            if i >= len(self.timestamps):
                break
            average[i] = sum(self.values[j] for j in window if (j-i) >= 0) / self.time_window

    def compute_metrics(self):
        mean = sum(self.values) / len(self.values)
        median = sorted(self.values)[len(self.values) // 2]
        stddev = math.sqrt(sum((x - mean)**2 for x in self.values)/len(self.values))
        return {'mean': mean, 'median': median, 'stddev': stddev}

    def export_metrics(self, output: str):
        metrics = self.compute_metrics()
        with open(output, 'w') as f:
            f.write("Sensor Data Metrics\n")
            f.write('-' * 40 + '\n')
            for k, v in metrics.items():
                f.write(f'{k}: {v}\n')
            f.write('-' * 40)
```

