#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>

typedef struct ContentBlock {
    char* content;
    int id;
} ContentBlock;

typedef struct Document {
    ContentBlock* cb;
    int* metadata; // array for additional attributes, such as creation timestamp and modification count
} Document;

// Helper function to compute SHA-256 checksum of a given string content
unsigned char* document_checksum(const char* data) {
    const unsigned char* d = (const unsigned char*)data;
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, d, strlen(data));
    SHA256_Final(digest, &ctx);
    return digest;
}

Document* create_document(const char* content) {
    // Compute checksum and generate unique id
    unsigned char* checksum = document_checksum(content);
    int id = *(int*)checksum;

    // Allocate memory for ContentBlock, metadata array, and Document structure
    ContentBlock* cb = malloc(sizeof(ContentBlock));
    if (!cb) {
        fprintf(stderr, "Error: Unable to allocate memory for ContentBlock.\n");
        exit(1);
    }
    cb->content = strdup(content);
    if (!cb->content) {
        fprintf(stderr, "Error: Unable to allocate memory for content string.\n");
        free(cb);
        exit(1);
    }
    cb->id = id;

    int* metadata = malloc(sizeof(int) * NUM_METADATA_ATTRIBUTES);
    if (!metadata) {
        fprintf(stderr, "Error: Unable to allocate memory for metadata array.\n");
        free(cb->content);
        free(cb);
        exit(1);
    }

    Document* doc = malloc(sizeof(Document));
    if (!doc) {
        fprintf(stderr, "Error: Unable to allocate memory for Document structure.\n");
        free(cb->content);
        free(cb);
        free(metadata);
        exit(1);
    }
    doc->cb = cb;
    doc->metadata = metadata;

    return doc;
}

void destroy_document(Document* doc) {
    if (doc->cb->content) free(doc->cb->content);
    if (doc->cb) free(doc->cb);
    if (doc->metadata) free(doc->metadata);
    if (doc) free(doc);
}
```

