[' Due to the complexity of the task, I'll provide a simplified C++17 solution using `std::unordered_map` and `std::vector` for the hash table and arrays respectively, with custom alignment support using `alignas`. For concurrent access, we use a thread-safe version of `std::unordered_map`, which is provided by `concurrency_std::concurrent_unordered_map` in the Concurrency Library.

```cpp
#include <iostream>
#include <vector>
#include <random>
#include <memory>
#include <concurrency>
#include <new>

alignas(64) struct Record {
    int value;
};

template<typename T, std::size_t Alignment>
T* align_allocator(std::size_t size) {
    void* ptr = ::operator new(size, Alignment);
    return static_cast<T*>(static_cast<char*>(ptr) + (Alignment - 1) & ~(Alignment - 1));
}

void init_arrays(std::vector<long long>* offsets, std::vector<int>* keys, std::vector<Record>* records, std::concurrency::concurrent_unordered_map<int, Record*>* hash_table, size_t size, alignas(64) std::allocator<long long>* offset_allocator, alignas(64) std::allocator<int>* key_allocator, alignas(64) std::allocator<Record>* record_allocator) {
    if (size == 0 || offset_allocator == nullptr || key_allocator == nullptr || record_allocator == nullptr) {
        std::cerr << "Invalid parameters." << std::endl;
        return;
    }

    try {
        offsets->resize(size, 0);
        keys->resize(size);
        records.reset(new (align_allocator<std::vector<Record>>(sizeof(Record) * size)) std::vector<Record>(size));
        hash_table->reserve(size);
    } catch (...) {
        std::cerr << "Out of memory." << std::endl;
        return;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(0, 100);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = static_cast<long long>(i * 2 + 1); // example offset value calculation
        keys[i] = i;
        records[i].value = distr(gen);

        hash_table->try_emplace(keys[i], std::move(*records[i]));
    }
}
```

This function initializes the specified arrays and the hash table, with custom alignment for memory allocation. It also generates random values for the records within a specified range (0-100 in this example). The hash table uses `std::concurrency::concurrent_unordered_map`, ensuring thread safety.']

['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Node structure
typedef struct Node {
    char* str;
    int priority;
    struct Node *next;
    pthread_mutex_t lock;
} Node;

// Function to generate a unique string for each node
char* gen_unique_str() {
    static int suffix = 0;
    char buf[32];
    snprintf(buf, sizeof(buf), "prefix-%d", suffix++);
    return strdup(buf);
}

// Function to dynamically allocate and initialize a node with given priority
Node* create_node(int prio) {
    Node *new_node = (Node*) malloc(sizeof(Node) + (sizeof(void*) - 1) & ~(sizeof(void*) - 1));
    if (!new_node) return NULL;

    new_node->str = gen_unique_str();
    new_node->priority = prio;
    new_node->next = NULL;

    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

// Function to insert a node into the priority queue, maintaining concurrent access efficiency and thread safety
void push(Node** head, Node* new_node) {
    pthread_mutex_lock(&new_node->lock);
    new_node->next = *head;
    *head = new_node;
    pthread_mutex_unlock(&new_node->lock);
}

// Function to remove and return the highest priority node from the priority queue, ensuring thread safety
Node* pop(Node** head) {
    Node *highest_priority_node = NULL, *current = *head;
    pthread_mutex_lock(&current->lock);

    while (current != NULL) {
        if (!highest_priority_node || current->priority > highest_priority_node->priority)
            highest_priority_node = current;

        current = current->next;
        pthread_mutex_unlock(&current->lock);
        pthread_mutex_lock(highest_priority_node ? &highest_priority_node->lock : head);
    }

    if (highest_priority_node) {
        *head = highest_priority_node->next;
        Node* tmp = highest_priority_node;
        pthread_mutex_unlock(head);
        free(tmp->str);
        free(tmp);
        return tmp;
    } else {
        pthread_mutex_unlock(head);
        return NULL;
    }
}

// Function to initialize a priority queue with given alignment requirement and minimum size
PriorityQueue* init_priority_queue(size_t align, size_t min_size) {
    if (align & (sizeof(void*) - 1)) {
        fprintf(stderr, "Invalid alignment requirement.\n");
        return NULL;
    }

    PriorityQueue *pq = (PriorityQueue*) malloc(align + sizeof(PriorityQueue));
    if (!pq) {
        perror("Out of memory");
        return NULL;
    }

    pq->head = NULL;
    pq->min_size = min_size;
    return pq;
}

// Function to dynamically allocate a priority queue and insert given nodes into it, ensuring efficient deallocation and minimal fragmentation
void create_priority_queue(PriorityQueue* pq, ...) {
    va_list ap;
    va_start(ap, pq);

    int prio;
    Node* node;
    while ((prio = va_arg(ap, int)) != -1) {
        node = create_node(prio);
        if (!node) {
            perror("Out of memory");
            return;
        }
        push(&pq->head, node);
    }

    va_end(ap);
}
```
This code defines a `Node` structure containing a string, priority, and a pointer to the next node. It also includes functions for creating nodes with unique strings, inserting nodes into the priority queue, and removing the highest-priority node from the queue while maintaining thread safety.

The `PriorityQueue` structure is used to manage the alignment requirement and minimum size of the priority queue, along with the head pointer pointing to the first node in the list. The code also includes functions for initializing a priority queue and inserting nodes into it using variable arguments.']

