#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>

#define RECORD_SIZE 16
#define MEMORY_BUDGET (1024 * 1024) // 1 MB
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2

typedef struct Record {
    long offset;
    int key;
    double timestamp;
} Record;

void log(int level, const char *message) {
    if (level <= getenv("LOG_LEVEL") && level > 0) {
        fprintf(stderr, "%s\n", message);
    }
}

unsigned long hash(const void *key) {
    const size_t key_size = strlen((const char *)key);
    unsigned long hash = 5381;
    for (size_t i = 0; i < key_size; ++i) {
        hash = ((hash << 5) + hash) + key[i];
    }
    return hash % MEMORY_BUDGET;
}

Record *initialize_records(FILE *file, size_t *capacity) {
    Record *records = mmap(NULL, *capacity * RECORD_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    size_t offset = 0;
    int keys[*capacity];
    char lines[256];
    while (fgets(lines, sizeof(lines), file)) {
        size_t len = strlen(lines);
        if (len > 0 && lines[len - 1] == '\n') {
            keys[offset] = atoi(lines);
            records[offset].offset = hash(&keys[offset]);
            records[offset].key = keys[offset];
            records[offset].timestamp = (double)time_t(NULL) * 1.e9;
            offset += RECORD_SIZE;
        }
    }
    *capacity *= 2;
    return realloc(records, *capacity * RECORD_SIZE);
}

void validate_data(const Record *records, size_t capacity) {
    for (size_t i = 0; i < capacity - RECORD_SIZE; ++i) {
        for (size_t j = i + RECORD_SIZE; j < capacity; j += RECORD_SIZE) {
            if (records[i].key == records[j].key && i != j) {
                log(LOG_LEVEL_ERROR, "Key collision detected: %d", records[i].key);
            }
        }
    }
}

void free_memory(Record *records, size_t capacity) {
    munmap(records, capacity * RECORD_SIZE);
}

void manage_memory(FILE *file, int log_level) {
    size_t capacity = 0;
    Record *records = NULL;

    srand((unsigned int)(time(NULL) * 1.e9));

    while (1) {
        records = initialize_records(file, &capacity);
        validate_data(records, capacity / RECORD_SIZE);

        size_t used_memory = ((capacity * RECORD_SIZE) + RECORD_SIZE - 1) & ~(RECORD_SIZE - 1);
        if (used_memory > MEMORY_BUDGET * 0.9 && log_level >= LOG_LEVEL_WARNING) {
            log(LOG_LEVEL_WARNING, "Memory usage is at 90% of the budget");
        } else if (used_memory > MEMORY_BUDGET) {
            log(LOG_LEVEL_ERROR, "Memory usage exceeded the budget");
            exit(EXIT_FAILURE);
        }
    }

    free_memory(records, capacity);
}
```

This code defines a function `manage_memory()`, which manages an array of records and handles memory allocation, validation, and logging as requested. The `initialize_records()` function is used to initialize the records with unique offsets derived from a hash function applied to the keys and timestamps. The `validate_data()` function checks for duplicate keys and unique offsets.']

