typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static Node* head = NULL;
static unsigned int capacity = 0;
static const unsigned int resize_threshold = 1000;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void create_log(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

NFAPI_CRC_INDICATION_PDU_T* create_structure() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        create_log("Failed to allocate memory for PDU structure");
        return NULL;
    }

    pdu->creation_timestamp = time(NULL);
    pdu->crc_indication.CRCFLAG = (rand() % 100) + 50; // Validating CRC_FLAG within a specified range [50, 149]

    create_log("Created PDU structure with timestamp:");
    create_log(ctime(&pdu->creation_timestamp));

    return pdu;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_mutex);

    if (head == NULL) {
        head = malloc(sizeof(Node));
        if (!head) {
            create_log("Failed to allocate memory for list header node");
            free(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        head->data = *pdu;
        head->next = NULL;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }

        current->next = malloc(sizeof(Node));
        if (!current->next) {
            create_log("Failed to allocate memory for new node in the list");
            free(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        current->next->data = *pdu;
        current->next->next = NULL;
    }

    if (capacity < capacity + 1 && capacity + 1 > resize_threshold) {
        Node** nodes = realloc(head, sizeof(Node) * (capacity + resize_threshold));
        if (!nodes) {
            create_log("Failed to reallocate memory for the list");
            while (capacity--) free(head[capacity]);
            free(head);
            free(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        head = nodes;
        capacity += resize_threshold;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Accessing the list is thread-safe, but modifying it requires locking the mutex
