// Define struct for RRCNAS_Message and NFAPI_MESSAGE_T
typedef struct {
    NAS_Message_Type msg_type;
    Message_ID msg_id;
    Security_Algorithm_Suite sec_alg_suite;
    NAS_Transaction_ID trans_id;
    size_t payload_size;
    char *payload; // dynamically allocated buffer for user-defined payload
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
} RRCNAS_Message;

typedef struct {
    RRCNAS_Message* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    semaphore_t free_slots; // Semaphore to manage available slots in the message array
} Session;

// Function to create and initialize a new session
Session* create_session(size_t max_messages) {
    Session *session = mmap(NULL, sizeof(Session), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (session == MAP_FAILED) {
        log_error("Failed to allocate memory for session");
        return NULL;
    }

    sem_init(&session->free_slots, 0, max_messages);
    pthread_mutex_init(&session->mutex, NULL);
    session->capacity = max_messages;
    session->count = 0;
    session->messages = calloc(max_messages, sizeof(RRCNAS_Message));
    if (!session->messages) {
        log_error("Failed to allocate memory for messages in the session");
        munmap(session, sizeof(Session));
        return NULL;
    }

    return session;
}

// Function to add a new message to the specified session
RRCNAS_Message* add_message(Session *session, NAS_Message_Type msg_type, Message_ID msg_id, Security_Algorithm_Suite sec_alg_suite, NAS_Transaction_ID trans_id, size_t payload_size, const void *payload, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    // Validate payload size and ensure no duplicate msg_id in the session
    if (payload_size > MAX_PAYLOAD_SIZE || find_message_by_msg_id(session, msg_id)) {
        log_error("Invalid or duplicate message ID");
        return NULL;
    }

    // Allocate memory for the new message and handle allocation failures gracefully
    RRCNAS_Message *msg = calloc(1, sizeof(RRCNAS_Message));
    if (!msg) {
        log_error("Failed to allocate memory for the message");
        return NULL;
    }

    msg->msg_type = msg_type;
    msg->msg_id = msg_id;
    msg->sec_alg_suite = sec_alg_suite;
    msg->trans_id = trans_id;
    msg->payload_size = payload_size;
    msg->payload = malloc(payload_size);
    if (!msg->payload) {
        free(msg);
        log_error("Failed to allocate memory for the message payload");
        return NULL;
    }

    memcpy(msg->payload, payload, payload_size);
    msg->tag = tag;
    msg->rnti = rnti;

    pthread_mutex_lock(&session->mutex);

    // Acquire a free slot and store the message in the session
    if (sem_wait(&session->free_slots) == -1) {
        log_error("Failed to acquire a free slot for the message");
        free(msg->payload);
        free(msg);
        pthread_mutex_unlock(&session->mutex);
        return NULL;
    }
    session->messages[session->count] = msg;
    session->count++;

    pthread_mutex_unlock(&session->mutex);

    return msg;
}

// Function to find a message by its msg_id in the specified session
bool find_message_by_msg_id(Session *session, Message_ID msg_id) {
    bool found = false;
    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < session->count; ++i) {
        if (session->messages[i].msg_id == msg_id) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&session->mutex);
    return found;
}
