Session* create_session(int max_session_length, int max_concurrent_sessions) {
    Session* session = malloc(sizeof(Session));
    if (!session) return NULL;

    session->session_index = -1;
    session->num_messages = 0;
    session->max_session_length = max_session_length;
    session->max_concurrent_sessions = max_concurrent_sessions;
    session->is_active = false;

    pthread_mutex_init(&session->mutex, NULL);
    pthread_cond_init(&session->cond, NULL);

    return session;
}

void destroy_session(Session* session) {
    for (int i = 0; i < session->num_messages; ++i) {
        free(session->messages[i].payload);
    }
    free(session->messages);
    pthread_mutex_destroy(&session->mutex);
    pthread_cond_destroy(&session->cond);
    free(session);
}
```

