```c
typedef void (*custom_payload_func)(NFAPI_MESSAGE_T*);

LTE_RRCNAS_Message* generate_message(Session* session, NAS_Message_Type msg_type,
                                    Message_ID msg_id, custom_payload_func payload_func) {
    if (session->num_messages >= session->max_session_length ||
        session->is_active && session->num_messages >= session->max_concurrent_sessions) {
        return NULL;
    }

    LTE_RRCNAS_Message* msg = malloc(sizeof(LTE_RRCNAS_Message));
    if (!msg) return NULL;

    msg->msg_type = msg_type;
    msg->msg_id = msg_id;

    // Generate a unique security suite for this session, ensuring it hasn't been used before
    msg->security_suite = generate_unique_security_suite();

    // Assign a valid transaction ID and payload size within limits
    msg->transaction_id = ++session->num_messages;
    msg->payload_size = rand() % MAX_PAYLOAD + 1;

    if (msg->payload_size > MAX_PAYLOAD) {
        free(msg);
        return NULL;
    }

    // Allocate payload buffer and assign RNTI values in NFAPI_MESSAGE_T structures
    msg->payload = malloc((MAX_PAYLOAD + sizeof(NFAPI_MESSAGE_T)) * (session->num_messages + 1));
    if (!msg->payload) {
        free(msg);
        return NULL;
    }

    for (int i = 0; i <= msg->payload_size + sizeof(NFAPI_MESSAGE_T) - 1; ++i) {
        ((NFAPI_MESSAGE_T*)(msg->payload + i))->rnti = i % 1024;
        ((NFAPI_MESSAGE_T*)(msg->payload + i))->tag = rand() % 65536;
    }

    if (payload_func) {
        payload_func((NFAPI_MESSAGE_T*)(msg->payload));
    }

    session->is_active = true;

    return msg;
}
