#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    uint32_t id;
    time_t timestamp;
    char* payload;
    size_t payload_size;
} NetworkMessage;

void log_message(const char* message) {
    FILE *logfile = fopen("log.txt", "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", message);
        fclose(logfile);
    }
}

NetworkMessage* initialize_message(size_t message_count) {
    NetworkMessage* messages = (NetworkMessage*)malloc(message_count * sizeof(NetworkMessage));
    if (!messages) {
        log_message("Failed to allocate memory for messages");
        return NULL;
    }

    for (size_t i = 0; i < message_count; ++i) {
        messages[i].id = i + 1;
        messages[i].timestamp = time(NULL);
        messages[i].payload_size = rand() % MAX_PAYLOAD_SIZE + MIN_PAYLOAD_SIZE;

        if (messages[i].payload_size == 0) {
            log_message("Zero-sized message encountered");
            continue;
        }

        messages[i].payload = malloc(messages[i].payload_size);
        if (!messages[i].payload) {
            log_message("Failed to allocate memory for payload of message ID: ", messages[i].id);
            free(messages);
            return NULL;
        }
    }

    return messages;
}

void serialize_messages(const char* filename, const NetworkMessage* messages, size_t count) {
    int file = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (file == -1) {
        log_message("Failed to open file for writing");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        write(file, &messages[i].id, sizeof(uint32_t));
        write(file, &messages[i].timestamp, sizeof(time_t));
        write(file, messages[i].payload, messages[i].payload_size);
    }

    close(file);
}

NetworkMessage* deserialize_messages(const char* filename, size_t* count) {
    int file = open(filename, O_RDONLY);
    if (file == -1) {
        log_message("Failed to open file for reading");
        *count = 0;
        return NULL;
    }

    struct stat file_info;
    fstat(file, &file_info);
    size_t total_size = file_info.st_size / sizeof(NetworkMessage);

    NetworkMessage* messages = (NetworkMessage*)malloc(total_size * sizeof(NetworkMessage));
    if (!messages) {
        log_message("Failed to allocate memory for deserialized messages");
        close(file);
        *count = 0;
        return NULL;
    }

    for (size_t i = 0; i < total_size; ++i) {
        read(file, &messages[i].id, sizeof(uint32_t));
        read(file, &messages[i].timestamp, sizeof(time_t));
        messages[i].payload = malloc(messages[i].payload_size);
        if (!messages[i].payload) {
            log_message("Failed to allocate memory for payload of message ID: ", messages[i].id);
            free(messages);
            close(file);
            *count = i;
            return NULL;
        }

        read(file, messages[i].payload, messages[i].payload_size);
    }

    close(file);
    *count = total_size;
    return messages;
}
