```cpp
#include <boost/circular_buffer.hpp>
#include <boost/log/trivial.hpp>
#include <cstdio>
#include <iostream>
#include <sstream>
#include <vector>

struct MediaPacket {
    uint64_t timestamp;
    size_t id;
    char* payload; // Dynamically allocated buffer for payload data
    size_t payloadSize; // Size of the payload data
};

class MediaQueue {
public:
    MediaQueue(size_t capacity) : m_buffer(capacity), m_head(0), m_tail(0) {}

    void push(MediaPacket& packet);
    MediaPacket pop();

private:
    boost::circular_buffer<MediaPacket, std::vector<MediaPacket>> m_buffer;
    size_t m_head;
    size_t m_tail;
};

void MediaQueue::push(MediaPacket& packet) {
    if (packet.payloadSize > 4096)
        throw std::invalid_argument("Payload size exceeds maximum limit");

    // Efficiently resize the memory pool if necessary
    if (m_buffer.size() >= 1000000 && m_buffer.capacity() < 2 * m_buffer.size())
        m_buffer.resize(2 * m_buffer.capacity());

    // Allocate payload buffer efficiently
    packet.payload = new char[packet.payloadSize];
    std::memcpy(packet.payload, /*source*/, packet.payloadSize);
    m_buffer[m_tail] = packet;
    m_tail = (m_tail + 1) % m_buffer.size();
}

MediaPacket MediaQueue::pop() {
    if (m_head == m_tail)
        throw std::runtime_error("No packets available in the queue");

    MediaPacket packet = m_buffer[m_head];
    m_head = (m_head + 1) % m_buffer.size();
    return packet;
}

// Implement the process_media_packets function here, using the MediaQueue class and handling the additional requirements as described above.
