typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* create_list(int n) {
    if (n <= 0 || n > 10000) {
        printf("Number of structures should be between 1 and 10,000\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU* head = NULL;
    NFAPI_CRC_INDICATION_PDU* current = NULL;

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));

        if (!node) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Set tag, RNTI and CRC_INDICATION fields

        node->next = NULL;

        if (i == 0) {
            head = current = node;
        } else {
            current->next = node;
            current = node;
        }
    }

    // Ensure uniqueness of RNTIs and avoid all flags being the same within a batch of 100 consecutive structures
    current = head;
    for (int i = 1; i < n; ++i) {
        while (current->next && current->next->rnti == current->next->next->rnti) {
            current = current->next;
        }

        if (i % 100 == 0) {
            current->crc_indication.CRCFLAG ^= 1; // Toggle the CRCFLAG every 100 structures to avoid all flags being the same within a batch of 100 consecutive structures
        }

        current = current->next;
    }

    return head;
