    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct _list_node* next;
    pthread_mutex_t mutex;
} list_node;

list_node* head = NULL;
pthread_mutex_t head_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t size = 0;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* data) {
    list_node* node = (list_node*)malloc(sizeof(list_node));
    if (!node) return;

    node->data = data;
    node->next = NULL;

    pthread_mutex_init(&node->mutex, NULL);

    // Lock head mutex to prevent race conditions during adding a new node
    pthread_mutex_lock(&head_mutex);

    if (!head) {
        head = node;
    } else {
        list_node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }

    size++;

    pthread_mutex_unlock(&head_mutex);

    // Validate RNTI uniqueness and set CRCFLAG
    validate_rnti(node->data->rnti);
    set_crcflag(node->data->crc_indication);
}

bool validate_rnti(uint32_t rnti) {
    bool isUnique = true;
    list_node* current = head;

    // Lock head mutex to prevent race conditions during checking for unique RNTIs
    pthread_mutex_lock(&head_mutex);

    while (current && isUnique) {
        if (current->data->rnti == rnti) {
            isUnique = false;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&head_mutex);

    return isUnique;
}

void set_crcflag(CRC_INDICATION_REL8_TAG* crc_indication) {
    srand((unsigned int)time(NULL));
    (*crc_indication) ^= rand() & 1;
}

void process_batch(NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    pthread_mutex_lock(&head_mutex);

    for (size_t i = 0; i < count; ++i) {
        add_to_list(data + i);
    }

    pthread_mutex_unlock(&head_mutex);
}

void log_event(const char* event, NFAPI_CRC_INDICATION_PDU_T* data) {
