    fclose(logFile);
}

void iterate_list(void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&head_mutex);

    list_node* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* data = current->data;
        operation(data);
        current = current->next;
    }

    pthread_mutex_unlock(&head_mutex);
}

// Free the list upon completion.
void free_list() {
    pthread_mutex_lock(&head_mutex);

    list_node* current = head;
    while (current) {
