size_t populate_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t N) {
    if (N == 0 || array == NULL) {
        return 0;
    }

    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return 0;
    }

    size_t allocated_elements = 0;
    for (size_t i = 0; i < N && allocated_elements < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = (*array + i);
        element->RX_UE_INFORMATION_TAG = i + 1;
        element->RNTI = (i % 504) + 1; // Valid range: [1, 504]
        element->CRC_INDICATION_REL8_TAG = ((element->RNTI >> 3) & 0x01) | ((!(element->RNTI & 0x1)) << 7);

        if (element->RNTI < 1 || element->RNTI > 504 || (element->CRC_INDICATION_REL8_TAG != 0 && element->CRC_INDICATION_REL8_TAG != 1)) {
            allocated_elements--;
            continue;
        }

        ++allocated_elements;
    }

    return allocated_elements;
}
