typedef struct LTE_TRANSPORT_CONTEXT {
    uint16_t rrc_instance_id;
    uint16_t transport_rlc_instance_id;
    uint8_t transport_channel_type;
} LTE_TRANSPORT_CONTEXT;

size_t create_lte_transport_context_array(LTE_TRANSPORT_CONTEXT** arr, size_t N) {
    size_t i;
    size_t count = 0;

    if (arr == NULL || N == 0)
        return 0;

    *arr = malloc(N * sizeof(LTE_TRANSPORT_CONTEXT));

    if (*arr == NULL) {
        free(*arr);
        return 0;
    }

    for (i = 0; i < N && count < N; ++i) {
        LTE_TRANSPORT_CONTEXT* curr = &((*arr)[count]);

        curr->rrc_instance_id = (uint16_t)(i + 1); // Valid RRC instance ID is between 1 and N.
        curr->transport_rlc_instance_id = (i + 1) % 10; // Valid transport RLC instance ID is between 1 and 10.
        curr->transport_channel_type = (i < 5) ? 1 : 2; // Transport channel type can be either 1 or 2, only the first 5 elements will have a type of 1.

        if (curr->transport_rlc_instance_id > 10 || curr->transport_channel_type > 2) {
            free(*arr);
            *arr = NULL;
            return count;
        }

        ++count;
    }

    return count;
}
