int main() {
    int N = 10; // number of interfaces to manage
    float error_threshold = 0.10f; // error rate threshold for high error interfaces
    InterfaceStat *interface_stats = malloc(N * sizeof(InterfaceStat));

    init_interface_stats(interface_stats, N, error_threshold);
    populate_interface_stats(interface_stats, N);

    int num_interfaces;
    InterfaceStat filtered_interfaces[N];
    filter_high_error_interfaces(interface_stats, N, filtered_interfaces, &num_interfaces);

    for (int i = 0; i < num_interfaces; ++i) {
