    }

    free(interface_stats);
    return 0;
}

void init_interface_stats(InterfaceStat* stats, int num_interfaces, float error_threshold) {
    for (int i = 0; i < num_interfaces; ++i) {
        stats[i].error_rate = error_threshold;
    }
}

void populate_interface_stats(InterfaceStat* stats, int num_interfaces) {
    srand((unsigned)time(NULL));
    for (int i = 0; i < num_interfaces; ++i) {
        sprintf(stats[i].interface, "iface%d", i);
        stats[i].timestamp = time(NULL);
        stats[i].packet_count = rand() % 1000 + 1;
        stats[i].byte_count = (unsigned long)(rand() % 100000 + 1) * sizeof(unsigned int);
        stats[i].error_rate = ((float)rand() % 20) / 100.0f;
    }
}

void filter_high_error_interfaces(const InterfaceStat* all_stats, int num_interfaces, InterfaceStat* filtered_stats, int* filtered_count) {
    *filtered_count = 0;
    for (int i = 0; i < num_interfaces; ++i) {
        if (get_error_rate(&all_stats[i]) <= 0.10f) {
            filtered_stats[*filtered_count] = all_stats[i];
            (*filtered_count)++;
        }
    }
}

float get_error_rate(const InterfaceStat* stat) {
    return (stat->packet_count - stat->byte_count * 8.0f / sizeof(unsigned int)) / (stat->byte_count * 8.0f / sizeof(unsigned int));
}
