2. Implement the dynamic list management function in C:

```c
NetworkConnectionState* createNode() {
    NetworkConnectionState* newNode = malloc(sizeof(NetworkConnectionState));
    if (!newNode) return NULL;

    memset(newNode, 0, sizeof(NetworkConnectionState));
    return newNode;
}

void freeNode(NetworkConnectionState* node) {
    if (!node) return;
    free(node);
}

NetworkConnectionState* addNode(NetworkConnectionState** head, NetworkConnectionState* newNode) {
    if (!head || !newNode) return NULL;

    if (*head == NULL) {
        *head = newNode;
        newNode->prev = newNode->next = newNode;
    } else {
        newNode->prev = (*head)->prev;
        newNode->next = *head;
        (*head)->prev->next = newNode;
        (*head)->prev = newNode;
    }

    return newNode;
}

void removeNode(NetworkConnectionState** head, NetworkConnectionState* node) {
    if (!head || !node || !(*head)) return;

    if (node->prev == node) { // Node is the only one in the list
        freeNode(node);
        *head = NULL;
    } else if (node == *head) { // Node is the first one in the list
        NetworkConnectionState* nextNode = node->next;
        freeNode(node);
        *head = nextNode;
        if (*head) (*head)->prev = (*head)->prev->prev;
    } else { // Node is somewhere in the middle or at the end of the list
        NetworkConnectionState* prevNode = node->prev;
        NetworkConnectionState* nextNode = node->next;
        freeNode(node);
        prevNode->next = nextNode;
        if (nextNode) nextNode->prev = prevNode;
    }
}

