async function reduceArray(arr, initialValue, callback) {
    try {
        return await arr.reduce((accumulatedValue, currentNumber) => {
            return new Promise((resolve) => {
                callback(accumulatedValue, currentNumber, resolve);
            });
        }, initialValue);
    } catch (error) {
        console.error('An error occurred:', error);
        throw error;
    }
}
