**Memory Management**

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

#define MAX_RECORDS 1024 // adjust as needed
#define BUFFER_SIZE 1048576 // 1 MB buffer size
#define THRESHOLD 95

typedef struct {
    long offset;
    int key;
    int data;
    time_t timestamp;
} Record;

// Custom memory pool allocator using mmap and pthread_mutex
Record* record_alloc(void) {
    static void *buffer = NULL;
    static size_t bufferSize = 0;
    static size_t pos = 0;

    if (!buffer || pos >= bufferSize) {
        if (pos > 0) {
            munmap((void *)((char*)buffer + pos), bufferSize - pos);
        }
        buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        bufferSize = BUFFER_SIZE;
        pos = 0;
    }

    Record* rec = (Record*)((char*)buffer + pos);
    pos += sizeof(Record);

    return rec;
}
```

**Record Structure and Hash Function**

```c
// Secure hash function using MurmurHash3
#include "murmurhash3.h"

void init_record(Record* rec, const char *str) {
    int len = strlen(str);
    murburhash3_hash64((const char*)str, len, 0, &rec->key);
    rec->offset = murmurhash3_x86_128(&rec->key, sizeof(rec->key), 0) & ((1ULL << 64) - MAX_RECORDS);
    rec->timestamp = time(NULL);
}
