#include <json-c/json.h>

bool is_valid_access_token(const char *token_str) {
    cJSON* root = cJSON_Parse(token_str);
    if (!root || !cJSON_IsObject(root)) {
        return false;
    }

    cJSON* access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    cJSON* expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    cJSON* token_type = cJSON_GetObjectItemCaseSensitive(root, "token_type");
    cJSON* refresh_token = cJSON_GetObjectItemCaseSensitive(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        return false;
    }

    if (strcmp(token_type->valuestring, "Bearer") != 0 || expires_in->valueint < 1) {
        return false;
    }

    // Optionally validate refresh_token if present

    cJSON_Delete(root);
    return true;
}
