struct NFAPI_MESSAGE_T {
    enum class RX_UE_INFORMATION_TAG : int {
        UE_ID = 1,
        SEQUENCE_NUMBER = 2,
        // ... other tags can be added here
    };
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
};

struct LTE_RRCNAS_Message {
    enum class NAS_Message_Type : int {
        // Define all supported message types here
    } message_type;
    int message_id;
    std::unique_ptr<uint8_t[]> payload; // Dynamically allocated payload buffer
    std::vector<NFAPI_MESSAGE_T> nfapi_messages;
    uint32_t security_algorithm_suite;
    uint32_t nas_transaction_id;

    LTE_RRCNAS_Message() : security_algorithm_suite(std::rand()), nas_transaction_id(std::rand()) {}
};

class RRCNAS_Session {
public:
    explicit RRCNAS_Session(size_t max_messages) : messages_(max_messages), next_message_id_(1) {}

    std::vector<LTE_RRCNAS_Message> generate_messages(size_t count, uint32_t rnti) {
        if (count > messages_.size()) {
            throw std::runtime_error("Requested message count exceeds maximum allowed per session");
        }

        auto start_time = std::chrono::steady_clock::now();
        std::vector<LTE_RRCNAS_Message> generated_messages;

        for (size_t i = 0; i < count; ++i) {
            if (i < messages_.size()) {
                auto& msg = messages_[i];
                if (msg.message_id == next_message_id_) {
                    throw std::runtime_error("Duplicate message ID encountered");
                }

                msg.message_id = next_message_id_;
                msg.payload.reset(new uint8_t[std::rand() % 1024]); // Set payload size limit
                for (auto& nfapi : msg.nfapi_messages) {
                    if (nfapi.tag == NFAPI_MESSAGE_T::RX_UE_INFORMATION_TAG::RNTI && nfapi.rnti == rnti) {
                        throw std::runtime_error("RNTI collision detected");
                    }
                }
                msg.nfapi_messages.emplace_back(NFAPI_MESSAGE_T::RX_UE_INFORMATION_TAG::UE_ID, rnti);
                generated_messages.push_back(msg);
            } else {
                break; // Session has reached its maximum size
