#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <event2/buffer.h>
#include <event2/dns.h>
#include <pthread.h>

struct dns_query {
    evdns_question_t question;
    struct sockaddr_in addr;
    int refcount;
};

struct ip_cache {
    evdns_resource_record_t *records[IN6ADDRSZ];
    time_t expire_time;
};

void dns_query_free(struct dns_query *query) {
    if (--query->refcount == 0) {
        free(query);
    }
}

static evdns_resolver_t *resolver = NULL;
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void dns_cache_init() {
    if (resolver) return;
    resolver = evdns_resolver_new();
}

struct ip_cache *dns_get(const char *hostname, time_t *timeout) {
    struct ip_cache *cache = NULL;
    struct dns_query *query;

    pthread_mutex_lock(&cache_lock);
    if (evdns_resource_record_find(resolver->cache, hostname, 0)) {
        cache = evdns_resource_record_get_addresses(resolver->cache, hostname);
        *timeout = cache->expire_time;
    } else {
        query = malloc(sizeof(*query));
        query->refcount = 1;
        memcpy(&query->question.name, hostname, strlen(hostname) + 1);
        query->question.type = EVDNSTYPE_A;
        query->addr = (struct sockaddr_in){0};

        evdns_query_send(resolver, &query->question, dns_query_free, NULL);
        cache = malloc(sizeof(*cache));
        memset(cache, 0, sizeof(*cache));
        *timeout = time(NULL) + 60; // 1-minute TTL
    }
    pthread_mutex_unlock(&cache_lock);

    return cache;
}

void dns_query_callback(struct event_loop *loop, evutil_socket_t fd, int events, void *arg) {
    struct dns_query *query = arg;
    struct ip_cache *cache = NULL;
    struct sockaddr_in *addr = &query->addr;

    if (events & EVUTIL_SOCKET_ERROR) {
        free(query);
        return;
    }

    evutil_inet_ntop(AF_INET, addr, query->question.name, sizeof(query->question.name));
    cache = dns_get(query->question.name, NULL);

    if (evdns_resource_record_find(cache->records, addr, 0)) {
        memcpy(arg, query, sizeof(*query));
        evutil_make_socket_nonblocking(fd);
        event_add(event_base, arg);
    } else {
        dns_query_free(query);
    }
}
