    while ((entry = readdir(dir))) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
        struct stat st;
        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", dirpath, entry->d_name);
        if (stat(filepath, &st) == -1) {
            perror("stat");
            exit(EXIT_FAILURE);
        }
        files_list[i++] = (file_info*)calloc(1, sizeof(file_info));
        if (!files_list[i-1]) {
            perror("calloc");
            exit(EXIT_FAILURE);
        }
        files_list[i-1]->filename = strdup(entry->d_name);
        if (!files_list[i-1]->filename) {
            perror("strdup");
            exit(EXIT_FAILURE);
        }
        files_list[i-1]->size = st.st_size;
        files_list[i-1]->mod_time = st.st_mtime;
    }
    closedir(dir);
    return files_list;
