    void addMessage(const LTE_RRCNAS_Message& message) {
        if (m_sessionMap.find(message.message_id) != m_sessionMap.end()) {
            throw std::invalid_argument("Duplicate Message ID within session");
        }

        if (m_sessionCount + 1 > MaxMessagesPerSession) {
            throw std::runtime_error("Maximum session length reached");
        }

        if (m_sessionCount + 1 > MaxConcurrentSessions * MaxMessagesPerSession) {
            throw std::runtime_error("Maximum number of concurrent sessions reached");
        }

        m_sessionMap[message.message_id] = std::make_unique<std::vector<LTE_RRCNAS_Message>>();
        (*m_sessionMap[message.message_id]).emplace_back(message);
        ++m_sessionCount;
    }

    void logCompletion() {
