typedef struct {
    sem_t queue_sem;
    pthread_mutex_t queue_lock;
    size_t capacity;
    size_t head;
    size_t tail;
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T* data;
} CircularQueue;

CircularQueue* circular_queue_create(size_t capacity) {
    CircularQueue* queue = malloc(sizeof(CircularQueue));
    if (!queue) return NULL;
    queue->capacity = capacity;
    queue->data = calloc(capacity, sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }
    sem_init(&queue->queue_sem, 0, capacity);
    pthread_mutex_init(&queue->queue_lock, NULL);
    return queue;
}

void circular_queue_push(CircularQueue* queue, NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T item) {
    sem_wait(&queue->queue_sem);
    pthread_mutex_lock(&queue->queue_lock);

    size_t next = (queue->head + 1) % queue->capacity;
    if (next == queue->tail) {
        pthread_mutex_unlock(&queue->queue_lock);
        sem_post(&queue->queue_sem);
        return; // Queue is full, drop the item
    }
    queue->data[queue->head] = item;
    queue->head = next;

    pthread_mutex_unlock(&queue->queue_lock);
    sem_post(&queue->queue_sem);
}

NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T circular_queue_pop(CircularQueue* queue) {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T item;
    sem_wait(&queue->queue_sem);
    pthread_mutex_lock(&queue->queue_lock);

    if (queue->head == queue->tail) {
        pthread_mutex_unlock(&queue->queue_lock);
        sem_post(&queue->queue_sem);
        return (NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_PDU_T){0}; // Queue is empty, return an empty item
    }
    item = queue->data[queue->tail];
    queue->tail = (queue->tail + 1) % queue->capacity;

    pthread_mutex_unlock(&queue->queue_lock);
    sem_post(&queue->queue_sem);
    return item;
}

