} Entry;

typedef struct list {
    Entry* entries;
    size_t capacity;
    size_t size;
    void (*destroy)(Entry*);
    int (*cmp)(const Entry*, const Entry*);
} List;

void destroy_entry(Entry* entry) {
    free(entry->name);
    free(entry);
}

int cmp_priority(const Entry* a, const Entry* b) {
    return a->priority - b->priority;
}

List* create_list(size_t capacity, size_t initial_size, void (*destroy)(Entry*)) {
    List* list = malloc(sizeof(List));
    list->capacity = capacity;
    list->size = initial_size;
    list->entries = malloc(initial_size * sizeof(Entry));
    list->destroy = destroy;
    list->cmp = cmp_priority;

    for (size_t i = 0; i < initial_size; ++i) {
        list->entries[i].name = NULL;
        list->entries[i].priority = 0;
    }

    return list;
}

void resize_list(List* list, size_t new_capacity) {
    if (new_capacity <= list->size)
        return;

    Entry* temp = realloc(list->entries, new_capacity * sizeof(Entry));
    if (!temp) {
        free(list->entries);
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }

    list->entries = temp;
    list->capacity = new_capacity;
}

void push_back(List* list, const char* name, int priority) {
    if (list->size == list->capacity)
        resize_list(list, 2 * list->capacity);

    Entry* entry = &list->entries[list->size];
    entry->name = strdup(name);
    entry->priority = priority;
    ++list->size;
}

void sort(List* list) {
    qsort(list->entries, list->size, sizeof(Entry), list->cmp);
}

void destroy_list(List* list) {
    for (size_t i = 0; i < list->size; ++i)
        list->destroy(&list->entries[i]);
    free(list->entries);
    free(list);
}
